class GraphCoordinator:
    """One in-process authority over a GraphStore's business SQLite connection.

    ``bootstrap`` is an object held only by trusted host setup. Domain code gets
    no GraphStore or bootstrap reference. Registration and guard mutation are
    setup/administrative operations, not user-supplied command fields.
    """

    def __init__(self, store: GraphStore, bootstrap: object, *,
                 deletion_journal=None, migration_authority=None,
                 restore_authority=None,
                 execution_journal_port: ExecutionJournalPort | None = None,
                 snapshot_requirements=None, holder=None, content_fence=None,
                 content_fence_v2: ContentFencePortV2 | None = None,
                 closure_verifier=None, d02_issuer=None, d11_issuer=None,
                 ingress_policy=None, ingress_clock=None,
                 owner_principal_resolver=None,
                 dispatch_admission_issuer=None, dispatch_clock_policy=None,
                 scene_identity_port=None, scene_clock_policy=None,
                   encoding_request_issuer=None, model_terminal_cost_port=None,
                   accounting_maintenance_port=None, self_identity_port=None,
                   worker_result_fact_port: WorkerResultReadFactPort | None = None,
                   original_c02_cost_intent_port=None):
        if not isinstance(store, GraphStore):
            raise TypeError("store must be GraphStore")
        if bootstrap is None or isinstance(bootstrap, (str, bytes, int, float)):
            raise TypeError("bootstrap must be an opaque host object")
        if isinstance(store, ProductionGraphStore):
            v2 = content_fence_v2 is not None
            if (not holder or (v2 and not isinstance(content_fence_v2, ContentFencePortV2))
                    or (not v2 and (deletion_journal is None
                        or migration_authority is None or restore_authority is None
                        or not callable(getattr(execution_journal_port, "verify_current_chain", None))
                        or not callable(snapshot_requirements) or not callable(content_fence)
                        or not callable(getattr(d02_issuer, "authorize_resources", None))
                        or not callable(getattr(d11_issuer, "admit_runtime", None))))):
                raise UnavailableGuard("production recovery and activation authority required")
        self.__store = store
        self.__bootstrap = bootstrap
        self.__deletion_journal = deletion_journal
        self.__migration_authority = migration_authority
        self.__restore_authority = restore_authority
        self.__execution_journal_port = execution_journal_port
        self.__snapshot_requirements = snapshot_requirements
        self.__holder = holder
        self.__content_fence = content_fence
        self.__content_fence_v2 = content_fence_v2
        self.__scene_identity_port = scene_identity_port
        self.__scene_clock_policy = scene_clock_policy
        self.__closure_verifier = closure_verifier
        self.__d02_issuer = d02_issuer
        self.__d11_issuer = d11_issuer
        if encoding_request_issuer is not None and not callable(encoding_request_issuer):
            raise TypeError("encoding_request_issuer must be callable")
        self.__encoding_request_issuer = encoding_request_issuer
        if model_terminal_cost_port is not None and not callable(model_terminal_cost_port):
            raise TypeError("model_terminal_cost_port must be callable")
        self.__model_terminal_cost_port = model_terminal_cost_port
        if (original_c02_cost_intent_port is not None
                and not callable(original_c02_cost_intent_port)):
            raise TypeError("original_c02_cost_intent_port must be callable")
        self.__original_c02_cost_intent_port = original_c02_cost_intent_port
        if (accounting_maintenance_port is not None
                and any(not callable(getattr(accounting_maintenance_port, name, None))
                        for name in ("begin", "validate", "finish", "recover_finish"))):
            raise TypeError("accounting maintenance port requires four operations")
        self.__accounting_maintenance_port = accounting_maintenance_port
        if (self_identity_port is not None
                and not callable(getattr(self_identity_port, "current_self_identity", None))):
            raise TypeError("self identity port requires current_self_identity")
        self.__self_identity_port = self_identity_port
        if (worker_result_fact_port is not None and not callable(
                getattr(worker_result_fact_port,
                        "current_worker_result_read_fact", None))):
            raise TypeError("worker result fact port requires current_worker_result_read_fact")
        self.__worker_result_fact_port = worker_result_fact_port
        if accounting_maintenance_port is not None:
            # Persist the fence attempt before asking Authority to begin it.
            # A process restart must never invent a second active attempt.
            with store._lock:
                store._db.execute("""
                    CREATE TABLE IF NOT EXISTS graph_original_model_cost_attempts_v1 (
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        call_id TEXT NOT NULL, intent_digest TEXT NOT NULL,
                        attempt_id TEXT NOT NULL, anchor_json TEXT NOT NULL,
                        state TEXT NOT NULL CHECK(state IN ('open','closed','committed')),
                        PRIMARY KEY(bot, persona, call_id), UNIQUE(attempt_id))
                """)
        with store._lock:
            store._db.execute("""
                CREATE TABLE IF NOT EXISTS graph_c02_cost_attempts_v1 (
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL,
                    intent_digest TEXT NOT NULL,
                    completion_digest TEXT NOT NULL,
                    attempt_id TEXT NOT NULL, anchor_json TEXT NOT NULL,
                    state TEXT NOT NULL CHECK(state IN ('open','closed','committed')),
                    PRIMARY KEY(bot,persona,operation_id), UNIQUE(attempt_id))
            """)
        # Installed by trusted host composition only.  A missing issuer leaves
        # D08/D09 candidates in HOLD; caller receipt strings are never enough.
        self.__dispatch_admission_issuer = dispatch_admission_issuer
        self.__dispatch_clock_policy = dispatch_clock_policy
        # No product numeric issuer is installed in alpha1. A DTO is never a permit.
        self.__product_advance_issuer = None
        if ingress_policy is not None and not callable(ingress_policy):
            raise TypeError("ingress_policy must be callable")
        self.__ingress_policy = ingress_policy
        if ingress_clock is not None and not callable(ingress_clock):
            raise TypeError("ingress_clock must be callable")
        self.__ingress_clock = ingress_clock
        if (owner_principal_resolver is not None
                and not callable(owner_principal_resolver)):
            raise TypeError("owner_principal_resolver must be callable")
        self.__owner_principal_resolver = owner_principal_resolver
        self.__ingress_clock_bindings: dict[
            tuple[NamespaceId, str, int], _IngressClockBinding] = {}
        self.__graph_capability = object()
        if isinstance(store, ProductionGraphStore):
            if getattr(store, "_coordinator_capability", None) is not None:
                raise AuthorityDenied("production graph store is already bound")
            store._coordinator_capability = self.__graph_capability
        self.__leases: dict[_AuthorityLease, tuple[str, str, str, NamespaceId, frozenset[str],
                                                  frozenset[str], int]] = {}
        self.__owner_leases: dict[_AuthorityLease, OwnerLeaseBindingV1] = {}
        self.__owner_session_proofs: dict[_AuthorityLease, tuple[str, object]] = {}
        self.__deletion_read_leases: set[_AuthorityLease] = set()
        self.__providers: dict[str, tuple[object, str, str]] = {}

    def _content_fence(self, namespace: NamespaceId, generation: int,
                       operation: str):
        if not isinstance(self.__store, ProductionGraphStore):
            return nullcontext()
        if self.__content_fence_v2 is not None:
            raise UnavailableGuard("v2 graph write path is not admitted")
        if self.__content_fence is None:
            raise UnavailableGuard("content authority fence unavailable")
        return self.__content_fence(namespace_ref(namespace), self.__holder,
                                    generation, operation)

    @staticmethod
    def _anchor_matches(requirements, anchor) -> bool:
        return (requirements.authority_id == anchor.authority_id
                and requirements.authority_namespace == anchor.namespace
                and requirements.activation_generation == anchor.activation_generation
                and requirements.deletion_journal_id == anchor.deletion_journal_id
                and requirements.deletion_seq == anchor.deletion_seq
                and requirements.deletion_digest == anchor.deletion_digest
                and requirements.execution_journal_id == anchor.execution_journal_id
                and requirements.execution_seq == anchor.execution_seq
                and requirements.execution_digest == anchor.execution_digest
                and requirements.revocation_epoch == anchor.revocation_epoch)

    def _v2_graph_stamp(self, namespace: NamespaceId):
        """Read both business stamps while the GraphStore lock is held."""
        store = self.__store
        metadata = store.graph_recovery_metadata(
            namespace, _capability=self.__graph_capability)
        if metadata is None:
            raise UnavailableGuard("v2 graph recovery metadata is absent")
        epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        return metadata, epoch

    def _read_v2(self, authority: AuthorityContext, reader, *,
                 owner_principal=None,
                 owner_binding: OwnerLeaseBindingV1 | None = None,
                 owner_view: bool = False,
                 owner_session_proof: tuple[str, object] | None = None,
                 final_check=None, return_recovery_context: bool = False,
                 durable_read_key: str | None = None):
        """Keep every Authority RPC outside the business graph lock."""
        if owner_view and owner_principal is None:
            raise ValueError("Owner view requires an expected principal")
        store = self.__store
        namespace = authority.namespace
        port = self.__content_fence_v2
        try:
            with store._lock:
                metadata, epoch = self._v2_graph_stamp(namespace)
            target = metadata.requirements
            if target.namespace != namespace or target.activation_generation != authority.activation_generation:
                raise UnavailableGuard("v2 graph recovery identity or generation differs")
            anchor = port.current_anchor(
                namespace=namespace, authority_namespace=target.authority_namespace)
            if not self._anchor_matches(target, anchor):
                raise UnavailableGuard("v2 graph recovery anchor differs")
            if durable_read_key is not None:
                self._recover_stage_candidate_read(
                    namespace, durable_read_key, metadata, epoch, anchor)
            operation_id = "graph-read-" + secrets.token_hex(16)
            if durable_read_key is not None:
                self._record_stage_candidate_read(
                    namespace, durable_read_key, operation_id, metadata, epoch,
                    anchor)
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=authority.activation_generation,
                operation="read", operation_id=operation_id, expected_anchor=anchor)
            scope = FenceScope(namespace, target.authority_namespace,
                               authority.activation_generation, "read", operation_id,
                               permit, anchor, epoch, metadata.graph_revision)
            try:
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("v2 read permit changed")
                if owner_principal is not None or owner_binding is not None:
                    observed_guard, observed_owner = self._owner_binding_in_fence(
                        authority, scope, owner_principal, owner_binding,
                        owner_session_proof)
                with store._lock:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("v2 graph recovery stamp changed")
                    result = reader()
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("v2 read permit changed")
                if owner_principal is not None or owner_binding is not None:
                    current_guard, _ = self._owner_binding_in_fence(
                        authority, scope, owner_principal, observed_owner,
                        owner_session_proof)
                    if current_guard != observed_guard:
                        raise UnavailableGuard("Owner Authority guard changed during read")
                with store._lock:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("v2 graph recovery stamp changed")
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("v2 read permit changed")
                if final_check is not None:
                    with store._lock:
                        if self._v2_graph_stamp(namespace) != (metadata, epoch):
                            raise UnavailableGuard("v2 graph recovery stamp changed")
                        final_check(result)
                if owner_view:
                    return CurrentOwnerViewV1(observed_guard, observed_owner)
                if return_recovery_context:
                    return result, anchor, metadata, epoch
                return result
            finally:
                port.finish_fence(
                    scope, request_id="finish:" + operation_id,
                    request_digest="sha256:" + canonical_digest({
                        "operation_id": operation_id, "permit_token": permit.token,
                        "action": "finish_read",
                    }))
                if durable_read_key is not None:
                    self._close_stage_candidate_read(
                        namespace, durable_read_key, operation_id)
        except UnavailableGuard:
            raise
        except Exception as exc:
            raise UnavailableGuard("v2 content authority is unavailable") from exc

    @staticmethod
    def _provision_row(db, namespace: NamespaceId):
        return db.execute(
            "SELECT operation_id,digest,receipt_json "
            "FROM graph_namespace_provisioning_v2 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()

    @staticmethod
    def _provision_intent_row(db, namespace: NamespaceId):
        row = db.execute(
            "SELECT operation_id,digest,identity_json,genesis_request_id,"
            "fence_attempt_id,graph_incarnation,anchor_json "
            "FROM graph_namespace_provision_intents_v2 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        if row is None:
            return None
        intent = _NamespaceProvisionIntentV2(namespace, *row)
        try:
            expected = GraphCoordinator._fixed_provision_ids(
                intent.identity_json, intent.operation_id, intent.digest)
            if (intent.genesis_request_id, intent.fence_attempt_id,
                    intent.graph_incarnation) != expected:
                raise ValueError("provisioning attempt IDs differ")
            if (intent.anchor_json is not None
                    and canonical_json(json.loads(intent.anchor_json))
                    != intent.anchor_json):
                raise ValueError("provisioning anchor is noncanonical")
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable v2 provisioning intent is invalid") from exc
        return intent

    @staticmethod
    def _fixed_provision_ids(identity_json, operation_id, digest):
        identity = json.loads(identity_json)
        if type(identity) is not dict or canonical_json(identity) != identity_json:
            raise ValueError("noncanonical provisioning identity")
        base = {
            "identity": identity, "operation_id": operation_id,
            "input_digest": digest,
        }
        def fixed_id(domain):
            return canonical_digest({"domain": domain, **base})
        return (
            "namespace-genesis-" + fixed_id("genesis")[:48],
            "provision-write-" + fixed_id("write")[:48],
            "graph:" + fixed_id("incarnation"),
        )

    @staticmethod
    def _check_provision_intent(intent, operation_id, digest, identity_json):
        if (intent.operation_id != operation_id or intent.digest != digest
                or intent.identity_json != identity_json):
            raise AuthorityDenied("namespace provisioning identity differs")

    def _ensure_provision_intent(self, policy, grant, operation_id, digest):
        store = self.__store
        namespace = policy.namespace
        identity_json = canonical_json({
            "policy": policy.digest_payload(), "authority_id": grant.authority_id,
            "subject": grant.subject, "holder": grant.administrator_holder,
            "installation_id": grant.installation_id,
            "authority_namespace": policy.authority_namespace,
        })
        with store._lock:
            store._ensure_open()
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                intent = self._provision_intent_row(db, namespace)
                if intent is None:
                    if policy.root_grant.valid_until_utc <= time.time():
                        raise UnavailableGuard("root grant expired before namespace genesis")
                    if (self._provision_row(db, namespace) is not None
                            or store._recovery_row(namespace) is not None
                            or store._has_namespace_history(namespace)
                            or GraphStore.graph_epoch(
                                store, *namespace.as_tuple,
                                _capability=self.__graph_capability).revision != 0):
                        raise UnavailableGuard("namespace has unsealed business history")
                    genesis_id, attempt_id, incarnation = self._fixed_provision_ids(
                        identity_json, operation_id, digest)
                    intent = _NamespaceProvisionIntentV2(
                        namespace, operation_id, digest, identity_json,
                        genesis_id, attempt_id, incarnation, None)
                    db.execute(
                        "INSERT INTO graph_namespace_provision_intents_v2"
                        "(bot,persona,operation_id,digest,identity_json,"
                        "genesis_request_id,fence_attempt_id,graph_incarnation,anchor_json)"
                        " VALUES(?,?,?,?,?,?,?,?,NULL)",
                        namespace.as_tuple + (
                            intent.operation_id, intent.digest, intent.identity_json,
                            intent.genesis_request_id, intent.fence_attempt_id,
                            intent.graph_incarnation))
                self._check_provision_intent(intent, operation_id, digest, identity_json)
                if self._provision_row(db, namespace) is None:
                    if (store._recovery_row(namespace) is not None
                            or store._has_namespace_history(
                                namespace, provision_intent=(operation_id, digest))
                            or GraphStore.graph_epoch(
                                store, *namespace.as_tuple,
                                _capability=self.__graph_capability).revision != 0):
                        raise UnavailableGuard("namespace has unsealed business history")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        return intent, identity_json

    def _persist_provision_anchor(self, intent, anchor, identity_json):
        store = self.__store
        encoded = canonical_json(asdict(anchor))
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current = self._provision_intent_row(db, intent.namespace)
                self._check_provision_intent(
                    current, intent.operation_id, intent.digest, identity_json)
                if current.anchor_json is None:
                    db.execute(
                        "UPDATE graph_namespace_provision_intents_v2 SET anchor_json=? "
                        "WHERE bot=? AND persona=? AND anchor_json IS NULL",
                        (encoded,) + intent.namespace.as_tuple)
                elif current.anchor_json != encoded:
                    raise UnavailableGuard("v2 provisioning genesis anchor differs")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        return self._provision_intent_row(store._db, intent.namespace)

    @staticmethod
    def _decode_provision_receipt(row) -> NamespaceProvisionReceiptV2:
        try:
            data = json.loads(row[2])
            if (type(data) is not dict
                    or set(data) != {item.name for item in fields(NamespaceProvisionReceiptV2)}
                    or type(data["namespace"]) is not dict):
                raise ValueError("invalid provisioning receipt fields")
            data["namespace"] = NamespaceId(**data["namespace"])
            receipt = NamespaceProvisionReceiptV2(**data)
            if (row[:2] != (receipt.operation_id, receipt.input_digest)
                    or canonical_json(asdict(receipt)) != row[2]):
                raise ValueError("noncanonical provisioning receipt")
            return receipt
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable v2 provisioning receipt is invalid") from exc

    def _verify_provision_receipt(self, policy, operation_id: str, digest: str):
        """Called with the graph lock; inspect linked business facts, not Authority."""
        store = self.__store
        namespace = policy.namespace
        row = self._provision_row(store._db, namespace)
        if row is None:
            raise UnavailableGuard("durable v2 provisioning receipt is absent")
        if row[0] != operation_id or row[1] != digest:
            raise AuthorityDenied("namespace provisioning identity differs")
        receipt = self._decode_provision_receipt(row)
        intent = self._provision_intent_row(store._db, namespace)
        if (intent is not None and (
                intent.operation_id != operation_id or intent.digest != digest
                or intent.fence_attempt_id != receipt.fence_attempt_id
                or intent.graph_incarnation != receipt.graph_incarnation
                or intent.anchor_json is None)):
            raise UnavailableGuard("durable v2 provisioning intent differs from receipt")
        metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (receipt.namespace != namespace
                or receipt.installation_id != policy.installation_id
                or receipt.manifest_digest != policy.manifest_digest
                or receipt.authority_id != target.authority_id
                or receipt.authority_namespace != target.authority_namespace
                or receipt.generation != target.activation_generation
                or receipt.graph_incarnation != target.graph_incarnation
                or receipt.graph_revision != 0 or metadata.graph_revision < 0
                or receipt.graph_epoch != 0 or epoch.revision < 0
                or receipt.catalogue_hash != policy.catalogue_hash
                or receipt.scheme_version != policy.scheme_version
                or receipt.operator_version != policy.operator_version
                or receipt.policy_version != policy.policy_version
                or receipt.root_lease_id != policy.root_lease.lease_id
                or receipt.root_grant_id != policy.root_grant.grant_id
                or receipt.root_grant_version != policy.root_grant.version):
            raise UnavailableGuard("durable v2 provisioning receipt differs from recovery state")
        from .authority_service.v2_contract import FencePermitV2, from_wire
        try:
            permit = from_wire(receipt.permit_wire)
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("durable v2 provisioning permit is invalid") from exc
        if (type(permit) is not FencePermitV2 or permit.operation_id != receipt.fence_attempt_id
                or (intent is not None and intent.anchor_json != canonical_json(
                    asdict(permit.pinned_anchor)))
                or permit.subject != self.__content_fence_v2.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != target.activation_generation
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.pinned_anchor.deletion_journal_id != target.deletion_journal_id
                or permit.pinned_anchor.execution_journal_id != target.execution_journal_id
                or permit.pinned_anchor.deletion_seq != 0
                or permit.pinned_anchor.deletion_digest != "genesis"
                or permit.pinned_anchor.execution_seq != 0
                or permit.pinned_anchor.execution_digest != "genesis"
                or permit.pinned_anchor.revocation_epoch != 0
                or receipt.finish_request_id != "finish:" + receipt.fence_attempt_id
                or receipt.finish_request_digest != "sha256:" + canonical_digest({
                    "operation_id": receipt.fence_attempt_id,
                    "permit_token": permit.token,
                    "action": "finish_namespace_provision",
                    "business_operation_id": operation_id,
                    "input_digest": digest,
                })):
            raise UnavailableGuard("durable v2 provisioning fence identity differs")
        for kind, version in (("scheme", policy.scheme_version),
                              ("operator", policy.operator_version),
                              ("policy", policy.policy_version),
                              ("activation", str(target.activation_generation))):
            if self._version(store._db, namespace, kind, "current") != str(version):
                raise UnavailableGuard("durable v2 provisioning guard changed")
        lease = get_budget_lease(store._db, policy.root_lease.lease_id)
        if (lease.parent_id is not None or lease.lease_id != policy.root_lease.lease_id
                or (lease.bot_id, lease.persona_id) != namespace.as_tuple
                or lease.currency != policy.root_lease.currency
                or lease.limits != policy.root_lease.limits):
            raise UnavailableGuard("durable v2 root budget differs")
        from .runtime.issuers import IssuerAuthorityDenied
        try:
            original_grant, original_signature = (
                self.__d11_issuer.signed_budget_grant_at_version(
                    store._db, lease.lease_id, receipt.root_grant_version))
        except IssuerAuthorityDenied as exc:
            raise UnavailableGuard("durable v2 D11 budget grant is invalid") from exc
        if original_grant != policy.root_grant:
            raise UnavailableGuard("durable v2 D11 budget grant differs")
        if original_signature != receipt.root_grant_signature:
            raise UnavailableGuard("durable v2 D11 signature differs")
        return receipt, metadata, epoch

    def _reconcile_provision_v2(self, policy, operation_id: str, digest: str):
        """Resolve an old write fence, then read under a fresh current fence."""
        from .authority_service.v2_contract import FencePermitV2, from_wire

        store = self.__store
        namespace = policy.namespace
        port = self.__content_fence_v2
        with store._lock:
            receipt, metadata, epoch = self._verify_provision_receipt(
                policy, operation_id, digest)
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("v2 provisioning recovery anchor differs")
        if not callable(getattr(port, "get_fence_operation", None)):
            raise UnavailableGuard("v2 Authority fence status is unavailable")
        original = from_wire(receipt.permit_wire)
        observed_permit, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=receipt.fence_attempt_id)
        if (type(original) is not FencePermitV2
                or type(observed_permit) is not FencePermitV2
                or observed_permit != original
                or state not in {"active", "finished"}):
            raise UnavailableGuard("v2 provisioning Authority fence status differs")
        if state == "active":
            if (metadata.graph_revision != receipt.graph_revision
                    or epoch.revision != receipt.graph_epoch
                    or original.pinned_anchor != anchor):
                raise UnavailableGuard("active v2 provisioning fence lost its business stamp")
            write_scope = FenceScope(
                namespace, target.authority_namespace,
                target.activation_generation, "write", receipt.fence_attempt_id,
                original, anchor, epoch, metadata.graph_revision)
            if port.validate_fence(write_scope) != original:
                raise UnavailableGuard("active v2 provisioning permit changed")
            port.finish_fence(
                write_scope, request_id=receipt.finish_request_id,
                request_digest=receipt.finish_request_digest)
        attempt_id = "provision-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="read", operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "read", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("v2 provisioning read permit changed")
            with store._lock:
                confirmed = self._verify_provision_receipt(policy, operation_id, digest)
                if confirmed != (receipt, metadata, epoch):
                    raise UnavailableGuard("v2 provisioning state changed during read")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("v2 provisioning read permit changed")
            with store._lock:
                if self._verify_provision_receipt(policy, operation_id, digest) != confirmed:
                    raise UnavailableGuard("v2 provisioning state changed during read")
            return receipt
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_provision_read",
                }))

    def _stage_first_owner_grant_locked(self, operation, pending, grant_value,
                                        scope: FenceScope, expected_metadata,
                                        expected_epoch):
        """Commit one first Owner grant under an already verified v2 write fence.

        This is deliberately private. A caller must obtain the original pending
        operation online from the paired Authority while holding the same live
        write fence. A caller-supplied pending DTO or bootstrap is not admission.
        No public route is installed until that Authority port exists.
        """
        from .authority_service.v2_owner_contract import (
            OwnerAuthorizationOperationV1, OwnerAuthorizationReceiptV1,
            OwnerGraphCommitProofV1,
        )
        from .graph_store import GraphRecoveryMetadataV2

        store = self.__store
        if not isinstance(store, ProductionGraphStore) or self.__content_fence_v2 is None:
            raise UnavailableGuard("owner grant requires a production v2 graph")
        if not store._lock._is_owned() or not store._db.in_transaction:
            raise RuntimeError("owner grant requires the graph lock and transaction")
        if (type(operation) is not OwnerAuthorizationOperationV1
                or operation.action != "issue" or operation.ticket is None
                or type(pending) is not OwnerAuthorizationReceiptV1
                or pending.phase != "pending" or pending.operation != operation
                or pending.guard != operation.expected_guard):
            raise AuthorityDenied("original pending Owner issue is required")
        if (type(scope) is not FenceScope or scope.operation != "write"
                or scope.namespace != operation.namespace
                or scope.authority_namespace != scope.pinned_anchor.namespace
                or scope.generation != 1
                or type(expected_metadata) is not GraphRecoveryMetadataV2
                or type(expected_epoch) is not NamespaceEpoch):
            raise AuthorityDenied("Owner issue requires the exact v2 write scope")
        namespace = operation.namespace
        if (scope.graph_revision != expected_metadata.graph_revision
                or scope.graph_epoch != expected_epoch
                or expected_epoch.bot != namespace.bot_id
                or expected_epoch.persona != namespace.persona_id
                or self._v2_graph_stamp(namespace) != (expected_metadata, expected_epoch)):
            raise StaleRead("Owner issue graph stamp changed")
        target = expected_metadata.requirements
        if (target.namespace != namespace or target.graph_incarnation == ""
                or target.activation_generation != scope.generation
                or target.authority_id != operation.authority_id
                or target.authority_namespace != scope.authority_namespace
                or not self._anchor_matches(target, scope.pinned_anchor)):
            raise AuthorityDenied("Owner issue differs from graph recovery identity")
        if (type(grant_value) is not dict
                or "sha256:" + canonical_digest(grant_value) != operation.grant_digest):
            raise AuthorityDenied("Owner grant payload differs from reserved digest")
        validate_owner_grant_v1(grant_value)
        ticket = operation.ticket
        principal = operation.principal
        if ticket.policy_digest != owner_grant_policy_digest_v1(
                grant_value, bot=namespace.bot_id, persona=namespace.persona_id):
            raise AuthorityDenied("Owner grant permissions differ from paired policy")
        expected_fields = {
            "authority_id": operation.authority_id,
            "installation_id": operation.installation_id,
            "grant_id": operation.grant_id,
            "principal": {
                "identity_provider": principal.identity_provider,
                "account_ref": principal.account_ref,
                "account_incarnation": principal.account_incarnation,
            },
            "ticket_id": ticket.ticket_id,
            "creation_operation_id": ticket.creation_operation_id,
            "creation_digest": ticket.creation_digest,
            "issue_operation_id": operation.operation_id,
            "grant_revision": 1,
            "activation_generation": scope.generation,
            "graph_incarnation": target.graph_incarnation,
        }
        if any(grant_value[name] != value for name, value in expected_fields.items()):
            raise AuthorityDenied("Owner grant identity differs from pending issue")
        provision_row = self._provision_row(store._db, namespace)
        if provision_row is None:
            raise UnavailableGuard("Owner issue requires completed namespace genesis")
        provision = self._decode_provision_receipt(provision_row)
        if (provision.operation_id != ticket.creation_operation_id
                or "sha256:" + provision.input_digest != ticket.creation_digest
                or provision.installation_id != operation.installation_id
                or provision.authority_id != operation.authority_id
                or provision.authority_namespace != target.authority_namespace
                or provision.namespace != namespace
                or provision.graph_incarnation != target.graph_incarnation
                or provision.generation != scope.generation):
            raise AuthorityDenied("Owner claim differs from completed creation")
        row = store._db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json FROM graph_owner_issue_operations_v1 "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        key = owner_grant_key(*namespace.as_tuple)
        if row is not None:
            if row[:5] != (operation.operation_id, operation.request_digest,
                           operation.grant_id, operation.grant_digest,
                           target.graph_incarnation):
                raise AuthorityDenied("first Owner grant already belongs to another issue")
            proof = OwnerGraphCommitProofV1(
                namespace, row[0], row[1], row[2], row[3], row[4],
                1, row[5], row[6], row[7])
            atom = store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone()
            if (row[8] != canonical_json(asdict(proof)) or atom is None
                    or atom != (1, canonical_json(grant_value), 1)):
                raise UnavailableGuard("durable Owner issue receipt differs from graph")
            return proof
        # The first Owner claim belongs to the namespace creation, not to a
        # later state in which host ingress or another content operation has
        # already established business history without that Owner.
        if (expected_metadata.graph_revision != provision.graph_revision
                or expected_epoch.revision != provision.graph_epoch
                or provision.graph_revision != 0 or provision.graph_epoch != 0):
            raise UnavailableGuard("first Owner claim requires creation genesis")
        # The active Owner write fence excludes another live namespace fence.
        # A terminal first-message rejection has no graph/business effect;
        # unresolved attempts still block Owner genesis.
        if store._db.execute(
                "SELECT 1 FROM graph_first_ingress_intents_v2 AS i "
                "LEFT JOIN graph_first_ingress_rejections_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.operation_id=i.operation_id "
                "WHERE i.bot=? AND i.persona=? AND "
                "(r.status IS NULL OR r.status!='rejected_no_commit' "
                "OR r.graph_revision!=i.graph_revision "
                "OR r.graph_epoch!=i.graph_epoch "
                "OR r.finish_request_id!='abort:'||i.fence_attempt_id) LIMIT 1",
                namespace.as_tuple).fetchone() is not None:
            raise UnavailableGuard("first Owner claim follows unresolved ingress")
        for table in (
                "graph_bundle_intents_v2",
                "graph_bundle_operations", "graph_product_advances",
                "graph_events", "graph_atoms"):
            if store._db.execute(
                    f"SELECT 1 FROM {table} WHERE bot=? AND persona=? LIMIT 1",
                    namespace.as_tuple).fetchone() is not None:
                raise UnavailableGuard("first Owner claim follows business activity")
        if (store._db.execute(
                "SELECT 1 FROM graph_atoms WHERE token=?", (key.token,)
                ).fetchone() is not None):
            raise UnavailableGuard("first Owner grant atom already exists")
        access_row = store._db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone() or (0, 0)
        if access_row != (0, 0):
            raise UnavailableGuard("first Owner grant requires zero access epochs")
        event = Event(
            Scope(*namespace.as_tuple, "owner-authorization-v1"),
            operation.operation_id, 0, "first_owner_grant", {
                "request_digest": operation.request_digest,
                "grant_digest": operation.grant_digest,
            },
        )
        candidate = GraphCandidate(
            event, (GraphVersion(key, 0),),
            (GraphWrite(key, grant_value),), (expected_epoch,),
        )
        graph_receipt = GraphStore._graph_commit_in_transaction(
            store, candidate, _capability=self.__graph_capability,
            _owner_issue=True)
        if (graph_receipt.status != "committed"
                or graph_receipt.revisions != (GraphVersion(key, 1),)):
            raise UnavailableGuard("first Owner graph commit did not create revision one")
        store._db.execute(
            "INSERT INTO graph_authority_epochs(bot,persona,access_epoch,delete_epoch) "
            "VALUES(?,?,1,0)", namespace.as_tuple,
        )
        store.cas_graph_recovery_metadata(
            expected_metadata, target, _capability=self.__graph_capability)
        digest = "sha256:" + canonical_digest({
            "schema": "sylanne3.graph.owner_issue_receipt.v1",
            "namespace": list(namespace.as_tuple),
            "operation_id": operation.operation_id,
            "request_digest": operation.request_digest,
            "grant_id": operation.grant_id,
            "grant_digest": operation.grant_digest,
            "graph_incarnation": target.graph_incarnation,
            "grant_revision": 1,
            "graph_access_epoch": 1,
            "graph_epoch": graph_receipt.epoch.revision,
            "graph_revision": expected_metadata.graph_revision + 1,
            "atom_token": key.token,
        })
        proof = OwnerGraphCommitProofV1(
            namespace, operation.operation_id, operation.request_digest,
            operation.grant_id, operation.grant_digest,
            target.graph_incarnation, 1, 1, graph_receipt.epoch.revision, digest,
        )
        store._db.execute(
            "INSERT INTO graph_owner_issue_operations_v1"
            "(bot,persona,operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (
                operation.operation_id, operation.request_digest,
                operation.grant_id, operation.grant_digest,
                target.graph_incarnation, 1, graph_receipt.epoch.revision,
                digest, canonical_json(asdict(proof))),
        )
        return proof

    def commit_first_owner_grant_v2(self, bootstrap: object, *,
                                    namespace: NamespaceId, operation_id: str,
                                    grant_value: dict):
        """Commit only the paired pending first Owner issue under a v2 write fence.

        Authority is queried as the installed graph peer, never through a DTO
        supplied by the caller. The resulting proof is inert until Authority
        independently verifies it and finalizes the issue.
        """
        from .authority_service.contract import identifier
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .authority_service.v2_owner_contract import OwnerGraphCommitProofV1

        if bootstrap is not self.__bootstrap:
            raise AuthorityDenied("owner graph issue requires host bootstrap")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("owner graph issue requires production v2")
        if type(namespace) is not NamespaceId:
            raise TypeError("namespace must be NamespaceId")
        identifier(operation_id, "operation_id")
        validate_owner_grant_v1(grant_value)
        grant_digest = "sha256:" + canonical_digest(grant_value)
        store = self.__store
        port = self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = store._db.execute(
                "SELECT operation_id,grant_digest,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch "
                "FROM graph_owner_issue_intents_v1 WHERE bot=? AND persona=? "
                "AND operation_id=? AND grant_digest=?",
                namespace.as_tuple + (operation_id, grant_digest),
            ).fetchone()
            rejected = store._db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_owner_issue_rejections_v1 WHERE bot=? AND persona=? "
                "AND operation_id=? AND grant_digest=?",
                namespace.as_tuple + (operation_id, grant_digest),
            ).fetchone()
            saved = store._db.execute(
                "SELECT operation_id,permit_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_owner_issue_fences_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            proof_row = store._db.execute(
                "SELECT operation_id,request_digest,grant_id,grant_digest,"
                "graph_incarnation,graph_access_epoch,graph_epoch,"
                "graph_receipt_digest,proof_json "
                "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace or target.activation_generation != 1
                or target.authority_id != port.installation_grant.authority_id
                or target.authority_namespace == ""):
            raise UnavailableGuard("owner graph recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("owner graph recovery anchor differs")
        attempt_id = "owner-write-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "grant_digest": grant_digest,
        })[:48]
        identity = (operation_id, grant_digest, attempt_id,
                    canonical_json(asdict(target)), canonical_json(asdict(anchor)))
        if intent is not None and intent[:5] != identity:
            raise AuthorityDenied("first Owner issue intent differs")
        if intent is not None and (metadata.graph_revision, epoch.revision) != intent[5:7]:
            if saved is None:
                raise UnavailableGuard("uncommitted Owner issue graph stamp changed")
        if rejected is not None:
            if saved is not None or proof_row is not None or intent is None:
                raise UnavailableGuard("rejected Owner issue has business receipt")
            permit = from_wire(json.loads(rejected[1]))
            abort_id = "abort:" + attempt_id
            abort_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_owner_commit",
                "business_operation_id": operation_id,
                "grant_digest": grant_digest,
            })
            if (rejected[0] != "rejected_no_commit"
                    or rejected[2:4] != intent[5:7]
                    or rejected[4:6] != (abort_id, abort_digest)
                    or permit.operation_id != attempt_id
                    or permit.operation != "write" or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.authority_id != target.authority_id
                    or permit.namespace != target.authority_namespace
                    or permit.generation != 1
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("durable Owner rejection identity differs")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("rejected Owner issue fence differs")
            if state == "active":
                scope = FenceScope(namespace, target.authority_namespace, 1,
                    "write", attempt_id, permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, intent[6]), intent[5])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("rejected Owner write permit changed")
                port.finish_fence(scope, request_id=abort_id,
                                  request_digest=abort_digest)
            raise AuthorityDenied("Owner issue is terminal rejected_no_commit")
        if (saved is None) != (proof_row is None):
            raise UnavailableGuard("Owner graph proof and fence receipt disagree")
        if saved is not None:
            try:
                permit = from_wire(json.loads(saved[1]))
                proof = OwnerGraphCommitProofV1(
                    namespace, proof_row[0], proof_row[1], proof_row[2],
                    proof_row[3], proof_row[4], 1, proof_row[5],
                    proof_row[6], proof_row[7])
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("durable Owner issue proof is invalid") from exc
            finish_id = "finish:" + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "finish_owner_issue", "business_operation_id": operation_id,
                "graph_receipt_digest": proof.graph_receipt_digest,
            })
            if (intent is None or saved[0] != operation_id
                    or saved[2:4] != intent[5:7]
                    or saved[4] != saved[2] + 1 or saved[5] != proof.graph_epoch
                    or saved[6:8] != (finish_id, finish_digest)
                    or proof_row[0] != operation_id or proof_row[3] != grant_digest
                    or proof_row[8] != canonical_json(asdict(proof))
                    or permit.operation_id != attempt_id or permit.operation != "write"
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.authority_id != target.authority_id
                    or permit.namespace != target.authority_namespace
                    or permit.generation != 1 or permit.pinned_anchor != anchor):
                raise UnavailableGuard("durable Owner issue fence identity differs")
            with store._lock:
                atom = store._db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (owner_grant_key(*namespace.as_tuple).token,),
                ).fetchone()
                access = store._db.execute(
                    "SELECT access_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if (atom != (1, canonical_json(grant_value), 1)
                        or access != (proof.graph_access_epoch,)):
                    raise UnavailableGuard("durable Owner grant differs from graph")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("Owner issue Authority fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("active Owner issue lost its graph stamp")
                scope = FenceScope(
                    namespace, target.authority_namespace, 1, "write", attempt_id,
                    permit, anchor, NamespaceEpoch(*namespace.as_tuple, saved[3]),
                    saved[2])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("Owner issue write permit changed")
                port.finish_fence(scope, request_id=finish_id,
                                  request_digest=finish_digest)
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("finished Owner issue lost its graph stamp")
            return proof
        if proof_row is not None:
            raise UnavailableGuard("Owner graph proof lacks durable fence receipt")
        if intent is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("Owner issue graph stamp changed before intent")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_owner_issue_intents_v1"
                        "(bot,persona,operation_id,grant_digest,fence_attempt_id,"
                        "requirements_json,anchor_json,graph_revision,graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + identity + (
                            metadata.graph_revision, epoch.revision),
                    )
                    intent = db.execute(
                        "SELECT operation_id,grant_digest,fence_attempt_id,"
                        "requirements_json,anchor_json,graph_revision,graph_epoch "
                        "FROM graph_owner_issue_intents_v1 WHERE bot=? AND persona=? "
                        "AND operation_id=? AND grant_digest=?",
                        namespace.as_tuple + (operation_id, grant_digest),
                    ).fetchone()
                    if intent != identity + (metadata.graph_revision, epoch.revision):
                        raise AuthorityDenied("Owner issue intent was not installed")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
        from .runtime.restore_anchor import RestoreAnchor
        try:
            pinned_anchor = RestoreAnchor(**json.loads(intent[4]))
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("Owner issue intent anchor is invalid") from exc
        if pinned_anchor != anchor:
            raise UnavailableGuard("Owner issue intent anchor changed")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="write",
            operation_id=attempt_id, expected_anchor=pinned_anchor,
            retain_on_unknown=True)
        if (type(permit) is not FencePermitV2 or permit.operation_id != attempt_id
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != 1 or permit.pinned_anchor != anchor):
            raise UnavailableGuard("Owner issue write permit differs")
        scope = FenceScope(namespace, target.authority_namespace, 1, "write",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        def reject_no_commit():
            abort_id = "abort:" + attempt_id
            abort_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_owner_commit",
                "business_operation_id": operation_id,
                "grant_digest": grant_digest,
            })
            rejection = (
                "rejected_no_commit", canonical_json(to_wire(permit)),
                metadata.graph_revision, epoch.revision,
                abort_id, abort_digest,
            )
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("Owner issue rollback stamp changed")
                    if db.execute(
                        "SELECT 1 FROM graph_owner_issue_operations_v1 "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() is not None:
                        raise UnavailableGuard("Owner issue has a business commit")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_owner_issue_rejections_v1"
                        "(bot,persona,operation_id,grant_digest,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (operation_id, grant_digest) + rejection,
                    )
                    actual = db.execute(
                        "SELECT status,permit_json,graph_revision,graph_epoch,"
                        "finish_request_id,finish_request_digest "
                        "FROM graph_owner_issue_rejections_v1 WHERE bot=? AND persona=? "
                        "AND operation_id=? AND grant_digest=?",
                        namespace.as_tuple + (operation_id, grant_digest),
                    ).fetchone()
                    if actual != rejection:
                        raise UnavailableGuard("Owner issue rejection differs")
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("rejected Owner write permit changed")
            port.finish_fence(scope, request_id=abort_id,
                              request_digest=abort_digest)

        pending_reader = getattr(port, "get_pending_owner_issue_for_graph_write", None)
        if not callable(pending_reader):
            raise UnavailableGuard("paired pending Owner issue port is unavailable")
        pending = pending_reader(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=operation_id, permit=permit)
        if pending is None or pending.operation.grant_digest != grant_digest:
            reject_no_commit()
            raise AuthorityDenied("paired pending Owner issue differs")
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("Owner issue write permit changed")
        rolled_back_error = None
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("Owner issue graph stamp changed")
                if db.execute(
                    "SELECT operation_id,grant_digest,fence_attempt_id,"
                    "requirements_json,anchor_json,graph_revision,graph_epoch "
                    "FROM graph_owner_issue_intents_v1 WHERE bot=? AND persona=? "
                    "AND operation_id=? AND grant_digest=?",
                    namespace.as_tuple + (operation_id, grant_digest),
                ).fetchone() != intent:
                    raise AuthorityDenied("first Owner issue intent changed")
                proof = self._stage_first_owner_grant_locked(
                    pending.operation, pending, grant_value, scope, metadata, epoch)
                finish_id = "finish:" + attempt_id
                finish_digest = "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_owner_issue", "business_operation_id": operation_id,
                    "graph_receipt_digest": proof.graph_receipt_digest,
                })
                db.execute(
                    "INSERT INTO graph_owner_issue_fences_v1"
                    "(bot,persona,operation_id,permit_json,pre_graph_revision,"
                    "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                    "finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        operation_id, canonical_json(to_wire(permit)),
                        metadata.graph_revision, epoch.revision,
                        metadata.graph_revision + 1, proof.graph_epoch,
                        finish_id, finish_digest),
                )
                db.execute("COMMIT")
            except BaseException as exc:
                if not db.in_transaction:
                    raise
                db.execute("ROLLBACK")
                if not isinstance(exc, Exception):
                    raise
                rolled_back_error = exc
        if rolled_back_error is not None:
            reject_no_commit()
            raise rolled_back_error
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("committed Owner issue permit changed")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != proof.graph_epoch):
                raise UnavailableGuard("committed Owner issue graph stamp changed")
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return proof

    def _reject_owner_graph_write_v2(self, *, kind, namespace, operation_id,
                                     input_digest, attempt_id, metadata, epoch,
                                     anchor, permit, intent):
        """Persist a proven no-commit outcome before finishing its original fence."""
        from .authority_service.v2_contract import to_wire

        if kind not in {"role_init", "scene_binding"}:
            raise ValueError("unknown Owner graph write")
        table = ("graph_role_init_rejections_v1" if kind == "role_init"
                 else "graph_scene_binding_rejections_v1")
        receipt_table = ("graph_role_init_receipts_v1" if kind == "role_init"
                         else "graph_scene_binding_receipts_v1")
        intent_table = ("graph_role_init_intents_v1" if kind == "role_init"
                        else "graph_scene_binding_intents_v1")
        finish_id = "abort:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "rejected_no_commit", "business_operation_id": operation_id,
            "input_digest": input_digest, "kind": kind,
        })
        expected = (operation_id, "rejected_no_commit",
                    canonical_json(to_wire(permit)), metadata.graph_revision,
                    epoch.revision, finish_id, finish_digest)
        store = self.__store
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise UnavailableGuard("Owner graph no-commit stamp changed")
                if db.execute(
                        f"SELECT 1 FROM {receipt_table} WHERE bot=? AND persona=? "
                        "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone() is not None:
                    raise UnavailableGuard("Owner graph business receipt exists")
                current_intent = db.execute(
                    f"SELECT * FROM {intent_table} WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone()
                if current_intent != namespace.as_tuple + intent:
                    raise UnavailableGuard("Owner graph durable intent changed")
                db.execute(
                    f"INSERT OR IGNORE INTO {table}"
                    "(bot,persona,operation_id,status,permit_json,graph_revision,"
                    "graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?)", namespace.as_tuple + expected,
                )
                recorded = db.execute(
                    f"SELECT operation_id,status,permit_json,graph_revision,"
                    "graph_epoch,finish_request_id,finish_request_digest "
                    f"FROM {table} WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if recorded != expected:
                    raise UnavailableGuard("Owner graph rejection identity differs")
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        self._finish_rejected_owner_graph_write_v2(
            kind=kind, namespace=namespace, operation_id=operation_id,
            input_digest=input_digest, attempt_id=attempt_id, metadata=metadata,
            epoch=epoch, anchor=anchor, rejection=expected)

    def _finish_rejected_owner_graph_write_v2(self, *, kind, namespace,
                                               operation_id, input_digest,
                                               attempt_id, metadata, epoch,
                                               anchor, rejection):
        from .authority_service.v2_contract import FencePermitV2, from_wire

        port = self.__content_fence_v2
        target = metadata.requirements
        try:
            permit = from_wire(json.loads(rejection[2]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("Owner graph rejected permit is invalid") from exc
        expected_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "rejected_no_commit", "business_operation_id": operation_id,
            "input_digest": input_digest, "kind": kind,
        })
        if (type(permit) is not FencePermitV2
                or rejection != (operation_id, "rejected_no_commit",
                                 rejection[2], metadata.graph_revision,
                                 epoch.revision, "abort:" + attempt_id,
                                 expected_digest)
                or permit.operation_id != attempt_id or permit.operation != "write"
                or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != 1 or permit.pinned_anchor != anchor):
            raise UnavailableGuard("Owner graph rejected fence identity differs")
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("Owner graph rejected Authority fence differs")
        if state == "active":
            scope = FenceScope(namespace, target.authority_namespace, 1, "write",
                               attempt_id, permit, anchor, epoch,
                               metadata.graph_revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("Owner graph rejected permit changed")
            port.finish_fence(scope, request_id=rejection[5],
                              request_digest=rejection[6])

    def reject_unresolvable_role_initialization_v2(
            self, *, namespace: NamespaceId, operation_id: str,
            request_digest: str, principal: OwnerPrincipalV1,
            actor_id: str, owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1) -> bool:
        """Finish an original pending fence only when no first-role write is proven."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_contract_digest,
        )

        if (type(namespace) is not NamespaceId or type(principal) is not OwnerPrincipalV1
                or type(operation_id) is not str or not operation_id
                or type(request_digest) is not str or not request_digest):
            raise TypeError("pending role recovery requires typed Owner identity")
        store = self.__store
        port = self.__content_fence_v2
        if not isinstance(store, ProductionGraphStore) or port is None:
            raise UnavailableGuard("pending role graph is unavailable")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            intent = db.execute(
                "SELECT operation_id,input_digest,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch "
                "FROM graph_role_init_intents_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            if intent is None:
                return False
            request_proof = db.execute(
                "SELECT operation_id,request_digest,input_digest "
                "FROM graph_role_init_request_proofs_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            saved = db.execute(
                "SELECT 1 FROM graph_role_init_receipts_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            rejection = db.execute(
                "SELECT 1 FROM graph_role_init_rejections_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            grant_key = owner_grant_key(*namespace.as_tuple)
            grant_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (grant_key.token,),
            ).fetchone()
            owner_proof_row = db.execute(
                "SELECT operation_id,request_digest,grant_id,grant_digest,"
                "graph_incarnation,graph_access_epoch,graph_epoch,"
                "graph_receipt_digest,proof_json "
                "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            business_atom = db.execute(
                "SELECT 1 FROM graph_atoms WHERE bot=? AND persona=? AND type_name IN "
                "('d01.persona_plan.v1','d01.persona_activation.v1',"
                "'runtime.role_resources.v1') LIMIT 1", namespace.as_tuple,
            ).fetchone()
        if request_proof is None:
            raise UnavailableGuard("pending role has no original request proof")
        if (intent[0] != operation_id
                or request_proof != (operation_id, request_digest, intent[1])):
            raise AuthorityDenied("pending role request identity differs")
        if saved is not None or rejection is not None or business_atom is not None:
            raise UnavailableGuard("pending role business outcome is not proven absent")
        if (metadata.graph_revision, epoch.revision) != intent[5:7]:
            raise UnavailableGuard("pending role graph stamp changed")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if (target.namespace != namespace or not self._anchor_matches(target, anchor)
                or intent[3] != canonical_json(asdict(target))
                or intent[4] != canonical_json(asdict(anchor))
                or grant_row is None or grant_row[0] != 1 or grant_row[2] != 1
                or owner_proof_row is None):
            raise UnavailableGuard("pending role recovery identity differs")
        grant = GraphAtom(grant_key, 1, json.loads(grant_row[1]), True)
        validate_owner_grant_v1(grant.value)
        proof = OwnerGraphCommitProofV1(
            namespace, owner_proof_row[0], owner_proof_row[1],
            owner_proof_row[2], owner_proof_row[3], owner_proof_row[4],
            1, owner_proof_row[5], owner_proof_row[6], owner_proof_row[7])
        if (owner_proof_row[8] != canonical_json(asdict(proof))
                or grant_row[1] != canonical_json(grant.value)
                or grant.value["principal"] != asdict(principal)
                or grant.value["grant_id"] != proof.grant_id
                or "sha256:" + canonical_digest(grant.value) != proof.grant_digest
                or grant.value["issue_operation_id"] != proof.operation_id
                or grant.value["graph_incarnation"] != proof.graph_incarnation
                or target.graph_incarnation != proof.graph_incarnation):
            raise AuthorityDenied("pending role Owner principal differs")
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=target)
        attempt_id = intent[2]
        permit, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if (type(permit) is not FencePermitV2 or state != "active"
                or permit.operation_id != attempt_id or permit.operation != "write"
                or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != 1 or permit.pinned_anchor != anchor):
            raise UnavailableGuard("pending role original fence differs")
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(guard_reader):
            raise UnavailableGuard("pending role signed Owner guard is unavailable")
        guarded = guard_reader(
            namespace=namespace, authority_namespace=target.authority_namespace,
            permit=permit, owner_actor_id=actor_id,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request)
        if (type(guarded) is not tuple or len(guarded) != 2
                or type(guarded[0]) is not OwnerAuthorizationGuardV1
                or guarded[1] != permit
                or guarded[0].authority_id != target.authority_id
                or guarded[0].installation_id != grant.value["installation_id"]
                or guarded[0].namespace != namespace
                or guarded[0].authorization_revision != 1
                or guarded[0].authorization_head != owner_contract_digest(proof)
                or guarded[0].pending_revoke_operation_id is not None
                or guarded[0].minimum_revocation_revision != 0
                or guarded[0].minimum_revocation_epoch != 0):
            raise UnavailableGuard("pending role signed Owner guard differs")
        self._reject_owner_graph_write_v2(
            kind="role_init", namespace=namespace, operation_id=operation_id,
            input_digest=intent[1], attempt_id=attempt_id, metadata=metadata,
            epoch=epoch, anchor=anchor, permit=permit, intent=intent)
        return True

    def replay_committed_role_initialization_v2(
            self, *, namespace: NamespaceId, operation_id: str,
            request_digest: str, principal: OwnerPrincipalV1,
            actor_id: str, owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1):
        """Recover an already committed first role from its original graph atoms."""
        from .domains.d01 import (
            PersonaPlan, _persona_block, _value_rule,
        )
        from .graph_types import Owner
        from .runtime.role_resources import (
            read_role_resources, role_resources_key,
        )
        from .workbench_api.d01_onboarding import (
            VerifiedBudgetLease, VerifiedCreationResources, VerifiedModelCapability,
        )

        if (type(namespace) is not NamespaceId or type(principal) is not OwnerPrincipalV1
                or type(operation_id) is not str or not operation_id
                or type(request_digest) is not str):
            raise TypeError("committed role replay requires typed Owner identity")
        store = self.__store
        if not isinstance(store, ProductionGraphStore):
            raise UnavailableGuard("committed role graph is unavailable")
        with store._lock:
            row = store._db.execute(
                "SELECT receipt_json FROM graph_role_init_receipts_v1 "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if row is None:
                return None
            try:
                payload = json.loads(row[0])
                receipt = RoleInitializationReceiptV1(
                    **{**payload, "namespace": NamespaceId(**payload["namespace"])})
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("committed role receipt is invalid") from exc
            if (receipt.operation_id != operation_id
                    or receipt.request_digest != request_digest):
                raise AuthorityDenied("committed role request identity differs")
            plan_key = AtomKey(
                Owner("persona", *namespace.as_tuple),
                "d01.persona_plan.v1", receipt.plan_id)
            resource_key = role_resources_key(namespace, receipt.plan_id)
            plan_row = store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (plan_key.token,),
            ).fetchone()
            resource_row = store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (resource_key.token,),
            ).fetchone()
        if plan_row is None or resource_row is None:
            raise UnavailableGuard("committed role atoms are incomplete")
        try:
            plan_value = json.loads(plan_row[1])
            store._registry.validate(plan_key, plan_value)
            plan = PersonaPlan(
                plan_value["plan_id"], NamespaceId(**plan_value["namespace"]),
                plan_value["version"],
                tuple(_persona_block(item) for item in plan_value["blocks"]),
                tuple(_value_rule(item) for item in plan_value["values"]),
                plan_value["authored"],
            )
            selected = read_role_resources(
                GraphAtom(resource_key, resource_row[0], json.loads(resource_row[1]),
                          bool(resource_row[2])),
                namespace=namespace, plan_id=receipt.plan_id,
                head_id=receipt.head_id,
            )
            resources = VerifiedCreationResources(
                namespace, selected.blueprint_ref, selected.model_capability_ref,
                selected.budget_ref, plan.version, selected.blueprint_digest,
                plan.blocks[1:], plan.values,
                VerifiedModelCapability(
                    namespace, selected.model_capability_ref,
                    selected.model_resource_ref, selected.model_revision,
                    selected.model_digest),
                VerifiedBudgetLease(
                    namespace, selected.budget_ref, selected.budget_lease_ref,
                    selected.budget_version, selected.budget_digest),
            )
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("committed role graph atoms are invalid") from exc
        return self.commit_role_initialization_v2(
            namespace=namespace, operation_id=operation_id, plan=plan,
            principal=principal, request_digest=request_digest,
            resources=resources, actor_id=actor_id,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request)

    def read_current_creation_budget_v2(
            self, *, namespace: NamespaceId, budget_ref: str,
            actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
            expected: VerifiedBudgetLease | None = None) -> CreationBudgetProofV1:
        """Read an existing D11 lease/grant under current Owner and Authority fences.

        The ref is the durable lease ID. This read does not reserve budget or
        make a later D01 commit safe without its own lease-version check.
        """
        from .authority_service.contract import identifier
        from .runtime.issuers import IssuerAuthorityDenied
        from .workbench_api.d01_onboarding import VerifiedBudgetLease

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(namespace) is not NamespaceId
                or type(principal) is not OwnerPrincipalV1):
            raise UnavailableGuard("creation budget requires production v2 Owner")
        identifier(budget_ref, "budget_ref")
        identifier(actor_id, "actor_id")
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1
        if (type(owner_session_token) is not str or not owner_session_token
                or type(owner_session_request) is not OwnerSessionLoginRequestV1):
            raise UnavailableGuard("signed creation Owner session is unavailable")
        if expected is not None and type(expected) is not VerifiedBudgetLease:
            raise TypeError("expected creation budget must be a verified lease")
        grant_reader = getattr(self.__d11_issuer, "current_budget_grant", None)
        if not callable(grant_reader):
            raise UnavailableGuard("current signed D11 budget grant is unavailable")
        store = self.__store
        port = self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != 1:
            raise UnavailableGuard("creation budget graph identity differs")
        if (owner_session_request.principal != principal
                or owner_session_request.authority_id != target.authority_id
                or owner_session_request.authority_namespace
                != target.authority_namespace
                or owner_session_request.installation_id
                != port.installation_grant.installation_id
                or owner_session_request.audience != "owner"):
            raise UnavailableGuard("creation Owner session identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("creation budget Authority anchor differs")
        attempt_id = "creation-budget-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="read",
            operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace, 1, "read",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        authority = AuthorityContext(
            actor_id, "d12", "creation-budget-read", namespace, ("persona",),
            "workbench_user_action", ("owner",), "owner-grant-v1", 1)
        try:
            guard, owner = self._owner_binding_in_fence(
                authority, scope, principal, None,
                (owner_session_token, owner_session_request))
            if "workbench.create" not in owner.capabilities:
                raise AuthorityDenied("Owner grant lacks creation permission")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("creation budget read permit changed")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("creation budget graph stamp changed")
                db = store._db
                try:
                    lease = get_budget_lease(db, budget_ref)
                    grant = grant_reader(db, budget_ref)
                except (BudgetError, IssuerAuthorityDenied) as exc:
                    raise UnavailableGuard("current D11 budget lease/grant is absent") from exc
                if (lease.lease_id != budget_ref
                        or (lease.bot_id, lease.persona_id) != namespace.as_tuple
                        or lease.state != "active"
                        or grant.lease_id != lease.lease_id
                        or (grant.bot_id, grant.persona_id) != namespace.as_tuple
                        or grant.currency != lease.currency):
                    raise UnavailableGuard("D11 budget lease/grant differs or is inactive")
                budget = VerifiedBudgetLease(
                    namespace, budget_ref, lease.lease_id, lease.version,
                    "sha256:" + canonical_digest(asdict(lease)))
                if expected is not None and budget != expected:
                    raise UnavailableGuard("creation budget selection changed")
                result = CreationBudgetProofV1(
                    budget, grant.grant_id, grant.version,
                    "sha256:" + canonical_digest(asdict(grant)),
                    metadata.graph_revision, epoch.revision,
                    guard.authorization_head)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("creation budget read permit changed")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("creation budget graph stamp changed after read")
            return result
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_creation_budget_read",
                }))

    def commit_role_initialization_v2(self, *, namespace: NamespaceId,
                                      operation_id: str, plan, principal,
                                      request_digest: str, resources,
                                      actor_id: str, owner_session_token: str,
                                      owner_session_request: OwnerSessionLoginRequestV1):
        """Install one authored D01 plan and active head after committed Owner issue.

        This internal GraphWorker operation is not an Owner login endpoint. Its
        caller must separately authenticate the claimant; the graph worker
        checks the paired Authority's current guard under its exact write fence.
        """
        from .authority_service.contract import identifier
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .authority_service.v2_owner_contract import (
            OwnerAuthorizationGuardV1, OwnerGraphCommitProofV1, OwnerPrincipalV1,
            canonical_digest as owner_contract_digest,
        )
        from .domains.d01 import PersonaDomain, PersonaPlan, _activation_key
        from .runtime.budget import BudgetError
        from .runtime.role_resources import (
            ROLE_RESOURCES_TYPE, RoleRuntimeResourcesV1, role_resources_write,
        )
        from .runtime.restore_anchor import RestoreAnchor
        from .workbench_api.d01_onboarding import (
            VerifiedBudgetLease, VerifiedCreationResources, VerifiedModelCapability,
        )

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("role initialization requires production v2")
        if type(namespace) is not NamespaceId or type(plan) is not PersonaPlan:
            raise TypeError("role initialization requires a typed namespace and plan")
        if type(principal) is not OwnerPrincipalV1:
            raise TypeError("role initialization requires the paired Owner principal")
        identifier(operation_id, "operation_id")
        if (type(request_digest) is not str or len(request_digest) != 71
                or not request_digest.startswith("sha256:")
                or any(char not in "0123456789abcdef" for char in request_digest[7:])):
            raise ValueError("full role creation request digest is required")
        if plan.namespace != namespace or plan.authored is not True:
            raise AuthorityDenied("role plan is not an authored plan for this namespace")
        if (type(resources) is not VerifiedCreationResources
                or resources.namespace != namespace
                or type(resources.model) is not VerifiedModelCapability
                or resources.model.namespace != namespace
                or resources.model.capability_ref != resources.model_capability_ref
                or type(resources.budget) is not VerifiedBudgetLease
                or resources.budget.namespace != namespace
                or resources.budget.budget_ref != resources.budget_ref
                or resources.blueprint_version != plan.version
                or plan.blocks[1:] != resources.blocks
                or plan.values != resources.values):
            raise AuthorityDenied("verified creation resources differ from authored plan")
        port = self.__content_fence_v2
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(guard_reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        store = self.__store
        domain = PersonaDomain()
        plan_write = domain.plan_write(plan)
        resource_value = RoleRuntimeResourcesV1(
            namespace.bot_id, namespace.persona_id, operation_id,
            plan.plan_id, plan.head_id, resources.blueprint_ref,
            resources.blueprint_digest, resources.model.capability_ref,
            resources.model.resource_ref, resources.model.revision,
            resources.model.digest, resources.budget.budget_ref,
            resources.budget.lease_ref, resources.budget.version,
            resources.budget.digest,
        )
        resource_write = role_resources_write(resource_value)

        def check_creation_budget(db):
            try:
                lease = get_budget_lease(db, resources.budget.lease_ref)
            except BudgetError as exc:
                raise AuthorityDenied("verified creation budget lease is unavailable") from exc
            if (lease.lease_id != resources.budget.lease_ref
                    or (lease.bot_id, lease.persona_id) != namespace.as_tuple
                    or lease.state != "active"
                    or lease.version != resources.budget.version
                    or "sha256:" + canonical_digest(asdict(lease)) != resources.budget.digest):
                raise AuthorityDenied("verified creation budget lease changed")

        try:
            spec = store._registry.spec(ROLE_RESOURCES_TYPE)
            if spec.writer_domain != "d11":
                raise UnavailableGuard("D11 role resource graph type is unavailable")
            store._registry.validate(resource_write.key, resource_write.value)
        except (KeyError, ValueError, TypeError) as exc:
            raise UnavailableGuard("D11 role resource graph type is unavailable") from exc
        activation_key = _activation_key(namespace)
        grant_key = owner_grant_key(*namespace.as_tuple)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            grant_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (grant_key.token,),
            ).fetchone()
            proof_row = db.execute(
                "SELECT operation_id,request_digest,grant_id,grant_digest,"
                "graph_incarnation,graph_access_epoch,graph_epoch,"
                "graph_receipt_digest,proof_json "
                "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            access_row = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            intent = db.execute(
                "SELECT operation_id,input_digest,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch "
                "FROM graph_role_init_intents_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            saved = db.execute(
                "SELECT operation_id,input_digest,permit_json,receipt_json,"
                "pre_graph_revision,pre_graph_epoch,post_graph_revision,"
                "post_graph_epoch,finish_request_id,finish_request_digest "
                "FROM graph_role_init_receipts_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            rejection = db.execute(
                "SELECT operation_id,status,permit_json,graph_revision,"
                "graph_epoch,finish_request_id,finish_request_digest "
                "FROM graph_role_init_rejections_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
        if (grant_row is None or grant_row[0] != 1 or grant_row[2] != 1
                or proof_row is None or access_row != (1, 0)):
            raise UnavailableGuard("first Owner grant or access epoch is unavailable")
        grant = GraphAtom(grant_key, grant_row[0], json.loads(grant_row[1]), True)
        validate_owner_grant_v1(grant.value)
        proof = OwnerGraphCommitProofV1(
            namespace, proof_row[0], proof_row[1], proof_row[2], proof_row[3],
            proof_row[4], 1, proof_row[5], proof_row[6], proof_row[7])
        if (proof_row[8] != canonical_json(asdict(proof))
                or grant_row[1] != canonical_json(grant.value)
                or grant.value["grant_id"] != proof.grant_id
                or "sha256:" + canonical_digest(grant.value) != proof.grant_digest
                or grant.value["graph_incarnation"] != proof.graph_incarnation
                or grant.value["principal"] != asdict(principal)
                or grant.value["issue_operation_id"] != proof.operation_id
                or proof.graph_access_epoch != 1
                or metadata.requirements.graph_incarnation != proof.graph_incarnation):
            raise AuthorityDenied("role principal or grant differs from Owner issue")
        if ("workbench.create" not in grant.value["capabilities"]
                or "workbench_user_action" not in grant.value["purposes"]
                or "owner" not in grant.value["audiences"]):
            raise AuthorityDenied("Owner grant lacks role creation permission")
        target = metadata.requirements
        if (target.namespace != namespace or target.activation_generation != 1
                or target.authority_id != grant.value["authority_id"]
                or port.installation_grant.authority_id != target.authority_id
                or port.installation_grant.installation_id != grant.value["installation_id"]):
            raise UnavailableGuard("role recovery or installation identity differs")
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=target)
        input_digest = "sha256:" + canonical_digest({
            "schema": "sylanne3.graph.role_initialization.v1",
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "request_digest": request_digest,
            "plan": asdict(plan), "principal": asdict(principal),
            "resources": asdict(resource_value),
            "owner_proof": asdict(proof),
        })
        attempt_id = "role-write-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "input_digest": input_digest,
        })[:48]
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("role recovery anchor differs")
        identity = (operation_id, input_digest, attempt_id,
                    canonical_json(asdict(target)), canonical_json(asdict(anchor)))
        if intent is not None and intent[:5] != identity:
            if saved is None and rejection is None:
                self.reject_unresolvable_role_initialization_v2(
                    namespace=namespace, operation_id=operation_id,
                    request_digest=request_digest, principal=principal,
                    actor_id=actor_id, owner_session_token=owner_session_token,
                    owner_session_request=owner_session_request)
            raise AuthorityDenied("role initialization identity differs")
        if (saved is None) != (intent is None) and saved is not None:
            raise UnavailableGuard("role receipt lacks original intent")
        if rejection is not None:
            if intent is None or saved is not None:
                raise UnavailableGuard("rejected role has a business receipt")
            self._finish_rejected_owner_graph_write_v2(
                kind="role_init", namespace=namespace, operation_id=operation_id,
                input_digest=input_digest, attempt_id=attempt_id, metadata=metadata,
                epoch=epoch, anchor=anchor, rejection=rejection)
            raise UnavailableGuard("role initialization terminal rejected_no_commit")
        if saved is not None:
            try:
                payload = json.loads(saved[3])
                if type(payload) is not dict or type(payload.get("namespace")) is not dict:
                    raise ValueError("role receipt is not canonical")
                payload["namespace"] = NamespaceId(**payload["namespace"])
                receipt = RoleInitializationReceiptV1(**payload)
                permit = from_wire(json.loads(saved[2]))
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("durable role receipt is invalid") from exc
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "finish_role_initialization",
                "business_operation_id": operation_id,
                "input_digest": input_digest,
            })
            if (type(permit) is not FencePermitV2
                    or saved[0:2] != (operation_id, input_digest)
                    or saved[4:6] != intent[5:7]
                    or saved[6:8] != (receipt.graph_revision, receipt.graph_epoch)
                    or saved[6] != saved[4] + 1
                    or saved[8:10] != ("finish:" + attempt_id, finish_digest)
                    or saved[3] != canonical_json(asdict(receipt))
                    or receipt.namespace != namespace
                    or receipt.operation_id != operation_id
                    or receipt.request_digest != request_digest
                    or receipt.input_digest != input_digest
                    or receipt.plan_id != plan.plan_id
                    or receipt.head_id != plan.head_id
                    or receipt.owner_grant_id != proof.grant_id
                    or receipt.owner_grant_revision != 1
                    or receipt.owner_authorization_head != owner_contract_digest(proof)
                    or receipt.graph_incarnation != proof.graph_incarnation
                    or receipt.fence_attempt_id != attempt_id
                    or receipt.finish_request_id != saved[8]
                    or receipt.finish_request_digest != saved[9]
                    or permit.operation_id != attempt_id or permit.operation != "write"
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.authority_id != target.authority_id
                    or permit.namespace != target.authority_namespace
                    or permit.generation != 1 or permit.pinned_anchor != anchor):
                raise UnavailableGuard("durable role initialization receipt differs")
            with store._lock:
                plan_row = store._db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (plan_write.key.token,),
                ).fetchone()
                activation_row = store._db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (activation_key.token,),
                ).fetchone()
                resource_row = store._db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (resource_write.key.token,),
                ).fetchone()
                committed_guard = OwnerAuthorizationGuardV1(
                    target.authority_id, grant.value["installation_id"], namespace,
                    1, receipt.owner_authorization_head, 0, 0)
                expected_activation = domain.activation_write(
                    plan, grant, committed_guard)
                if (plan_row != (1, canonical_json(plan_write.value), 1)
                        or resource_row != (1, canonical_json(resource_write.value), 1)
                        or activation_row != (
                            1, canonical_json(expected_activation.value), 1)):
                    raise UnavailableGuard("durable role graph atoms differ")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("role Authority fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[6:8]:
                    raise UnavailableGuard("active role fence lost business stamp")
                scope = FenceScope(
                    namespace, target.authority_namespace, 1, "write", attempt_id,
                    permit, anchor, NamespaceEpoch(*namespace.as_tuple, intent[6]),
                    intent[5])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("role write permit changed")
                port.finish_fence(scope, request_id=saved[8],
                                  request_digest=saved[9])
            elif (metadata.graph_revision < saved[6]
                  or epoch.revision < saved[7]):
                raise UnavailableGuard("finished role lost business stamp")
            self._read_current_owner_session_v2(
                namespace=namespace, principal=principal, actor_id=actor_id,
                token=owner_session_token, request=owner_session_request,
                capability="workbench.create")
            return receipt
        if (intent is not None and
                (metadata.graph_revision, epoch.revision) != intent[5:7]):
            raise UnavailableGuard("uncommitted role graph stamp changed")
        try:
            with store._lock:
                check_creation_budget(store._db)
        except AuthorityDenied:
            if intent is None:
                raise
            if (metadata.graph_revision, epoch.revision) != intent[5:7]:
                raise UnavailableGuard("uncommitted role graph stamp changed")
            with store._lock:
                db = store._db
                if (db.execute(
                        "SELECT 1 FROM graph_role_init_receipts_v1 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                ).fetchone() is not None or db.execute(
                        "SELECT 1 FROM graph_atoms WHERE token IN (?,?,?) LIMIT 1",
                        (plan_write.key.token, activation_key.token,
                         resource_write.key.token),
                ).fetchone() is not None):
                    raise UnavailableGuard("role write outcome is not proven absent")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if (type(observed) is not FencePermitV2 or state != "active"
                    or observed.operation_id != attempt_id
                    or observed.operation != "write"
                    or observed.holder != self.__holder
                    or observed.subject != port.installation_grant.subject
                    or observed.authority_id != target.authority_id
                    or observed.namespace != target.authority_namespace
                    or observed.generation != 1 or observed.pinned_anchor != anchor):
                raise UnavailableGuard("original role fence cannot prove no commit")
            self._reject_owner_graph_write_v2(
                kind="role_init", namespace=namespace, operation_id=operation_id,
                input_digest=input_digest, attempt_id=attempt_id, metadata=metadata,
                epoch=epoch, anchor=anchor, permit=observed, intent=intent)
            raise
        if (metadata.graph_revision != 1 or epoch.revision != proof.graph_epoch
                or proof.graph_epoch != 1):
            raise UnavailableGuard("role initialization requires first Owner graph head")
        with store._lock:
            if (store._db.execute(
                    "SELECT 1 FROM graph_atoms WHERE token IN (?,?,?) LIMIT 1",
                    (plan_write.key.token, activation_key.token,
                     resource_write.key.token)).fetchone() is not None):
                raise UnavailableGuard("initial role atoms already exist")
        if intent is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("role graph stamp changed before intent")
                    db.execute(
                        "INSERT INTO graph_role_init_intents_v1"
                        "(bot,persona,operation_id,input_digest,fence_attempt_id,"
                        "requirements_json,anchor_json,graph_revision,graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + identity + (
                            metadata.graph_revision, epoch.revision),
                    )
                    db.execute(
                        "INSERT INTO graph_role_init_request_proofs_v1"
                        "(bot,persona,operation_id,request_digest,input_digest) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + (operation_id, request_digest, input_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            intent = identity + (metadata.graph_revision, epoch.revision)
        pinned_anchor = RestoreAnchor(**json.loads(intent[4]))
        if pinned_anchor != anchor:
            raise UnavailableGuard("role original fence anchor changed")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="write",
            operation_id=attempt_id, expected_anchor=pinned_anchor,
            retain_on_unknown=True)
        if (type(permit) is not FencePermitV2 or permit.operation_id != attempt_id
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != 1 or permit.pinned_anchor != anchor):
            raise UnavailableGuard("role write permit differs")
        scope = FenceScope(namespace, target.authority_namespace, 1, "write",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        try:
            guarded = guard_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit, owner_actor_id=actor_id,
                owner_session_token=owner_session_token,
                owner_session_request=owner_session_request)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("current Owner guard response is unavailable")
            guard = guarded[0]
            if (guard.authority_id != target.authority_id
                    or guard.installation_id != grant.value["installation_id"]
                    or guard.namespace != namespace
                    or guard.authorization_revision != 1
                    or guard.authorization_head != owner_contract_digest(proof)
                    or guard.pending_revoke_operation_id is not None
                    or guard.minimum_revocation_revision != 0
                    or guard.minimum_revocation_epoch != 0):
                raise AuthorityDenied("current Owner authorization differs from graph")
        except Exception:
            self._reject_owner_graph_write_v2(
                kind="role_init", namespace=namespace, operation_id=operation_id,
                input_digest=input_digest, attempt_id=attempt_id, metadata=metadata,
                epoch=epoch, anchor=anchor, permit=permit, intent=intent)
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("role write permit changed")
        class _CreationBudgetChangedNoCommit(Exception):
            pass

        budget_denial = None
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("role graph stamp changed")
                if db.execute(
                    "SELECT operation_id,input_digest,fence_attempt_id,"
                    "requirements_json,anchor_json,graph_revision,graph_epoch "
                    "FROM graph_role_init_intents_v1 WHERE bot=? AND persona=?",
                    namespace.as_tuple,
                ).fetchone() != intent:
                    raise UnavailableGuard("role durable intent changed")
                current_grant = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (grant_key.token,),
                ).fetchone()
                current_access = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if current_grant != grant_row or current_access != (1, 0):
                    raise StaleRead("Owner grant changed before role initialization")
                try:
                    check_creation_budget(db)
                except AuthorityDenied as exc:
                    budget_denial = exc
                    raise _CreationBudgetChangedNoCommit from exc
                activation_write = domain.activation_write(plan, grant, guard)
                candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, "d01-role-initialization"),
                          operation_id, 0, "role_initialized", {
                              "input_digest": input_digest,
                              "owner_grant_id": proof.grant_id,
                              "authorization_head": guard.authorization_head,
                          }),
                    (GraphVersion(grant_key, 1), GraphVersion(plan_write.key, 0),
                     GraphVersion(activation_key, 0),
                     GraphVersion(resource_write.key, 0)),
                    (plan_write, activation_write, resource_write), (epoch,),
                )
                graph_receipt = GraphStore._graph_commit_in_transaction(
                    store, candidate, _capability=self.__graph_capability)
                if (graph_receipt.status != "committed"
                        or graph_receipt.epoch.revision != epoch.revision + 1
                        or graph_receipt.revisions != (
                            GraphVersion(plan_write.key, 1),
                            GraphVersion(activation_key, 1),
                            GraphVersion(resource_write.key, 1))):
                    raise UnavailableGuard("role graph transaction did not commit all atoms")
                store.cas_graph_recovery_metadata(
                    metadata, target, _capability=self.__graph_capability)
                finish_id = "finish:" + attempt_id
                finish_digest = "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_role_initialization",
                    "business_operation_id": operation_id,
                    "input_digest": input_digest,
                })
                receipt = RoleInitializationReceiptV1(
                    namespace, operation_id, request_digest, input_digest, plan.plan_id,
                    plan.head_id, proof.grant_id, 1, guard.authorization_head,
                    proof.graph_incarnation, metadata.graph_revision + 1,
                    graph_receipt.epoch.revision, attempt_id,
                    finish_id, finish_digest,
                )
                db.execute(
                    "INSERT INTO graph_role_init_receipts_v1"
                    "(bot,persona,operation_id,input_digest,permit_json,receipt_json,"
                    "pre_graph_revision,pre_graph_epoch,post_graph_revision,"
                    "post_graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        operation_id, input_digest, canonical_json(to_wire(permit)),
                        canonical_json(asdict(receipt)), metadata.graph_revision,
                        epoch.revision, receipt.graph_revision,
                        receipt.graph_epoch, finish_id, finish_digest),
                )
                db.execute("COMMIT")
            except _CreationBudgetChangedNoCommit:
                if db.in_transaction:
                    db.execute("ROLLBACK")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        if budget_denial is not None:
            self._reject_owner_graph_write_v2(
                kind="role_init", namespace=namespace, operation_id=operation_id,
                input_digest=input_digest, attempt_id=attempt_id, metadata=metadata,
                epoch=epoch, anchor=anchor, permit=permit, intent=intent)
            raise budget_denial
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("committed role write permit changed")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.graph_revision != receipt.graph_revision
                    or current_epoch.revision != receipt.graph_epoch):
                raise UnavailableGuard("committed role graph stamp changed")
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return receipt

    def _scene_binding_state_locked(self, namespace, guard, prior=None):
        """Read the complete current D01 head and D03 binding query at one epoch."""
        from .domains.d01 import PersonaDomain, _activation_key
        from .domains.d03 import RoleBinding
        from .graph_types import GraphSnapshot
        from .runtime_contracts import QueryEpoch

        store = self.__store
        db = store._db
        epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        activation_key = _activation_key(namespace)
        grant_key = owner_grant_key(*namespace.as_tuple)
        activation_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (activation_key.token,),
        ).fetchone()
        if activation_row is None or activation_row[2] != 1:
            raise UnavailableGuard("active D01 role head is absent")
        activation = json.loads(activation_row[1])
        if type(activation) is not dict or type(activation.get("plan_id")) is not str:
            raise UnavailableGuard("active D01 role head is invalid")
        from .graph_types import AtomKey, Owner
        plan_key = AtomKey(Owner("persona", *namespace.as_tuple),
                           "d01.persona_plan.v1", activation["plan_id"])
        atoms = []
        for key in (activation_key, plan_key, grant_key):
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("active role graph atoms are incomplete")
            atoms.append(GraphAtom(key, row[0], json.loads(row[1]), bool(row[2])))
        try:
            role = PersonaDomain.resolve_active_role(
                GraphSnapshot(tuple(atoms), (epoch,)), namespace=namespace,
                current_guard=guard)
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("active role differs from Owner guard") from exc
        saved_role = db.execute(
            "SELECT receipt_json FROM graph_role_init_receipts_v1 "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if saved_role is None:
            raise UnavailableGuard("D01 role has no durable initialization receipt")
        data = json.loads(saved_role[0])
        if (type(data) is not dict or data.get("head_id") != role.head_id
                or data.get("owner_grant_id") != atoms[2].value["grant_id"]
                or data.get("owner_authorization_head") != guard.authorization_head):
            raise UnavailableGuard("D01 initialization receipt differs from active role")
        rows = db.execute(
            "SELECT token,revision,value FROM graph_atoms "
            "WHERE bot=? AND persona=? AND type_name='d03.role_binding' "
            "AND valid=1 ORDER BY token", namespace.as_tuple,
        ).fetchall()
        versions = []
        bindings = []
        for token, revision, encoded in rows:
            key = AtomKey.from_token(token)
            value = json.loads(encoded)
            try:
                binding = RoleBinding(**{
                    **value, "norm_refs": tuple(value["norm_refs"]),
                    "source_refs": tuple(value["source_refs"]),
                })
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("current D03 binding is invalid") from exc
            if (key.name != binding.role_binding_id
                    or revision != binding.binding_version
                    or (key.owner.kind == "scene"
                        and key.owner.subject != binding.scene_ref)):
                raise UnavailableGuard("current D03 binding identity differs")
            versions.append(GraphVersion(key, revision))
            bindings.append(binding)
        query = QueryEpoch(namespace, "d03.role_binding", epoch.revision)
        if (prior is not None and (prior.query_epoch != query
                or len(prior.read_versions) != len(versions)
                or set(prior.read_versions) != set(versions))):
            raise StaleRead("D03 negative query versions or epoch changed")
        if prior is None:
            return role, tuple(bindings), epoch, tuple(versions)
        return role, tuple(bindings), epoch

    def _check_owner_session_v2(self, *, namespace, principal, actor_id,
                                token, request, target):
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1

        port = self.__content_fence_v2
        if (type(actor_id) is not str or not actor_id
                or type(token) is not str or not token
                or type(request) is not OwnerSessionLoginRequestV1
                or request.principal != principal
                or request.authority_id != target.authority_id
                or request.authority_namespace != target.authority_namespace
                or request.installation_id
                != port.installation_grant.installation_id
                or request.audience != "owner"
                or self._current_owner_principal(actor_id, namespace) != principal):
            raise UnavailableGuard("current signed Owner session differs")

    def _read_current_owner_session_v2(self, *, namespace, principal, actor_id,
                                       token, request, capability):
        """Recheck a current signed Owner session under a new read fence."""
        port = self.__content_fence_v2
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=token, request=request, target=target)
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("scene replay Authority anchor differs")
        attempt_id = "owner-session-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="read",
            operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace, 1, "read",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        authority = AuthorityContext(
            actor_id, "d12", "owner-session-read", namespace,
            ("persona",), "workbench_user_action", ("owner",),
            "owner-grant-v1", 1)
        try:
            _, owner = self._owner_binding_in_fence(
                authority, scope, principal, None, (token, request))
            if capability not in owner.capabilities:
                raise AuthorityDenied("Owner grant lacks requested permission")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("scene replay read permit changed")
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_owner_session_read",
                }))

    def replay_committed_scene_binding_v2(
            self, *, namespace: NamespaceId, operation_id: str,
            request_digest: str, principal: OwnerPrincipalV1,
            actor_id: str, owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1):
        """Read a completed Owner scene operation from its original frozen input."""
        from .domains.d03 import RoleBindingRequest, RoleBindingResolution
        from .host.current_scene import CurrentHostScene
        from .runtime_contracts import QueryEpoch

        if type(namespace) is not NamespaceId or type(principal) is not OwnerPrincipalV1:
            raise TypeError("typed scene replay identity is required")
        with self.__store._lock:
            db = self.__store._db
            saved = db.execute(
                "SELECT 1 FROM graph_scene_binding_receipts_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if saved is None:
                return None
            proof = db.execute(
                "SELECT request_digest,principal_json,frozen_json "
                "FROM graph_scene_binding_request_proofs_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        if proof is None:
            raise UnavailableGuard("committed scene lacks original request proof; HOLD")
        if (proof[0] != request_digest
                or proof[1] != canonical_json(asdict(principal))):
            raise AuthorityDenied("scene operation request or principal differs")
        try:
            frozen = json.loads(proof[2])
            scene_data = frozen["scene"]
            scene = CurrentHostScene(
                NamespaceId(**scene_data["namespace"]),
                scene_data["platform_ref"], scene_data["conversation_ref"],
                scene_data["visibility"], scene_data["scene_ref"],
            )
            prior_data = frozen["prior"]
            query = prior_data["query_epoch"]
            versions = tuple(GraphVersion(
                AtomKey(Owner(**item["key"]["owner"]),
                        item["key"]["type_name"], item["key"]["name"]),
                item["revision"],
            ) for item in prior_data["read_versions"])
            prior = RoleBindingResolution(
                prior_data["status"], tuple(prior_data["matched_bindings"]),
                tuple(prior_data["applicable_norm_refs"]),
                tuple(prior_data["missing_items"]), versions,
                QueryEpoch(NamespaceId(**query["namespace"]),
                           query["scope_ref"], query["revision"]),
                prior_data["valid_until"],
                RoleBindingRequest(**prior_data["request"]),
            )
            if (proof[2] != canonical_json(frozen)
                    or frozen["prior_digest"] != canonical_digest(asdict(prior))):
                raise ValueError("frozen prior digest differs")
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("committed scene frozen input is invalid") from exc
        return self.commit_scene_binding_v2(
            namespace=namespace, operation_id=operation_id, scene=scene,
            prior=prior, principal=principal, actor_id=actor_id,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request,
            request_digest=request_digest,
        )

    def commit_scene_binding_v2(self, *, namespace: NamespaceId,
                                operation_id: str, scene, prior, principal,
                                actor_id: str, request_digest: str,
                                owner_session_token: str,
                                owner_session_request: OwnerSessionLoginRequestV1):
        """Commit one Owner-configured scene and two D06 provenance sources."""
        from .authority_service.contract import identifier
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .authority_service.v2_owner_contract import (
            OwnerAuthorizationGuardV1, OwnerGraphCommitProofV1, OwnerPrincipalV1,
            canonical_digest as owner_contract_digest,
        )
        from .domains.d03 import ContextProvider, RoleBinding, RoleBindingResolution
        from .host.current_scene import CurrentHostScene
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.restore_anchor import RestoreAnchor
        from .runtime_contracts import QueryEpoch
        from .workbench_api.scene_binding_evidence import build_scene_binding_evidence

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("scene binding requires production v2")
        if (type(namespace) is not NamespaceId or type(scene) is not CurrentHostScene
                or type(prior) is not RoleBindingResolution
                or type(principal) is not OwnerPrincipalV1):
            raise TypeError("scene binding requires typed scene, D03 and Owner inputs")
        identifier(operation_id, "operation_id")
        identifier(actor_id, "actor_id")
        if (type(request_digest) is not str or len(request_digest) != 71
                or not request_digest.startswith("sha256:")
                or any(char not in "0123456789abcdef" for char in request_digest[7:])):
            raise ValueError("full scene binding request digest is required")
        registration = self.__providers.get("d03")
        if registration is None or type(registration[0]) is not ContextProvider:
            raise UnavailableGuard("trusted D03 scene provider is unavailable")
        provider = registration[0]
        if (scene.namespace != namespace or prior.request is None
                or not prior.request.scope_complete
                or prior.status != "no_applicable_binding"
                or prior.matched_bindings or prior.missing_items
                or prior.query_epoch is None
                or prior.request.requested_action_kind != "bind_scene"
                or prior.request.purpose != "workbench_user_action"
                or scene.scene_ref != prior.request.scene_ref):
            raise AuthorityDenied("scene request is not a complete first binding")
        port = self.__content_fence_v2
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(guard_reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            grant_key = owner_grant_key(*namespace.as_tuple)
            grant_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (grant_key.token,),
            ).fetchone()
            proof_row = db.execute(
                "SELECT operation_id,request_digest,grant_id,grant_digest,"
                "graph_incarnation,graph_access_epoch,graph_epoch,"
                "graph_receipt_digest,proof_json "
                "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            access_row = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            intent = db.execute(
                "SELECT operation_id,input_digest,binding_id,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch "
                "FROM graph_scene_binding_intents_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            request_proof = db.execute(
                "SELECT request_digest,principal_json,frozen_json,input_digest "
                "FROM graph_scene_binding_request_proofs_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            saved = db.execute(
                "SELECT input_digest,permit_json,receipt_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_scene_binding_receipts_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            rejection = db.execute(
                "SELECT operation_id,status,permit_json,graph_revision,"
                "graph_epoch,finish_request_id,finish_request_digest "
                "FROM graph_scene_binding_rejections_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
        if (grant_row is None or grant_row[0] != 1 or grant_row[2] != 1
                or proof_row is None or access_row != (1, 0)):
            raise UnavailableGuard("current first Owner grant is unavailable")
        grant = json.loads(grant_row[1])
        validate_owner_grant_v1(grant)
        proof = OwnerGraphCommitProofV1(
            namespace, proof_row[0], proof_row[1], proof_row[2], proof_row[3],
            proof_row[4], 1, proof_row[5], proof_row[6], proof_row[7])
        target = metadata.requirements
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=target)
        if (proof_row[8] != canonical_json(asdict(proof))
                or grant_row[1] != canonical_json(grant)
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["principal"] != asdict(principal)
                or grant["grant_id"] != proof.grant_id
                or grant["graph_incarnation"] != proof.graph_incarnation
                or proof.graph_access_epoch != 1
                or target.namespace != namespace
                or target.graph_incarnation != proof.graph_incarnation
                or target.activation_generation != 1
                or target.authority_id != grant["authority_id"]
                or port.installation_grant.installation_id != grant["installation_id"]):
            raise AuthorityDenied("scene principal or Owner grant differs")
        if ("workbench.bind_scene" not in grant["capabilities"]
                or "workbench_user_action" not in grant["purposes"]
                or "owner" not in grant["audiences"]):
            raise AuthorityDenied("Owner grant lacks scene binding permission")
        if intent is not None and request_proof is None:
            raise UnavailableGuard("legacy scene intent lacks original request proof; HOLD")
        if request_proof is not None:
            if (request_proof[0] != request_digest
                    or request_proof[1] != canonical_json(asdict(principal))):
                raise AuthorityDenied("scene operation request or principal differs")
            try:
                frozen = json.loads(request_proof[2])
                original_scene = CurrentHostScene(**{
                    **frozen["scene"], "namespace": NamespaceId(**frozen["scene"]["namespace"]),
                })
                observed_at = frozen["observed_at"]
                original_actor = frozen["actor_id"]
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("scene frozen request proof is invalid") from exc
            if (request_proof[2] != canonical_json(frozen)
                    or original_actor != actor_id
                    or original_scene.namespace != namespace
                    or original_scene.scene_ref != scene.scene_ref):
                raise AuthorityDenied("scene frozen request identity differs")
            pending_input_changed = (saved is None and (
                original_scene != scene
                or frozen["prior_digest"] != canonical_digest(asdict(prior))))
        else:
            verifier = getattr(self.__scene_identity_port, "verify", None)
            if not callable(verifier) or verifier(namespace, scene.scene_ref,
                                                 scene.visibility) != scene:
                raise UnavailableGuard("current scene identity is unavailable; HOLD")
            if type(self.__scene_clock_policy) is not AdminIngressClockPolicy:
                raise UnavailableGuard("paired scene clock policy is unavailable; HOLD")
            try:
                reading = port.read_ingress_clock(self.__scene_clock_policy)
                observed_at = reading.utc_upper_bound_seconds
            except Exception as exc:
                raise UnavailableGuard("paired scene clock is unavailable; HOLD") from exc
            original_scene = scene
            original_actor = actor_id
            frozen = {
                "scene": asdict(scene), "observed_at": observed_at,
                "actor_id": actor_id, "prior_digest": canonical_digest(asdict(prior)),
                "prior": json.loads(canonical_serialize(asdict(prior))),
                "at_time": prior.request.at_time,
            }
            pending_input_changed = False
        evidence = build_scene_binding_evidence(
            namespace=namespace, scene=original_scene, owner_actor=original_actor,
            operation_id=operation_id, request_digest=request_digest,
            authorization_head=owner_contract_digest(proof),
            observed_at=observed_at,
        )
        source_writes = tuple(
            GraphWrite(key, value) for source in (
                evidence.owner_config, evidence.host_identity)
            for key, value in ((source.source_key, source.source_value),
                               (source.access_key, source.access_value))
        )
        binding = RoleBinding(
            "binding:" + canonical_digest({"operation_id": operation_id,
                                            "scene_ref": original_scene.scene_ref})[:48],
            f"persona:{namespace.persona_id}", "scene_participant", None, None,
            original_scene.scene_ref, "scene", original_scene.visibility, (),
            frozen["at_time"], None, 0,
            (evidence.owner_config.source_key.token,
             evidence.host_identity.source_key.token), 1, "active",
        )
        write_key = AtomKey(Owner("scene", *namespace.as_tuple, binding.scene_ref),
                            "d03.role_binding", binding.role_binding_id)
        value = asdict(binding)
        value["norm_refs"] = list(binding.norm_refs)
        value["source_refs"] = list(binding.source_refs)
        input_digest = "sha256:" + canonical_digest({
            "schema": "sylanne3.graph.scene_binding.v1",
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "request_digest": request_digest, "frozen": frozen,
            "principal": asdict(principal), "owner_proof": asdict(proof),
        })
        if request_proof is not None and request_proof[3] != input_digest:
            raise UnavailableGuard("scene frozen input digest differs")
        attempt_id = "scene-write-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "input_digest": input_digest,
        })[:48]
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("scene recovery anchor differs")
        identity = (operation_id, input_digest, binding.role_binding_id,
                    attempt_id, canonical_json(asdict(target)),
                    canonical_json(asdict(anchor)))
        if intent is not None and intent[:6] != identity:
            raise AuthorityDenied("scene binding operation replay differs")
        if rejection is not None:
            if intent is None or saved is not None:
                raise UnavailableGuard("rejected scene has a business receipt")
            self._finish_rejected_owner_graph_write_v2(
                kind="scene_binding", namespace=namespace,
                operation_id=operation_id, input_digest=input_digest,
                attempt_id=attempt_id, metadata=metadata, epoch=epoch,
                anchor=anchor, rejection=rejection)
            raise UnavailableGuard("scene binding terminal rejected_no_commit")
        if saved is not None:
            if intent is None:
                raise UnavailableGuard("scene receipt lacks durable intent")
            try:
                payload = json.loads(saved[2])
                if type(payload) is not dict or type(payload.get("namespace")) is not dict:
                    raise ValueError("scene receipt is not canonical")
                payload["namespace"] = NamespaceId(**payload["namespace"])
                receipt = SceneBindingReceiptV1(**payload)
                permit = from_wire(json.loads(saved[1]))
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("durable scene receipt is invalid") from exc
            finish_id = "finish:" + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "finish_scene_binding",
                "business_operation_id": operation_id,
                "input_digest": input_digest,
            })
            if (type(permit) is not FencePermitV2
                    or saved[0] != input_digest
                    or saved[2] != canonical_json(asdict(receipt))
                    or saved[3:5] != intent[6:8]
                    or saved[5:7] != (receipt.graph_revision, receipt.graph_epoch)
                    or saved[5] != saved[3] + 1
                    or saved[7:9] != (finish_id, finish_digest)
                    or receipt.namespace != namespace
                    or receipt.operation_id != operation_id
                    or receipt.request_digest != request_digest
                    or receipt.input_digest != input_digest
                    or receipt.scene_ref != binding.scene_ref
                    or receipt.binding_id != binding.role_binding_id
                    or receipt.owner_grant_id != proof.grant_id
                    or receipt.owner_authorization_head != owner_contract_digest(proof)
                    or receipt.graph_incarnation != proof.graph_incarnation
                    or receipt.fence_attempt_id != attempt_id
                    or receipt.finish_request_id != finish_id
                    or receipt.finish_request_digest != finish_digest
                    or permit.operation_id != attempt_id or permit.operation != "write"
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.authority_id != target.authority_id
                    or permit.namespace != target.authority_namespace
                    or permit.generation != 1 or permit.pinned_anchor != anchor):
                raise UnavailableGuard("durable scene receipt differs")
            with store._lock:
                for key, expected_value in (
                        *((item.key, item.value) for item in source_writes),
                        (write_key, value)):
                    atom = store._db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    if atom != (1, canonical_json(expected_value), 1):
                        raise UnavailableGuard("durable scene source or binding atom differs")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("scene Authority fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[5:7]:
                    raise UnavailableGuard("active scene fence lost business stamp")
                scope = FenceScope(
                    namespace, target.authority_namespace, 1, "write", attempt_id,
                    permit, anchor, NamespaceEpoch(*namespace.as_tuple, intent[7]),
                    intent[6])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("scene write permit changed")
                port.finish_fence(scope, request_id=finish_id,
                                  request_digest=finish_digest)
            elif (metadata.graph_revision < saved[5]
                  or epoch.revision < saved[6]):
                raise UnavailableGuard("finished scene lost business stamp")
            self._read_current_owner_session_v2(
                namespace=namespace, principal=principal, actor_id=actor_id,
                token=owner_session_token, request=owner_session_request,
                capability="workbench.bind_scene")
            return receipt
        # This command only creates the first binding for a scene. D03's
        # no_applicable_binding can also describe a revoked or out-of-window
        # valid atom; accepting a second one would make the scene unreadable.
        with store._lock:
            if store._db.execute(
                    "SELECT 1 FROM graph_atoms WHERE bot=? AND persona=? "
                    "AND owner_kind='scene' AND subject=? "
                    "AND type_name='d03.role_binding' AND valid=1 LIMIT 1",
                    namespace.as_tuple + (binding.scene_ref,),
            ).fetchone() is not None:
                raise AuthorityDenied("scene already has a valid D03 binding")
        if prior.query_epoch != QueryEpoch(namespace, "d03.role_binding", epoch.revision):
            raise StaleRead("D03 negative query versions or epoch changed")
        if intent is not None and (metadata.graph_revision, epoch.revision) != intent[6:8]:
            raise UnavailableGuard("uncommitted scene graph stamp changed")
        if intent is not None:
            with store._lock:
                if any(store._db.execute(
                    "SELECT 1 FROM graph_atoms WHERE token=?", (key.token,),
                ).fetchone() is not None for key in (
                    *(item.key for item in source_writes), write_key,
                )):
                    raise UnavailableGuard("pending scene has a business atom; HOLD")
        if intent is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("scene graph stamp changed before intent")
                    db.execute(
                        "INSERT INTO graph_scene_binding_intents_v1"
                        "(bot,persona,operation_id,input_digest,binding_id,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch) VALUES(?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + identity + (
                            metadata.graph_revision, epoch.revision),
                    )
                    db.execute(
                        "INSERT INTO graph_scene_binding_request_proofs_v1"
                        "(bot,persona,operation_id,request_digest,principal_json,"
                        "frozen_json,input_digest) VALUES(?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, request_digest,
                            canonical_json(asdict(principal)),
                            canonical_json(frozen), input_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise
            intent = identity + (metadata.graph_revision, epoch.revision)
        pinned_anchor = RestoreAnchor(**json.loads(intent[5]))
        if pinned_anchor != anchor:
            raise UnavailableGuard("scene original fence anchor changed")
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="write",
            operation_id=attempt_id, expected_anchor=pinned_anchor,
            retain_on_unknown=True)
        if (type(permit) is not FencePermitV2 or permit.operation_id != attempt_id
                or permit.operation != "write" or permit.holder != self.__holder
                or permit.subject != port.installation_grant.subject
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != 1 or permit.pinned_anchor != anchor):
            raise UnavailableGuard("scene write permit differs")
        scope = FenceScope(namespace, target.authority_namespace, 1, "write",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        try:
            if pending_input_changed:
                raise UnavailableGuard("pending scene proof differs from original")
            verifier = getattr(self.__scene_identity_port, "verify", None)
            if (not callable(verifier)
                    or verifier(namespace, original_scene.scene_ref,
                                original_scene.visibility) != original_scene):
                raise UnavailableGuard("current scene identity changed")
            guarded = guard_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit, owner_actor_id=actor_id,
                owner_session_token=owner_session_token,
                owner_session_request=owner_session_request)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("current scene Owner guard is unavailable")
            guard = guarded[0]
            if (guard.authority_id != target.authority_id
                    or guard.installation_id != grant["installation_id"]
                    or guard.namespace != namespace
                    or guard.authorization_revision != 1
                    or guard.authorization_head != owner_contract_digest(proof)
                    or guard.pending_revoke_operation_id is not None
                    or guard.minimum_revocation_revision != 0
                    or guard.minimum_revocation_epoch != 0):
                raise AuthorityDenied("scene Owner authorization changed")
        except Exception:
            self._reject_owner_graph_write_v2(
                kind="scene_binding", namespace=namespace,
                operation_id=operation_id, input_digest=input_digest,
                attempt_id=attempt_id, metadata=metadata, epoch=epoch,
                anchor=anchor, permit=permit, intent=intent)
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("scene write permit changed")
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("scene graph stamp changed")
                if db.execute(
                    "SELECT operation_id,input_digest,binding_id,fence_attempt_id,"
                    "requirements_json,anchor_json,graph_revision,graph_epoch "
                    "FROM graph_scene_binding_intents_v1 WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone() != intent:
                    raise UnavailableGuard("scene durable intent changed")
                role, bindings, current_epoch = self._scene_binding_state_locked(
                    namespace, guard, prior)
                if current_epoch != epoch:
                    raise StaleRead("scene negative query epoch changed")
                if db.execute(
                        "SELECT 1 FROM graph_atoms WHERE bot=? AND persona=? "
                        "AND owner_kind='scene' AND subject=? "
                        "AND type_name='d03.role_binding' AND valid=1 LIMIT 1",
                        namespace.as_tuple + (binding.scene_ref,),
                ).fetchone() is not None:
                    raise AuthorityDenied("scene already has a valid D03 binding")
                observed_negative = provider.resolve_role_binding(
                    prior.request, bindings)
                if observed_negative.status != "no_applicable_binding":
                    raise AuthorityDenied("scene has an applicable binding")
                write = provider.build_owner_scene_binding_write(
                    binding, role, guard, prior,
                    owner_config_source_key=evidence.owner_config.source_key,
                    host_identity_source_key=evidence.host_identity.source_key,
                )
                if (write.key != write_key or write.value != value
                        or write.key.type_name != "d03.role_binding"):
                    raise AuthorityDenied("D03 Owner binding write differs")
                expected_versions = (
                    set(role.read_versions) | set(prior.read_versions)
                    | {GraphVersion(write.key, 0)}
                    | {GraphVersion(item.key, 0) for item in source_writes}
                )
                if prior.query_epoch != QueryEpoch(
                        namespace, "d03.role_binding", epoch.revision):
                    raise StaleRead("D03 negative query changed")
                candidate = GraphCandidate(
                    Event(Scope(*namespace.as_tuple, "d03-scene-binding"),
                          operation_id, 0, "scene_binding", {
                              "request_digest": request_digest,
                              "input_digest": input_digest,
                              "role_head_id": role.head_id,
                          }),
                    tuple(sorted(expected_versions, key=lambda item: item.key.token)),
                    source_writes + (write,),
                    (epoch,),
                )
                graph_receipt = GraphStore._graph_commit_in_transaction(
                    store, candidate, _capability=self.__graph_capability)
                if (graph_receipt.status != "committed"
                        or set(graph_receipt.revisions) != {
                            GraphVersion(item.key, 1) for item in source_writes + (write,)
                        }
                        or graph_receipt.epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("D03 scene binding graph commit differed")
                store.cas_graph_recovery_metadata(
                    metadata, target, _capability=self.__graph_capability)
                finish_id = "finish:" + attempt_id
                finish_digest = "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_scene_binding",
                    "business_operation_id": operation_id,
                    "input_digest": input_digest,
                })
                receipt = SceneBindingReceiptV1(
                    namespace, operation_id, request_digest, input_digest,
                    binding.scene_ref, binding.role_binding_id, role.head_id,
                    proof.grant_id, guard.authorization_head,
                    proof.graph_incarnation, metadata.graph_revision + 1,
                    graph_receipt.epoch.revision, attempt_id,
                    finish_id, finish_digest,
                )
                db.execute(
                    "INSERT INTO graph_scene_binding_receipts_v1"
                    "(bot,persona,operation_id,input_digest,permit_json,receipt_json,"
                    "pre_graph_revision,pre_graph_epoch,post_graph_revision,"
                    "post_graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        operation_id, input_digest, canonical_json(to_wire(permit)),
                        canonical_json(asdict(receipt)), metadata.graph_revision,
                        epoch.revision, receipt.graph_revision,
                        receipt.graph_epoch, finish_id, finish_digest),
                )
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("committed scene write permit changed")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.graph_revision != receipt.graph_revision
                    or current_epoch.revision != receipt.graph_epoch):
                raise UnavailableGuard("committed scene graph stamp changed")
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return receipt

    def read_active_role_v2(self, *, namespace: NamespaceId):
        """Read the current D01 head under one paired Authority read fence."""
        return self._read_active_scene_v2(namespace, None)[0]

    def read_first_scene_binding_proof_v2(
        self, *, namespace: NamespaceId, scene_ref: str, purpose: str,
        principal, actor_id: str, owner_session_token: str | None = None,
        owner_session_request: OwnerSessionLoginRequestV1 | None = None,
    ):
        """Prove a complete first-binding absence with current Owner and D01 heads."""
        from .authority_service.contract import identifier
        from .authority_service.v2_owner_contract import (
            OwnerAuthorizationGuardV1, OwnerPrincipalV1,
        )
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1
        from .domains.d03 import (
            ContextProvider, RoleBindingRequest, RoleBindingResolution,
        )
        from .runtime_contracts import QueryEpoch
        from .workbench_api.d03_onboarding import (
            CurrentFirstBindingProof, CurrentGraphGuardMetadata,
        )

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None or type(namespace) is not NamespaceId
                or type(principal) is not OwnerPrincipalV1):
            raise UnavailableGuard("first scene proof requires production v2 Owner")
        identifier(scene_ref, "scene_ref")
        identifier(purpose, "purpose")
        identifier(actor_id, "actor_id")
        if not scene_ref.startswith("scene:"):
            raise ValueError("scene_ref must be a scene identity")
        if self._current_owner_principal(actor_id, namespace) != principal:
            raise UnavailableGuard("current Owner pairing differs")
        signed_session = (owner_session_token is not None
                          or owner_session_request is not None)
        if signed_session and (type(owner_session_token) is not str
                               or not owner_session_token
                               or type(owner_session_request)
                               is not OwnerSessionLoginRequestV1):
            raise UnavailableGuard("Owner session token and request must be paired")
        port = self.__content_fence_v2
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(guard_reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != 1:
            raise UnavailableGuard("first scene recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("first scene recovery anchor differs")
        session_kwargs = {}
        if signed_session:
            if (owner_session_request.authority_id != anchor.authority_id
                    or owner_session_request.authority_namespace
                    != target.authority_namespace
                    or owner_session_request.installation_id
                    != port.installation_grant.installation_id
                    or owner_session_request.principal != principal
                    or owner_session_request.audience != "owner"):
                raise UnavailableGuard("first scene Owner session identity differs")
            session_kwargs = {
                "owner_actor_id": actor_id,
                "owner_session_token": owner_session_token,
                "owner_session_request": owner_session_request,
            }
        attempt_id = "scene-negative-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="read",
            operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace, 1, "read",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        authority = AuthorityContext(
            actor_id, "d12", "first-scene-read", namespace,
            ("persona", "scene"), purpose, ("owner",), "owner-grant-v1", 1)

        def current_guard():
            guarded = guard_reader(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                permit=permit, **session_kwargs)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("current Owner guard is unavailable")
            return guarded[0]

        def check_owner(guard):
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("first scene graph stamp changed")
                binding = self._owner_graph_binding_locked(authority, principal)
            if (guard.authority_id != anchor.authority_id
                    or guard.installation_id
                    != port.installation_grant.installation_id
                    or guard.namespace != namespace
                    or guard.authorization_revision != binding.authorization_revision
                    or guard.authorization_head != binding.authorization_head
                    or guard.minimum_revocation_revision != 0
                    or guard.minimum_revocation_epoch != binding.revocation_epoch
                    or guard.pending_revoke_operation_id is not None):
                raise UnavailableGuard("first scene Owner head changed")
            return binding

        def current_graph_guard_locked():
            db = store._db
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("first scene graph authority epochs are unavailable")
            return CurrentGraphGuardMetadata(
                namespace, epoch.revision, epochs[0], epochs[1],
                store._registry.catalogue_hash,
                self._version(db, namespace, "scheme", "current"),
                self._version(db, namespace, "operator", "current"),
                self._version(db, namespace, "policy", "current"),
            )

        try:
            guard = current_guard()
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first scene read permit changed")
            owner = check_owner(guard)
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("first scene graph stamp changed")
                role, bindings, current_epoch, versions = (
                    self._scene_binding_state_locked(namespace, guard))
                if current_epoch != epoch:
                    raise StaleRead("first scene query epoch changed")
                # First binding means no valid binding atom for this scene,
                # including one that is currently out of its effective window.
                if any(item.scene_ref == scene_ref for item in bindings):
                    raise AuthorityDenied("scene already has a valid D03 binding")
                request = RoleBindingRequest(
                    f"persona:{namespace.persona_id}", None, None, scene_ref,
                    "bind_scene", purpose, time.time(), True)
                result = ContextProvider().resolve_role_binding(
                    request, bindings)
                if result.status != "no_applicable_binding":
                    raise UnavailableGuard("first scene D03 query is incomplete")
                prior = RoleBindingResolution(
                    result.status, result.matched_bindings,
                    result.applicable_norm_refs, result.missing_items,
                    versions, QueryEpoch(namespace, "d03.role_binding", epoch.revision),
                    result.valid_until, request)
                graph_guard = current_graph_guard_locked()
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first scene read permit changed")
            if (self._current_owner_principal(actor_id, namespace) != principal
                    or current_guard() != guard or check_owner(guard) != owner):
                raise UnavailableGuard("first scene Owner head changed")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("first scene graph stamp changed after read")
                if current_graph_guard_locked() != graph_guard:
                    raise StaleRead("first scene graph guard changed after read")
            return CurrentFirstBindingProof(role, prior, guard, graph_guard)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_first_scene_read",
                }))

    def read_active_scene_v2(self, *, namespace: NamespaceId, scene_ref: str):
        """Read current D01 head and one scene binding at the same graph epoch."""
        from .authority_service.contract import identifier
        identifier(scene_ref, "scene_ref")
        if not scene_ref.startswith("scene:"):
            raise ValueError("scene_ref must be a scene identity")
        return self._read_active_scene_v2(namespace, scene_ref)

    def _read_active_scene_v2(self, namespace: NamespaceId,
                              scene_ref: str | None):
        from .authority_service.v2_owner_contract import (
            OwnerAuthorizationGuardV1, OwnerGraphCommitProofV1,
            canonical_digest as owner_contract_digest,
        )
        from .domains.d01 import PersonaDomain, _activation_key
        from .domains.d03 import RoleBinding
        from .graph_types import AtomKey, GraphSnapshot, Owner

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None or type(namespace) is not NamespaceId):
            raise UnavailableGuard("active role requires a production v2 namespace")
        port = self.__content_fence_v2
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(guard_reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != 1:
            raise UnavailableGuard("active role recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("active role recovery anchor differs")
        attempt_id = "role-read-" + secrets.token_hex(16)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=1, operation="read",
            operation_id=attempt_id, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace, 1, "read",
                           attempt_id, permit, anchor, epoch, metadata.graph_revision)
        try:
            guarded = guard_reader(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("current Owner guard is unavailable")
            guard = guarded[0]
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("active role read permit changed")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("active role graph stamp changed")
                db = store._db
                proof_row = db.execute(
                    "SELECT operation_id,request_digest,grant_id,grant_digest,"
                    "graph_incarnation,graph_access_epoch,graph_epoch,"
                    "graph_receipt_digest,proof_json "
                    "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
                    namespace.as_tuple,
                ).fetchone()
                if proof_row is None:
                    raise UnavailableGuard("first Owner graph proof is absent")
                proof = OwnerGraphCommitProofV1(
                    namespace, proof_row[0], proof_row[1], proof_row[2],
                    proof_row[3], proof_row[4], 1, proof_row[5],
                    proof_row[6], proof_row[7])
                if (proof_row[8] != canonical_json(asdict(proof))
                        or guard.authorization_head != owner_contract_digest(proof)
                        or guard.authorization_revision != 1
                        or guard.pending_revoke_operation_id is not None
                        or guard.minimum_revocation_revision != 0
                        or guard.minimum_revocation_epoch != 0):
                    raise UnavailableGuard("current Owner authorization differs")
                activation_key = _activation_key(namespace)
                activation_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (activation_key.token,),
                ).fetchone()
                if activation_row is None or activation_row[2] != 1:
                    raise UnavailableGuard("active role head is absent")
                activation = json.loads(activation_row[1])
                plan_key = AtomKey(
                    Owner("persona", *namespace.as_tuple),
                    "d01.persona_plan.v1", activation["plan_id"])
                keys = (activation_key, plan_key,
                        owner_grant_key(*namespace.as_tuple))
                atoms = []
                for key in keys:
                    row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    if row is None:
                        raise UnavailableGuard("active role graph atoms are incomplete")
                    atoms.append(GraphAtom(
                        key, row[0], json.loads(row[1]), bool(row[2])))
                try:
                    role = PersonaDomain.resolve_active_role(
                        GraphSnapshot(tuple(atoms), (epoch,)), namespace=namespace,
                        current_guard=guard)
                except (TypeError, ValueError) as exc:
                    raise UnavailableGuard("active role qualification failed") from exc
                role_row = db.execute(
                    "SELECT receipt_json FROM graph_role_init_receipts_v1 "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if role_row is None:
                    raise UnavailableGuard("active role lacks initialization receipt")
                role_receipt = json.loads(role_row[0])
                if (role_receipt.get("head_id") != role.head_id
                        or role_receipt.get("owner_grant_id")
                        != atoms[2].value["grant_id"]
                        or role_receipt.get("owner_authorization_head")
                        != guard.authorization_head):
                    raise UnavailableGuard("active role receipt differs")
                binding = None
                if scene_ref is not None:
                    rows = db.execute(
                        "SELECT token,revision,value FROM graph_atoms WHERE bot=? "
                        "AND persona=? AND owner_kind='scene' AND subject=? "
                        "AND type_name='d03.role_binding' AND valid=1",
                        namespace.as_tuple + (scene_ref,),
                    ).fetchall()
                    if len(rows) != 1:
                        raise UnavailableGuard("current scene binding is unavailable")
                    key = AtomKey.from_token(rows[0][0])
                    value = json.loads(rows[0][2])
                    binding = RoleBinding(**{
                        **value, "norm_refs": tuple(value["norm_refs"]),
                        "source_refs": tuple(value["source_refs"]),
                    })
                    if (rows[0][1] != binding.binding_version
                            or key.name != binding.role_binding_id
                            or binding.scene_ref != scene_ref
                            or binding.subject_persona_ref
                            != f"persona:{namespace.persona_id}"
                            or binding.status != "active"):
                        raise UnavailableGuard("current scene binding differs")
                    scene_row = db.execute(
                        "SELECT r.receipt_json FROM graph_history AS h "
                        "JOIN graph_scene_binding_receipts_v1 AS r "
                        "ON r.bot=h.event_bot AND r.persona=h.event_persona "
                        "AND r.operation_id=h.event_id "
                        "WHERE h.token=? AND h.revision=? "
                        "AND h.event_session='d03-scene-binding'",
                        (key.token, rows[0][1]),
                    ).fetchone()
                    if scene_row is None:
                        raise UnavailableGuard("scene binding lacks fenced receipt")
                    scene_receipt = json.loads(scene_row[0])
                    if (scene_receipt.get("scene_ref") != scene_ref
                            or scene_receipt.get("binding_id") != binding.role_binding_id
                            or scene_receipt.get("role_head_id") != role.head_id):
                        raise UnavailableGuard("scene binding receipt differs")
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("active role read permit changed")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("active role graph stamp changed after read")
            return role, binding
        finally:
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_active_role_read",
                }))

    def provision_namespace_v2(self, bootstrap: object, policy, *,
                               operation_id: str) -> NamespaceProvisionReceiptV2:
        """Install one administrator-owned namespace under a v2 write fence.

        The DTO is a value contract, not administrator authentication. The host
        must load it through its protected installation profile before passing
        this coordinator's opaque bootstrap capability.
        """
        from .installation_policy import AdminInstallationPolicy
        from .runtime.issuers import (
            BudgetLeaseGrant, D11BudgetGrantIssuer, D11BudgetJobIssuer,
            install_schema as install_issuer_schema,
        )
        from .runtime_contracts import (
            InstallationGrantV2, NamespaceBootstrapV2, NamespaceRuntimeState,
            SnapshotRequirementsV2,
        )
        from .authority_service.v2_contract import to_wire

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or not callable(getattr(port, "provision_namespace", None))
                or type(self.__d11_issuer) not in (D11BudgetGrantIssuer, D11BudgetJobIssuer)):
            raise UnavailableGuard("production v2 provisioning authorities are unavailable")
        if type(policy) is not AdminInstallationPolicy:
            raise TypeError("verified administrator installation policy is required")
        if (type(operation_id) is not str or not operation_id
                or len(operation_id) > 128):
            raise ValueError("invalid namespace provisioning operation ID")
        grant = getattr(port, "installation_grant", None)
        namespace = policy.namespace
        if (type(grant) is not InstallationGrantV2
                or grant.authority_id != policy.expected_authority_id
                or grant.administrator_holder != policy.administrator_holder
                or grant.installation_id != policy.installation_id
                or grant.manifest_digest != policy.manifest_digest
                or self.__holder != policy.administrator_holder
                or policy.catalogue_hash != store._registry.catalogue_hash
                or policy.root_lease.parent_id is not None
                or (policy.root_lease.bot_id, policy.root_lease.persona_id) != namespace.as_tuple
                or (policy.root_grant.bot_id, policy.root_grant.persona_id) != namespace.as_tuple
                or policy.root_grant.lease_id != policy.root_lease.lease_id):
            raise AuthorityDenied("administrator installation policy differs from paired authority")
        digest = canonical_digest(policy.digest_payload())
        # The installation DTO freezes its budget maps. D11's durable JSON
        # primitives take their own normalized, mutable value copies.
        source_lease = policy.root_lease
        root_lease = BudgetLease(
            source_lease.lease_id, source_lease.parent_id,
            source_lease.bot_id, source_lease.persona_id,
            source_lease.currency, dict(source_lease.limits),
            dict(source_lease.used), dict(source_lease.reserved),
            dict(source_lease.unconfirmed), source_lease.version,
            source_lease.state,
        )
        source_grant = policy.root_grant
        root_grant = BudgetLeaseGrant(
            source_grant.grant_id, source_grant.version,
            source_grant.bot_id, source_grant.persona_id,
            source_grant.lease_id, source_grant.currency,
            dict(source_grant.max_ceiling),
            tuple(source_grant.allowed_work_kinds),
            source_grant.valid_until_utc, source_grant.policy_ref,
        )
        with store._lock:
            row = self._provision_row(store._db, namespace)
        if row is not None:
            if row[:2] != (operation_id, digest):
                raise AuthorityDenied("namespace provisioning identity differs")
            return self._reconcile_provision_v2(policy, operation_id, digest)
        intent, identity_json = self._ensure_provision_intent(
            policy, grant, operation_id, digest)

        if intent.anchor_json is None:
            observed = port.provision_namespace(
                namespace=namespace, request_id=intent.genesis_request_id)
            if (type(observed) is not NamespaceBootstrapV2
                    or observed.namespace != namespace
                    or observed.authority_id != policy.expected_authority_id
                    or observed.authority_namespace != policy.authority_namespace
                    or observed.holder != self.__holder
                    or observed.state is not NamespaceRuntimeState.ACTIVE
                    or observed.phase != "active" or observed.generation != 1
                    or observed.anchor is None or observed.blocking_reasons):
                raise UnavailableGuard("Authority v2 namespace genesis is not active")
            anchor = observed.anchor
            current_anchor = port.current_anchor(
                namespace=namespace, authority_namespace=policy.authority_namespace)
            if current_anchor != anchor:
                raise UnavailableGuard("Authority v2 current anchor differs from genesis")
            intent = self._persist_provision_anchor(intent, anchor, identity_json)
        else:
            from .runtime.restore_anchor import RestoreAnchor
            try:
                data = json.loads(intent.anchor_json)
                if (type(data) is not dict
                        or set(data) != {field.name for field in fields(RestoreAnchor)}):
                    raise ValueError("invalid anchor fields")
                anchor = RestoreAnchor(**data)
            except (TypeError, ValueError) as exc:
                raise UnavailableGuard("durable v2 provisioning anchor is invalid") from exc
        current_anchor = port.current_anchor(
            namespace=namespace, authority_namespace=policy.authority_namespace)
        if (anchor != current_anchor or anchor.authority_id != policy.expected_authority_id
                or anchor.namespace != policy.authority_namespace
                or anchor.activation_generation != 1 or anchor.deletion_seq != 0
                or anchor.execution_seq != 0 or anchor.revocation_epoch != 0):
            raise UnavailableGuard("Authority v2 current anchor differs from genesis")
        with store._lock:
            epoch = GraphStore.graph_epoch(
                store, *namespace.as_tuple, _capability=self.__graph_capability)
            if epoch.revision != 0:
                raise UnavailableGuard("namespace graph has a prior epoch")
        attempt_id = intent.fence_attempt_id
        try:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=policy.authority_namespace,
                holder=self.__holder, generation=1, operation="write",
                operation_id=attempt_id, expected_anchor=anchor,
                retain_on_unknown=True)
        except Exception as exc:
            raise UnavailableGuard(
                "v2 provisioning write fence unavailable; HOLD pending exact attempt") from exc
        scope = FenceScope(namespace, policy.authority_namespace, 1, "write",
                           attempt_id, permit, anchor, epoch, 0)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "finish_namespace_provision",
            "business_operation_id": operation_id, "input_digest": digest,
        })
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 provisioning write permit changed")
        requirements = SnapshotRequirementsV2(
            namespace, anchor.authority_id, anchor.namespace,
            anchor.activation_generation, anchor.deletion_journal_id,
            anchor.deletion_seq, anchor.deletion_digest,
            anchor.execution_journal_id, anchor.execution_seq,
            anchor.execution_digest, anchor.revocation_epoch,
            intent.graph_incarnation,
        )
        with store._lock:
            store._ensure_open()
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current_intent = self._provision_intent_row(db, namespace)
                self._check_provision_intent(
                    current_intent, operation_id, digest, identity_json)
                if current_intent != intent or self._provision_row(db, namespace) is not None:
                    raise UnavailableGuard("namespace provisioned concurrently; retry reconciliation")
                if GraphStore.graph_epoch(
                        store, *namespace.as_tuple,
                        _capability=self.__graph_capability) != epoch:
                    raise UnavailableGuard("namespace graph epoch changed")
                store._install_graph_recovery_genesis_locked(
                    requirements, _capability=self.__graph_capability,
                    provision_intent=(operation_id, digest))
                for kind, version in (("scheme", policy.scheme_version),
                                      ("operator", policy.operator_version),
                                      ("policy", policy.policy_version),
                                      ("activation", "1")):
                    db.execute(
                        "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + (kind, "current", str(version)),
                    )
                create_budget_lease(
                    db, root_lease,
                    "root-budget-" + canonical_digest({
                        "namespace": list(namespace.as_tuple),
                        "operation_id": operation_id,
                    })[:48], digest)
                install_issuer_schema(db)
                grant_signature = self.__d11_issuer.issue_budget_grant(
                    db, root_grant)
                receipt = NamespaceProvisionReceiptV2(
                    namespace, operation_id, digest, policy.installation_id,
                    policy.manifest_digest, anchor.authority_id,
                    anchor.namespace, 1, requirements.graph_incarnation,
                    0, epoch.revision, policy.catalogue_hash,
                    str(policy.scheme_version), str(policy.operator_version),
                    str(policy.policy_version), policy.root_lease.lease_id,
                    policy.root_grant.grant_id, policy.root_grant.version,
                    grant_signature, attempt_id, finish_id, finish_digest,
                    to_wire(permit),
                )
                db.execute(
                    "INSERT INTO graph_namespace_provisioning_v2"
                    "(bot,persona,operation_id,digest,receipt_json) VALUES(?,?,?,?,?)",
                    namespace.as_tuple + (operation_id, digest,
                                          canonical_json(asdict(receipt))),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 provisioning write permit changed after commit")
        with store._lock:
            if self._verify_provision_receipt(policy, operation_id, digest)[0] != receipt:
                raise UnavailableGuard("v2 provisioning state changed after commit")
        port.finish_fence(scope, request_id=finish_id,
                          request_digest=finish_digest)
        return receipt

    def _admit_content(self, namespace: NamespaceId, generation: int,
                       operation: str, refs: tuple[str, ...] = ()) -> None:
        """Called while the authority fence and business lock are held."""
        if not isinstance(self.__store, ProductionGraphStore):
            return
        if self.__deletion_journal is None:
            raise UnavailableGuard("independent deletion journal unavailable")
        identity = namespace_ref(namespace)
        try:
            self.__migration_authority.check(
                namespace=identity, holder=self.__holder,
                generation=generation, operation=operation)
            snapshot = self.__snapshot_requirements(namespace)
            if not isinstance(snapshot, SnapshotRequirements) or snapshot.namespace != identity:
                raise UnavailableGuard("business restore requirements unavailable")
            if snapshot.activation_generation != generation:
                raise UnavailableGuard("business snapshot activation generation is stale")
            anchor = validate_restore(
                snapshot=snapshot, authority=self.__restore_authority,
                deletion_journal=self.__deletion_journal,
                execution_journal_port=self.__execution_journal_port,
                active_generation=generation,
            )
            if (anchor.deletion_seq != snapshot.deletion_seq
                    or anchor.execution_seq != snapshot.execution_seq
                    or anchor.revocation_epoch != snapshot.revocation_epoch):
                raise UnavailableGuard("independent constraints require recovery merge")
            self.__deletion_journal.assert_access(
                identity, content_refs=refs or None,
                closure_verifier=self.__closure_verifier)
        except UnavailableGuard:
            raise
        except Exception as exc:
            raise UnavailableGuard("current content authority is unavailable") from exc

    def register_provider(self, bootstrap: object, domain: str, provider: object,
                          proposal_schema: str, proposal_schema_hash: str) -> None:
        self._admin(bootstrap)
        if not domain or domain in self.__providers:
            raise ValueError("domain must be nonempty and registered once")
        if not callable(getattr(provider, "validate", None)):
            raise TypeError("provider requires validate")
        if (type(proposal_schema_hash) is not str or len(proposal_schema_hash) != 64
                or any(ch not in "0123456789abcdef" for ch in proposal_schema_hash)):
            raise ValueError("proposal schema hash must be SHA-256")
        self.__providers[domain] = (provider, proposal_schema, proposal_schema_hash)

    def grant(self, bootstrap: object, *, actor: str, issuer_domain: str,
              namespace: NamespaceId, domains: tuple[str, ...],
              activation_generation: int,
              operation_id: str | None = None) -> tuple[object, str]:
        self._admin(bootstrap)
        if (issuer_domain == "d12"
                and isinstance(self.__store, ProductionGraphStore)):
            raise UnavailableGuard("D12 requires a current Owner graph lease")
        return self._grant_registered(
            actor=actor, issuer_domain=issuer_domain, namespace=namespace,
            domains=domains, activation_generation=activation_generation,
            operation_id=operation_id)

    def release_authority_lease(self, bootstrap: object, lease: object) -> None:
        """Discard a plain process capability after its host operation ends.

        This touches no graph, job, reservation, or Authority receipt. A later
        recovery may mint a new lease scoped to the original operation ID.
        Owner and deletion read leases keep their dedicated release paths.
        """
        self._admin(bootstrap)
        if type(lease) is not _AuthorityLease:
            raise AuthorityDenied("process authority lease required")
        if lease in self.__owner_leases or lease in self.__deletion_read_leases:
            raise AuthorityDenied("specialized lease requires its own release")
        try:
            del self.__leases[lease]
        except (KeyError, TypeError):
            raise AuthorityDenied("unknown process authority") from None

    def grant_deletion_read(self, bootstrap: object, *, actor: str,
                            namespace: NamespaceId,
                            activation_generation: int) -> tuple[AuthorityContext, object]:
        """Host-mint a D06-only wide read lease for candidate closure evidence."""
        self._admin(bootstrap)
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or "d06" not in self.__providers
                or type(activation_generation) is not int
                or activation_generation < 1):
            raise UnavailableGuard("D06 deletion read authority is unavailable")
        specs = self.__store._registry.specs
        if not specs or any(spec.writer_domain is None for spec in specs):
            raise UnavailableGuard("deletion read requires complete type ownership")
        domains = tuple(sorted({spec.writer_domain for spec in specs}))
        lease, ref = self._grant_registered(
            actor=actor, issuer_domain="d06", namespace=namespace,
            domains=domains, activation_generation=activation_generation)
        owner_scope = tuple(sorted(self.__leases[lease][5]))
        authority = AuthorityContext(
            actor, "d06", ref, namespace, owner_scope, "deletion_cleanup",
            ("internal",), "d06-deletion-closure-v1", activation_generation)
        self.__deletion_read_leases.add(lease)
        return authority, lease

    def release_deletion_read_lease(self, bootstrap: object, lease: object) -> None:
        self._admin(bootstrap)
        if lease not in self.__deletion_read_leases:
            raise AuthorityDenied("deletion read lease required")
        self.__deletion_read_leases.remove(lease)
        del self.__leases[lease]

    def _grant_registered(self, *, actor: str, issuer_domain: str,
                          namespace: NamespaceId, domains: tuple[str, ...],
                          activation_generation: int,
                          operation_id: str | None = None) -> tuple[object, str]:
        if not actor or not issuer_domain or not isinstance(namespace, NamespaceId):
            raise ValueError("invalid authority grant")
        domain_set = frozenset(domains)
        if not domain_set or any(domain not in self.__providers for domain in domain_set):
            raise AuthorityDenied("unregistered domain in authority grant")
        if type(activation_generation) is not int or activation_generation < 0:
            raise ValueError("invalid activation generation")
        if operation_id is not None and (not isinstance(operation_id, str)
                                      or not operation_id or len(operation_id) > 128):
            raise ValueError("invalid scoped operation identity")
        lease = _AuthorityLease(object())
        ref = (secrets.token_hex(24) if operation_id is None else
               _operation_capability_ref(namespace, actor, issuer_domain,
                                         domain_set, activation_generation,
                                         operation_id))
        owners = frozenset(kind for spec in self.__store._registry.specs
                           if spec.writer_domain in domain_set
                           for kind in spec.owner_kinds)
        self.__leases[lease] = (ref, actor, issuer_domain, namespace, domain_set,
                                owners, activation_generation)
        return lease, ref

    def grant_current_owner(self, bootstrap: object, *, actor: str,
                            namespace: NamespaceId, domains: tuple[str, ...],
                            purpose: str, audience: str,
                            activation_generation: int,
                            owner_session_token: str | None = None,
                            owner_session_request: object | None = None,
                            ) -> tuple[AuthorityContext, object, OwnerLeaseBindingV1]:
        """Mint a D12 read lease only from a trusted paired principal and live heads."""
        self._admin(bootstrap)
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__owner_principal_resolver is None):
            raise UnavailableGuard("current Owner principal resolver is unavailable")
        if not purpose or not audience:
            raise ValueError("Owner read requires purpose and audience")
        proof = self._owner_session_proof(
            actor, owner_session_token, owner_session_request)
        principal = self._current_owner_principal(actor, namespace)
        lease, ref = self._grant_registered(
            actor=actor, issuer_domain="d12", namespace=namespace,
            domains=domains, activation_generation=activation_generation)
        owner_scope = tuple(sorted(self.__leases[lease][5]))
        authority = AuthorityContext(
            actor, "d12", ref, namespace, owner_scope, purpose,
            (audience,), "owner-grant-v1", activation_generation)
        try:
            binding = self._read_v2(
                authority,
                lambda: self._owner_graph_binding_locked(authority, principal),
                owner_principal=principal, owner_session_proof=proof)
        except BaseException:
            del self.__leases[lease]
            raise
        self.__owner_leases[lease] = binding
        if proof is not None:
            self.__owner_session_proofs[lease] = proof
        return authority, lease, binding

    def release_current_owner_lease(self, bootstrap: object, lease: object) -> None:
        """End one D12 read lease after its worker command completes."""
        self._admin(bootstrap)
        if lease not in self.__owner_leases:
            raise AuthorityDenied("current Owner lease required")
        del self.__owner_leases[lease]
        self.__owner_session_proofs.pop(lease, None)
        del self.__leases[lease]

    def read_current_owner_view(self, bootstrap: object, *, actor: str,
                                namespace: NamespaceId, purpose: str,
                                audience: str,
                                expected_principal: OwnerPrincipalV1,
                                owner_session_token: str | None = None,
                                owner_session_request: object | None = None,
                                ) -> CurrentOwnerViewV1:
        """Project current Owner heads without minting a process lease."""
        self._admin(bootstrap)
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__owner_principal_resolver is None):
            raise UnavailableGuard("current Owner read authority is unavailable")
        if type(expected_principal) is not OwnerPrincipalV1:
            raise UnavailableGuard("expected Owner principal is unavailable")
        if not isinstance(namespace, NamespaceId):
            raise TypeError("namespace must be NamespaceId")
        proof = self._owner_session_proof(
            actor, owner_session_token, owner_session_request)
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            actor, "d12", "owner-view:" + secrets.token_hex(16), namespace,
            ("persona",), purpose, (audience,), "owner-view-v1",
            metadata.requirements.activation_generation)
        return self._read_v2(
            authority, lambda: None, owner_principal=expected_principal,
            owner_view=True, owner_session_proof=proof)

    def commit_source_correction_v1(
            self, *, request, actor_id: str, principal: OwnerPrincipalV1,
            purpose: str, audience: str, installation_policy, admin_policy,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ):
        """Commit one Owner correction and queue its bounded reevaluation."""
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1
        from .domains.d04.source_head import D04SourceHeadRead, _qualified_head
        from .domains.d06 import (
            CorrectionRequest, D06DomainAdapter, SourceCorrectionReadSetV1,
            source_correction_head_key,
        )
        from .domains.d07 import D07DomainProvider
        from .host.authority_profile import (
            AdminD06SourceCorrectionPolicy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .memory_types import InterpretationRecord, interpretation_key
        from .runtime.d11_types import (
            D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH, RuntimeOutboxValue,
            job_graph_write, outbox_graph_write,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime_contracts import (
            CommandEnvelope, DependencySet, DomainProposal, OperationIdentity,
            QueryEpoch, RUNTIME_SCHEMA, VersionedRef,
        )
        from .workbench_api.source_correction import (
            SourceCorrectionCommitReceiptV1, SourceCorrectionRequestV1,
        )

        if (type(request) is not SourceCorrectionRequestV1
                or type(principal) is not OwnerPrincipalV1
                or type(owner_session_request) is not OwnerSessionLoginRequestV1
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06SourceCorrectionPolicy
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None or self.__d11_issuer is None):
            raise UnavailableGuard("installed source correction authority unavailable; HOLD")
        namespace = request.namespace
        if (installation_policy.namespace != namespace
                or installation_policy.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or type(actor_id) is not str or not actor_id
                or purpose != "workbench_user_action"
                or audience != "owner"
                or owner_session_request.audience != audience):
            raise AuthorityDenied("source correction Owner or installation differs")
        original_input = {
            "schema": request.schema, "correction_kind": "source_claim",
            "statement": request.statement,
            "source_refs": list(request.source_refs),
            "target_refs": list(request.target_refs),
            "access_epoch": request.access_epoch,
            "deletion_epoch": request.deletion_epoch,
        }
        if request.impact_preview_ref is not None:
            original_input["impact_preview_ref"] = request.impact_preview_ref
        original_command = {
            "action": "correct_or_edit", "scope": "/".join(namespace.as_tuple),
            "purpose": purpose, "audience": audience,
            "operation_id": request.operation_id, "input": original_input,
        }
        actual_digest = "sha256:" + hashlib.sha256(json.dumps(
            original_command, sort_keys=True, separators=(",", ":"),
            allow_nan=False).encode("utf-8")).hexdigest()
        if actual_digest != request.request_digest:
            raise AuthorityDenied("source correction original command digest differs")
        store = self.__store
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=metadata.requirements)
        owner_authority = AuthorityContext(
            actor_id, "d12", "owner-correction:" + secrets.token_hex(16),
            namespace, ("persona", "event", "activity"),
            "workbench_user_action", (audience,), "owner-grant-v1",
            metadata.requirements.activation_generation)
        session_proof = (owner_session_token, owner_session_request)
        owner_binding = self._read_v2(
            owner_authority,
            lambda: self._owner_graph_binding_locked(owner_authority, principal),
            owner_principal=principal, owner_session_proof=session_proof)
        if "workbench.correct" not in owner_binding.capabilities:
            raise AuthorityDenied("Owner grant lacks correction capability")

        correction = CorrectionRequest(
            request.operation_id, request.target_refs, request.source_refs,
            request.statement, request.access_epoch, request.deletion_epoch)
        adapter = D06DomainAdapter(namespace)
        correction_key = adapter.correction_source_key(correction)
        head_refs = tuple(source_correction_head_key(
            namespace, self._parse_ref(ref, namespace).owner.subject).token
            for ref in request.source_refs)

        def prior_or_pending():
            db = store._db
            row = db.execute(
                "SELECT activity_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (request.operation_id,),
            ).fetchone()
            if row is not None:
                detail = json.loads(row[1]).get("source_correction")
                fence = db.execute(
                    "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (request.operation_id,),
                ).fetchone()
                committed = self._get_operation_fenced(
                    owner_authority, request.operation_id, v2=True)
                if (type(detail) is not dict or committed is None
                        or committed.status != "committed"
                        or fence is None or fence[0] != committed.operation_digest
                        or not {item.key.token for item in committed.write_versions}
                        .issuperset({correction_key.token, *request.target_refs,
                                    *head_refs, detail.get("reevaluation_outbox_ref")})
                        or detail.get("request_digest") != request.request_digest
                        or detail.get("correction_source_ref") != correction_key.token
                        or detail.get("source_refs") != list(request.source_refs)
                        or detail.get("correction_head_refs") != list(head_refs)
                        or detail.get("invalidated_target_refs")
                        != list(request.target_refs)
                        or detail.get("reevaluation_status") != "pending"):
                    raise EventConflict("source correction operation ID differs")
                return SourceCorrectionCommitReceiptV1(
                    namespace, request.operation_id, request.request_digest,
                    detail["correction_source_ref"], request.source_refs,
                    request.target_refs, detail["reevaluation_outbox_ref"],
                    detail["audit_event_ref"], detail["graph_revision"],
                    detail["access_epoch"], detail["deletion_epoch"])
            if db.execute(
                "SELECT 1 FROM graph_bundle_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (request.operation_id,),
            ).fetchone() is not None:
                raise UnavailableGuard("source correction outcome unknown; HOLD")
            return None

        prior = self._read_v2(
            owner_authority, prior_or_pending, owner_binding=owner_binding,
            owner_session_proof=session_proof)
        if prior is not None:
            return prior

        lease, capability = self._grant_registered(
            actor=actor_id, issuer_domain="d06", namespace=namespace,
            domains=("d06", "d07", "d11"),
            activation_generation=metadata.requirements.activation_generation,
            operation_id=request.operation_id)
        try:
            authority = AuthorityContext(
                actor_id, "d06", capability, namespace,
                tuple(sorted(self.__leases[lease][5])), "context", (audience,),
                installation_policy.root_grant.policy_ref,
                metadata.requirements.activation_generation)
            try:
                reading = self.__content_fence_v2.read_ingress_clock(
                    self.__scene_clock_policy)
                now = trusted_upper(reading)
            except Exception as exc:
                raise UnavailableGuard("paired correction clock unavailable; HOLD") from exc
            deadline = min(math.nextafter(
                now + admin_policy.deadline_after_seconds, -math.inf),
                installation_policy.root_grant.valid_until_utc)
            if deadline <= now:
                raise UnavailableGuard("source correction deadline unavailable; HOLD")

            def read_candidate():
                db = store._db
                if db.in_transaction:
                    raise UnavailableGuard("source correction needs idle graph connection")
                db.execute("BEGIN")
                try:
                    if prior_or_pending() is not None:
                        raise UnavailableGuard("source correction committed during read; retry")
                    _, epoch = self._v2_graph_stamp(namespace)
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone()
                    if epochs != (request.access_epoch, request.deletion_epoch):
                        raise StaleRead("source correction access or deletion epoch changed")
                    atoms: dict[AtomKey, GraphAtom] = {}

                    def load(key: AtomKey) -> GraphAtom:
                        if NamespaceId.from_key(key) != namespace:
                            raise AuthorityDenied("source correction crosses namespace")
                        if key not in atoms:
                            if len(atoms) >= 512:
                                raise UnavailableGuard("source correction closure exceeds bound")
                            store._validate_key(key)
                            row = db.execute(
                                "SELECT revision,value,valid FROM graph_atoms "
                                "WHERE token=?", (key.token,),
                            ).fetchone()
                            atoms[key] = (GraphAtom(
                                key, row[0], json.loads(row[1]), bool(row[2]))
                                if row else GraphAtom(key, 0, {}, False))
                        return atoms[key]

                    selected_sources = []
                    selected_accesses = []
                    pending = list(request.source_refs)
                    seen: set[str] = set()
                    while pending:
                        ref = pending.pop()
                        if ref in seen:
                            continue
                        seen.add(ref)
                        if len(seen) > 256:
                            raise UnavailableGuard("source correction ancestry exceeds bound")
                        key = self._parse_ref(ref, namespace)
                        if key != source_key(*namespace.as_tuple, key.owner.subject or ""):
                            raise AuthorityDenied("correction source ref is not canonical")
                        source = load(key)
                        access = load(access_key(
                            *namespace.as_tuple, key.owner.subject))
                        head = load(source_correction_head_key(
                            namespace, key.owner.subject))
                        if not source.valid or not access.valid:
                            raise UnavailableGuard("correction source or ancestor unavailable")
                        if head.revision != 0:
                            raise UnavailableGuard(
                                "correction source or ancestor has pending reevaluation")
                        record = SourceRecord.from_dict(source.value)
                        validate_access(access.value)
                        pending.extend(source_key(*namespace.as_tuple, parent).token
                                       for parent in record.parent_source_ids)
                    snapshot = GraphSnapshot(tuple(atoms.values()), (epoch,))
                    head_read = D04SourceHeadRead(
                        snapshot, namespace, (audience,), "context", None,
                        False, False, False)
                    for ref in request.source_refs:
                        head, reason = _qualified_head(ref, atoms, head_read)
                        if head is None:
                            raise UnavailableGuard(
                                f"source correction ancestor access unavailable: {reason}")
                        key = self._parse_ref(ref, namespace)
                        selected_sources.append(SourceRecord.from_dict(load(key).value))
                        selected_accesses.append(load(access_key(
                            *namespace.as_tuple, key.owner.subject)).value)
                    interpretations = []
                    for ref in request.target_refs:
                        key = self._parse_ref(ref, namespace)
                        if key != interpretation_key(
                                *namespace.as_tuple, key.owner.subject or ""):
                            raise AuthorityDenied("correction target is not canonical")
                        atom = load(key)
                        if not atom.valid:
                            raise UnavailableGuard("correction target unavailable")
                        interpretations.append(InterpretationRecord.from_dict(atom.value))
                    beliefs = db.execute(
                        "SELECT token,revision,value,valid FROM graph_atoms "
                        "WHERE bot=? AND persona=? AND type_name=? AND valid=1 "
                        "ORDER BY token LIMIT 513",
                        namespace.as_tuple + ("d07.belief_revision.v1",),
                    ).fetchall()
                    if len(beliefs) > 512:
                        raise UnavailableGuard("correction belief scan exceeds bound")
                    affected = set(request.source_refs + request.target_refs)
                    belief_refs = []
                    for token, revision, encoded, valid in beliefs:
                        value = json.loads(encoded)
                        if value.get("current") and affected.intersection(
                                value.get("source_refs", ())):
                            key = self._parse_ref(token, namespace)
                            atoms[key] = GraphAtom(key, revision, value, bool(valid))
                            belief_refs.append(token)
                    load(correction_key)
                    load(access_key(*namespace.as_tuple, correction_key.owner.subject))
                    reads = SourceCorrectionReadSetV1(
                        tuple(selected_sources), tuple(selected_accesses),
                        tuple(interpretations), tuple(belief_refs))
                    activity_id = "source-correction-" + request.operation_id
                    input_refs = (correction_key.token, *request.source_refs,
                                  *request.target_refs, *belief_refs)
                    guard_versions = {
                        kind: self._version(db, namespace, kind, "current")
                        for kind in ("scheme", "operator", "policy")
                    }
                    from .runtime.issuers import (
                        d06_source_correction_job_ref,
                        d06_source_correction_outbox_ref,
                    )
                    job_ref = d06_source_correction_job_ref(
                        namespace, activity_id, request.operation_id)
                    outbox_ref = d06_source_correction_outbox_ref(
                        namespace, activity_id, request.operation_id)
                    job_key = self._parse_ref(job_ref, namespace)
                    outbox_key = self._parse_ref(outbox_ref, namespace)
                    if (job_key.type_name != "runtime.job"
                            or outbox_key.type_name != "runtime.outbox"):
                        raise UnavailableGuard("correction runtime refs differ")
                    load(job_key)
                    load(outbox_key)
                    snapshot = GraphSnapshot(tuple(atoms.values()), (epoch,))
                    qualification = SourceQualification(
                        (correction_key.token, *request.source_refs), "reported",
                        None, now, "external_report", "eligible", None,
                        "not_applicable")
                    envelope = CommandEnvelope(
                        RUNTIME_SCHEMA,
                        OperationIdentity(
                            activity_id, None, "source-correction",
                            "source-correction", request.operation_id,
                            canonical_digest({"input_refs": list(input_refs)})),
                        authority,
                        VersionGuard(
                            snapshot.versions,
                            (QueryEpoch(namespace, "all", epoch.revision),),
                            *epochs, store._registry.catalogue_hash,
                            guard_versions["scheme"],
                            guard_versions["operator"],
                            guard_versions["policy"], (), (), ()),
                        qualification, input_refs,
                        installation_policy.root_grant.lease_id, deadline,
                        reading.monotonic_after_seconds + (
                            deadline - reading.utc_upper_bound_seconds),
                        "character-v1",
                        (request.operation_id,),
                    )
                    quote, job = self.__d11_issuer.plan_d06_source_correction_quote(
                        db, envelope, admin_policy, request,
                        installation_id=installation_policy.installation_id,
                        now_utc=now)
                    db.execute("COMMIT")
                    return snapshot, reads, envelope, quote, job
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                    raise

            snapshot, reads, pre_quote, quote, job = self._read_v2(
                owner_authority, read_candidate, owner_binding=owner_binding,
                owner_session_proof=session_proof)
            envelope = replace(pre_quote, version_guard=replace(
                pre_quote.version_guard,
                resource_lease_versions=(VersionedRef(
                    quote.quote_id, quote.version),)))
            d06 = adapter.compile_source_correction(
                envelope, correction, reads, recorded_at=now)
            proposals = [d06.proposal]
            if reads.d07_belief_refs:
                proposals.append(D07DomainProvider().source_correction_belief_proposal(
                    envelope, GraphSnapshot(tuple(
                        atom for atom in snapshot.atoms
                        if atom.key != correction_key), snapshot.epochs),
                    belief_refs=reads.d07_belief_refs,
                    correction_source_ref=d06.correction_source_ref,
                    source_refs=request.source_refs,
                    target_refs=request.target_refs))
            job_key = self._parse_ref(quote.graph_job_ref, namespace)
            outbox_key = self._parse_ref(quote.outbox_refs[0], namespace)
            idempotency_key = "source-correction:" + request.operation_id
            outbox = RuntimeOutboxValue(
                *namespace.as_tuple, envelope.identity.activity_id,
                request.operation_id, None, outbox_key.name, job.job_id,
                job_key.token, correction_key.owner.subject, idempotency_key,
                "pending", authority.activation_generation)
            d11 = DomainProposal(
                "d11", D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH,
                envelope, (job_graph_write(job), outbox_graph_write(outbox, job_key)),
                DependencySet(current_invalidation=(GraphVersion(job_key, 0),)),
                (), ())
            bundle = DomainBundle(
                envelope, (*proposals, d11), (), (), (), (),
                (idempotency_key,), (job_key.token,), (outbox_key.token,))
            self._commit_domain_bundle_v2(
                bundle, lease, correction_issuance=(
                    admin_policy, installation_policy.installation_id,
                    now, request, pre_quote, quote, owner_authority,
                    principal, owner_binding, session_proof))
            return self._read_v2(
                owner_authority, prior_or_pending, owner_binding=owner_binding,
                owner_session_proof=session_proof)
        finally:
            del self.__leases[lease]

    def read_current_recollection_experience_v1(
            self, *, namespace: NamespaceId, operation_id: str,
            experience_ref: str, actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ) -> CurrentRecollectionExperienceV1:
        return self._read_current_recollection_v1(
            namespace=namespace, operation_id=operation_id,
            experience_ref=experience_ref, projection_ref=None,
            actor_id=actor_id, principal=principal,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request)

    def read_current_recollection_projection_v1(
            self, *, namespace: NamespaceId, operation_id: str,
            projection_ref: str, actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ) -> CurrentRecollectionProjectionV1:
        return self._read_current_recollection_v1(
            namespace=namespace, operation_id=operation_id,
            experience_ref=None, projection_ref=projection_ref,
            actor_id=actor_id, principal=principal,
            owner_session_token=owner_session_token,
            owner_session_request=owner_session_request)

    def _read_current_recollection_v1(
            self, *, namespace: NamespaceId, operation_id: str,
            experience_ref: str | None, projection_ref: str | None,
            actor_id: str, principal: OwnerPrincipalV1,
            owner_session_token: str,
            owner_session_request: OwnerSessionLoginRequestV1,
    ) -> CurrentRecollectionExperienceV1 | CurrentRecollectionProjectionV1:
        """Recheck a committed C04 experience and all source ancestors now.

        D04 and D06 inspectors share one business snapshot under one read fence.
        Only content-free subjective values escape this method.
        """
        from .authority_service.contract import identifier
        from .domains.d04.affect import AffectProvider, AffectScheme
        from .domains.d04.recollection_read import (
            RecollectionSnapshotUnavailable,
            inspect_recollection_experience_snapshot,
        )
        from .domains.d06 import (
            RecollectionProjectionUnavailable,
            inspect_recollection_projection_snapshot,
            source_correction_head_key, validate_source_correction_head,
        )

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("current recollection requires production v2")
        if type(namespace) is not NamespaceId or type(principal) is not OwnerPrincipalV1:
            raise TypeError("typed recollection Owner identity is required")
        identifier(operation_id, "operation_id")
        identifier(actor_id, "actor_id")
        if (experience_ref is None) == (projection_ref is None):
            raise ValueError("exactly one recollection read ref is required")
        experience_key = (self._parse_ref(experience_ref, namespace)
                          if experience_ref is not None else None)
        projection_key = (self._parse_ref(projection_ref, namespace)
                          if projection_ref is not None else None)
        if (experience_key is not None and
                (experience_key.type_name != "d04.recollection_experience.v1"
                 or experience_key.owner.kind != "activity")):
            raise AuthorityDenied("recollection experience ref differs")
        if (projection_key is not None and
                (projection_key.type_name != "d06.recollection_projection.v1"
                 or projection_key.owner.kind != "activity")):
            raise AuthorityDenied("recollection projection ref differs")
        registration = self.__providers.get("d04")
        if registration is None or not isinstance(registration[0], AffectProvider):
            raise UnavailableGuard("registered D04 affect provider is unavailable")
        scheme = registration[0]._active_scheme
        if type(scheme) is not AffectScheme:
            raise UnavailableGuard("active D04 affect scheme is unavailable")
        store = self.__store
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        self._check_owner_session_v2(
            namespace=namespace, principal=principal, actor_id=actor_id,
            token=owner_session_token, request=owner_session_request,
            target=metadata.requirements)
        authority = AuthorityContext(
            actor_id, "d12", "recollection-read:" + secrets.token_hex(16),
            namespace, ("persona", "activity", "event"), "workbench_view",
            ("owner",), "owner-grant-v1",
            metadata.requirements.activation_generation)
        mood_key = AtomKey(Owner("persona", *namespace.as_tuple),
                           "d04.mood_field.v1", "current")

        def reader() -> CurrentRecollectionExperienceV1 | CurrentRecollectionProjectionV1:
            db = store._db
            if db.in_transaction:
                raise UnavailableGuard("recollection read requires an idle graph connection")
            db.execute("BEGIN")
            try:
                epoch = GraphStore.graph_epoch(
                    store, *namespace.as_tuple,
                    _capability=self.__graph_capability)
                epoch_row = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone()
                if epoch_row is None:
                    raise UnavailableGuard("recollection access epochs are unavailable")
                if (self._version(db, namespace, "scheme", "current")
                        != scheme.scheme_version
                        or self._version(db, namespace, "operator", "current")
                        != scheme.operator_version):
                    raise UnavailableGuard("current D04 affect scheme changed")
                receipt = self._get_operation_fenced(
                    authority, operation_id, v2=True)
                if (receipt is None or receipt.status != "committed"
                        or receipt.operation_id != operation_id
                        or receipt.activity_id != (
                            experience_key or projection_key).owner.subject
                        or len(receipt.invalidated_epochs) != 1
                        or receipt.invalidated_epochs[0].revision > epoch.revision):
                    raise UnavailableGuard("committed C04 operation is unavailable")

                atoms: dict[AtomKey, GraphAtom] = {}

                def load(key: AtomKey) -> GraphAtom:
                    if NamespaceId.from_key(key) != namespace:
                        raise AuthorityDenied("recollection source crosses namespace")
                    if key not in atoms:
                        if len(atoms) >= 512:
                            raise UnavailableGuard("recollection source closure exceeds read bound")
                        store._validate_key(key)
                        row = db.execute(
                            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                            (key.token,),
                        ).fetchone()
                        atoms[key] = (GraphAtom(key, row[0], json.loads(row[1]),
                                                bool(row[2])) if row else
                                      GraphAtom(key, 0, {}, False))
                    return atoms[key]

                selected_experience_key = experience_key
                if projection_key is not None:
                    projection_atom = load(projection_key)
                    if not projection_atom.valid:
                        raise UnavailableGuard("current D06 projection is absent")
                    try:
                        selected_experience_key = self._parse_ref(
                            projection_atom.value["experience_ref"], namespace)
                        projection_mood_key = self._parse_ref(
                            projection_atom.value["mood_ref"], namespace)
                    except (KeyError, TypeError, ValueError) as exc:
                        raise UnavailableGuard(
                            "current D06 projection refs are invalid") from exc
                    if (selected_experience_key.type_name
                            != "d04.recollection_experience.v1"
                            or selected_experience_key.owner.subject
                            != projection_key.owner.subject
                            or projection_mood_key != mood_key):
                        raise UnavailableGuard(
                            "current D06 projection experience or mood differs")
                experience_atom = load(selected_experience_key)
                mood_atom = load(mood_key)
                if not experience_atom.valid or not mood_atom.valid:
                    raise UnavailableGuard("current C04 experience or mood is absent")
                try:
                    recollection_key = self._parse_ref(
                        experience_atom.value["recollection_ref"], namespace)
                    source = self._parse_ref(
                        experience_atom.value["memory_ref"], namespace)
                    basis = tuple(mood_atom.value["source_refs"])
                    if not basis or len(basis) > 256:
                        raise ValueError("mood source set is unbounded")
                except (KeyError, TypeError, ValueError) as exc:
                    raise UnavailableGuard("current C04 source identities are invalid") from exc
                load(recollection_key)
                if (recollection_key.token not in receipt.ledger_refs
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_refs WHERE bot=? AND persona=? "
                            "AND operation_id=? AND ref_kind='experience' AND ref=?",
                            namespace.as_tuple + (operation_id, recollection_key.token),
                        ).fetchone() is None):
                    raise UnavailableGuard("C04 operation does not own the recollection")
                pending = [source.token, *basis]
                seen: set[str] = set()
                while pending:
                    ref = pending.pop()
                    if ref in seen:
                        continue
                    seen.add(ref)
                    if len(seen) > 256:
                        raise UnavailableGuard("recollection source ancestry exceeds read bound")
                    key = self._parse_ref(ref, namespace)
                    if key != source_key(*namespace.as_tuple, key.owner.subject or ""):
                        raise UnavailableGuard("recollection source ref is not canonical")
                    source_atom = load(key)
                    load(access_key(*namespace.as_tuple, key.owner.subject))
                    correction_head = load(source_correction_head_key(
                        namespace, key.owner.subject))
                    if not source_atom.valid:
                        raise UnavailableGuard("current recollection ancestor is absent")
                    if correction_head.revision:
                        try:
                            if not correction_head.valid:
                                raise ValueError("inactive correction head")
                            validate_source_correction_head(
                                correction_head.key, correction_head.value)
                        except (TypeError, ValueError) as exc:
                            raise UnavailableGuard(
                                "current recollection correction head is invalid") from exc
                        raise UnavailableGuard(
                            "current recollection interpretation awaits reevaluation")
                    try:
                        record = SourceRecord.from_dict(source_atom.value)
                    except (TypeError, ValueError) as exc:
                        raise UnavailableGuard("current recollection ancestor is invalid") from exc
                    pending.extend(source_key(*namespace.as_tuple, parent).token
                                   for parent in record.parent_source_ids)
                snapshot = GraphSnapshot(tuple(atoms.values()), (epoch,))
                try:
                    if projection_key is None:
                        candidate = inspect_recollection_experience_snapshot(
                            snapshot, namespace=namespace, audience=("owner",),
                            purpose="context", experience_ref=experience_ref,
                            mood_key=mood_key, receipt=receipt, scheme=scheme)
                    else:
                        candidate = inspect_recollection_projection_snapshot(
                            snapshot, namespace=namespace, audience=("owner",),
                            purpose="context", projection_ref=projection_ref,
                            receipt=receipt, scheme=scheme)
                except (RecollectionSnapshotUnavailable,
                        RecollectionProjectionUnavailable) as exc:
                    raise UnavailableGuard("current recollection source is unavailable") from exc
                if projection_key is None:
                    result = CurrentRecollectionExperienceV1(
                        namespace, operation_id, candidate.experience, candidate.mood,
                        candidate.source_ref, candidate.source_kind,
                        candidate.assertion_status, candidate.provenance_eligibility,
                        candidate.read_versions, candidate.epoch,
                        epoch_row[0], epoch_row[1])
                else:
                    result = CurrentRecollectionProjectionV1(
                        namespace, operation_id, candidate.projection_ref,
                        candidate.recollection_ref, candidate.experience_ref,
                        candidate.experience, candidate.mood,
                        candidate.source_ref, candidate.source_kind,
                        candidate.assertion_status, candidate.provenance_eligibility,
                        candidate.subjective_weight, candidate.subjective_tone,
                        candidate.duration_interval, candidate.read_versions,
                        candidate.epoch, epoch_row[0], epoch_row[1])
                db.execute("COMMIT")
                return result
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise

        def final_check(result: CurrentRecollectionExperienceV1) -> None:
            current = store._db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if current != (result.access_epoch, result.deletion_epoch):
                raise UnavailableGuard("recollection access or deletion epoch changed")

        return self._read_v2(
            authority, reader, owner_principal=principal,
            owner_session_proof=(owner_session_token, owner_session_request),
            final_check=final_check)

    @staticmethod
    def _owner_session_proof(actor: str, token: str | None,
                             request: object | None) -> tuple[str, object] | None:
        from .authority_service.v2_owner_session import OwnerSessionLoginRequestV1

        if token is None and request is None:
            return None
        if (type(token) is not str or not token
                or type(request) is not OwnerSessionLoginRequestV1
                or type(actor) is not str or not actor):
            raise UnavailableGuard("Owner signed session proof is unavailable")
        return token, request

    def _current_owner_principal(self, actor: str, namespace: NamespaceId):
        from .authority_service.v2_owner_contract import OwnerPrincipalV1

        if self.__owner_principal_resolver is None:
            raise UnavailableGuard("current Owner pairing is unavailable")
        try:
            principal = self.__owner_principal_resolver(actor, namespace)
        except Exception as exc:
            raise UnavailableGuard("current Owner pairing is unavailable") from exc
        if type(principal) is not OwnerPrincipalV1:
            raise UnavailableGuard("current Owner pairing is unavailable")
        return principal

    def _owner_graph_binding_locked(self, authority: AuthorityContext,
                                    principal) -> OwnerLeaseBindingV1:
        """Resolve the graph ACL and its independently finalized issue proof."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, OwnerPrincipalV1,
            canonical_digest as owner_contract_digest,
        )

        if type(principal) is not OwnerPrincipalV1:
            raise UnavailableGuard("trusted Owner principal is unavailable")
        store = self.__store
        namespace = authority.namespace
        metadata, graph_epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        db = store._db
        atom = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if (atom is None or atom[0] != 1 or atom[2] != 1
                or proof_row is None or epochs is None):
            raise UnavailableGuard("current Owner graph grant is unavailable")
        try:
            grant = json.loads(atom[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], 1, proof_row[5],
                proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable Owner graph grant is invalid") from exc
        if (atom[1] != canonical_json(grant)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["principal"] != asdict(principal)
                or grant["graph_incarnation"] != proof.graph_incarnation
                or grant["graph_incarnation"] != target.graph_incarnation
                or grant["authority_id"] != target.authority_id
                or grant["installation_id"]
                != self.__content_fence_v2.installation_grant.installation_id
                or grant["activation_generation"] != authority.activation_generation
                or grant["scope"] != "bot/persona"
                or target.namespace != namespace
                or target.activation_generation != authority.activation_generation
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > graph_epoch.revision
                or "workbench.read" not in grant["capabilities"]
                or authority.purpose not in grant["purposes"]
                or not set(authority.audience).issubset(grant["audiences"])):
            raise AuthorityDenied("Owner graph grant does not authorize this read")
        return OwnerLeaseBindingV1(
            principal, authority.actor, namespace, authority.purpose,
            authority.audience[0], grant["grant_id"], grant["scope"],
            grant["issuer_ref"], frozenset(grant["capabilities"]),
            frozenset(grant["purposes"]), frozenset(grant["audiences"]),
            proof.grant_digest, 1, epochs[0], epochs[1], proof.graph_incarnation,
            owner_contract_digest(proof), 1, 0)

    def _owner_binding_in_fence(self, authority: AuthorityContext,
                                scope: FenceScope, principal,
                                expected: OwnerLeaseBindingV1 | None,
                                owner_session_proof: tuple[str, object] | None = None,
                                ) -> tuple[OwnerAuthorizationGuardV1, OwnerLeaseBindingV1]:
        port = self.__content_fence_v2
        if (principal is None and expected is None):
            raise UnavailableGuard("Owner lease has no paired principal")
        paired = self._current_owner_principal(
            authority.actor, authority.namespace)
        if paired != (expected.principal if expected is not None else principal):
            raise UnavailableGuard("Owner pairing changed")
        reader = getattr(port, "get_current_owner_guard_for_fence", None)
        if not callable(reader):
            raise UnavailableGuard("current Owner guard fence port is unavailable")
        proof_args = {}
        if owner_session_proof is not None:
            token, request = owner_session_proof
            if request.principal != paired:
                raise UnavailableGuard("Owner signed session principal differs")
            proof_args = {
                "owner_actor_id": authority.actor,
                "owner_session_token": token,
                "owner_session_request": request,
            }
        guarded = reader(
            namespace=authority.namespace, authority_namespace=scope.authority_namespace,
            permit=scope.permit, **proof_args)
        if (type(guarded) is not tuple or len(guarded) != 2
                or type(guarded[0]) is not OwnerAuthorizationGuardV1
                or guarded[1] != scope.permit):
            raise UnavailableGuard("current Owner Authority head is unavailable")
        guard = guarded[0]
        if expected is not None:
            principal = expected.principal
        with self.__store._lock:
            metadata, epoch = self._v2_graph_stamp(authority.namespace)
            if (metadata.graph_revision != scope.graph_revision
                    or epoch != scope.graph_epoch):
                raise StaleRead("Owner graph stamp changed under read fence")
            current = self._owner_graph_binding_locked(authority, principal)
        if (guard.authority_id != scope.pinned_anchor.authority_id
                or guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or guard.namespace != authority.namespace
                or guard.authorization_revision != current.authorization_revision
                or guard.authorization_head != current.authorization_head
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != current.revocation_epoch
                or guard.pending_revoke_operation_id is not None
                or (expected is not None and current != expected)):
            raise UnavailableGuard("Owner lease differs from current grant or revoke head")
        return guard, current

    def _admin(self, bootstrap: object) -> None:
        if bootstrap is not self.__bootstrap:
            raise AuthorityDenied("host bootstrap authority required")

    @contextmanager
    def _admin_write_gate(self, namespace: NamespaceId):
        """Allow installer bookkeeping only on this authority's active holder."""
        if not isinstance(self.__store, ProductionGraphStore):
            yield
            return
        if self.__content_fence_v2 is not None:
            raise UnavailableGuard("v2 graph write path is not admitted")
        try:
            proof = self.__migration_authority.current(namespace_ref(namespace))
        except Exception as exc:
            raise UnavailableGuard("installer write activation is unavailable") from exc
        with self._content_fence(namespace, proof.generation, "write"):
            try:
                self.__migration_authority.check(
                    namespace=namespace_ref(namespace), holder=self.__holder,
                    generation=proof.generation, operation="write")
            except Exception as exc:
                raise UnavailableGuard("installer write activation is unavailable") from exc
            yield

    def set_guard_version(self, bootstrap: object, namespace: NamespaceId,
                          kind: str, ref: str, version: str | int) -> None:
        self._admin(bootstrap)
        if not isinstance(namespace, NamespaceId) or not kind or not ref or not str(version):
            raise ValueError("invalid guard version")
        store = self.__store
        with self._admin_write_gate(namespace), store._lock:
            store._ensure_open()
            store._db.execute("BEGIN IMMEDIATE")
            try:
                store._db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?) ON CONFLICT(bot,persona,kind,ref) DO UPDATE "
                    "SET version=excluded.version",
                    namespace.as_tuple + (kind, ref, str(version)),
                )
                store._db.execute("COMMIT")
            except BaseException:
                store._db.execute("ROLLBACK")
                raise

    def advance_authority_epoch(self, bootstrap: object, namespace: NamespaceId,
                                kind: str) -> int:
        self._admin(bootstrap)
        if kind not in {"access", "delete"}:
            raise ValueError("kind must be access or delete")
        store = self.__store
        with self._admin_write_gate(namespace), store._lock:
            store._ensure_open()
            store._db.execute("BEGIN IMMEDIATE")
            try:
                store._db.execute(
                    "INSERT OR IGNORE INTO graph_authority_epochs(bot,persona) VALUES(?,?)",
                    namespace.as_tuple,
                )
                column = kind + "_epoch"
                store._db.execute(
                    f"UPDATE graph_authority_epochs SET {column}={column}+1 "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                )
                revision = store._db.execute(
                    f"SELECT {column} FROM graph_authority_epochs WHERE bot=? AND persona=?",
                    namespace.as_tuple,
                ).fetchone()[0]
                store._db.execute("COMMIT")
                return revision
            except BaseException:
                store._db.execute("ROLLBACK")
                raise

    def _authorize(self, lease: object, authority: AuthorityContext,
                   domains: frozenset[str], *, owner_read: bool = False) -> None:
        try:
            ref, actor, issuer_domain, namespace, allowed, owner_scope, generation = self.__leases[lease]
        except (KeyError, TypeError):
            raise AuthorityDenied("unknown process authority") from None
        if (authority.capability_ref != ref or authority.actor != actor
                or authority.issuer_domain != issuer_domain
                or authority.namespace != namespace
                or authority.activation_generation != generation
                or not set(authority.owner_scope).issubset(owner_scope)
                or not domains.issubset(allowed)):
            raise AuthorityDenied("authority assertion does not match process grant")
        if (issuer_domain == "d12"
                and isinstance(self.__store, ProductionGraphStore)):
            binding = self.__owner_leases.get(lease)
            if (not owner_read or binding is None
                    or binding.actor != authority.actor
                    or binding.namespace != authority.namespace
                    or binding.purpose != authority.purpose
                    or authority.audience != (binding.audience,)
                    or authority.provider_policy_ref != "owner-grant-v1"):
                raise UnavailableGuard("current Owner graph read lease is unavailable")

    @staticmethod
    def _version(db, namespace: NamespaceId, kind: str, ref: str) -> str:
        row = db.execute(
            "SELECT version FROM graph_guard_versions WHERE bot=? AND persona=? "
            "AND kind=? AND ref=?", namespace.as_tuple + (kind, ref),
        ).fetchone()
        if row is None:
            raise UnavailableGuard(f"{kind} authority is unavailable")
        return row[0]

    def _admit_ingress_deadline(self, namespace: NamespaceId,
                                operation_id: str, generation: int,
                                deadline_utc: float) -> None:
        """Rebind durable UTC to this process; never trust envelope monotonic."""
        if self.__ingress_clock is None:
            raise UnavailableGuard("installation-owned ingress clock is unavailable")
        try:
            sample = self.__ingress_clock()
        except Exception as exc:
            raise UnavailableGuard("trusted ingress clock read failed") from exc
        if type(sample) is not IngressClockSample or not sample.clock_trusted:
            raise UnavailableGuard("trusted ingress clock is unavailable")
        if sample.wall_now_utc >= deadline_utc:
            raise UnavailableGuard("ingress UTC deadline has expired")
        key = (namespace, operation_id, generation)
        prior = self.__ingress_clock_bindings.get(key)
        if prior is None:
            monotonic_deadline = sample.monotonic_now + (
                deadline_utc - sample.wall_now_utc)
            if not math.isfinite(monotonic_deadline):
                raise UnavailableGuard("ingress monotonic deadline cannot be rebuilt")
            self.__ingress_clock_bindings[key] = _IngressClockBinding(
                sample.clock_epoch, deadline_utc, monotonic_deadline,
                sample.wall_now_utc, sample.monotonic_now)
            return
        if (prior.clock_epoch != sample.clock_epoch
                or prior.deadline_utc != deadline_utc
                or sample.monotonic_now < prior.last_monotonic
                or sample.wall_now_utc < prior.last_wall_utc):
            raise UnavailableGuard("ingress process clock binding changed")
        if sample.monotonic_now >= prior.monotonic_deadline:
            raise UnavailableGuard("ingress monotonic deadline has expired")
        self.__ingress_clock_bindings[key] = _IngressClockBinding(
            prior.clock_epoch, prior.deadline_utc,
            prior.monotonic_deadline, sample.wall_now_utc,
            sample.monotonic_now)

    def _exact_ingress_without_query(self, db, bundle: DomainBundle, *,
                                     deadline_check=None) -> bool:
        """Only the issued four-key first ingress may omit a range predicate."""
        if not isinstance(bundle, DomainBundle):
            return False
        envelope = bundle.envelope
        identity = envelope.identity
        authority = envelope.authority
        guard = envelope.version_guard
        namespace = authority.namespace
        if (identity.phase != "ingress" or authority.issuer_domain != "d06"
                or guard.query_epochs or len(guard.resource_lease_versions) != 1
                or len(guard.read_versions) != 4
                or any(read.revision != 0 for read in guard.read_versions)
                or len(envelope.source_qualification.source_refs) != 1
                or envelope.input_refs != envelope.source_qualification.source_refs
                or tuple(proposal.domain for proposal in bundle.proposals) != ("d06", "d11")
                or len(bundle.persistent_job_refs) != 1
                or len(bundle.outbox_refs) != 1):
            return False
        if authority.capability_ref != _operation_capability_ref(
                namespace, authority.actor, "d06", frozenset({"d06", "d11"}),
                authority.activation_generation, identity.operation_id):
            return False
        try:
            source = AtomKey.from_token(envelope.source_qualification.source_refs[0])
            if (source != source_key(*namespace.as_tuple, source.owner.subject or "")
                    or NamespaceId.from_key(source) != namespace):
                return False
            access = access_key(*namespace.as_tuple, source.owner.subject or "")
            job = AtomKey.from_token(bundle.persistent_job_refs[0])
            outbox = AtomKey.from_token(bundle.outbox_refs[0])
        except (TypeError, ValueError):
            return False
        if (job.type_name != "runtime.job" or outbox.type_name != "runtime.outbox"
                or job.owner.kind != "activity" or outbox.owner.kind != "activity"
                or job.owner.subject != identity.activity_id
                or outbox.owner.subject != identity.activity_id
                or any(NamespaceId.from_key(key) != namespace for key in (job, outbox))
                or {read.key for read in guard.read_versions}
                != {source, access, job, outbox}
                or {write.key for write in bundle.proposals[0].typed_writes}
                != {source, access}
                or {write.key for write in bundle.proposals[1].typed_writes}
                != {job, outbox}):
            return False
        row = db.execute(
            "SELECT activation_generation,quote_id,policy_json "
            "FROM runtime_ingress_issuance "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (identity.operation_id,),
        ).fetchone()
        sealed = db.execute(
            "SELECT bundle_digest FROM ingress_first_observations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (identity.operation_id,),
        ).fetchone()
        if (row is None or row[0] != authority.activation_generation
                or row[1] != guard.resource_lease_versions[0].ref
                or sealed is None or sealed[0] != bundle.digest):
            return False
        try:
            policy = IngressIssuancePolicy(**json.loads(row[2]))
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("durable ingress policy is invalid") from exc
        if policy.deadline_utc != envelope.deadline_utc:
            return False
        if deadline_check is None:
            self._admit_ingress_deadline(
                namespace, identity.operation_id,
                authority.activation_generation, policy.deadline_utc)
        else:
            deadline_check(policy.deadline_utc)
        return True

    def _current_scene_proof_locked(self, db, namespace, receipt, source_atom,
                                    owner_guard, graph_epoch):
        """Join current graph heads to a committed ingress in this SQLite read."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_contract_digest,
        )
        from .domains.d03 import RoleBinding, RoleBindingRequest
        from .runtime.first_ingress_v2 import scene_ref_for_conversation

        if (type(owner_guard) is not OwnerAuthorizationGuardV1
                or source_atom is None or not source_atom.valid
                or source_atom.key.type_name != "memory.source"):
            raise UnavailableGuard("current scene Owner or source is unavailable")
        source = SourceRecord.from_dict(source_atom.value)
        identity = json.loads(receipt.identity_json)
        if (type(identity) is not dict
                or identity.get("namespace") != list(namespace.as_tuple)
                or identity.get("source_ref") != source.source_id
                or source_atom.key.owner.subject != source.source_id
                or source.recorded_at != receipt.learned_at):
            raise UnavailableGuard("current scene ingress source differs")
        scene_ref = scene_ref_for_conversation(
            namespace, identity["platform_ref"], identity["conversation_ref"])
        visibility = identity["visibility"]
        metadata, current_epoch = self._v2_graph_stamp(namespace)
        if current_epoch != graph_epoch:
            raise StaleRead("current scene graph epoch changed")
        target = metadata.requirements
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if grant_row is None or proof_row is None or epochs is None:
            raise UnavailableGuard("current scene Owner graph proof is absent")
        try:
            grant = json.loads(grant_row[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], grant["grant_revision"],
                proof_row[5], proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current scene Owner graph proof is invalid") from exc
        if (grant_row[0] != grant["grant_revision"] or grant_row[2] != 1
                or grant_row[1] != canonical_json(grant)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["activation_generation"] != target.activation_generation
                or grant["scope"] != "bot/persona"
                or target.namespace != namespace
                or grant["graph_incarnation"] != target.graph_incarnation
                or proof.graph_incarnation != target.graph_incarnation
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > graph_epoch.revision
                or owner_guard.namespace != namespace
                or owner_guard.authority_id != target.authority_id
                or owner_guard.authority_id != grant["authority_id"]
                or owner_guard.installation_id != grant["installation_id"]
                or owner_guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or owner_guard.authorization_revision != grant["grant_revision"]
                or owner_guard.authorization_head != owner_contract_digest(proof)
                or target.revocation_epoch
                != owner_guard.minimum_revocation_epoch
                or owner_guard.minimum_revocation_revision != 0
                or owner_guard.minimum_revocation_epoch != 0
                or owner_guard.pending_revoke_operation_id is not None):
            # The only durable graph authorization here is the initial issue.
            # A later Owner head requires a separately authorized refresh.
            raise UnavailableGuard("current scene Owner head lacks matching graph authorization")
        role, _, role_epoch, _ = self._scene_binding_state_locked(
            namespace, owner_guard)
        if role_epoch != graph_epoch:
            raise StaleRead("current scene D01 epoch changed")
        rows = db.execute(
            "SELECT token,revision,value FROM graph_atoms WHERE bot=? AND persona=? "
            "AND owner_kind='scene' AND subject=? "
            "AND type_name='d03.role_binding' AND valid=1",
            namespace.as_tuple + (scene_ref,),
        ).fetchall()
        applicable = []
        for token, revision, encoded in rows:
            key = AtomKey.from_token(token)
            try:
                value = json.loads(encoded)
                binding = RoleBinding(**{
                    **value, "norm_refs": tuple(value["norm_refs"]),
                    "source_refs": tuple(value["source_refs"]),
                })
                at_occurrence = RoleBindingRequest(
                    f"persona:{namespace.persona_id}", None, None, scene_ref,
                    "message", "context", source.occurred_at, True)
                at_learning = replace(at_occurrence, at_time=source.recorded_at)
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("current scene binding is invalid") from exc
            if (key.name != binding.role_binding_id
                    or key.owner.subject != scene_ref
                    or revision != binding.binding_version
                    or binding.scene_ref != scene_ref):
                raise UnavailableGuard("current scene binding identity differs")
            if (binding.scope_selector == "scene"
                    and binding.visibility_scope == visibility
                    and binding.target_entity_ref is None
                    and binding.group_ref is None
                    and binding.applies_to(at_occurrence)
                    and binding.applies_to(at_learning)):
                applicable.append((key, revision, binding))
        if len(applicable) != 1:
            raise UnavailableGuard("current scene has no unique applicable binding")
        key, revision, binding = applicable[0]
        receipt_row = db.execute(
            "SELECT r.operation_id,r.receipt_json,r.pre_graph_revision,"
            "r.pre_graph_epoch,r.post_graph_revision,r.post_graph_epoch,"
            "h.value,h.valid FROM graph_history AS h "
            "JOIN graph_scene_binding_receipts_v1 AS r "
            "ON r.bot=h.event_bot AND r.persona=h.event_persona "
            "AND r.operation_id=h.event_id "
            "WHERE h.token=? AND h.revision=? "
            "AND h.event_session='d03-scene-binding'",
            (key.token, revision),
        ).fetchone()
        if receipt_row is None:
            raise UnavailableGuard("current scene binding lacks fenced history receipt")
        try:
            payload = json.loads(receipt_row[1])
            payload["namespace"] = NamespaceId(**payload["namespace"])
            binding_receipt = SceneBindingReceiptV1(**payload)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current scene binding receipt is invalid") from exc
        if (receipt_row[1] != canonical_json(asdict(binding_receipt))
                or receipt_row[6] != encoded or receipt_row[7] != 1
                or receipt_row[4] != receipt_row[2] + 1
                or receipt_row[5] != receipt_row[3] + 1
                or binding_receipt.operation_id != receipt_row[0]
                or binding_receipt.namespace != namespace
                or binding_receipt.scene_ref != scene_ref
                or binding_receipt.binding_id != binding.role_binding_id
                or binding_receipt.role_head_id != role.head_id
                or binding_receipt.owner_grant_id != grant["grant_id"]
                or binding_receipt.owner_authorization_head
                != owner_guard.authorization_head
                or binding_receipt.graph_incarnation != target.graph_incarnation
                or binding_receipt.graph_revision != receipt_row[4]
                or binding_receipt.graph_epoch != receipt_row[5]
                or binding_receipt.graph_revision > metadata.graph_revision
                or binding_receipt.graph_epoch > graph_epoch.revision):
            raise UnavailableGuard("current scene binding receipt differs from current heads")
        return CurrentSceneProof(
            source.source_id, scene_ref, visibility, source.recorded_at,
            graph_epoch.revision, target.graph_incarnation, grant["grant_id"],
            owner_guard.authorization_revision, owner_guard.authorization_head,
            owner_guard.minimum_revocation_epoch, role.head_id,
            binding.role_binding_id, revision, binding_receipt.operation_id,
            binding_receipt.graph_epoch,
        )

    def _check_guard(self, db, bundle: DomainBundle, *,
                     ingress_deadline_check=None,
                     scene_owner_guard=None) -> GraphSnapshot:
        store = self.__store
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        guard = envelope.version_guard
        if guard.catalogue_version != store._registry.catalogue_hash:
            raise StaleRead("type catalogue changed")
        for kind, version in (("scheme", guard.scheme_version),
                              ("operator", guard.operator_version),
                              ("policy", guard.policy_version)):
            if self._version(db, namespace, kind, "current") != version:
                raise StaleRead(f"{kind} version changed")
        if self._version(db, namespace, "activation", "current") != str(
                envelope.authority.activation_generation):
            raise StaleRead("activation generation changed")
        # A namespace string flag cannot prove a particular worker still owns
        # its job. Runtime job identity/fence is checked inside the same commit.
        budget = get_budget_lease(db, envelope.parent_budget_lease_ref)
        if (budget.state != "active" or
                (budget.bot_id, budget.persona_id) != namespace.as_tuple):
            raise UnavailableGuard("parent budget lease is unavailable for this namespace")
        epoch_row = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        access_epoch, delete_epoch = epoch_row if epoch_row else (0, 0)
        if (guard.access_epoch, guard.delete_epoch) != (access_epoch, delete_epoch):
            raise StaleRead("access or deletion epoch changed")
        graph_epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        if not guard.query_epochs and not self._exact_ingress_without_query(
                db, bundle, deadline_check=ingress_deadline_check):
            raise UnavailableGuard("namespace query epoch is required")
        for query in guard.query_epochs:
            if query.namespace != namespace or query.revision != graph_epoch.revision:
                raise StaleRead("positive or negative query changed")
        for kind, refs in (("source_grant", guard.source_grant_refs),
                           ("focus_lease", guard.focus_lease_versions),
                           ("resource_lease", guard.resource_lease_versions)):
            for item in refs:
                if self._version(db, namespace, kind, item.ref) != str(item.version):
                    raise StaleRead(f"{kind} changed")
        atoms = []
        for read in guard.read_versions:
            if NamespaceId.from_key(read.key) != namespace:
                raise AuthorityDenied("cross-namespace read")
            store._validate_key(read.key)
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (read.key.token,),
            ).fetchone()
            revision = row[0] if row else 0
            if revision != read.revision:
                raise StaleRead("read version changed")
            atoms.append(GraphAtom(read.key, revision, json.loads(row[1]), bool(row[2]))
                         if row else GraphAtom(read.key, 0, {}, False))
        ingress_receipts = []
        host_observed = any(
                proposal.domain == "d03" and any(
                    write.key.type_name == "d03.world_event"
                    and (write.value.get("kind") == "message_received"
                         or write.value.get("reality") == "host_observed")
                    for write in proposal.typed_writes)
                for proposal in bundle.proposals)
        if host_observed:
            from .runtime.ingress_observation import read_committed_ingress_identity

            for source_ref in envelope.source_qualification.source_refs:
                key = self._parse_ref(source_ref, namespace)
                if key.type_name != "memory.source" or key.owner.subject is None:
                    raise UnavailableGuard("host arrival lacks a source identity")
                receipt = read_committed_ingress_identity(
                    db, namespace, key.owner.subject)
                if receipt is not None:
                    ingress_receipts.append(receipt)
        scene_proofs = ()
        if host_observed and scene_owner_guard is not None:
            if len(ingress_receipts) != 1 or len(envelope.source_qualification.source_refs) != 1:
                raise UnavailableGuard("current scene needs one committed host ingress")
            source_key_current = self._parse_ref(
                envelope.source_qualification.source_refs[0], namespace)
            source_atom = next((atom for atom in atoms
                                if atom.key == source_key_current), None)
            scene_proofs = (self._current_scene_proof_locked(
                db, namespace, ingress_receipts[0], source_atom,
                scene_owner_guard, graph_epoch),)
        return GraphSnapshot(tuple(atoms), (graph_epoch,),
                             tuple(ingress_receipts), scene_proofs)

    @staticmethod
    def _parse_ref(ref: str, namespace: NamespaceId) -> AtomKey:
        key = AtomKey.from_token(ref)
        if NamespaceId.from_key(key) != namespace:
            raise AuthorityDenied("bundle reference crosses namespace")
        return key

    def _first_ingress_boundary_locked(self, namespace: NamespaceId,
                                       guard: OwnerAuthorizationGuardV1,
                                       scene_ref: str, visibility: str,
                                       at_time: float) -> None:
        """Require the current Owner, active role, and fenced scene graph heads."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_contract_digest,
        )
        from .domains.d03 import RoleBinding, RoleBindingRequest

        db = self.__store._db
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if proof_row is None or epochs != (1, 0):
            raise UnavailableGuard("first ingress current Owner proof is absent")
        proof = OwnerGraphCommitProofV1(
            namespace, proof_row[0], proof_row[1], proof_row[2],
            proof_row[3], proof_row[4], 1, proof_row[5], proof_row[6],
            proof_row[7],
        )
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        if grant_row is None or grant_row[0] != 1 or grant_row[2] != 1:
            raise UnavailableGuard("first ingress current Owner grant is absent")
        grant = json.loads(grant_row[1])
        validate_owner_grant_v1(grant)
        metadata, _ = self._v2_graph_stamp(namespace)
        if (proof_row[8] != canonical_json(asdict(proof))
                or grant_row[1] != canonical_json(grant)
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or grant["grant_id"] != proof.grant_id
                or grant["issue_operation_id"] != proof.operation_id
                or grant["graph_incarnation"] != proof.graph_incarnation
                or proof.graph_incarnation != metadata.requirements.graph_incarnation
                or proof.graph_access_epoch != epochs[0]
                or guard.namespace != namespace
                or guard.authority_id != grant["authority_id"]
                or guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or guard.installation_id != grant["installation_id"]
                or guard.authorization_revision != 1
                or guard.authorization_head != owner_contract_digest(proof)
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != 0
                or guard.pending_revoke_operation_id is not None):
            raise UnavailableGuard("first ingress current Owner head differs")
        role, _, _, _ = self._scene_binding_state_locked(namespace, guard)
        rows = db.execute(
            "SELECT token,revision,value FROM graph_atoms WHERE bot=? AND persona=? "
            "AND owner_kind='scene' AND subject=? "
            "AND type_name='d03.role_binding' AND valid=1",
            namespace.as_tuple + (scene_ref,),
        ).fetchall()
        if len(rows) != 1:
            raise UnavailableGuard("first ingress current scene binding is absent")
        token, revision, encoded = rows[0]
        key = AtomKey.from_token(token)
        value = json.loads(encoded)
        try:
            binding = RoleBinding(**{
                **value, "norm_refs": tuple(value["norm_refs"]),
                "source_refs": tuple(value["source_refs"]),
            })
            request = RoleBindingRequest(
                f"persona:{namespace.persona_id}", None, None, scene_ref,
                "message", "context", at_time, True)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("first ingress current scene binding is invalid") from exc
        if (key.name != binding.role_binding_id
                or key.owner.subject != scene_ref
                or revision != binding.binding_version
                or binding.scene_ref != scene_ref
                or binding.scope_selector != "scene"
                or binding.visibility_scope != visibility
                or not binding.applies_to(request)):
            raise AuthorityDenied("first ingress scene does not admit this conversation")
        receipt_row = db.execute(
            "SELECT r.receipt_json FROM graph_history AS h "
            "JOIN graph_scene_binding_receipts_v1 AS r "
            "ON r.bot=h.event_bot AND r.persona=h.event_persona "
            "AND r.operation_id=h.event_id "
            "WHERE h.token=? AND h.revision=? "
            "AND h.event_session='d03-scene-binding'",
            (token, revision),
        ).fetchone()
        if receipt_row is None:
            raise UnavailableGuard("first ingress scene lacks fenced binding receipt")
        scene_receipt = json.loads(receipt_row[0])
        if (scene_receipt.get("scene_ref") != scene_ref
                or scene_receipt.get("binding_id") != binding.role_binding_id
                or scene_receipt.get("role_head_id") != role.head_id
                or scene_receipt.get("owner_grant_id") != proof.grant_id
                or scene_receipt.get("owner_authorization_head")
                != guard.authorization_head):
            raise UnavailableGuard("first ingress scene receipt differs from current heads")

    def commit_first_ingress_v2(self, bootstrap: object, host: IngressHostFacts,
                                installation_policy, clock_policy,
                                encoding_policy,
                                reply_source_policy=None) -> CommitReceipt:
        """Commit the first reported source and encoding job in one fenced write."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .domains.d06 import D06DomainAdapter, SourceAdmission
        from .host.authority_profile import (
            AdminIngressClockPolicy, AdminIngressEncodingPolicy,
            AdminD06PrivateReplySourcePolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d11_types import runtime_job_key, runtime_outbox_key
        from .runtime.first_ingress_bundle import build_first_ingress_bundle
        from .runtime.first_ingress_v2 import (
            finish_digest, ingress_ids, policy_identity,
            scene_ref_for_conversation, trusted_upper,
        )
        from .runtime.issuers import (
            D02ResourceIssuer, D11BudgetJobIssuer, ResourceQuote,
            install_schema as install_issuer_schema,
        )
        from .runtime_contracts import (
            RUNTIME_SCHEMA, CommandEnvelope, OperationIdentity,
            VersionGuard, VersionedRef,
        )

        self._admin(bootstrap)
        if (installation_policy is None or clock_policy is None
                or encoding_policy is None):
            raise UnavailableGuard("v2 first ingress administrator policy missing; HOLD")
        if (type(host) is not IngressHostFacts
                or type(installation_policy) is not AdminInstallationPolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or type(encoding_policy) is not AdminIngressEncodingPolicy):
            raise TypeError("typed v2 first ingress facts and policies required")
        if reply_source_policy is not None and (
                type(reply_source_policy) is not AdminD06PrivateReplySourcePolicy
                or reply_source_policy.version != 1
                or reply_source_policy.scope != "private_conversation"
                or reply_source_policy.grant_expression is not True):
            raise AuthorityDenied("private reply source policy differs from host scope")
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer):
            raise UnavailableGuard("v2 first ingress authorities are unavailable")
        namespace = host.namespace
        policy = installation_policy
        if namespace != policy.namespace or host.lineage.source_ref == "":
            raise AuthorityDenied("first ingress namespace or source differs")
        scene_ref = scene_ref_for_conversation(
            namespace, host.platform_ref, host.conversation_ref)
        source_identity, activity_id, operation_id, job_id, outbox_id, idem = (
            ingress_ids(host.lineage.source_ref))
        fingerprint = ingress_host_fingerprint(host)
        identity_json = policy_identity(
            policy, clock_policy, encoding_policy, fingerprint,
            host.lineage.source_ref, host.conversation_ref)
        if reply_source_policy is not None:
            identity_data = json.loads(identity_json)
            identity_data["d06_private_reply_source"] = asdict(reply_source_policy)
            identity_json = canonical_json(identity_data)
        attempt_id = "first-ingress-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            "identity": identity_json,
        })[:48]
        grant = policy.root_grant
        if ("d06.encode_source" not in grant.allowed_work_kinds
                or any(amount > grant.max_ceiling.get(name, 0)
                       for name, amount in encoding_policy.quote_ceiling.items())):
            raise UnavailableGuard("root grant does not admit source encoding ceiling")

        # All Authority calls precede the business lock. The profile's signed
        # root grant is read from the provisioned DB; no new grant is minted.
        with store._lock:
            provision = self._provision_row(store._db, namespace)
            if provision is None:
                raise UnavailableGuard("v2 namespace is not provisioned")
            genesis = self._decode_provision_receipt(provision)
            metadata, epoch = self._v2_graph_stamp(namespace)
            stored_grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                store._db, grant.lease_id, grant.version)
            if (stored_grant != grant or signature != genesis.root_grant_signature
                    or genesis.root_grant_id != grant.grant_id
                    or genesis.root_lease_id != grant.lease_id
                    or genesis.installation_id != policy.installation_id
                    or genesis.manifest_digest != policy.manifest_digest):
                raise UnavailableGuard("provisioned signed root grant differs")
            row = store._db.execute(
                "SELECT identity_json,learned_at,deadline_utc,fence_attempt_id,"
                "requirements_json,anchor_json,graph_revision,graph_epoch,"
                "monotonic_deadline "
                "FROM graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or target.activation_generation != genesis.generation):
            raise UnavailableGuard("v2 first ingress recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("v2 first ingress Authority anchor differs")
        reading = None
        upper = None
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))

        def read_clock():
            try:
                sample = port.read_ingress_clock(clock_policy)
                return sample, trusted_upper(sample)
            except Exception as exc:
                raise UnavailableGuard("paired ingress clock unavailable; HOLD") from exc

        if row is None:
            reading, upper = read_clock()
            learned_at = upper
            deadline = min(
                math.nextafter(math.fsum((learned_at,
                    encoding_policy.deadline_after_seconds)), -math.inf),
                grant.valid_until_utc)
            if (deadline <= learned_at or
                    host.occurred_at is not None and host.occurred_at > learned_at):
                raise UnavailableGuard("paired ingress clock cannot admit source")
            monotonic_deadline = reading.monotonic_after_seconds + (
                deadline - reading.utc_upper_bound_seconds)
            if not math.isfinite(monotonic_deadline):
                raise UnavailableGuard("paired ingress monotonic deadline is invalid")
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("first ingress pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_first_ingress_intents_v2"
                        "(bot,persona,operation_id,identity_json,learned_at,"
                        "deadline_utc,fence_attempt_id,requirements_json,"
                        "anchor_json,graph_revision,graph_epoch,"
                        "monotonic_deadline) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (operation_id, identity_json,
                        learned_at, deadline, attempt_id, requirements_json,
                        anchor_json, metadata.graph_revision, epoch.revision,
                        monotonic_deadline),
                    )
                    row = db.execute(
                        "SELECT identity_json,learned_at,deadline_utc,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,monotonic_deadline "
                        "FROM graph_first_ingress_intents_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if (row[0] != identity_json or row[3] != attempt_id
                or row[4] != requirements_json or row[5] != anchor_json):
            raise UnavailableGuard("durable first ingress intent identity differs")
        learned_at, deadline = row[1:3]
        if (not math.isfinite(learned_at) or not math.isfinite(deadline)
                or not math.isfinite(row[8])
                or deadline <= learned_at or deadline > grant.valid_until_utc):
            raise UnavailableGuard("durable first ingress time is invalid")

        def deadline_check(expected):
            if expected != deadline or trusted_upper(reading) >= deadline:
                raise UnavailableGuard("first ingress paired deadline expired")

        with store._lock:
            db = store._db
            saved = db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_first_ingress_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            receipt = self._get_operation_fenced(
                AuthorityContext(policy.administrator_holder, "d06", "audit",
                    namespace, ("event", "activity"), "context",
                    (host.conversation_ref,), grant.policy_ref,
                    target.activation_generation), operation_id, v2=True)
        if receipt is not None or rejected is not None:
            if (receipt is None) == (rejected is None):
                raise UnavailableGuard("first ingress terminal ledgers disagree")
            encoded = saved[1] if receipt is not None and saved else (
                rejected[1] if rejected else None)
            if encoded is None:
                raise UnavailableGuard("first ingress terminal permit absent")
            permit = from_wire(json.loads(encoded))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject):
                raise UnavailableGuard("first ingress terminal permit differs")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise FirstIngressOutcomeUnknown(
                    operation_id, "first ingress terminal Authority status unknown; HOLD"
                ) from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("first ingress Authority status differs")
            if receipt is not None:
                with store._lock:
                    obs = store._db.execute(
                        "SELECT content_fingerprint,learned_at,bundle_digest "
                        "FROM ingress_first_observations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    identity_row = store._db.execute(
                        "SELECT identity_json,content_fingerprint,learned_at,"
                        "bundle_digest FROM graph_first_ingress_identity_v1 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() if store._db.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' AND "
                        "name='graph_first_ingress_identity_v1'").fetchone() else None
                if (saved[0] != receipt.operation_digest
                        or obs != (fingerprint, learned_at, receipt.operation_digest)
                        or identity_row != (
                            ingress_host_identity_json(host, operation_id),
                            fingerprint, learned_at, receipt.operation_digest)
                        or saved[2:4] != row[6:8]
                        or saved[4] != saved[2] + 1
                        or saved[5] != receipt.invalidated_epochs[0].revision
                        or saved[5] <= saved[3]
                        or saved[6] != "finish:" + attempt_id
                        or saved[7] != finish_digest(
                            attempt_id, permit.token, operation_id,
                            receipt.operation_digest)):
                    raise UnavailableGuard("first ingress business receipt differs")
                if state == "active":
                    if (metadata.graph_revision != saved[4]
                            or epoch.revision != saved[5]):
                        raise UnavailableGuard("first ingress committed stamp differs")
                    scope = FenceScope(namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id,
                        permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                            row[7]), row[6])
                    try:
                        if port.validate_fence(scope) != permit:
                            raise UnavailableGuard("first ingress permit changed")
                        port.finish_fence(scope, request_id=saved[6],
                                          request_digest=saved[7])
                    except Exception as exc:
                        raise FirstIngressOutcomeUnknown(
                            operation_id,
                            "first ingress committed finish unconfirmed; HOLD"
                        ) from exc
                elif (metadata.graph_revision < saved[4]
                      or epoch.revision < saved[5]):
                    raise UnavailableGuard(
                        "finished first ingress lost its business recovery stamp")
                return receipt
            if (rejected[0] != "rejected_no_commit"
                    or rejected[2:4] != row[6:8]
                    or rejected[4] != "abort:" + attempt_id
                    or rejected[5] != finish_digest(
                        attempt_id, permit.token, operation_id, None,
                        rejected=True)):
                raise UnavailableGuard("first ingress rejection differs")
            scope = FenceScope(namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor, NamespaceEpoch(*namespace.as_tuple, row[7]),
                row[6])
            if state == "active":
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("first ingress rejected permit changed")
                try:
                    port.finish_fence(scope, request_id=rejected[4],
                                      request_digest=rejected[5])
                except Exception as exc:
                    raise FirstIngressOutcomeUnknown(
                        operation_id,
                        "first ingress rejected finish unconfirmed; HOLD"
                    ) from exc
            raise UnavailableGuard("first ingress terminal rejected_no_commit")
        if reading is None:
            reading, upper = read_clock()
        if upper >= deadline or upper >= grant.valid_until_utc:
            raise UnavailableGuard("first ingress paired deadline expired")
        if (metadata.graph_revision, epoch.revision) != row[6:8]:
            raise UnavailableGuard("uncommitted first ingress pre-stamp changed")
        try:
            # Authority treats the original active operation ID as an exact
            # retry, including after a lost begin response or process crash.
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress begin outcome unknown; HOLD original attempt") from exc
        scope = FenceScope(namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("first ingress write permit changed")
        guard_reader = getattr(port, "get_current_owner_guard_for_fence", None)
        try:
            if not callable(guard_reader):
                raise UnavailableGuard("first ingress current Owner guard is unavailable")
            guarded = guard_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("first ingress current Owner guard is unavailable")
            owner_guard = guarded[0]
        except Exception:
            self._reject_first_ingress_v2(
                namespace, operation_id, row, permit, scope)
            raise

        actor = policy.administrator_holder
        lease, capability_ref = self.grant(
            bootstrap, actor=actor, issuer_domain="d06", namespace=namespace,
            domains=("d06", "d11"),
            activation_generation=target.activation_generation,
            operation_id=operation_id)
        authority = AuthorityContext(
            actor, "d06", capability_ref, namespace, ("event", "activity"),
            "context", (host.conversation_ref,), grant.policy_ref,
            target.activation_generation)
        source = source_key(*namespace.as_tuple, host.lineage.source_ref)
        access = access_key(*namespace.as_tuple, host.lineage.source_ref)
        job_key = runtime_job_key(*namespace.as_tuple, activity_id, job_id)
        outbox_key = runtime_outbox_key(*namespace.as_tuple, activity_id, outbox_id)
        quote_id = "ingress-q-" + hashlib.sha256(
            canonical_json([*namespace.as_tuple, operation_id]).encode()
        ).hexdigest()[:40]
        ingress_policy = IngressIssuancePolicy(
            grant.lease_id, dict(encoding_policy.quote_ceiling),
            dict(grant.max_ceiling), deadline, grant.valid_until_utc,
            row[8],
            encoding_policy.snapshot_ref, encoding_policy.resource_ref,
            encoding_policy.character_interval_ref)
        result = None
        transaction_rolled_back = False
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("first ingress recovery stamp changed")
                    if db.execute(
                        "SELECT identity_json,learned_at,deadline_utc,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,monotonic_deadline "
                        "FROM graph_first_ingress_intents_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() != row:
                        raise UnavailableGuard("first ingress durable intent changed")
                    deadline_check(deadline)
                    for key in (source, access, job_key, outbox_key):
                        if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                      (key.token,)).fetchone():
                            raise StaleRead("first ingress revision-0 key changed")
                    if db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone():
                        raise EventConflict("first ingress operation already committed")
                    current_grant = self.__d11_issuer.current_budget_grant(
                        db, grant.lease_id)
                    if current_grant != grant:
                        raise AuthorityDenied("root grant changed before ingress")
                    self._first_ingress_boundary_locked(
                        namespace, owner_guard, scene_ref, host.visibility,
                        trusted_upper(reading))
                    budget = get_budget_lease(db, grant.lease_id)
                    if budget.state != "active" or any(
                            amount > budget.limits.get(name, 0)
                            - budget.used.get(name, 0)
                            - budget.reserved.get(name, 0)
                            - budget.unconfirmed.get(name, 0)
                            for name, amount in encoding_policy.quote_ceiling.items()):
                        raise UnavailableGuard("root budget has insufficient capacity")
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    guard_data = {
                        "access_epoch": epochs[0], "delete_epoch": epochs[1],
                        "scheme": self._version(db, namespace, "scheme", "current"),
                        "operator": self._version(db, namespace, "operator", "current"),
                        "policy": self._version(db, namespace, "policy", "current"),
                    }
                    admission = SourceAdmission(
                        host.lineage.source_ref, host.text, host.sender_ref,
                        host.lineage.source_kind, "reported",
                        host.lineage.evidence_eligibility,
                        host.lineage.internal_activity_actuality,
                        host.occurred_at, learned_at,
                        host.lineage.provenance_family,
                        (host.conversation_ref,),
                        (("context", "consolidation", "expression")
                         if (reply_source_policy is not None
                             and host.visibility == "private") else
                         ("context", "consolidation")))
                    candidate = D06DomainAdapter(namespace).admit_source(admission)
                    command = CommandEnvelope(
                        RUNTIME_SCHEMA,
                        OperationIdentity(activity_id, None, "first", "ingress",
                            operation_id, canonical_digest({
                                "input_refs": list(candidate.qualification.source_refs)})),
                        authority,
                        VersionGuard(
                            tuple(GraphVersion(key, 0) for key in
                                  (source, access, job_key, outbox_key)),
                            (), epochs[0], epochs[1],
                            store._registry.catalogue_hash,
                            guard_data["scheme"], guard_data["operator"],
                            guard_data["policy"], (), (),
                            (VersionedRef(quote_id, 1),)),
                        candidate.qualification,
                        candidate.qualification.source_refs,
                        grant.lease_id, deadline,
                        ingress_policy.monotonic_deadline,
                        encoding_policy.character_interval_ref,
                        (host.message_id,))
                    install_issuer_schema(db)
                    db.execute("""CREATE TABLE IF NOT EXISTS ingress_first_observations(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        content_fingerprint TEXT NOT NULL,
                        learned_at REAL NOT NULL CHECK(learned_at > 0),
                        bundle_digest TEXT,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    db.execute("""CREATE TABLE IF NOT EXISTS graph_first_ingress_identity_v1(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        source_ref TEXT NOT NULL,
                        platform_ref TEXT NOT NULL,
                        conversation_ref TEXT NOT NULL,
                        sender_ref TEXT NOT NULL,
                        message_id TEXT NOT NULL,
                        visibility TEXT NOT NULL,
                        identity_json TEXT NOT NULL,
                        content_fingerprint TEXT NOT NULL,
                        learned_at REAL NOT NULL,
                        bundle_digest TEXT NOT NULL,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    db.execute("""CREATE TABLE IF NOT EXISTS runtime_ingress_issuance(
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        activation_generation INTEGER NOT NULL,
                        request_digest TEXT NOT NULL, policy_json TEXT NOT NULL,
                        quote_id TEXT NOT NULL, grant_id TEXT NOT NULL,
                        guard_json TEXT NOT NULL,
                        source_qualification_json TEXT,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    if "source_qualification_json" not in {
                            column[1] for column in db.execute(
                                "PRAGMA table_info(runtime_ingress_issuance)")}:
                        db.execute("ALTER TABLE runtime_ingress_issuance "
                                   "ADD COLUMN source_qualification_json TEXT")
                    db.execute("""CREATE TRIGGER IF NOT EXISTS
                        runtime_ingress_issuance_no_update_v2
                        BEFORE UPDATE ON runtime_ingress_issuance
                        BEGIN SELECT RAISE(ABORT, 'ingress issuance is immutable'); END
                    """)
                    db.execute(
                        "INSERT INTO ingress_first_observations"
                        "(bot,persona,operation_id,content_fingerprint,"
                        "learned_at,bundle_digest) VALUES(?,?,?,?,?,NULL)",
                        namespace.as_tuple + (operation_id, fingerprint,
                                              learned_at))
                    quote = ResourceQuote(
                        quote_id, 1, *namespace.as_tuple, activity_id,
                        operation_id, None, grant.lease_id,
                        "d06.encode_source", encoding_policy.snapshot_ref,
                        deadline, encoding_policy.resource_ref, job_key.token,
                        (outbox_key.token,), (), dict(encoding_policy.quote_ceiling),
                        None, deadline)
                    self.__d02_issuer.issue_quote(db, quote)
                    db.execute(
                        "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + ("resource_lease", quote_id, "1"))
                    db.execute(
                        "INSERT INTO runtime_ingress_issuance"
                        "(bot,persona,operation_id,activation_generation,"
                        "request_digest,policy_json,quote_id,grant_id,guard_json,"
                        "source_qualification_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, target.activation_generation,
                            canonical_digest(identity_json),
                            canonical_json(asdict(ingress_policy)), quote_id,
                            grant.grant_id, canonical_json(guard_data),
                            canonical_serialize(asdict(candidate.qualification))))
                    now_utc = trusted_upper(reading)
                    job = self.__d11_issuer.job_for(
                        command, db, now_utc=now_utc)
                    bundle = build_first_ingress_bundle(
                        command, job, admission,
                        source_identity=source_identity,
                        payload_ref=host.lineage.source_ref,
                        idempotency_key=idem)
                    db.execute(
                        "INSERT INTO graph_first_ingress_identity_v1"
                        "(bot,persona,operation_id,source_ref,platform_ref,"
                        "conversation_ref,sender_ref,message_id,visibility,"
                        "identity_json,content_fingerprint,learned_at,"
                        "bundle_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, host.lineage.source_ref,
                            host.platform_ref, host.conversation_ref,
                            host.sender_ref, host.message_id, host.visibility,
                            ingress_host_identity_json(host, operation_id),
                            fingerprint, learned_at, bundle.digest),
                    )
                    db.execute(
                        "UPDATE ingress_first_observations SET bundle_digest=? "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        (bundle.digest,) + namespace.as_tuple + (operation_id,))
                    finish_id = "finish:" + attempt_id
                    finished_digest = finish_digest(
                        attempt_id, permit.token, operation_id, bundle.digest)
                    result = self._commit_domain_bundle_fenced(
                        bundle, lease, in_transaction=True, now_utc=now_utc,
                        ingress_deadline_check=deadline_check,
                        v2_write=(metadata, epoch, finish_id,
                                  finished_digest,
                                  canonical_json(to_wire(permit))))
                    db.execute("COMMIT")
                except BaseException:
                    if db.in_transaction:
                        db.execute("ROLLBACK")
                        transaction_rolled_back = True
                    raise
        except Exception as exc:
            if transaction_rolled_back:
                try:
                    self._reject_first_ingress_v2(
                        namespace, operation_id, row, permit, scope)
                except Exception as reconcile_exc:
                    raise FirstIngressOutcomeUnknown(
                        operation_id,
                        "first ingress rejection finish unconfirmed; HOLD original attempt"
                    ) from reconcile_exc
                raise
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress commit outcome unknown; HOLD original attempt") from exc
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first ingress permit changed after commit")
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress committed permit unconfirmed; HOLD"
            ) from exc
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != result.invalidated_epochs[0].revision):
                raise FirstIngressOutcomeUnknown(
                    operation_id, "first ingress committed stamp unconfirmed; HOLD")
        try:
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finished_digest)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id,
                "first ingress finish outcome unknown; HOLD original attempt") from exc
        return result

    def _reject_first_ingress_v2(self, namespace, operation_id, row,
                                 permit, scope) -> None:
        """Only a proven rollback may become a durable abort identity."""
        from .authority_service.v2_contract import to_wire
        from .runtime.first_ingress_v2 import finish_digest

        store = self.__store
        attempt_id = row[3]
        abort_id = "abort:" + attempt_id
        digest = finish_digest(
            attempt_id, permit.token, operation_id, None, rejected=True)
        expected = ("rejected_no_commit", canonical_json(to_wire(permit)),
                    row[6], row[7], abort_id, digest)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current_epoch != scope.graph_epoch
                        or current.graph_revision != scope.graph_revision
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone()):
                    raise UnavailableGuard("first ingress rollback cannot be proven")
                if current.graph_revision != row[6]:
                    raise UnavailableGuard("first ingress rollback stamp changed")
                db.execute(
                    "INSERT OR IGNORE INTO graph_first_ingress_rejections_v2"
                    "(bot,persona,operation_id,status,permit_json,graph_revision,"
                    "graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (operation_id,) + expected)
                if db.execute(
                    "SELECT status,permit_json,graph_revision,graph_epoch,"
                    "finish_request_id,finish_request_digest "
                    "FROM graph_first_ingress_rejections_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone() != expected:
                    raise UnavailableGuard("first ingress rejection identity differs")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        port = self.__content_fence_v2
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("first ingress rejected permit changed")
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress rejected permit unconfirmed; HOLD"
            ) from exc
        try:
            port.finish_fence(scope, request_id=abort_id,
                              request_digest=digest)
        except Exception as exc:
            raise FirstIngressOutcomeUnknown(
                operation_id, "first ingress rejected finish outcome unknown; HOLD"
            ) from exc

    def issue_ingress_authorization(self, bootstrap: object, request, session):
        """Issue first D06+D11 ingress from installation policy and signed facts.

        The policy callback is installed with the coordinator and receives only
        namespace and policy identity. It cannot inspect chat content or the DB.
        A missing callback, observation, or real issuer fails closed.
        """
        from .domains.d06 import D06DomainAdapter, SourceAdmission
        from .runtime.d11_types import runtime_job_key, runtime_outbox_key
        from .runtime.issuers import (
            BudgetLeaseGrant, D02ResourceIssuer, D11BudgetJobIssuer,
            ResourceQuote, install_schema as install_issuer_schema,
        )
        from .runtime_contracts import (
            RUNTIME_SCHEMA, CommandEnvelope, OperationIdentity,
            VersionGuard, VersionedRef,
        )

        self._admin(bootstrap)
        if not isinstance(request, IngressIssuanceRequest):
            raise TypeError("typed ingress issuance request required")
        if not isinstance(getattr(session, "authority", None), AuthorityContext) or \
                getattr(session, "lease", None) is None:
            raise TypeError("ingress authority session required")
        authority = session.authority
        self._authorize(session.lease, authority, frozenset({"d06", "d11"}))
        if authority.capability_ref != _operation_capability_ref(
                authority.namespace, authority.actor, authority.issuer_domain,
                frozenset({"d06", "d11"}), authority.activation_generation,
                request.operation_id):
            raise AuthorityDenied("ingress lease is not scoped to this operation")
        if (authority.issuer_domain != "d06" or authority.purpose != "context"
                or authority.namespace != request.host.namespace
                or authority.audience != (request.host.conversation_ref,)
                or not {"event", "activity"}.issubset(authority.owner_scope)):
            raise AuthorityDenied("ingress session differs from trusted host scope")
        if (type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or self.__ingress_policy is None):
            raise UnavailableGuard("real D02/D11 issuers and ingress policy are required")
        host = request.host
        namespace = host.namespace
        admission = request.admission
        expected_admission = SourceAdmission(
            host.lineage.source_ref, host.text, host.sender_ref,
            host.lineage.source_kind, "reported",
            host.lineage.evidence_eligibility,
            host.lineage.internal_activity_actuality,
            host.occurred_at, host.learned_at,
            host.lineage.provenance_family,
            (host.conversation_ref,), ("context", "consolidation"),
        )
        if (host.lineage.content_reality != "external_report"
                or admission != expected_admission
                or admission.parent_source_ids
                or request.candidate != D06DomainAdapter(namespace).admit_source(admission)):
            raise AuthorityDenied("ingress source differs from canonical host report")
        digest = hashlib.sha256(
            ("sylanne3.host-ingress.v1:" + host.lineage.source_ref).encode("ascii")
        ).hexdigest()
        if (request.activity_id != "ingress-" + digest[:24]
                or request.operation_id != "host-ingress-" + digest[:32]
                or request.job_id != "encode-" + digest[:24]
                or request.outbox_id != "encode-outbox-" + digest[:24]
                or request.payload_ref != host.lineage.source_ref
                or request.idempotency_key != "host-ingress:" + digest
                or request.job_ref != runtime_job_key(
                    *namespace.as_tuple, request.activity_id, request.job_id).token
                or request.outbox_ref != runtime_outbox_key(
                    *namespace.as_tuple, request.activity_id, request.outbox_id).token):
            raise AuthorityDenied("ingress runtime refs differ from canonical identity")
        request_digest = canonical_digest(request)
        source = source_key(*namespace.as_tuple, admission.source_id)
        access = access_key(*namespace.as_tuple, admission.source_id)
        keys = (source, access, self._parse_ref(request.job_ref, namespace),
                self._parse_ref(request.outbox_ref, namespace))
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    db = store._db
                    self._admit_content(namespace, authority.activation_generation,
                                        "write", tuple(key.token for key in keys))
                    if self._version(db, namespace, "activation", "current") != str(
                            authority.activation_generation):
                        raise StaleRead("activation generation changed")
                    observation = db.execute(
                        "SELECT content_fingerprint,learned_at FROM ingress_first_observations "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (request.operation_id,),
                    ).fetchone()
                    if observation is None:
                        raise UnavailableGuard("canonical first observation is absent")
                    if (observation[0] != ingress_host_fingerprint(host)
                            or observation[1] != host.learned_at):
                        raise EventConflict("ingress content or canonical learned time changed")
                    install_issuer_schema(db)
                    db.execute("""CREATE TABLE IF NOT EXISTS runtime_ingress_issuance(
                        bot TEXT NOT NULL, persona TEXT NOT NULL, operation_id TEXT NOT NULL,
                        activation_generation INTEGER NOT NULL,
                        request_digest TEXT NOT NULL, policy_json TEXT NOT NULL,
                        quote_id TEXT NOT NULL, grant_id TEXT NOT NULL,
                        guard_json TEXT NOT NULL,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    prior = db.execute(
                        "SELECT activation_generation,request_digest,policy_json,"
                        "quote_id,grant_id,guard_json "
                        "FROM runtime_ingress_issuance WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (request.operation_id,),
                    ).fetchone()
                    if prior is not None and prior[0] != authority.activation_generation:
                        raise StaleRead("ingress issuance activation generation changed")
                    if prior is not None and prior[1] != request_digest:
                        raise EventConflict("ingress operation request changed")
                    if prior is None:
                        policy = self.__ingress_policy(namespace, authority.provider_policy_ref)
                        if not isinstance(policy, IngressIssuancePolicy):
                            raise UnavailableGuard("typed installed ingress policy unavailable")
                        quote_id = "ingress-q-" + hashlib.sha256(
                            canonical_json([*namespace.as_tuple, request.operation_id]).encode()
                        ).hexdigest()[:40]
                        grant_id = "ingress-g-" + hashlib.sha256(
                            canonical_json([*namespace.as_tuple,
                                            policy.parent_budget_lease_ref,
                                            authority.provider_policy_ref]).encode()
                        ).hexdigest()[:40]
                        epochs = db.execute(
                            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                            "WHERE bot=? AND persona=?", namespace.as_tuple,
                        ).fetchone() or (0, 0)
                        guard_data = {
                            "access_epoch": epochs[0], "delete_epoch": epochs[1],
                            "scheme": self._version(db, namespace, "scheme", "current"),
                            "operator": self._version(db, namespace, "operator", "current"),
                            "policy": self._version(db, namespace, "policy", "current"),
                        }
                        for key in keys:
                            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                          (key.token,)).fetchone() is not None:
                                raise StaleRead("first ingress atom already exists")
                        lease = get_budget_lease(db, policy.parent_budget_lease_ref)
                        if (lease.state != "active" or
                                (lease.bot_id, lease.persona_id) != namespace.as_tuple):
                            raise UnavailableGuard("existing active parent budget required")
                        if any(amount > lease.limits.get(name, 0)
                               for name, amount in policy.grant_ceiling.items()):
                            raise UnavailableGuard("installation grant exceeds parent budget limit")
                        if any(amount > lease.limits.get(name, 0)
                               - lease.used.get(name, 0)
                               - lease.reserved.get(name, 0)
                               - lease.unconfirmed.get(name, 0)
                               for name, amount in policy.ceiling.items()):
                            raise UnavailableGuard("parent budget has insufficient available capacity")
                        grant = BudgetLeaseGrant(
                            grant_id, 1, *namespace.as_tuple, lease.lease_id,
                            lease.currency, policy.grant_ceiling, ("d06.encode_source",),
                            policy.grant_valid_until_utc, authority.provider_policy_ref,
                        )
                        if db.execute("SELECT 1 FROM runtime_budget_grants WHERE lease_id=?",
                                      (lease.lease_id,)).fetchone() is None:
                            self.__d11_issuer.issue_budget_grant(db, grant)
                        elif self.__d11_issuer.current_budget_grant(db, lease.lease_id) != grant:
                            raise AuthorityDenied("existing signed D11 grant differs from ingress policy")
                        quote = ResourceQuote(
                            quote_id, 1, *namespace.as_tuple, request.activity_id,
                            request.operation_id, None, lease.lease_id,
                            "d06.encode_source", policy.snapshot_ref,
                            policy.deadline_utc, policy.resource_ref, request.job_ref,
                            (request.outbox_ref,), (), policy.ceiling, None,
                            policy.deadline_utc,
                        )
                        self.__d02_issuer.issue_quote(db, quote)
                        db.execute(
                            "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                            "VALUES(?,?,?,?,?)",
                            namespace.as_tuple + ("resource_lease", quote_id, "1"),
                        )
                        db.execute(
                            "INSERT INTO runtime_ingress_issuance"
                            "(bot,persona,operation_id,activation_generation,"
                            "request_digest,policy_json,quote_id,grant_id,guard_json) "
                            "VALUES(?,?,?,?,?,?,?,?,?)",
                            namespace.as_tuple + (
                                request.operation_id, authority.activation_generation,
                                request_digest,
                                json.dumps(asdict(policy), sort_keys=True),
                                quote_id, grant_id,
                                json.dumps(guard_data, sort_keys=True)),
                        )
                    else:
                        policy = IngressIssuancePolicy(**json.loads(prior[2]))
                        quote_id, grant_id = prior[3], prior[4]
                        guard_data = json.loads(prior[5])
                    self._admit_ingress_deadline(
                        namespace, request.operation_id,
                        authority.activation_generation, policy.deadline_utc)
                    if (self._version(db, namespace, "scheme", "current") != guard_data["scheme"]
                            or self._version(db, namespace, "operator", "current") != guard_data["operator"]
                            or self._version(db, namespace, "policy", "current") != guard_data["policy"]
                            or self._version(db, namespace, "resource_lease", quote_id) != "1"):
                        raise StaleRead("ingress guard version changed")
                    current_epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    if tuple(current_epochs) != (
                            guard_data["access_epoch"], guard_data["delete_epoch"]):
                        raise StaleRead("ingress access or deletion epoch changed")
                    committed = db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?", namespace.as_tuple + (request.operation_id,),
                    ).fetchone() is not None
                    if not committed:
                        for key in keys:
                            if db.execute("SELECT 1 FROM graph_atoms WHERE token=?",
                                          (key.token,)).fetchone() is not None:
                                raise StaleRead("first ingress atom changed")
                    identity = OperationIdentity(
                        request.activity_id, None, "first", "ingress",
                        request.operation_id, canonical_digest({
                            "input_refs": list(request.candidate.qualification.source_refs),
                        }),
                    )
                    envelope = CommandEnvelope(
                        RUNTIME_SCHEMA, identity, authority,
                        VersionGuard(
                            tuple(GraphVersion(key, 0) for key in keys),
                            (),
                            guard_data["access_epoch"], guard_data["delete_epoch"],
                            store._registry.catalogue_hash,
                            guard_data["scheme"], guard_data["operator"],
                            guard_data["policy"], (), (),
                            (VersionedRef(quote_id, 1),),
                        ),
                        request.candidate.qualification,
                        request.candidate.qualification.source_refs,
                        policy.parent_budget_lease_ref, policy.deadline_utc,
                        policy.monotonic_deadline, policy.character_interval_ref,
                        (host.message_id,),
                    )
                    quote = self.__d02_issuer.qualified_quote(envelope, db)
                    if (quote.quote_id != quote_id or quote.graph_job_ref != request.job_ref
                            or quote.outbox_refs != (request.outbox_ref,)
                            or dict(quote.ceiling) != dict(policy.ceiling)
                            or quote.snapshot_ref != policy.snapshot_ref
                            or quote.resource_ref != policy.resource_ref):
                        raise AuthorityDenied("signed D02 quote differs from durable ingress policy")
                    grant = self.__d11_issuer.current_budget_grant(
                        db, policy.parent_budget_lease_ref)
                    if (grant.grant_id != grant_id
                            or dict(grant.max_ceiling) != dict(policy.grant_ceiling)
                            or grant.valid_until_utc != policy.grant_valid_until_utc
                            or grant.policy_ref != authority.provider_policy_ref):
                        raise AuthorityDenied("signed D11 grant differs from durable ingress policy")
                    current_lease = get_budget_lease(db, policy.parent_budget_lease_ref)
                    if not committed and any(
                            amount > current_lease.limits.get(name, 0)
                            - current_lease.used.get(name, 0)
                            - current_lease.reserved.get(name, 0)
                            - current_lease.unconfirmed.get(name, 0)
                            for name, amount in policy.ceiling.items()):
                        raise UnavailableGuard("parent budget has insufficient available capacity")
                    job = self.__d11_issuer.job_for(envelope, db)
                    if (job.job_id != request.job_id or
                            job.work_kind != "d06.encode_source"):
                        raise AuthorityDenied("D11 job differs from ingress encoding work")
                    db.execute("COMMIT")
                    return IngressAuthorizationResult(envelope, session.lease, job)
                except BaseException:
                    if store._db.in_transaction:
                        store._db.execute("ROLLBACK")
                    raise

    def reserve_and_schedule(self, envelope, lease: object) -> tuple[BudgetReceipt, PersistentJob]:
        """Reserve before an external effect and persist its runnable job atomically.

        The D02/D11 issuers are trusted host dependencies. A command envelope
        alone is never permission to spend or schedule work.
        """
        authority = envelope.authority
        self._authorize(lease, authority, frozenset())
        if (not callable(getattr(self.__d02_issuer, "authorize_schedule", None))
                or not callable(getattr(self.__d11_issuer, "admit_schedule", None))):
            raise UnavailableGuard("D02 and D11 schedule issuers are required")
        namespace = authority.namespace
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                self._admit_content(namespace, authority.activation_generation, "write",
                                    tuple(item.key.token for item in
                                          envelope.version_guard.read_versions))
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    self._check_guard(store._db, SimpleNamespace(
                        envelope=envelope, proposals=()))
                    if self.__d02_issuer.authorize_schedule(envelope, store._db) is not True:
                        raise AuthorityDenied("D02 did not authorize scheduling resources")
                    admission = self.__d11_issuer.admit_schedule(envelope, store._db)
                    if not isinstance(admission, ScheduleAdmission):
                        raise AuthorityDenied("D11 did not issue a typed schedule admission")
                    budget, job = admission.budget, admission.job
                    if not isinstance(budget, BudgetAdmission) or not isinstance(job, PersistentJob):
                        raise AuthorityDenied("D11 schedule admission is incomplete")
                    if (budget.lease_id != envelope.parent_budget_lease_ref
                            or budget.pre_reserved or budget.settle_now
                            or budget.reservation_operation_id is not None):
                        raise AuthorityDenied("schedule must reserve the command budget once")
                    current = get_budget_lease(store._db, budget.lease_id)
                    if (current.state != "active" or current.version != budget.expected_version
                            or (current.bot_id, current.persona_id) != namespace.as_tuple):
                        raise StaleRead("D11 schedule budget lease is stale")
                    identity = envelope.identity
                    if ((job.bot_id, job.persona_id) != namespace.as_tuple
                            or job.operation_id != identity.operation_id
                            or job.activity_id != identity.activity_id
                            or job.effect_id != identity.effect_id
                            or job.budget_ref != budget.lease_id
                            or job.phase not in {"queued", "waiting"}):
                        raise AuthorityDenied("D11 schedule job identity differs from command")
                    digest = budget_operation_digest(envelope, budget.lease_id,
                                                     budget.ceiling)
                    receipt = reserve_budget(store._db, budget.lease_id,
                                             identity.operation_id, digest, budget.ceiling)
                    job_operation = "job:" + hashlib.sha256(
                        (identity.operation_id + job.job_id).encode("utf-8")
                    ).hexdigest()[:32]
                    persisted = create_job(store._db, job, job_operation, digest)
                    store._db.execute("COMMIT")
                    return receipt, persisted
                except BaseException:
                    store._db.execute("ROLLBACK")
                    raise

    def acquire_persistent_job(self, authority: AuthorityContext, lease: object,
                               job_id: str, *, now_utc: str,
                               lease_seconds: int) -> PersistentJob:
        if isinstance(self.__store, ProductionGraphStore):
            raise UnavailableGuard("production job acquire requires the v2 fenced command")
        self._authorize(lease, authority, frozenset())
        return self._mutate_job(authority, job_id, lambda db: acquire_job(
            db, job_id, authority.actor, now_utc=now_utc,
            lease_seconds=lease_seconds))

    def _first_ingress_encoding_job_locked(self, namespace: NamespaceId,
                                           job_id: str):
        """Join the original business receipt, job table, and graph projections."""
        from .runtime.d11_types import (
            RuntimeOutboxValue, job_graph_write, runtime_job_key,
            runtime_outbox_key,
        )
        from .runtime.first_ingress_v2 import ingress_ids
        from .memory_types import SourceRecord, access_key, source_key, validate_access

        db = self.__store._db
        job = get_job(db, job_id)
        if ((job.bot_id, job.persona_id) != namespace.as_tuple
                or job.work_kind != "d06.encode_source" or job.effect_id is not None):
            raise AuthorityDenied("job is not an installed first-ingress encoding job")
        job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
        job_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (job_key.token,),
        ).fetchone()
        if (job_row is None or job_row[2] != 1
                or json.loads(job_row[1]) != job_graph_write(job).value):
            raise UnavailableGuard("encoding job graph projection differs from durable job")
        rows = db.execute(
            "SELECT token,revision,value,valid FROM graph_atoms WHERE bot=? "
            "AND persona=? AND owner_kind='activity' AND subject=? "
            "AND type_name='runtime.outbox'",
            namespace.as_tuple + (job.activity_id,),
        ).fetchall()
        matches = []
        for token, revision, value_json, valid in rows:
            value = json.loads(value_json)
            if value.get("job_id") == job_id:
                matches.append((token, revision, value, valid))
        if len(matches) != 1:
            raise UnavailableGuard("encoding job needs exactly one original outbox")
        token, outbox_revision, value, valid = matches[0]
        outbox = RuntimeOutboxValue(**value)
        expected = ingress_ids(outbox.payload_ref)
        source_key_value = source_key(*namespace.as_tuple, outbox.payload_ref)
        access_key_value = access_key(*namespace.as_tuple, outbox.payload_ref)
        source_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (source_key_value.token,),
        ).fetchone()
        access_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (access_key_value.token,),
        ).fetchone()
        if (source_row is None or access_row is None
                or source_row[2] != 1 or access_row[2] != 1):
            raise UnavailableGuard("encoding source or access is unavailable")
        try:
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access_value = json.loads(access_row[1])
            validate_access(access_value)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("encoding source or access is invalid") from exc
        source_dependency = db.execute(
            "SELECT dependency_revision FROM graph_dependencies WHERE dependent_token=? "
            "AND dependency_token=?",
            (access_key_value.token, source_key_value.token),
        ).fetchone()
        if (source.source_id != outbox.payload_ref
                or access_value["source_id"] != source.source_id
                or access_value["status"] != "active"
                or "consolidation" not in access_value["purposes"]
                or "consolidation" not in source.purposes
                or not set(access_value["audiences"]).issubset(source.audiences)
                or source_dependency != (source_row[0],)):
            raise UnavailableGuard("encoding source access lost current eligibility")
        outbox_key = runtime_outbox_key(
            *namespace.as_tuple, job.activity_id, outbox.outbox_id)
        receipt_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (job.operation_id,),
        ).fetchone()
        dependencies = db.execute(
            "SELECT dependency_revision FROM graph_dependencies WHERE dependent_token=? "
            "AND dependency_token=?",
            (outbox_key.token, job_key.token),
        ).fetchone()
        if (valid != 1 or token != outbox_key.token
                or (expected[1], expected[2], expected[3], expected[4]) != (
                    job.activity_id, job.operation_id, job.job_id, outbox.outbox_id)
                or (outbox.bot_id, outbox.persona_id, outbox.activity_id,
                    outbox.operation_id, outbox.effect_id, outbox.job_ref,
                    outbox.phase) != (
                    namespace.bot_id, namespace.persona_id, job.activity_id,
                    job.operation_id, None, job_key.token, "pending")
                or dependencies != (job_row[0],)
                or receipt_row is None
                or outbox_key.token not in json.loads(receipt_row[0]).get("outbox_refs", ())):
            raise UnavailableGuard("encoding outbox lost its original business linkage")
        self._original_first_ingress_qualification_locked(
            namespace, job.operation_id, source_key_value.token)
        return (job, job_key, job_row[0], outbox, outbox_key,
                outbox_revision, GraphVersion(source_key_value, source_row[0]),
                GraphVersion(access_key_value, access_row[0]))

    def _original_first_ingress_qualification_locked(
        self, namespace: NamespaceId, operation_id: str, source_ref: str,
    ):
        """Read only the D06 qualification committed with the first bundle."""
        db = self.__store._db
        columns = {column[1] for column in db.execute(
            "PRAGMA table_info(runtime_ingress_issuance)")}
        if "source_qualification_json" not in columns:
            raise UnavailableGuard("original D06 source qualification absent; HOLD")
        row = db.execute(
            "SELECT source_qualification_json FROM runtime_ingress_issuance "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if row is None or row[0] is None:
            raise UnavailableGuard("original D06 source qualification absent; HOLD")
        try:
            data = json.loads(row[0])
            data["source_refs"] = tuple(data["source_refs"])
            qualification = SourceQualification(**data)
            if (canonical_serialize(asdict(qualification)) != row[0]
                    or qualification.source_refs != (source_ref,)):
                raise ValueError("qualification identity differs")
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard(
                "original D06 source qualification invalid; HOLD") from exc
        return qualification

    def read_first_ingress_baseline_inputs_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        original_operation_id: str,
    ):
        """Read queued C01 evidence for D04 without acquiring an encoding worker.

        This returns no D03 self perspective and grants no D04 write authority.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .memory_types import SourceRecord
        from .runtime.first_ingress_baseline_inputs import FirstIngressBaselineInputsV1
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed first-ingress baseline read authorities required")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        namespace = authority.namespace
        if (authority.issuer_domain != "d11" or authority.actor != self.__holder
                or "activity" not in authority.owner_scope
                or authority.purpose != "context"
                or authority.worker_fence is not None
                or type(original_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, original_operation_id)):
            raise AuthorityDenied("baseline read requires the original job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("baseline trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            job, job_key, _, outbox, _, _, source_version, access_version = (
                self._first_ingress_encoding_job_locked(namespace, job_id))
            if (job.operation_id != original_operation_id
                    or job.phase != "queued" or job.fence != 0
                    or job.lease_holder is not None
                    or job.lease_expires_utc is not None
                    or job.cancel_epoch != 0 or job.result_ref is not None):
                raise UnavailableGuard("baseline job is no longer queued; HOLD")
            deadline = datetime.fromisoformat(
                job.deadline_utc.replace("Z", "+00:00")).timestamp()
            if now >= deadline:
                raise UnavailableGuard("baseline job deadline expired; HOLD")
            self.__d11_issuer.authorize_existing_encoding_job(db, job, now_utc=now)
            if (self.__d11_issuer.current_budget_grant(db, job.budget_ref).policy_ref
                    != authority.provider_policy_ref):
                raise UnavailableGuard("baseline D11 policy identity differs; HOLD")
            identity = db.execute(
                "SELECT source_ref,platform_ref,conversation_ref,sender_ref,"
                "message_id,visibility,identity_json,bundle_digest FROM "
                "graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            intent = db.execute(
                "SELECT identity_json,requirements_json FROM "
                "graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            bundle = db.execute(
                "SELECT digest,receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None or intent is None or bundle is None:
                raise UnavailableGuard("baseline original ingress identity absent; HOLD")
            original = json.loads(identity[6])
            original_intent = json.loads(intent[0])
            receipt = json.loads(bundle[1])
            if (identity[0] != outbox.payload_ref
                    or (original_intent["source_ref"],
                        original_intent["conversation_ref"]) != (identity[0], identity[2])
                    or (original["source_ref"], original["platform_ref"],
                        original["conversation_ref"], original["sender_ref"],
                        original["message_id"], original["visibility"],
                        original["operation_id"]) != (*identity[:6], original_operation_id)
                    or identity[7] != bundle[0]
                    or job_key.token not in receipt.get("ledger_refs", ())
                    or authority.audience != (identity[2],)):
                raise UnavailableGuard("baseline original ingress identity differs; HOLD")
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? AND valid=1",
                (source_version.key.token, source_version.revision),
            ).fetchone()
            access_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? AND valid=1",
                (access_version.key.token, access_version.revision),
            ).fetchone()
            if source_row is None or access_row is None:
                raise UnavailableGuard("baseline current source/access disappeared; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            access = json.loads(access_row[0])
            if (source.speaker_id != identity[3]
                    or "context" not in source.purposes
                    or "context" not in access["purposes"]
                    or identity[2] not in source.audiences
                    or identity[2] not in access["audiences"]):
                raise UnavailableGuard("baseline current source/access differs; HOLD")
            qualification = self._original_first_ingress_qualification_locked(
                namespace, original_operation_id, source_version.key.token)
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("baseline current authority epochs absent; HOLD")
            return (job, source_version, access_version, qualification, epochs,
                    json.loads(intent[1])["graph_incarnation"])

        prepared, anchor, metadata, graph_epoch = self._read_v2(
            authority, reader, return_recovery_context=True,
            durable_read_key="d04-baseline:" + original_operation_id)
        job, source_version, access_version, qualification, epochs, original_incarnation = prepared
        if metadata.requirements.graph_incarnation != original_incarnation:
            raise UnavailableGuard("baseline graph incarnation differs from original ingress; HOLD")
        return FirstIngressBaselineInputsV1(
            namespace, original_incarnation, metadata.graph_revision,
            graph_epoch.revision, *epochs, job_id, job.activity_id,
            original_operation_id, source_version.key.token,
            source_version.revision, access_version.revision, qualification,
            anchor)

    def read_first_ingress_encoding_job_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> PersistentJob:
        """Read one D11 job only through the current v2 Authority fence."""
        if not isinstance(self.__store, ProductionGraphStore) or self.__content_fence_v2 is None:
            raise UnavailableGuard("v2 job read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if "activity" not in authority.owner_scope:
            raise AuthorityDenied("D11 job read requires activity owner scope")
        if (type(acquire_operation_id) is not str or not acquire_operation_id
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("D11 job read lease is not scoped to this operation")
        def reader():
            job = self._first_ingress_encoding_job_locked(
                authority.namespace, job_id)[0]
            if not _job_acquire_id_matches(
                    acquire_operation_id, authority.namespace, job_id,
                    job.operation_id, authority.actor,
                    authority.activation_generation):
                raise AuthorityDenied("D11 job read lease names another job")
            return job

        return self._read_v2(authority, reader)

    def read_first_ingress_encoding_inputs_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> FirstIngressEncodingInputsV1:
        """Read the acquired job and its original source under one v2 fence.

        This is preparation only. A caller cannot turn this read into a model
        handoff or durable binding without the separate write admission.
        """
        from .memory_types import SourceRecord
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 encoding input read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("encoding input read requires the job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("encoding input trusted clock unavailable; HOLD") from exc

        def reader():
            (job, _, _, outbox, _, _, source_version, access_version) = (
                self._first_ingress_encoding_job_locked(authority.namespace, job_id))
            if not _job_acquire_id_matches(
                    acquire_operation_id, authority.namespace, job_id,
                    job.operation_id, authority.actor,
                    authority.activation_generation):
                raise AuthorityDenied("encoding input read lease names another job")
            if (job.phase != "running" or job.lease_holder != authority.actor
                    or job.cancel_epoch or job.fence < 1
                    or authority.worker_fence != job.fence):
                raise UnavailableGuard("encoding input job lease is not current; HOLD")
            from datetime import datetime
            expiry = datetime.fromisoformat(
                job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            if now >= expiry:
                raise UnavailableGuard("encoding input job lease expired; HOLD")
            self.__d11_issuer.authorize_existing_encoding_job(
                self.__store._db, job, now_utc=now)
            row = self.__store._db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (source_version.key.token,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("encoding source disappeared; HOLD")
            source = SourceRecord.from_dict(json.loads(row[0]))
            if source.source_id != outbox.payload_ref:
                raise UnavailableGuard("encoding source differs from original outbox")
            if self.__store._db.execute(
                    "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                    "WHERE bot=? AND persona=? AND source_id=? LIMIT 1",
                    authority.namespace.as_tuple + (source.source_id,),
            ).fetchone():
                raise UnavailableGuard("encoding source request was erased; HOLD")
            return FirstIngressEncodingInputsV1(
                job, source, source_version.revision, access_version.revision,
                job.budget_ref, job.operation_id)

        return self._read_v2(authority, reader)

    def read_first_ingress_encoding_binding_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ):
        """Return the original frozen request to its current acquired D11 worker.

        This content read is fenced and requires current source access. Cost
        reconciliation must use an independent content-free terminal query.
        """
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 encoding binding read requires the installed graph")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("encoding binding read requires the job-bound D11 lease")
        try:
            clock = self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy)
            now = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("encoding binding trusted clock unavailable; HOLD") from exc

        def reader():
            return self._first_ingress_encoding_binding_locked(
                authority, job_id, acquire_operation_id, clock, now)[0]

        return self._read_v2(authority, reader)

    def _first_ingress_encoding_binding_locked(
        self, authority: AuthorityContext, job_id: str,
        acquire_operation_id: str, clock, now: float,
    ):
        """Qualify the original binding and current worker under the graph lock."""
        from datetime import datetime

        from .runtime.encoding_call_binding import binding_from_json, load_binding

        db = self.__store._db
        (job, _, _, outbox, outbox_key, _, source_version, access_version) = (
            self._first_ingress_encoding_job_locked(authority.namespace, job_id))
        if (not _job_acquire_id_matches(
                acquire_operation_id, authority.namespace, job_id,
                job.operation_id, authority.actor,
                authority.activation_generation)
                or job.phase != "running" or job.lease_holder != authority.actor
                or job.cancel_epoch or job.fence < 1 or job.result_ref is not None
                or authority.worker_fence != job.fence):
            raise UnavailableGuard("encoding binding job lease is not current; HOLD")
        expiry = datetime.fromisoformat(
            job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
        if now >= expiry:
            raise UnavailableGuard("encoding binding job lease expired; HOLD")
        self.__d11_issuer.authorize_existing_encoding_job(db, job, now_utc=now)
        intent = db.execute(
            "SELECT encoding_binding_json FROM graph_job_acquire_intents_v2 "
            "WHERE bot=? AND persona=? AND acquire_operation_id=? "
            "AND job_id=? AND original_operation_id=? AND actor=?",
            authority.namespace.as_tuple + (
                acquire_operation_id, job_id, job.operation_id, authority.actor),
        ).fetchone()
        receipt = db.execute(
            "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
            "AND persona=? AND acquire_operation_id=?",
            authority.namespace.as_tuple + (acquire_operation_id,),
        ).fetchone()
        binding = load_binding(db, authority.namespace, job_id)
        if (intent is None or intent[0] is None or receipt is None
                or binding is None or binding != binding_from_json(intent[0])
                or binding.request.get("schema") not in {
                    "sylanne.first-ingress-encoding-call.v2",
                    "sylanne.first-ingress-encoding-call.v3"}):
            raise UnavailableGuard("committed original encoding binding is absent; HOLD")
        self._validate_first_ingress_encoding_binding_context(
            authority.namespace, job, outbox, source_version, access_version,
            authority, now, acquire_operation_id, clock, binding)
        return binding, job, outbox, outbox_key

    def commit_post_c02_attention_v1(
        self, bundle: DomainBundle, lease: object, installed_bundle,
    ) -> CommitReceipt:
        """Sign a bounded D07 quote inside its original fenced graph write."""
        from .host.authority_profile import (
            AdminD07AttentionPolicy, AdminInstallationBundle,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.reply_model_job import d07_attention_quote_id_v1
        from .runtime_contracts import VersionedRef

        if (type(bundle) is not DomainBundle
                or type(installed_bundle) is not AdminInstallationBundle
                or type(installed_bundle.d07_attention)
                is not AdminD07AttentionPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("installed D07 attention issuance unavailable; HOLD")
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        quote_id = d07_attention_quote_id_v1(
            namespace, envelope.identity.operation_id)
        if (installed_bundle.installation_policy.namespace != namespace
                or envelope.identity.phase != "post_c02_attention"
                or envelope.authority.purpose != "expression"
                or len(envelope.authority.audience) != 1
                or len(envelope.source_qualification.source_refs) != 1
                or len(envelope.causation) != 1
                or len(bundle.proposals) != 1
                or bundle.proposals[0].domain != "d07"
                or {write.key.type_name for write in
                    bundle.proposals[0].typed_writes} != {
                        "d07.attention_ticket.v1", "d07.focus.v1"}
                or bundle.persistent_job_refs or bundle.outbox_refs
                or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs
                or envelope.version_guard.resource_lease_versions !=
                   (VersionedRef(quote_id, 1),)):
            raise AuthorityDenied("post-C02 attention bundle identity differs")
        now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
            self.__scene_clock_policy))
        self._authorize(lease, envelope.authority, frozenset({"d07"}))
        return self._commit_domain_bundle_v2(
            bundle, lease, attention_issuance=(installed_bundle, now))

    def read_post_c02_attention_inputs_v1(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str | None, installed_bundle,
    ):
        """Fenced current C02/source read for a separate D07 ticket proposal."""
        from .host.authority_profile import AdminInstallationBundle
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.reply_model_job import (
            read_settled_c02_reply_source_v1, source_key_from_ref,
        )
        from .runtime.c02_bundle_codec import c02_bundle_from_wire
        from .memory_types import access_key, source_key
        from .runtime_contracts import QueryEpoch, VersionGuard

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed post-C02 attention read unavailable; HOLD")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            provision_row = self._provision_row(store._db, namespace)
            provision = (self._decode_provision_receipt(provision_row)
                         if provision_row is not None else None)
        target = metadata.requirements
        if (provision is None or target.namespace != namespace
                or provision.installation_id !=
                   installed_bundle.installation_policy.installation_id
                or provision.generation != target.activation_generation):
            raise UnavailableGuard("post-C02 attention installation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("post-C02 attention anchor differs; HOLD")
        operation_id = "reply-attention-read-" + secrets.token_hex(24)
        permit = port.begin_fence(
            namespace=namespace,
            authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="read", operation_id=operation_id,
            expected_anchor=anchor)
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "read", operation_id, permit, anchor, epoch,
            metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("post-C02 attention read fence changed")
            with store._lock:
                db = store._db
                db.execute("BEGIN")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("post-C02 attention graph changed")
                    sealed = db.execute(
                        "SELECT bundle_json FROM graph_first_ingress_c02_committed_seals_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if sealed is None:
                        raise UnavailableGuard("original C02 seal absent; HOLD")
                    frozen_sources = c02_bundle_from_wire(
                        sealed[0]).envelope.source_qualification.source_refs
                    if (len(frozen_sources) != 1 or
                            (source_ref is not None and source_ref != frozen_sources[0])):
                        raise UnavailableGuard("post-C02 source differs from seal; HOLD")
                    source_ref = frozen_sources[0]
                    source_id = source_key_from_ref(source_ref, namespace)
                    keys = (source_key(*namespace.as_tuple, source_id),
                            access_key(*namespace.as_tuple, source_id),
                            AtomKey(Owner("persona", *namespace.as_tuple),
                                    "d07.focus.v1", namespace.persona_id))
                    atoms = []
                    for key in keys:
                        row = db.execute(
                            "SELECT revision,value,valid FROM graph_atoms "
                            "WHERE token=?", (key.token,),
                        ).fetchone()
                        atoms.append(GraphAtom(
                            key, row[0], json.loads(row[1]), bool(row[2]))
                            if row else GraphAtom(key, 0, {}, False))
                    snapshot = GraphSnapshot(tuple(atoms), (epoch,))
                    c02_row = db.execute(
                        "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                        "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if c02_row is None:
                        raise UnavailableGuard("original C02 receipt absent; HOLD")
                    event = db.execute(
                        "SELECT reads,revisions,epoch_revision FROM graph_events "
                        "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (c02_row[1], c02_operation_id),
                    ).fetchone()
                    if event is None:
                        raise UnavailableGuard("original C02 graph event absent; HOLD")
                    detail = json.loads(c02_row[4])
                    receipt = CommitReceipt(
                        "committed", c02_operation_id, c02_row[0], c02_row[1],
                        c02_row[2], c02_row[3],
                        GraphStore._version_rows(event[0]),
                        GraphStore._version_rows(event[1]),
                        (NamespaceEpoch(*namespace.as_tuple, event[2]),),
                        tuple(detail["ledger_refs"]),
                        tuple(detail["outbox_refs"]))
                    current = read_settled_c02_reply_source_v1(
                        db, self.__d02_issuer, namespace, receipt,
                        source_ref, snapshot)
                    access_epoch, delete_epoch = self._deletion_epochs_locked(
                        db, namespace)
                    guard = VersionGuard(
                        snapshot.versions,
                        (QueryEpoch(namespace, "all", epoch.revision),),
                        access_epoch, delete_epoch,
                        store._registry.catalogue_hash,
                        self._version(db, namespace, "scheme", "current"),
                        self._version(db, namespace, "operator", "current"),
                        self._version(db, namespace, "policy", "current"),
                        (), (), ())
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("post-C02 attention read changed; HOLD")
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise UnavailableGuard("post-C02 attention graph changed; HOLD")
            return (receipt, snapshot, current.source_qualification,
                    current.conversation_ref, guard, anchor, reading)
        finally:
            port.finish_fence(
                scope, request_id="finish:" + operation_id,
                request_digest="sha256:" + canonical_digest({
                    "action": "finish_reply_attention_read",
                    "operation_id": operation_id,
                    "permit_token": permit.token,
                }))

    def _current_post_c02_reply_inputs_locked(
        self, namespace: NamespaceId, c02_operation_id: str,
        source_ref: str, now_utc: float, epoch: NamespaceEpoch,
    ):
        """Read original C02 and current D06/D07 atoms in this graph tx."""
        from .domains.d07 import attention_ticket_key, read_current_focus_attention_ticket
        from .memory_types import access_key, source_key
        from .runtime.reply_model_job import (
            ReplyModelJobHold, read_current_reply_model_inputs_v1,
            source_key_from_ref,
        )

        db = self.__store._db
        source_id = source_key_from_ref(source_ref, namespace)
        focus_key = AtomKey(
            Owner("persona", *namespace.as_tuple),
            "d07.focus.v1", namespace.persona_id)
        focus = db.execute(
            "SELECT value,valid FROM graph_atoms WHERE token=?",
            (focus_key.token,),
        ).fetchone()
        if focus is None or focus[1] != 1:
            raise ReplyModelJobHold("current D07 focus is absent")
        ticket_ref = json.loads(focus[0]).get("primary_ticket_ref")
        ticket_key = AtomKey.from_token(ticket_ref)
        if ticket_key != attention_ticket_key(namespace, ticket_key.name):
            raise ReplyModelJobHold("current D07 ticket identity differs")
        keys = (source_key(*namespace.as_tuple, source_id),
                access_key(*namespace.as_tuple, source_id),
                focus_key, ticket_key)
        atoms = []
        for key in keys:
            row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms "
                "WHERE token=?", (key.token,),
            ).fetchone()
            atoms.append(GraphAtom(
                key, row[0], json.loads(row[1]), bool(row[2]))
                if row else GraphAtom(key, 0, {}, False))
        snapshot = GraphSnapshot(tuple(atoms), (epoch,))
        attention = read_current_focus_attention_ticket(
            snapshot, namespace, now=now_utc)
        if attention is None:
            raise ReplyModelJobHold("current D07 attention is unavailable")
        c02_row = db.execute(
            "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
            "FROM graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (c02_operation_id,),
        ).fetchone()
        if c02_row is None:
            raise ReplyModelJobHold("original C02 receipt is absent")
        c02_event = db.execute(
            "SELECT reads,revisions,epoch_revision FROM graph_events "
            "WHERE bot=? AND persona=? AND session=? AND event_id=?",
            namespace.as_tuple + (c02_row[1], c02_operation_id),
        ).fetchone()
        if c02_event is None:
            raise ReplyModelJobHold("original C02 graph event is absent")
        c02_detail = json.loads(c02_row[4])
        receipt = CommitReceipt(
            "committed", c02_operation_id, c02_row[0], c02_row[1],
            c02_row[2], c02_row[3],
            GraphStore._version_rows(c02_event[0]),
            GraphStore._version_rows(c02_event[1]),
            (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
            tuple(c02_detail["ledger_refs"]),
            tuple(c02_detail["outbox_refs"]))
        return read_current_reply_model_inputs_v1(
            db, self.__d02_issuer, namespace, receipt,
            source_ref, snapshot, attention)

    def _finish_committed_post_c02_reply_fence_v1(
        self, namespace: NamespaceId, metadata, epoch: NamespaceEpoch,
        anchor, attempt_id: str, anchor_json: str,
        prior_revision: int, prior_epoch: int, action: str,
    ) -> None:
        """Resolve only the original committed write after a lost finish ACK."""
        from .authority_service.v2_contract import FencePermitV2

        port = self.__content_fence_v2
        target = metadata.requirements
        if (port is None or anchor_json != canonical_json(asdict(anchor))
                or action not in {"finish_reply_job", "finish_reply_acquire"}):
            raise UnavailableGuard("reply committed write identity differs; HOLD")
        permit, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if (type(permit) is not FencePermitV2
                or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.holder != self.__holder
                or permit.pinned_anchor != anchor
                or state not in {"active", "finished"}
                or metadata.graph_revision < prior_revision + 1
                or epoch.revision < prior_epoch + 1):
            raise UnavailableGuard("reply committed Authority write differs; HOLD")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (
                    prior_revision + 1, prior_epoch + 1):
                raise UnavailableGuard("reply active write lost graph stamp; HOLD")
            scope = FenceScope(
                namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, prior_epoch),
                prior_revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("reply committed write permit changed; HOLD")
            port.finish_fence(
                scope, request_id="finish:" + attempt_id,
                request_digest="sha256:" + canonical_digest({
                    "action": action, "attempt_id": attempt_id,
                    "permit_token": permit.token,
                }))

    def prepare_post_c02_reply_model_job_v1(
        self, bootstrap: object, namespace: NamespaceId,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Commit one source-qualified reply job, quote and reserve together.

        The graph worker calls this synchronously. All Authority fence RPCs
        occur outside GraphStore's lock; the current C02/source/access/D07
        reads and all business writes occur inside one BEGIN IMMEDIATE.
        """
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .domains.d07 import read_current_focus_attention_ticket
        from .host.authority_profile import AdminIngressClockPolicy, AdminInstallationBundle
        from .memory_types import access_key, source_key
        from .runtime.d11_types import job_graph_write, runtime_job_key
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, install_schema, issue_reply_job_in_transaction_v1,
            read_current_reply_model_inputs_v1, read_saved_reply_job_v1,
            reply_job_original_operation_id_v1, source_key_from_ref,
        )

        self._admin(bootstrap)
        store = self.__store
        port = self.__content_fence_v2
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(namespace) is not NamespaceId
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or self.__d11_issuer.resource_issuer is not self.__d02_issuer
                or installed_bundle.installation_policy.namespace != namespace):
            raise UnavailableGuard("installed reply graph authorities are unavailable; HOLD")
        try:
            source_id = source_key_from_ref(source_ref, namespace)
            now = trusted_upper(port.read_ingress_clock(self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("reply source or trusted clock is unavailable; HOLD") from exc
        original_operation_id = reply_job_original_operation_id_v1(
            c02_operation_id, source_ref)
        input_digest = canonical_digest({
            "schema": "sylanne.post-c02-reply-preparation.v1",
            "namespace": list(namespace.as_tuple),
            "c02_operation_id": c02_operation_id,
            "source_ref": source_ref,
            "installation_id": installed_bundle.installation_policy.installation_id,
            "reply_workflow": ({
                "provider_id": installed_bundle.model_workflows.reply.provider_id,
                "model_id": installed_bundle.model_workflows.reply.model_id,
                "provider_config_digest": installed_bundle.model_workflows.reply.provider_config_digest,
                "template_version": installed_bundle.model_workflows.reply.template_version,
                "quote_ceiling": dict(installed_bundle.model_workflows.reply.quote_ceiling),
            } if installed_bundle.model_workflows is not None else None),
        })
        with store._lock:
            db = store._db
            install_schema(db)
            saved = read_saved_reply_job_v1(
                db, self.__d02_issuer, namespace, c02_operation_id, source_ref)
            attempt = db.execute(
                "SELECT input_digest,attempt_id,anchor_json,graph_revision,"
                "graph_epoch,state FROM graph_post_c02_reply_model_attempts_v1 "
                "WHERE bot=? AND persona=? AND original_operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        provision_row = self._provision_row(store._db, namespace)
        provision = (self._decode_provision_receipt(provision_row)
                     if provision_row is not None else None)
        if (target.namespace != namespace or provision is None
                or provision.generation != target.activation_generation
                or provision.installation_id !=
                   installed_bundle.installation_policy.installation_id
                or provision.authority_id != target.authority_id
                or provision.authority_namespace != target.authority_namespace):
            raise UnavailableGuard("reply graph activation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("reply Authority anchor differs; HOLD")
        if attempt is not None and attempt[0] != input_digest:
            raise EventConflict("reply preparation identity reused with another profile")
        if saved is not None:
            if attempt is None or attempt[5] != "committed":
                raise UnavailableGuard("reply preparation lacks its write fence; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor, attempt[1], attempt[2],
                attempt[3], attempt[4], "finish_reply_job")
            return saved
        if attempt is not None and attempt[5] == "committed":
            raise UnavailableGuard("reply committed fence lacks job; HOLD")
        if attempt is not None and attempt[5] == "open":
            if (attempt[2] != canonical_json(asdict(anchor))
                    or (attempt[3], attempt[4]) != (
                        metadata.graph_revision, epoch.revision)):
                raise UnavailableGuard("reply pending write anchor changed; HOLD")
            attempt_id = attempt[1]
            attempt_was_open = True
        else:
            attempt_id = "reply-job-write-" + secrets.token_hex(24)
            attempt_was_open = False
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before write intent")
                    db.execute(
                        "INSERT INTO graph_post_c02_reply_model_attempts_v1"
                        "(bot,persona,original_operation_id,input_digest,attempt_id,"
                        "anchor_json,graph_revision,graph_epoch,state) "
                        "VALUES(?,?,?,?,?,?,?,?,'open') "
                        "ON CONFLICT(bot,persona,original_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,"
                        "graph_epoch=excluded.graph_epoch,state='open' "
                        "WHERE graph_post_c02_reply_model_attempts_v1.state='closed' "
                        "AND graph_post_c02_reply_model_attempts_v1.input_digest=excluded.input_digest",
                        namespace.as_tuple + (original_operation_id, input_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if attempt_was_open:
            try:
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                # A crash may leave the local exact attempt before begin_fence.
                # Retry that same operation ID; Authority rejects any collision.
                observed_permit, observed_state = None, "absent"
        else:
            observed_permit, observed_state = None, "absent"
        if observed_state == "absent":
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif observed_state == "active":
            permit = observed_permit
        else:
            raise UnavailableGuard("reply write attempt has unresolved Authority state; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id or permit.holder != self.__holder
                or permit.pinned_anchor != anchor):
            raise UnavailableGuard("reply write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply write fence is stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before business write")
                    from .domains.d07 import attention_ticket_key
                    focus_key = AtomKey(
                        Owner("persona", *namespace.as_tuple),
                        "d07.focus.v1", namespace.persona_id)
                    focus = db.execute(
                        "SELECT value,valid FROM graph_atoms WHERE token=?",
                        (focus_key.token,),
                    ).fetchone()
                    if focus is None or focus[1] != 1:
                        raise ReplyModelJobHold("current D07 focus is absent")
                    ticket_ref = json.loads(focus[0]).get("primary_ticket_ref")
                    ticket_key = AtomKey.from_token(ticket_ref)
                    if ticket_key != attention_ticket_key(namespace, ticket_key.name):
                        raise ReplyModelJobHold("current D07 ticket identity differs")
                    source_key_value = source_key(*namespace.as_tuple, source_id)
                    access_key_value = access_key(*namespace.as_tuple, source_id)
                    atoms = []
                    for key in (source_key_value, access_key_value,
                                focus_key, ticket_key):
                        row = db.execute(
                            "SELECT revision,value,valid FROM graph_atoms "
                            "WHERE token=?", (key.token,),
                        ).fetchone()
                        atoms.append(GraphAtom(
                            key, row[0], json.loads(row[1]), bool(row[2]))
                            if row else GraphAtom(key, 0, {}, False))
                    snapshot = GraphSnapshot(tuple(atoms), (epoch,))
                    attention = read_current_focus_attention_ticket(
                        snapshot, namespace, now=now)
                    if attention is None:
                        raise ReplyModelJobHold("current D07 attention is unavailable")
                    c02_row = db.execute(
                        "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                        "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                        "AND operation_id=?",
                        namespace.as_tuple + (c02_operation_id,),
                    ).fetchone()
                    if c02_row is None:
                        raise ReplyModelJobHold("original C02 receipt is absent")
                    c02_event = db.execute(
                        "SELECT reads,revisions,epoch_revision FROM graph_events "
                        "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                        namespace.as_tuple + (c02_row[1], c02_operation_id),
                    ).fetchone()
                    if c02_event is None:
                        raise ReplyModelJobHold("original C02 graph event is absent")
                    c02_detail = json.loads(c02_row[4])
                    c02_receipt = CommitReceipt(
                        "committed", c02_operation_id, c02_row[0], c02_row[1],
                        c02_row[2], c02_row[3],
                        GraphStore._version_rows(c02_event[0]),
                        GraphStore._version_rows(c02_event[1]),
                        (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
                        tuple(c02_detail["ledger_refs"]),
                        tuple(c02_detail["outbox_refs"]))
                    inputs = read_current_reply_model_inputs_v1(
                        db, self.__d02_issuer, namespace, c02_receipt,
                        source_ref, snapshot, attention)
                    job, quote, reservation_digest = (
                        issue_reply_job_in_transaction_v1(
                            db, namespace=namespace, inputs=inputs,
                            installed_bundle=installed_bundle,
                            d02_issuer=self.__d02_issuer,
                            d11_issuer=self.__d11_issuer, now_utc=now))
                    write = job_graph_write(job)
                    reconcile_runtime_write(db, write)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple, job.activity_id),
                              original_operation_id, now, "domain_bundle",
                              {"bundle_digest": input_digest}),
                        (GraphVersion(write.key, 0),) + snapshot.versions,
                        (GraphWrite(write.key, write.value,
                                    (source_key_value, access_key_value,
                                     ticket_key, focus_key)),), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("reply graph job did not commit")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence "
                        "WHERE bot=? AND persona=?",
                        namespace.as_tuple,
                    ).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq",
                        namespace.as_tuple + (seq,),
                    )
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (original_operation_id,
                        input_digest, job.activity_id, None, seq,
                        canonical_json({
                            "c02_operation_id": c02_operation_id,
                            "source_ref": source_ref,
                            "job_ref": write.key.token,
                            "quote_id": quote.quote_id,
                            "reservation_digest": reservation_digest,
                            "ledger_refs": [write.key.token],
                            "outbox_refs": [],
                        })),
                    )
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_attempts_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=?",
                        namespace.as_tuple + (original_operation_id, attempt_id),
                    )
                    saved = read_saved_reply_job_v1(
                        db, self.__d02_issuer, namespace,
                        c02_operation_id, source_ref)
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_reply_job", "attempt_id": attempt_id,
                        "permit_token": permit.token,
                    }))
                with store._lock:
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_attempts_v1 "
                        "SET state='closed' WHERE bot=? AND persona=? "
                        "AND original_operation_id=? AND attempt_id=? AND state='open'",
                        namespace.as_tuple + (original_operation_id, attempt_id),
                    )
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply committed write fence outcome unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_job", "attempt_id": attempt_id,
                "permit_token": permit.token,
            }))
        return saved

    def acquire_post_c02_reply_model_job_v1(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, source_ref: str, installed_bundle,
        *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire the original queued reply job and freeze its exact call."""
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.contract import AuthorityUnavailable
        from .host.authority_profile import AdminInstallationBundle
        from .host.installed_reply_model_driver import reply_model_operation_id_v1
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, freeze_acquired_reply_binding_v1,
            install_schema, read_saved_reply_job_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        acquire_operation_id = reply_model_operation_id_v1(
            c02_operation_id, source_ref)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace
                or type(lease_seconds) is not int
                or not 1 <= lease_seconds <= 3600):
            raise UnavailableGuard("installed reply acquire authorities are absent; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11"
                or authority.purpose != "proposal"
                or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("reply acquire requires original D11 worker lease")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)
        now_text = __import__("datetime").datetime.fromtimestamp(
            now, __import__("datetime").timezone.utc).isoformat().replace(
                "+00:00", "Z")
        with store._lock:
            db = store._db
            install_schema(db)
            saved = read_saved_reply_job_v1(
                db, self.__d02_issuer, namespace, c02_operation_id, source_ref)
            if saved is None:
                raise ReplyModelJobHold("original queued reply job is absent")
            row = db.execute(
                "SELECT state,acquire_operation_id,actor,worker_fence,"
                "model_request_digest FROM graph_post_c02_reply_model_preparations_v1 "
                "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                namespace.as_tuple + (c02_operation_id, source_ref),
            ).fetchone()
            committed_attempt = db.execute(
                "SELECT attempt_id,anchor_json,graph_revision,graph_epoch,state "
                "FROM graph_post_c02_reply_model_acquires_v1 WHERE bot=? "
                "AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            metadata, epoch = self._v2_graph_stamp(namespace)
        if row[0] == "acquired":
            if (row[1] != acquire_operation_id or row[2] != authority.actor
                    or row[3] != saved.job.fence
                    or not row[4] or saved.job.phase != "running"
                    or saved.job.lease_holder != authority.actor
                    or committed_attempt is None
                    or committed_attempt[4] != "committed"):
                raise ReplyModelJobHold("original reply acquire identity differs")
            target = metadata.requirements
            anchor = port.current_anchor(
                namespace=namespace,
                authority_namespace=target.authority_namespace)
            if not self._anchor_matches(target, anchor):
                raise UnavailableGuard("reply acquire replay anchor differs; HOLD")
            self._finish_committed_post_c02_reply_fence_v1(
                namespace, metadata, epoch, anchor,
                committed_attempt[0], committed_attempt[1],
                committed_attempt[2], committed_attempt[3],
                "finish_reply_acquire")
            return saved.job
        if row[0] != "queued" or saved.job.phase != "queued":
            raise ReplyModelJobHold("reply job is not queued")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if (target.activation_generation != authority.activation_generation
                or not self._anchor_matches(target, anchor)):
            raise UnavailableGuard("reply acquire Authority anchor differs; HOLD")
        request_digest = canonical_digest({
            "schema": "sylanne.post-c02-reply-acquire.v1",
            "original_operation_id": saved.original_operation_id,
            "acquire_operation_id": acquire_operation_id,
            "job_id": saved.job.job_id, "actor": authority.actor,
            "lease_seconds": lease_seconds,
            "expected_fence": saved.job.fence,
        })
        with store._lock:
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("reply graph changed before acquire intent")
                attempt = db.execute(
                    "SELECT request_digest,attempt_id,anchor_json,graph_revision,"
                    "graph_epoch,state FROM graph_post_c02_reply_model_acquires_v1 "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
                ).fetchone()
                if attempt is not None and attempt[0] != request_digest:
                    raise EventConflict("reply acquire identity reused with different input")
                if attempt is None or attempt[5] == "closed":
                    attempt_id = "reply-acquire-write-" + secrets.token_hex(24)
                    attempt_was_open = False
                    db.execute(
                        "INSERT INTO graph_post_c02_reply_model_acquires_v1"
                        "(bot,persona,acquire_operation_id,original_operation_id,"
                        "request_digest,attempt_id,anchor_json,graph_revision,"
                        "graph_epoch,state) VALUES(?,?,?,?,?,?,?,?,?,'open') "
                        "ON CONFLICT(bot,persona,acquire_operation_id) DO UPDATE SET "
                        "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                        "graph_revision=excluded.graph_revision,graph_epoch=excluded.graph_epoch,"
                        "state='open' WHERE graph_post_c02_reply_model_acquires_v1.state='closed' "
                        "AND graph_post_c02_reply_model_acquires_v1.request_digest=excluded.request_digest",
                        namespace.as_tuple + (acquire_operation_id,
                        saved.original_operation_id, request_digest,
                        attempt_id, canonical_json(asdict(anchor)),
                        metadata.graph_revision, epoch.revision),
                    )
                elif attempt[5] == "open" and (
                        attempt[2] == canonical_json(asdict(anchor))
                        and attempt[3:5] == (
                            metadata.graph_revision, epoch.revision)):
                    attempt_id = attempt[1]
                    attempt_was_open = True
                else:
                    raise ReplyModelJobHold("reply acquire attempt is unresolved")
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        if attempt_was_open:
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except AuthorityUnavailable:
                # Keep the original durable attempt across an interrupted begin.
                observed, state = None, "absent"
        else:
            observed, state = None, "absent"
        if state == "absent":
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor)
        elif state == "active":
            permit = observed
        else:
            raise UnavailableGuard("reply acquire fence outcome unknown; HOLD")
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder):
            raise UnavailableGuard("reply acquire write permit differs; HOLD")
        scope = FenceScope(
            namespace, target.authority_namespace, target.activation_generation,
            "write", attempt_id, permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply acquire write fence stale; HOLD")
        try:
            with store._lock:
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("reply graph changed before acquire")
                    inputs = self._current_post_c02_reply_inputs_locked(
                        namespace, c02_operation_id, source_ref, now, epoch)
                    frozen = db.execute(
                        "SELECT source_revision,access_revision,attention_ticket_id,"
                        "focus_revision,audience,graph_job_revision "
                        "FROM graph_post_c02_reply_model_preparations_v1 "
                        "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                        namespace.as_tuple + (c02_operation_id, source_ref),
                    ).fetchone()
                    if frozen != (
                            inputs.source.source_revision,
                            inputs.source.access_revision,
                            inputs.attention.ticket.ticket_id,
                            inputs.attention.focus_version.revision,
                            inputs.conversation_ref, saved.graph_job_revision):
                        raise ReplyModelJobHold("queued reply source or attention changed")
                    if authority.audience != (inputs.conversation_ref,):
                        raise AuthorityDenied("reply worker audience differs")
                    if (installed_bundle.installation_policy.catalogue_hash
                            != store._registry.catalogue_hash
                            or installed_bundle.installation_policy.scheme_version
                            != self._version(db, namespace, "scheme", "current")
                            or installed_bundle.installation_policy.operator_version
                            != self._version(db, namespace, "operator", "current")
                            or installed_bundle.installation_policy.policy_version
                            != self._version(db, namespace, "policy", "current")):
                        raise ReplyModelJobHold("reply installed guard versions changed")
                    current = get_job(db, saved.job.job_id)
                    if current != saved.job:
                        raise ReplyModelJobHold("reply D11 job changed")
                    planned = plan_job_acquire(
                        current, authority.actor, now_utc=now_text,
                        lease_seconds=lease_seconds)
                    worker_authority = replace(authority, worker_fence=planned.fence)
                    quote = self.__d02_issuer.original_signed_quote(
                        db, saved.quote.quote_id, saved.quote.version)
                    access_epoch, delete_epoch = self._deletion_epochs_locked(
                        db, namespace)
                    envelope, installed, binding_digest, request_json = (
                        freeze_acquired_reply_binding_v1(
                            db, namespace=namespace, inputs=inputs,
                            job=planned, quote=quote, authority=worker_authority,
                            installed_bundle=installed_bundle,
                            graph_epoch=epoch.revision,
                            access_epoch=access_epoch,
                            delete_epoch=delete_epoch, now_utc=now,
                            monotonic_now=reading.monotonic_after_seconds,
                            acquire_operation_id=acquire_operation_id))
                    acquired = acquire_job(
                        db, current.job_id, authority.actor,
                        now_utc=now_text, lease_seconds=lease_seconds)
                    if acquired != planned:
                        raise ReplyModelJobHold("reply job acquire CAS differed")
                    write = job_graph_write(acquired)
                    reconcile_runtime_write(db, write)
                    candidate = GraphCandidate(
                        Event(Scope(*namespace.as_tuple, current.activity_id),
                              acquire_operation_id, now, "domain_bundle",
                              {"bundle_digest": request_digest}),
                        (GraphVersion(write.key, saved.graph_job_revision),)
                        + inputs.graph_snapshot.versions,
                        (GraphWrite(write.key, write.value,
                                    tuple(atom.key for atom in
                                          inputs.graph_snapshot.atoms)),),
                        (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("reply acquire graph event differs")
                    store.cas_graph_recovery_metadata(
                        metadata, metadata.requirements,
                        _capability=self.__graph_capability)
                    changed = db.execute(
                        "UPDATE graph_post_c02_reply_model_preparations_v1 SET "
                        "state='acquired',acquire_operation_id=?,actor=?,worker_fence=?,"
                        "call_id=?,model_request_digest=?,binding_digest=?,"
                        "envelope_json=?,request_json=?,graph_job_revision=? "
                        "WHERE bot=? AND persona=? AND c02_operation_id=? "
                        "AND source_ref=? AND state='queued'",
                        (acquire_operation_id, authority.actor, acquired.fence,
                         installed.request.call_id, installed.request.digest,
                         binding_digest, canonical_serialize(envelope),
                         request_json, graph_receipt.revisions[0].revision)
                        + namespace.as_tuple + (c02_operation_id, source_ref),
                    ).rowcount
                    if changed != 1:
                        raise ReplyModelJobHold("reply acquire row CAS differs")
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_acquires_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=? AND attempt_id=?",
                        namespace.as_tuple + (acquire_operation_id, attempt_id),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        except BaseException:
            try:
                port.finish_fence(
                    scope, request_id="finish:" + attempt_id,
                    request_digest="sha256:" + canonical_digest({
                        "action": "abort_reply_acquire", "attempt_id": attempt_id,
                        "permit_token": permit.token}))
                with store._lock:
                    db.execute(
                        "UPDATE graph_post_c02_reply_model_acquires_v1 SET state='closed' "
                        "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                        "AND attempt_id=? AND state='open'",
                        namespace.as_tuple + (acquire_operation_id, attempt_id))
            except Exception:
                pass
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("reply acquire committed but finish unknown; HOLD")
        port.finish_fence(
            scope, request_id="finish:" + attempt_id,
            request_digest="sha256:" + canonical_digest({
                "action": "finish_reply_acquire", "attempt_id": attempt_id,
                "permit_token": permit.token}))
        return acquired

    def read_post_c02_reply_model_egress_preparation_v1(
        self, authority: AuthorityContext, lease: object,
        c02_operation_id: str, source_ref: str, installed_bundle,
    ):
        """Return a current reply draft; only Authority can issue its intent."""
        from datetime import datetime

        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminInstallationBundle
        from .host.installed_reply_model_driver import reply_model_operation_id_v1
        from .model_broker.reply_language import freeze_installed_reply_request_v1
        from .runtime.budget import get_budget_lease
        from .runtime.d11_types import job_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.reply_model_job import (
            ReplyModelJobHold, read_saved_reply_job_v1,
            reply_binding_digest_v1, reply_envelope_from_wire_v1,
            reply_request_wire_v1,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        acquire_operation_id = reply_model_operation_id_v1(
            c02_operation_id, source_ref)
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(installed_bundle) is not AdminInstallationBundle
                or installed_bundle.ingress_clock != self.__scene_clock_policy
                or installed_bundle.installation_policy.namespace != namespace
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer):
            raise UnavailableGuard("installed reply model preparation is unavailable; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11"
                or authority.purpose != "proposal"
                or authority.worker_fence is None
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("reply model requires the original D11 worker")
        reading = port.read_ingress_clock(self.__scene_clock_policy)
        now = trusted_upper(reading)

        def reader():
            db = store._db
            db.execute("BEGIN")
            try:
                metadata, epoch = self._v2_graph_stamp(namespace)
                inputs = self._current_post_c02_reply_inputs_locked(
                    namespace, c02_operation_id, source_ref, now, epoch)
                saved = read_saved_reply_job_v1(
                    db, self.__d02_issuer, namespace,
                    c02_operation_id, source_ref)
                row = db.execute(
                    "SELECT c02_receipt_digest,source_id,source_revision,"
                    "access_revision,attention_ticket_id,focus_revision,audience,"
                    "state,acquire_operation_id,actor,worker_fence,call_id,"
                    "model_request_digest,binding_digest,envelope_json,request_json "
                    "FROM graph_post_c02_reply_model_preparations_v1 "
                    "WHERE bot=? AND persona=? AND c02_operation_id=? AND source_ref=?",
                    namespace.as_tuple + (c02_operation_id, source_ref),
                ).fetchone()
                if saved is None or row is None:
                    raise ReplyModelJobHold("acquired reply preparation is absent")
                job, quote = saved.job, saved.quote
                deadline = datetime.fromisoformat(
                    job.deadline_utc.replace("Z", "+00:00")).timestamp()
                expiry = datetime.fromisoformat(
                    job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
                lease_state = get_budget_lease(db, job.budget_ref)
                grant = self.__d11_issuer.current_budget_grant(
                    db, job.budget_ref)
                reserve = db.execute(
                    "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone()
                reserve_op = db.execute(
                    "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                    "AND persona_id=? AND operation_id=? AND phase='reserve'",
                    namespace.as_tuple + (job.operation_id,),
                ).fetchone()
                acquire = db.execute(
                    "SELECT state FROM graph_post_c02_reply_model_acquires_v1 "
                    "WHERE bot=? AND persona=? AND acquire_operation_id=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,
                                          job.operation_id),
                ).fetchone()
                if (row[0] != canonical_digest(asdict(inputs.c02_receipt))
                        or row[1:7] != (
                            inputs.source.source.source_id,
                            inputs.source.source_revision,
                            inputs.source.access_revision,
                            inputs.attention.ticket.ticket_id,
                            inputs.attention.focus_version.revision,
                            inputs.conversation_ref)
                        or row[7:11] != (
                            "acquired", acquire_operation_id,
                            authority.actor, authority.worker_fence)
                        or acquire != ("committed",)
                        or job.phase != "running"
                        or job.lease_holder != authority.actor
                        or job.fence != authority.worker_fence
                        or job.cancel_epoch != 0 or job.result_ref is not None
                        or not now < min(expiry, deadline, quote.valid_until_utc)
                        or authority.audience != (inputs.conversation_ref,)
                        or grant != installed_bundle.installation_policy.root_grant
                        or lease_state.state != "active"
                        or reserve is None or reserve_op is None
                        or reserve != (
                            saved.reservation_digest,
                            canonical_json(dict(quote.ceiling)), "reserved")
                        or reserve_op != (saved.reservation_digest,)
                        or row[14] is None or row[15] is None):
                    raise ReplyModelJobHold("original reply model eligibility changed")
                envelope = reply_envelope_from_wire_v1(row[14])
                installed = freeze_installed_reply_request_v1(
                    envelope, inputs.source, bundle=installed_bundle)
                request = installed.request
                if (envelope.authority != authority
                        or row[11] != request.call_id
                        or row[12] != request.digest
                        or row[13] != reply_binding_digest_v1(
                            job, inputs, acquire_operation_id,
                            request.call_id, request.digest)
                        or row[15] != canonical_serialize(
                            reply_request_wire_v1(envelope, request))
                        or quote.ceiling != installed.quote_ceiling
                        or job_graph_write(job).key.token !=
                           saved.quote.graph_job_ref):
                    raise ReplyModelJobHold("frozen reply binding differs")
                epochs = self._deletion_epochs_locked(db, namespace)
                result = (inputs, saved, envelope, installed,
                          row[13], epochs, metadata, epoch)
                db.execute("COMMIT")
                return result
            except BaseException:
                db.execute("ROLLBACK")
                raise

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        inputs, saved, envelope, installed, binding_digest, epochs, _, _ = prepared
        target = metadata.requirements
        job = saved.job
        request = installed.request
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            acquire_operation_id, request.call_id, request.digest,
            job.job_id, job.fence,
            (inputs.source.source.source_id,),
            ((inputs.source.source.source_id, inputs.source.source_revision),),
            ((inputs.source.source.source_id, inputs.source.access_revision),),
            epochs[0], epochs[1], epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, job.operation_id, saved.reservation_digest,
            tuple(sorted(saved.quote.ceiling.items())),
            request.provider_id, request.model_id,
            installed.provider_config_digest, request.max_output_tokens,
            acquire_operation_id=acquire_operation_id,
            binding_digest=binding_digest,
        )
        return (inputs.c02_receipt, envelope, inputs.source,
                inputs.attention.ticket, inputs.attention.focus_version.revision,
                draft, anchor)

    def read_first_ingress_model_egress_preparation_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ) -> tuple[EncodingCallBinding, ModelEgressDraftV1, RestoreAnchor]:
        """Return one current binding, Authority draft, and pinned restore anchor.

        The paired clock and all Authority fence RPCs run outside the graph
        lock. No graph version, budget ceiling, or Authority head is supplied by
        the host. The later Authority prepare independently verifies currentness.
        """
        from .authority_service.v2_model_egress_contract import ModelEgressDraftV1
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.budget import get_budget_lease
        from .runtime.d11_types import runtime_job_key
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("v2 model preparation requires installed graph authorities")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    authority.namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("model preparation requires the job-bound D11 lease")
        try:
            clock = self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy)
            now = trusted_upper(clock)
        except Exception as exc:
            raise UnavailableGuard("model preparation trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            binding, job, outbox, outbox_key = (
                self._first_ingress_encoding_binding_locked(
                    authority, job_id, acquire_operation_id, clock, now))
            quote_ref = job.operator_versions["resource_quote"]
            quote_id, version_text = quote_ref.rsplit(":", 1)
            quote = self.__d02_issuer.original_signed_quote(
                db, quote_id, int(version_text))
            reservation = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (job.budget_ref, job.operation_id),
            ).fetchone()
            reserve_receipt = db.execute(
                "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='reserve'",
                authority.namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            lease = get_budget_lease(db, job.budget_ref)
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", authority.namespace.as_tuple,
            ).fetchone()
            ceiling = quote.ceiling
            if (reservation is None or reserve_receipt is None or epochs is None
                    or reservation[2] != "reserved"
                    or reservation[0] != reserve_receipt[0]
                    or reservation[1] != canonical_json(ceiling)
                    or (lease.bot_id, lease.persona_id)
                    != authority.namespace.as_tuple or lease.state != "active"
                    or any(lease.reserved.get(key, 0) < amount
                           for key, amount in ceiling.items())
                    or (quote.bot_id, quote.persona_id, quote.activity_id,
                        quote.operation_id, quote.effect_id, quote.graph_job_ref,
                        quote.outbox_refs, quote.parent_budget_lease_ref,
                        quote.work_kind, quote.snapshot_ref, quote.resource_ref)
                    != (*authority.namespace.as_tuple, job.activity_id,
                        job.operation_id, None,
                        runtime_job_key(*authority.namespace.as_tuple,
                                        job.activity_id, job.job_id).token,
                        (outbox_key.token,), job.budget_ref, job.work_kind,
                        job.snapshot_ref, job.resource_ref)
                    or binding.budget_lease_id != job.budget_ref
                    or binding.budget_reservation_operation_id != job.operation_id):
                raise UnavailableGuard("original model budget or quote changed; HOLD")
            return binding, job, reservation[0], tuple(sorted(ceiling.items())), epochs

        (prepared, anchor, metadata, epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        binding, job, reservation_digest, ceiling, epochs = prepared
        target = metadata.requirements
        frozen = binding.request
        draft = ModelEgressDraftV1(
            target.authority_id, target.authority_namespace, authority.actor,
            acquire_operation_id, binding.call_id, binding.model_request_digest,
            job_id, job.fence, (binding.source_id,),
            ((binding.source_id, binding.source_revision),),
            ((binding.source_id, binding.access_revision),),
            epochs[0], epochs[1], epoch.revision, metadata.graph_revision,
            target.activation_generation, target.revocation_epoch,
            target.deletion_seq, target.execution_seq,
            job.budget_ref, job.operation_id, reservation_digest, ceiling,
            frozen["provider_id"], frozen["model_id"],
            frozen["provider_config_digest"], frozen["max_output_tokens"],
            acquire_operation_id=acquire_operation_id,
            binding_digest=binding.binding_digest,
        )
        return binding, draft, anchor

    def read_first_ingress_original_model_result_context_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str,
    ):
        """Read historical model identity under a current worker content fence.

        This is a result-consumption context, not another model dispatch.
        Original D11 reservation, quote expiry, and current outbox phase are
        deliberately absent from its *current* eligibility checks.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .memory_types import SourceRecord, access_key, source_key, validate_access
        from .runtime.d11_types import RuntimeOutboxValue, job_graph_write, runtime_job_key
        from .runtime.encoding_call_binding import (
            binding_from_json, binding_to_json, load_binding,
        )
        from .runtime.first_ingress_v2 import ingress_ids, trusted_upper
        from .runtime.issuers import D02ResourceIssuer, D11BudgetJobIssuer
        from .runtime.original_model_result_context import OriginalModelResultContextV1

        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or type(self.__d02_issuer) is not D02ResourceIssuer
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed worker result read authorities required")
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        namespace = authority.namespace
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or authority.purpose != "consolidation"
                or type(acquire_operation_id) is not str
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("original result read requires the job-bound D11 lease")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("worker result trusted clock unavailable; HOLD") from exc

        def reader():
            db = self.__store._db
            job = get_job(db, job_id)
            if ((job.bot_id, job.persona_id) != namespace.as_tuple
                    or job.work_kind != "d06.encode_source"
                    or job.effect_id is not None or job.phase != "running"
                    or job.lease_holder != authority.actor
                    or job.fence != authority.worker_fence or job.fence < 1
                    or job.cancel_epoch != 0 or job.result_ref is not None
                    or job.lease_expires_utc is None):
                raise UnavailableGuard("worker result job lease is not current; HOLD")
            expiry = datetime.fromisoformat(
                job.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            deadline = datetime.fromisoformat(
                job.deadline_utc.replace("Z", "+00:00")).timestamp()
            if now >= min(expiry, deadline):
                raise UnavailableGuard("worker result lease or deadline expired; HOLD")
            if not _job_acquire_id_matches(
                    acquire_operation_id, namespace, job_id, job.operation_id,
                    authority.actor, authority.activation_generation):
                raise AuthorityDenied("original result acquire identity differs")

            job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
            job_atom = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (job_key.token,),
            ).fetchone()
            if (job_atom is None or job_atom[2] != 1
                    or json.loads(job_atom[1]) != job_graph_write(job).value):
                raise UnavailableGuard("worker result job projection differs; HOLD")

            ingress = db.execute(
                "SELECT activity_id,effect_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            if ingress is None or ingress[:2] != (job.activity_id, None):
                raise UnavailableGuard("original committed ingress is absent; HOLD")
            ingress_receipt = json.loads(ingress[2])
            outbox_refs = ingress_receipt.get("outbox_refs")
            if (job_key.token not in ingress_receipt.get("ledger_refs", ())
                    or type(outbox_refs) is not list or len(outbox_refs) != 1):
                raise UnavailableGuard("original ingress job/outbox identity differs; HOLD")
            outbox_token = outbox_refs[0]
            outbox_key = AtomKey.from_token(outbox_token)
            if (outbox_key.type_name != "runtime.outbox"
                    or outbox_key.owner != Owner(
                        "activity", *namespace.as_tuple, job.activity_id)):
                raise UnavailableGuard("original outbox identity differs; HOLD")
            # The ingress event's first outbox write is historical evidence.
            # Its present phase is irrelevant to result consumption.
            outbox_rows = db.execute(
                "SELECT value FROM graph_history WHERE token=? AND valid=1 "
                "AND event_bot=? AND event_persona=? AND event_session=? "
                "AND event_id=?",
                (outbox_token, *namespace.as_tuple, job.activity_id,
                 job.operation_id),
            ).fetchall()
            if len(outbox_rows) != 1:
                raise UnavailableGuard("original ingress outbox write is absent; HOLD")
            outbox = RuntimeOutboxValue(**json.loads(outbox_rows[0][0]))
            expected = ingress_ids(outbox.payload_ref)
            if ((outbox.bot_id, outbox.persona_id, outbox.activity_id,
                 outbox.operation_id, outbox.effect_id, outbox.job_id,
                 outbox.job_ref, outbox.outbox_id,
                 outbox.idempotency_key, outbox.phase) != (
                    *namespace.as_tuple, job.activity_id, job.operation_id,
                    None, job_id, job_key.token, expected[4], expected[5],
                    "pending")
                    or expected[1:5] != (
                        job.activity_id, job.operation_id, job_id,
                        outbox.outbox_id)):
                raise UnavailableGuard("original outbox does not bind this job; HOLD")

            acquire = db.execute(
                "SELECT i.job_id,i.original_operation_id,i.actor,"
                "i.encoding_binding_json,r.job_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchall()
            binding = load_binding(db, namespace, job_id)
            if len(acquire) != 1 or binding is None or acquire[0][3] is None:
                raise UnavailableGuard("original committed acquire/binding is absent; HOLD")
            frozen_job = json.loads(acquire[0][4])
            historical_requirements = json.loads(acquire[0][5])
            if (acquire[0][:4] != (
                    job_id, job.operation_id, authority.actor,
                    binding_to_json(binding))
                    or binding_from_json(acquire[0][3]) != binding
                    or frozen_job.get("job_id") != job_id
                    or frozen_job.get("fence") != job.fence
                    or frozen_job.get("lease_holder") != authority.actor
                    or frozen_job.get("lease_expires_utc") != job.lease_expires_utc
                    or historical_requirements.get("namespace") != asdict(namespace)
                    or not historical_requirements.get("graph_incarnation")):
                raise UnavailableGuard("original acquire differs from current worker; HOLD")
            if db.execute(
                    "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                    "WHERE bot=? AND persona=? AND "
                    "(call_id=? OR source_id=?) LIMIT 1",
                    namespace.as_tuple + (binding.call_id, binding.source_id),
            ).fetchone() is not None:
                raise UnavailableGuard("original encoding binding was redacted; HOLD")
            frozen = binding.request
            envelope_authority = frozen["envelope"]["authority"]
            if (frozen["schema"] not in {
                    "sylanne.first-ingress-encoding-call.v2",
                    "sylanne.first-ingress-encoding-call.v3"}
                    or frozen["acquire_operation_id"] != acquire_operation_id
                    or frozen["original_operation_id"] != job.operation_id
                    or frozen["worker_fence"] != job.fence
                    or frozen["worker_lease_expires_utc"] != job.lease_expires_utc
                    or frozen["source_id"] != outbox.payload_ref
                    or binding.source_id != outbox.payload_ref
                    or binding.budget_lease_id != job.budget_ref
                    or binding.budget_reservation_operation_id != job.operation_id
                    or envelope_authority["actor"] != authority.actor
                    or envelope_authority["worker_fence"] != job.fence
                    or envelope_authority["purpose"] != "consolidation"):
                raise UnavailableGuard("original model binding identity differs; HOLD")
            if frozen["schema"] == "sylanne.first-ingress-encoding-call.v3":
                current_metadata, current_epoch = self._v2_graph_stamp(namespace)
                baseline = self._committed_first_ingress_baseline_locked(
                    namespace, binding.source_id, current_metadata, current_epoch,
                    acquire_stamp=acquire[0][6:8])
                if frozen.get("baseline") != asdict(baseline):
                    raise UnavailableGuard("original V3 D04 baseline identity differs; HOLD")

            # Historical signatures remain checkable after D11 settlement or
            # grant/quote revocation. Neither is used as a new-work permit.
            quote_ref = job.operator_versions.get("resource_quote")
            if type(quote_ref) is not str or ":" not in quote_ref:
                raise UnavailableGuard("original encoding quote reference is absent; HOLD")
            quote_id, version_text = quote_ref.rsplit(":", 1)
            quote = self.__d02_issuer.original_signed_quote(
                db, quote_id, int(version_text))
            issuance = db.execute(
                "SELECT activation_generation,quote_id,grant_id "
                "FROM runtime_ingress_issuance WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("original provisioning receipt is absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                db, provision.root_lease_id, provision.root_grant_version)
            if (issuance != (authority.activation_generation,
                            quote_id, grant.grant_id)
                    or (provision.authority_id, provision.authority_namespace,
                        provision.generation, provision.root_lease_id,
                        provision.root_grant_id,
                        provision.root_grant_signature) != (
                        historical_requirements["authority_id"],
                        historical_requirements["authority_namespace"],
                        authority.activation_generation, job.budget_ref,
                        grant.grant_id, signature)
                    or (grant.bot_id, grant.persona_id, grant.lease_id) != (
                        *namespace.as_tuple, job.budget_ref)
                    or job.work_kind not in grant.allowed_work_kinds
                    or (quote.bot_id, quote.persona_id, quote.activity_id,
                        quote.operation_id, quote.effect_id,
                        quote.parent_budget_lease_ref, quote.work_kind,
                        quote.graph_job_ref, quote.outbox_refs) != (
                        *namespace.as_tuple, job.activity_id,
                        job.operation_id, None, job.budget_ref, job.work_kind,
                        job_key.token, (outbox_token,))):
                raise UnavailableGuard("original signed encoding bounds differ; HOLD")
            original_reservation = db.execute(
                "SELECT digest,ceiling_json FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (job.budget_ref, job.operation_id),
            ).fetchone()
            original_reserve_receipt = db.execute(
                "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='reserve'",
                namespace.as_tuple + (job.operation_id,),
            ).fetchone()
            if (original_reservation is None or original_reserve_receipt is None
                    or original_reservation != (
                        original_reserve_receipt[0], canonical_json(quote.ceiling))):
                raise UnavailableGuard("original reservation identity differs; HOLD")
            self._original_first_ingress_qualification_locked(
                namespace, job.operation_id,
                source_key(*namespace.as_tuple, binding.source_id).token)

            source_key_value = source_key(*namespace.as_tuple, binding.source_id)
            access_key_value = access_key(*namespace.as_tuple, binding.source_id)
            source_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_key_value.token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_key_value.token,),
            ).fetchone()
            dependency = db.execute(
                "SELECT dependency_revision FROM graph_dependencies WHERE "
                "dependent_token=? AND dependency_token=?",
                (access_key_value.token, source_key_value.token),
            ).fetchone()
            if (source_row is None or access_row is None
                    or source_row[2] != 1 or access_row[2] != 1
                    or source_row[0] != binding.source_revision
                    or access_row[0] != binding.access_revision
                    or dependency != (source_row[0],)):
                raise UnavailableGuard("worker result source/access version changed; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access = json.loads(access_row[1])
            validate_access(access)
            audience = envelope_authority["audience"]
            if (source.source_id != binding.source_id
                    or access["source_id"] != binding.source_id
                    or access["status"] != "active"
                    or "consolidation" not in source.purposes
                    or "consolidation" not in access["purposes"]
                    or type(audience) is not list or not audience
                    or not set(audience).issubset(source.audiences)
                    or not set(audience).issubset(access["audiences"])):
                raise UnavailableGuard("worker result source access revoked; HOLD")
            epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("worker result authority epochs absent; HOLD")
            return (binding, job, epochs,
                    historical_requirements["graph_incarnation"],
                    provision.installation_id)

        (prepared, anchor, metadata, graph_epoch) = self._read_v2(
            authority, reader, return_recovery_context=True)
        binding, job, epochs, original_incarnation, installation_id = prepared
        target = metadata.requirements
        if (target.namespace != namespace
                or target.graph_incarnation != original_incarnation):
            raise UnavailableGuard("worker result graph recovery identity differs; HOLD")
        return OriginalModelResultContextV1(
            namespace, target.authority_id, target.authority_namespace,
            installation_id,
            target.graph_incarnation, metadata.graph_revision,
            graph_epoch.revision, *epochs, job_id, acquire_operation_id,
            job.operation_id, binding.call_id, binding.binding_digest,
            binding.model_request_digest, binding.source_id,
            binding.source_revision, binding.access_revision,
            authority.actor, job.fence, job.lease_expires_utc, anchor)

    def discover_first_ingress_unacquired_v1(
        self, bootstrap: object, namespace: NamespaceId,
        after_job_id: str | None = None, limit: int = 8,
    ):
        """Find original queued C01 work under a fresh paired read fence.

        The keyset is only a traversal hint. Every returned row is requalified
        against the current graph, D06 grant, D11 job, and committed D03/D04
        baseline; the page carries no worker or model authority.
        """
        from datetime import datetime

        from .host.authority_profile import AdminIngressClockPolicy
        from .host.d06_ingress import ingress_content_fingerprint
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .memory_types import SourceRecord, validate_access
        from .runtime.first_ingress_unacquired import (
            FirstIngressUnacquiredItemV1, FirstIngressUnacquiredPageV1,
        )
        from .runtime.first_ingress_v2 import ingress_ids, trusted_upper
        from .runtime.ingress_observation import read_committed_ingress_identity

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId or type(limit) is not int
                or not 1 <= limit <= 8
                or after_job_id is not None and (
                    type(after_job_id) is not str or not after_job_id
                    or len(after_job_id) > 128)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d11_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed bounded ingress discovery required")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("ingress discovery clock unavailable; HOLD") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "unacquired-discovery", namespace,
            ("activity",), "context", ("internal",),
            "unacquired-discovery-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("ingress discovery provisioning absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (target.namespace != namespace
                    or provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation):
                raise UnavailableGuard("ingress discovery installation differs; HOLD")
            last = after_job_id or ""
            items = []
            while True:
                rows = db.execute(
                    "SELECT job_id FROM runtime_jobs WHERE bot_id=? AND "
                    "persona_id=? AND job_id>? AND work_kind='d06.encode_source' "
                    "ORDER BY job_id LIMIT ?",
                    namespace.as_tuple + (last, limit + 1),
                ).fetchall()
                if not rows:
                    break
                for (job_id,) in rows[:limit]:
                    last = job_id
                    try:
                        job, job_key, _, outbox, _, _, source_version, access_version = (
                            self._first_ingress_encoding_job_locked(namespace, job_id))
                        if (job.phase != "queued" or job.fence != 0
                                or job.lease_holder is not None
                                or job.lease_expires_utc is not None
                                or job.cancel_epoch != 0 or job.result_ref is not None
                                or now >= datetime.fromisoformat(
                                    job.deadline_utc.replace("Z", "+00:00")
                                ).timestamp()):
                            continue
                        self.__d11_issuer.authorize_existing_encoding_job(
                            db, job, now_utc=now)
                        source_id = outbox.payload_ref
                        if (job.operation_id != ingress_ids(source_id)[2]
                                or job_id != ingress_ids(source_id)[3]
                                or db.execute(
                                    "SELECT 1 FROM graph_job_acquire_intents_v2 "
                                    "WHERE bot=? AND persona=? AND job_id=? LIMIT 1",
                                    namespace.as_tuple + (job_id,),
                                ).fetchone() is not None):
                            continue
                        receipt = read_committed_ingress_identity(
                            db, namespace, source_id)
                        if receipt is None:
                            continue
                        identity = json.loads(receipt.identity_json)
                        intent = db.execute(
                            "SELECT identity_json,requirements_json FROM "
                            "graph_first_ingress_intents_v2 WHERE bot=? AND "
                            "persona=? AND operation_id=?",
                            namespace.as_tuple + (job.operation_id,),
                        ).fetchone()
                        bundle = db.execute(
                            "SELECT digest,receipt_json FROM graph_bundle_operations "
                            "WHERE bot=? AND persona=? AND operation_id=?",
                            namespace.as_tuple + (job.operation_id,),
                        ).fetchone()
                        if (intent is None or bundle is None
                                or bundle[0] != receipt.bundle_digest
                                or json.loads(intent[1]).get("graph_incarnation")
                                   != target.graph_incarnation
                                or job_key.token not in json.loads(bundle[1]).get(
                                    "ledger_refs", ())
                                or json.loads(intent[0]).get("source_ref")
                                   != source_id):
                            continue
                        source_row = db.execute(
                            "SELECT value FROM graph_atoms WHERE token=? AND "
                            "revision=? AND valid=1",
                            (source_version.key.token, source_version.revision),
                        ).fetchone()
                        access_row = db.execute(
                            "SELECT value FROM graph_atoms WHERE token=? AND "
                            "revision=? AND valid=1",
                            (access_version.key.token, access_version.revision),
                        ).fetchone()
                        if source_row is None or access_row is None:
                            continue
                        source = SourceRecord.from_dict(json.loads(source_row[0]))
                        access = json.loads(access_row[0])
                        validate_access(access)
                        if (source.source_id != source_id
                                or source.speaker_id != identity["sender_ref"]
                                or source.source_kind != "reported"
                                or "context" not in source.purposes
                                or "consolidation" not in source.purposes
                                or identity["conversation_ref"] not in source.audiences
                                or access["status"] != "active"
                                or access["source_id"] != source_id
                                or "context" not in access["purposes"]
                                or "consolidation" not in access["purposes"]
                                or identity["conversation_ref"] not in access["audiences"]):
                            continue
                        envelope = HostIngressEnvelope(
                            namespace, identity["platform_ref"],
                            identity["conversation_ref"], identity["sender_ref"],
                            identity["message_id"], source.text,
                            source.occurred_at, source.recorded_at,
                            identity["visibility"], SourceLineage(**identity["lineage"]),
                        )
                        if ingress_content_fingerprint(envelope) != receipt.content_fingerprint:
                            continue
                        self._committed_first_ingress_baseline_locked(
                            namespace, source_id, current, epoch)
                        item = FirstIngressUnacquiredItemV1(
                            namespace, provision.installation_id, job_id,
                            job.operation_id, envelope, receipt.content_fingerprint,
                            receipt.bundle_digest)
                    except (AuthorityDenied, UnavailableGuard, EventConflict,
                            KeyError, TypeError, ValueError):
                        continue
                    items.append(item)
                if len(rows) > limit:
                    return FirstIngressUnacquiredPageV1(
                        namespace, provision.installation_id,
                        target.graph_incarnation, current.graph_revision,
                        epoch.revision, tuple(items), last)
                break
            return FirstIngressUnacquiredPageV1(
                namespace, provision.installation_id,
                target.graph_incarnation, current.graph_revision,
                epoch.revision, tuple(items), None)

        return self._read_v2(authority, reader)

    def discover_first_ingress_recovery_v1(
        self, bootstrap: object, namespace: NamespaceId,
        cursor: str | None = None, limit: int = 20,
    ):
        """List original V3 call identities; this grants no new dispatch."""
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.first_ingress_recovery import FirstIngressRecoveryPageV1
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId or type(limit) is not int
                or not 1 <= limit <= 50
                or cursor is not None and (type(cursor) is not str
                                           or len(cursor) > 1024)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed, bounded V3 recovery discovery required")
        parsed_cursor = self._parse_first_ingress_recovery_cursor_v1(cursor)
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("recovery discovery clock unavailable") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "recovery-discovery", namespace,
            ("activity",), "recovery", ("internal",),
            "recovery-discovery-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("V3 recovery provisioning absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation
                    or target.namespace != namespace):
                raise UnavailableGuard("V3 recovery installation differs; HOLD")
            stamp = {
                "schema": "sylanne3.runtime.first-ingress-recovery-cursor.v1",
                "namespace": asdict(namespace),
                "installation_id": provision.installation_id,
                "graph_incarnation": target.graph_incarnation,
                "graph_revision": current.graph_revision,
                "graph_epoch": epoch.revision,
            }
            last = ""
            if parsed_cursor is not None:
                if any(parsed_cursor.get(key) != value for key, value in stamp.items()):
                    raise UnavailableGuard("V3 recovery cursor lost graph stamp")
                last = parsed_cursor["last_acquire_operation_id"]
                if db.execute(
                    "SELECT 1 FROM graph_job_acquire_intents_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=? AND "
                    "json_extract(json_extract(encoding_binding_json,"
                    "'$.request_json'),'$.schema')=?",
                    namespace.as_tuple + (last,
                        "sylanne.first-ingress-encoding-call.v3"),
                ).fetchone() is None:
                    raise UnavailableGuard("V3 recovery cursor row is absent")
            rows = db.execute(
                "SELECT i.acquire_operation_id,i.job_id,i.original_operation_id,"
                "i.actor,i.encoding_binding_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch,i.request_digest,"
                "r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id>? "
                "AND json_extract(json_extract(i.encoding_binding_json,"
                "'$.request_json'),'$.schema')=? "
                "ORDER BY i.acquire_operation_id LIMIT ?",
                namespace.as_tuple + (last,
                    "sylanne.first-ingress-encoding-call.v3", limit + 1),
            ).fetchall()
            items = []
            for row in rows[:limit]:
                if self._first_ingress_recovery_ineligible_locked_v1(
                        namespace, epoch, row):
                    continue
                items.append(self._first_ingress_recovery_item_locked_v1(
                    namespace, provision.installation_id, current, epoch, now,
                    row))
            next_cursor = None
            if len(rows) > limit:
                payload = {**stamp, "last_acquire_operation_id": rows[limit - 1][0]}
                next_cursor = canonical_json({
                    **payload, "digest": canonical_digest(payload)})
            return FirstIngressRecoveryPageV1(
                namespace, provision.installation_id,
                target.graph_incarnation, current.graph_revision,
                epoch.revision, tuple(items), next_cursor)

        return self._read_v2(authority, reader)

    def read_first_ingress_acquired_handoff_v1(
        self, bootstrap: object, namespace: NamespaceId,
        acquire_operation_id: str,
    ):
        """Rehydrate one live original V3 ingress under the current read fence.

        Discovery supplies only an operation key. This read requalifies the
        acquired job and the original C01 content; it grants no model send.
        """
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.d06_ingress import ingress_content_fingerprint
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .memory_types import SourceRecord, source_key
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.ingress_observation import read_committed_ingress_identity

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(acquire_operation_id) is not str
                or not 1 <= len(acquire_operation_id) <= 128
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed acquired ingress handoff required")
        try:
            now = trusted_upper(self.__content_fence_v2.read_ingress_clock(
                self.__scene_clock_policy))
        except Exception as exc:
            raise UnavailableGuard("acquired ingress clock unavailable; HOLD") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        authority = AuthorityContext(
            self.__holder, "d11", "acquired-handoff", namespace,
            ("activity",), "context", ("internal",),
            "acquired-handoff-v1",
            metadata.requirements.activation_generation)

        def reader():
            db = self.__store._db
            current, epoch = self._v2_graph_stamp(namespace)
            target = current.requirements
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("acquired ingress installation absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (target.namespace != namespace
                    or provision.installation_id != installed.installation_id
                    or provision.authority_id != installed.authority_id
                    or provision.authority_namespace != target.authority_namespace
                    or provision.generation != target.activation_generation):
                raise UnavailableGuard("acquired ingress installation differs; HOLD")
            row = db.execute(
                "SELECT i.acquire_operation_id,i.job_id,i.original_operation_id,"
                "i.actor,i.encoding_binding_json,i.requirements_json,"
                "i.graph_revision,i.graph_epoch,i.request_digest,"
                "r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=? "
                "AND json_extract(json_extract(i.encoding_binding_json,"
                "'$.request_json'),'$.schema')=?",
                namespace.as_tuple + (acquire_operation_id,
                    "sylanne.first-ingress-encoding-call.v3"),
            ).fetchone()
            if row is None or self._first_ingress_recovery_ineligible_locked_v1(
                    namespace, epoch, row):
                raise UnavailableGuard("original acquired ingress absent; HOLD")
            item = self._first_ingress_recovery_item_locked_v1(
                namespace, provision.installation_id, current, epoch, now, row)
            if item.recovery_state != "original_fence":
                raise UnavailableGuard("original acquired ingress is not live; HOLD")
            binding = load_binding(db, namespace, item.job_id)
            if binding is None:
                raise UnavailableGuard("original acquired binding absent; HOLD")
            receipt = read_committed_ingress_identity(
                db, namespace, binding.source_id)
            intent = db.execute(
                "SELECT identity_json,requirements_json FROM "
                "graph_first_ingress_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (item.original_operation_id,),
            ).fetchone()
            bundle = db.execute(
                "SELECT digest,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (item.original_operation_id,),
            ).fetchone()
            if (receipt is None or intent is None or bundle is None
                    or bundle[0] != receipt.bundle_digest
                    or json.loads(intent[1]).get("graph_incarnation")
                       != target.graph_incarnation
                    or json.loads(intent[0]).get("source_ref")
                       != binding.source_id):
                raise UnavailableGuard("original acquired C01 receipt differs; HOLD")
            identity = json.loads(receipt.identity_json)
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND revision=? "
                "AND valid=1",
                (source_key(*namespace.as_tuple, binding.source_id).token,
                 binding.source_revision),
            ).fetchone()
            if source_row is None:
                raise UnavailableGuard("original acquired source absent; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            if (source.source_id != binding.source_id
                    or source.speaker_id != identity["sender_ref"]
                    or source.source_kind != "reported"
                    or identity["conversation_ref"] not in source.audiences):
                raise UnavailableGuard("original acquired source differs; HOLD")
            envelope = HostIngressEnvelope(
                namespace, identity["platform_ref"],
                identity["conversation_ref"], identity["sender_ref"],
                identity["message_id"], source.text, source.occurred_at,
                source.recorded_at, identity["visibility"],
                SourceLineage(**identity["lineage"]),
            )
            if ingress_content_fingerprint(envelope) != receipt.content_fingerprint:
                raise UnavailableGuard("original acquired content differs; HOLD")
            return item, envelope

        return self._read_v2(authority, reader)

    @staticmethod
    def _parse_first_ingress_recovery_cursor_v1(cursor):
        if cursor is None:
            return None
        try:
            parsed = json.loads(cursor)
            if (type(parsed) is not dict
                    or set(parsed) != {
                        "schema", "namespace", "installation_id",
                        "graph_incarnation", "graph_revision", "graph_epoch",
                        "last_acquire_operation_id", "digest"}
                    or parsed["schema"] !=
                    "sylanne3.runtime.first-ingress-recovery-cursor.v1"
                    or type(parsed["last_acquire_operation_id"]) is not str
                    or not 1 <= len(parsed["last_acquire_operation_id"]) <= 128
                    or cursor != canonical_json(parsed)
                    or parsed["digest"] != canonical_digest({
                        key: value for key, value in parsed.items()
                        if key != "digest"})):
                raise ValueError("recovery cursor differs")
        except (TypeError, ValueError, KeyError, AttributeError) as exc:
            raise UnavailableGuard("invalid V3 recovery cursor") from exc
        return parsed

    def _first_ingress_recovery_ineligible_locked_v1(
        self, namespace, epoch, row,
    ):
        """Skip only a graph-committed source/access withdrawal, never drift."""
        from .memory_types import access_key, source_key, validate_access
        from .runtime.encoding_call_binding import binding_from_json, load_binding

        db = self.__store._db
        acquire_id, job_id, original_id, actor, binding_json = row[:5]
        binding = binding_from_json(binding_json)
        request = binding.request
        if (binding.namespace != namespace or binding.job_id != job_id
                or binding != load_binding(db, namespace, job_id)
                or row[8] != row[9]
                or request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or request.get("acquire_operation_id") != acquire_id
                or request.get("original_operation_id") != original_id
                or request.get("envelope", {}).get("authority", {}).get(
                    "actor") != actor):
            raise UnavailableGuard("V3 recovery withdrawn row identity differs; HOLD")

        def proven_current_change(key, original_revision, *, access):
            current = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone()
            if current is None or current[0] <= original_revision:
                return False
            withdrawn = current[2] == 0
            if access and current[2] == 1:
                value = json.loads(current[1])
                validate_access(value)
                withdrawn = value["status"] == "withdrawn"
            if not withdrawn:
                return False
            original = db.execute(
                "SELECT valid FROM graph_history WHERE token=? AND revision=?",
                (key.token, original_revision),
            ).fetchone()
            history = db.execute(
                "SELECT value,valid,event_bot,event_persona,event_session,"
                "event_id FROM graph_history WHERE token=? AND revision=?",
                (key.token, current[0]),
            ).fetchone()
            if (original != (1,) or history is None
                    or history[:2] != (current[1], current[2])
                    or history[2:4] != namespace.as_tuple):
                raise UnavailableGuard("V3 recovery withdrawal has no graph history")
            event = db.execute(
                "SELECT revisions,invalidated,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                history[2:6],
            ).fetchone()
            expected = [key.token, current[0]]
            if (event is None or expected not in json.loads(
                    event[1] if current[2] == 0 else event[0])
                    or event[2] > epoch.revision):
                raise UnavailableGuard("V3 recovery withdrawal event differs")
            return True

        source = source_key(*namespace.as_tuple, binding.source_id)
        access = access_key(*namespace.as_tuple, binding.source_id)
        return (proven_current_change(source, binding.source_revision,
                                      access=False)
                or proven_current_change(access, binding.access_revision,
                                         access=True))

    def _first_ingress_recovery_item_locked_v1(
        self, namespace, installation_id, metadata, epoch, now, row,
    ):
        """Join one V3 receipt to its current graph without exposing content."""
        from datetime import datetime

        from .memory_types import access_key, episode_key, source_key, validate_access
        from .runtime.d11_types import RuntimeOutboxValue, job_graph_write, runtime_job_key
        from .runtime.encoding_call_binding import binding_from_json, load_binding
        from .runtime.first_ingress_c02_identity import (
            first_ingress_c02_consumer_operation_id_v1,
        )
        from .runtime.first_ingress_recovery import FirstIngressRecoveryItemV1
        from .runtime.first_ingress_v2 import ingress_ids

        (acquire_id, job_id, original_id, actor, binding_json,
         requirements_json, acquired_revision, acquired_epoch,
         intent_digest, receipt_digest, job_json) = row
        db = self.__store._db
        binding = binding_from_json(binding_json)
        frozen = binding.request
        original = PersistentJob(**json.loads(job_json))
        job = get_job(db, job_id)
        historical = json.loads(requirements_json)
        if (binding != load_binding(db, namespace, job_id)
                or binding.namespace != namespace
                or intent_digest != receipt_digest
                or historical.get("namespace") != asdict(namespace)
                or historical.get("graph_incarnation") !=
                metadata.requirements.graph_incarnation
                or historical.get("authority_id") !=
                metadata.requirements.authority_id
                or historical.get("authority_namespace") !=
                metadata.requirements.authority_namespace
                or frozen.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or frozen.get("acquire_operation_id") != acquire_id
                or frozen.get("original_operation_id") != original_id
                or frozen.get("worker_fence") != original.fence
                or frozen.get("worker_lease_expires_utc") !=
                original.lease_expires_utc
                or frozen.get("baseline") is None
                or frozen.get("call_id") != binding.call_id
                or frozen.get("model_request_digest") !=
                binding.model_request_digest
                or (original.job_id, original.operation_id,
                    original.phase, original.lease_holder,
                    original.cancel_epoch) != (
                    job_id, original_id, "running", actor, 0)
                or (job.bot_id, job.persona_id, job.job_id,
                    job.operation_id, job.activity_id, job.budget_ref,
                    job.work_kind, job.fence, job.cancel_epoch) != (
                    *namespace.as_tuple, job_id, original_id,
                    original.activity_id, original.budget_ref,
                    "d06.encode_source", original.fence, 0)
                or job.phase not in {"running", "completed"}
                or not _job_acquire_id_matches(
                    acquire_id, namespace, job_id, original_id, actor,
                    metadata.requirements.activation_generation)):
            raise UnavailableGuard("V3 recovery original acquire differs; HOLD")
        if db.execute(
                "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                "WHERE bot=? AND persona=? AND "
                "(acquire_operation_id=? OR call_id=? OR source_id=?) LIMIT 1",
                namespace.as_tuple + (
                    acquire_id, binding.call_id, binding.source_id),
        ).fetchone() is not None:
            raise UnavailableGuard("V3 recovery original call was redacted; HOLD")
        job_key = runtime_job_key(*namespace.as_tuple, job.activity_id, job_id)
        current_job_atom = db.execute(
            "SELECT value,valid FROM graph_atoms WHERE token=?",
            (job_key.token,),
        ).fetchone()
        original_job_atom = db.execute(
            "SELECT value FROM graph_history WHERE token=? AND valid=1 "
            "AND event_bot=? AND event_persona=? AND event_session=? "
            "AND event_id=?",
            (job_key.token, *namespace.as_tuple, job.activity_id, acquire_id),
        ).fetchone()
        if (current_job_atom != (canonical_json(job_graph_write(job).value), 1)
                or original_job_atom != (
                    canonical_json(job_graph_write(original).value),)):
            raise UnavailableGuard("V3 recovery job graph history differs; HOLD")
        source_key_value = source_key(*namespace.as_tuple, binding.source_id)
        access_key_value = access_key(*namespace.as_tuple, binding.source_id)
        source_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (source_key_value.token,),
        ).fetchone()
        access_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (access_key_value.token,),
        ).fetchone()
        if (source_row is None or access_row is None
                or (source_row[0], source_row[2]) != (
                    binding.source_revision, 1)
                or (access_row[0], access_row[2]) != (
                    binding.access_revision, 1)
                or db.execute(
                    "SELECT dependency_revision FROM graph_dependencies "
                    "WHERE dependent_token=? AND dependency_token=?",
                    (access_key_value.token, source_key_value.token),
                ).fetchone() != (binding.source_revision,)):
            raise UnavailableGuard("V3 recovery source/access revoked; HOLD")
        source = SourceRecord.from_dict(json.loads(source_row[1]))
        access = json.loads(access_row[1])
        validate_access(access)
        frozen_authority = frozen["envelope"]["authority"]
        audience = frozen_authority["audience"]
        if (source.source_id != binding.source_id
                or access["source_id"] != binding.source_id
                or access["status"] != "active"
                or "consolidation" not in source.purposes
                or "consolidation" not in access["purposes"]
                or type(audience) is not list or not audience
                or not set(audience).issubset(source.audiences)
                or not set(audience).issubset(access["audiences"])
                or frozen_authority["actor"] != actor
                or frozen_authority["worker_fence"] != original.fence):
            raise UnavailableGuard("V3 recovery source scope differs; HOLD")
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=(acquired_revision, acquired_epoch))
        if frozen["baseline"] != asdict(baseline):
            raise UnavailableGuard("V3 recovery baseline differs; HOLD")
        receipt = db.execute(
            "SELECT activity_id,receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (original_id,),
        ).fetchone()
        expected = ingress_ids(binding.source_id)
        if (receipt is None or receipt[0] != job.activity_id
                or (expected[1], expected[2], expected[3]) != (
                    job.activity_id, original_id, job_id)
                or job_key.token not in json.loads(receipt[1]).get(
                    "ledger_refs", ())):
            raise UnavailableGuard("V3 recovery ingress receipt differs; HOLD")
        self._original_first_ingress_qualification_locked(
            namespace, original_id, source_key_value.token)
        outbox_refs = json.loads(receipt[1]).get("outbox_refs")
        if type(outbox_refs) is not list or len(outbox_refs) != 1:
            raise UnavailableGuard("V3 recovery original outbox differs; HOLD")
        outbox_token = outbox_refs[0]
        outbox_key = AtomKey.from_token(outbox_token)
        historical_outbox = db.execute(
            "SELECT value FROM graph_history WHERE token=? AND valid=1 "
            "AND event_bot=? AND event_persona=? AND event_session=? "
            "AND event_id=?",
            (outbox_token, *namespace.as_tuple, job.activity_id, original_id),
        ).fetchall()
        if len(historical_outbox) != 1:
            raise UnavailableGuard("V3 recovery original outbox absent; HOLD")
        outbox = RuntimeOutboxValue(**json.loads(historical_outbox[0][0]))
        if (outbox_key.type_name != "runtime.outbox"
                or outbox_key.owner != Owner(
                    "activity", *namespace.as_tuple, job.activity_id)
                or outbox.payload_ref != binding.source_id
                or outbox.job_ref != job_key.token
                or outbox.operation_id != original_id
                or outbox.job_id != job_id
                or outbox.phase != "pending"
                or outbox.outbox_id != expected[4]
                or outbox.idempotency_key != expected[5]):
            raise UnavailableGuard("V3 recovery original outbox changed; HOLD")
        quote_ref = job.operator_versions.get("resource_quote")
        if type(quote_ref) is not str or ":" not in quote_ref:
            raise UnavailableGuard("V3 recovery signed quote absent; HOLD")
        quote_id, version_text = quote_ref.rsplit(":", 1)
        quote = self.__d02_issuer.original_signed_quote(
            db, quote_id, int(version_text))
        reservation = db.execute(
            "SELECT digest,ceiling_json FROM runtime_budget_reservations "
            "WHERE lease_id=? AND operation_id=?",
            (job.budget_ref, original_id),
        ).fetchone()
        reserve_receipt = db.execute(
            "SELECT digest FROM runtime_budget_operations WHERE bot_id=? "
            "AND persona_id=? AND operation_id=? AND phase='reserve'",
            namespace.as_tuple + (original_id,),
        ).fetchone()
        if (quote.graph_job_ref != job_key.token
                or quote.operation_id != original_id
                or quote.activity_id != job.activity_id
                or quote.parent_budget_lease_ref != job.budget_ref
                or reservation is None or reserve_receipt is None
                or reservation != (reserve_receipt[0],
                                   canonical_json(quote.ceiling))):
            raise UnavailableGuard("V3 recovery original budget differs; HOLD")
        consumer_id = first_ingress_c02_consumer_operation_id_v1(
            namespace=namespace,
            authority_id=metadata.requirements.authority_id,
            authority_namespace=metadata.requirements.authority_namespace,
            installation_id=installation_id, job_id=job_id,
            acquire_operation_id=acquire_id,
            original_operation_id=original_id, call_id=binding.call_id,
            binding_digest=binding.binding_digest,
            model_request_digest=binding.model_request_digest)
        c02 = db.execute(
            "SELECT digest,commit_seq,receipt_json FROM "
            "graph_bundle_operations WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (consumer_id,),
        ).fetchone()
        pending_c02 = db.execute(
            "SELECT digest FROM graph_bundle_intents_v2 WHERE bot=? "
            "AND persona=? AND operation_id=?",
            namespace.as_tuple + (consumer_id,),
        ).fetchone()
        if job.phase == "running":
            if (c02 is not None or job.lease_holder != actor
                    or job.lease_expires_utc != original.lease_expires_utc
                    or job.result_ref is not None):
                raise UnavailableGuard("V3 recovery original lease changed; HOLD")
            expires = datetime.fromisoformat(
                original.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            state = ("c02_pending_hold" if pending_c02 is not None
                     else "expired_lease_hold" if now >= expires
                     else "original_fence")
            c02_digest = c02_seq = None
        else:
            if (c02 is None or job.lease_holder is not None
                    or job.lease_expires_utc is not None or not job.result_ref):
                raise UnavailableGuard("V3 recovery completion receipt absent; HOLD")
            detail = json.loads(c02[2]).get("first_ingress_c02")
            event = db.execute(
                "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (job.activity_id, consumer_id),
            ).fetchone()
            fence = db.execute(
                "SELECT digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_id,),
            ).fetchone()
            episode = episode_key(*namespace.as_tuple, job.result_ref)
            episode_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?", (episode.token,),
            ).fetchone()
            if (type(detail) is not dict or event is None
                    or fence != (c02[0],) or episode_row != (1,)
                    or type(c02[1]) is not int or c02[1] < 1):
                raise UnavailableGuard("V3 recovery C02 receipt differs; HOLD")
            state, c02_digest, c02_seq = "c02_committed", c02[0], c02[1]
        return FirstIngressRecoveryItemV1(
            namespace, installation_id, job_id, acquire_id, original_id,
            binding.call_id, binding.binding_digest,
            binding.model_request_digest, consumer_id, job.phase, actor,
            original.fence, original.lease_expires_utc, state,
            c02_digest, c02_seq)

    def prepare_first_ingress_model_cost_v1(
        self, bootstrap: object, namespace: NamespaceId, original_intent,
        *, quote_id: str, quote_version: int,
    ):
        """Read authenticated original cost and business bounds without writes.

        The installation port makes its Authority mTLS call before a GraphStore
        lock or transaction is acquired. The subsequent business read is v2
        fenced. Its plan must be recomputed in a separate cost write transaction;
        this method cannot settle a budget or release a reservation.
        """
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.model_cost_settlement import (
            ModelCostUnavailable, prepare_original_model_cost_plan,
            read_original_model_cost,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(original_intent) is not ModelEgressIntentV1
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__model_terminal_cost_port is None
                or self.__d02_issuer is None):
            raise UnavailableGuard("installed v2 original cost authorities are required")
        # The installed port owns the designated-observer credential. This is
        # intentionally outside both the graph lock and the read fence.
        try:
            fact = read_original_model_cost(
                self.__model_terminal_cost_port, original_intent)
        except Exception as exc:
            raise UnavailableGuard("original Authority terminal cost is unavailable; HOLD") from exc
        with self.__store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (original_intent.authority_id != target.authority_id
                or original_intent.namespace != target.authority_namespace):
            raise UnavailableGuard("original model call belongs to another authority")
        operation_id = "model-cost-read-" + canonical_digest({
            "namespace": list(namespace.as_tuple),
            "call_id": original_intent.call_id,
        })[:48]
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d11",), activation_generation=target.activation_generation,
            operation_id=operation_id,
        )
        authority = AuthorityContext(
            "host", "d11", capability, namespace, ("activity",), "audit",
            ("internal",), "model-cost-accounting-v1", target.activation_generation,
        )
        self._authorize(lease, authority, frozenset({"d11"}), owner_read=True)
        try:
            return self._read_v2(authority, lambda: prepare_original_model_cost_plan(
                self.__store._db, self.__d02_issuer, namespace, fact,
                quote_id=quote_id, quote_version=quote_version))
        except ModelCostUnavailable as exc:
            raise UnavailableGuard(str(exc)) from exc

    @staticmethod
    def _accounting_anchor_covers(target, anchor) -> bool:
        """Accounting may follow a closed deletion; never rewind graph history."""
        return (target.authority_id == anchor.authority_id
                and target.authority_namespace == anchor.namespace
                and target.activation_generation == anchor.activation_generation
                and target.deletion_journal_id == anchor.deletion_journal_id
                and target.execution_journal_id == anchor.execution_journal_id
                and target.deletion_seq <= anchor.deletion_seq
                and target.execution_seq <= anchor.execution_seq
                and target.revocation_epoch <= anchor.revocation_epoch
                and (target.deletion_seq != anchor.deletion_seq
                     or target.deletion_digest == anchor.deletion_digest)
                and (target.execution_seq != anchor.execution_seq
                     or target.execution_digest == anchor.execution_digest))

    def commit_first_ingress_model_cost_v1(
        self, bootstrap: object, namespace: NamespaceId, original_intent,
        *, quote_id: str, quote_version: int,
    ):
        """Commit one original model cost bundle, independent of D06 content.

        The installed ports own mTLS credentials. Their calls happen only
        outside GraphStore's lock; the signed quote and D11 reservation are
        re-read in the single graph transaction. A fence attempt is durable
        before begin, while the business operation stays fixed to call_id.
        """
        from .authority_service.v2_accounting_contract import (
            AccountingMaintenanceGrantV1, AccountingMaintenanceRequestV1,
        )
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.restore_anchor import RestoreAnchor
        from .runtime.model_cost_settlement import (
            OriginalModelCostCommitV1, apply_original_model_budget_in_transaction,
            prepare_original_model_cost_plan, read_original_model_cost,
        )
        from .runtime.d11_types import (
            D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH, validate_d11_writes,
        )
        from .runtime_contracts import (
            CommandEnvelope, DependencySet, DomainProposal, OperationIdentity,
            RUNTIME_SCHEMA,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(original_intent) is not ModelEgressIntentV1
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__model_terminal_cost_port is None
                or self.__accounting_maintenance_port is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("installed original model accounting authorities required")
        store, port = self.__store, self.__accounting_maintenance_port
        # The receipt is an Authority fact, never a caller-supplied cost.
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if fact.recovery.state != "observed":
            raise UnavailableGuard("unobserved model cost retains original upper bound; HOLD")
        intent_digest = canonical_digest(asdict(original_intent))
        terminal_digest = canonical_digest(asdict(fact.receipt))
        operation_id = "model-cost-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "call_id": original_intent.call_id,
        })[:48]

        def business_receipt_locked():
            row = store._db.execute(
                "SELECT activity_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            data = json.loads(row[2])
            if (data.get("original_intent_digest") != intent_digest
                    or data.get("terminal_receipt_digest") != terminal_digest
                    or data.get("quote_id") != quote_id
                    or data.get("quote_version") != quote_version):
                raise EventConflict("original model cost operation identity differs")
            committed = OriginalModelCostCommitV1(**data["original_model_cost"])
            graph_event = store._db.execute(
                "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?", namespace.as_tuple +
                (row[0], operation_id),
            ).fetchone()
            atom = store._db.execute(
                "SELECT 1 FROM graph_atoms WHERE token=? AND valid=1",
                (committed.cost_ref,),
            ).fetchone()
            budget = store._db.execute(
                "SELECT 1 FROM runtime_budget_operations WHERE bot_id=? "
                "AND persona_id=? AND operation_id=? AND phase='settle'",
                namespace.as_tuple + (original_intent.budget_reservation_operation_id,),
            ).fetchone()
            if (committed.status != "committed"
                    or committed.operation_id != operation_id
                    or committed.call_id != original_intent.call_id
                    or committed.quote_id != quote_id
                    or committed.quote_version != quote_version
                    or committed.terminal_receipt_digest != terminal_digest
                    or committed.commit_seq != row[1]
                    or graph_event is None or atom is None or budget is None):
                raise UnavailableGuard("original cost business receipt is incomplete")
            return committed

        with store._lock:
            committed = business_receipt_locked()
            metadata, _ = self._v2_graph_stamp(namespace)
            attempt = store._db.execute(
                "SELECT intent_digest,attempt_id,anchor_json,state FROM "
                "graph_original_model_cost_attempts_v1 WHERE bot=? AND persona=? "
                "AND call_id=?", namespace.as_tuple + (original_intent.call_id,),
            ).fetchone()
        if committed is not None:
            if attempt is None or attempt[0] != intent_digest or attempt[3] != "committed":
                raise UnavailableGuard("committed cost lacks original fence attempt")
            request = AccountingMaintenanceRequestV1(
                attempt[1], original_intent, RestoreAnchor(**json.loads(attempt[2])))
            port.recover_finish(request)
            return replace(committed, status="duplicate")
        target = metadata.requirements
        if (original_intent.authority_id != target.authority_id
                or original_intent.namespace != target.authority_namespace):
            raise UnavailableGuard("original model call belongs to another authority")

        if attempt is not None and attempt[3] == "open":
            if attempt[0] != intent_digest:
                raise EventConflict("original call ID reused with different intent")
            # A prior invocation may have rolled back after begin or lost its
            # finish reply. First prove no business receipt, then close it.
            old_request = AccountingMaintenanceRequestV1(
                attempt[1], original_intent, RestoreAnchor(**json.loads(attempt[2])))
            try:
                port.recover_finish(old_request)
            except Exception:
                # The durable local intent may precede Authority begin. The
                # exact same attempt ID is safe to begin or replay; any other
                # Authority failure remains HOLD rather than minting a new ID.
                old_grant = port.begin(old_request)
                port.finish(old_request, old_grant)
            with store._lock:
                if business_receipt_locked() is not None:
                    raise UnavailableGuard("cost committed during fence recovery; retry")
                store._db.execute(
                    "UPDATE graph_original_model_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND call_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple +
                    (original_intent.call_id, attempt[1]),
                )

        # current_anchor is an Authority network read. It is outside the
        # graph lock and can advance past a completed source deletion.
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._accounting_anchor_covers(target, anchor):
            raise UnavailableGuard("accounting Authority anchor differs from graph history")
        attempt_id = "model-cost-fence-" + secrets.token_hex(24)
        request = AccountingMaintenanceRequestV1(attempt_id, original_intent, anchor)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if business_receipt_locked() is not None or self._v2_graph_stamp(namespace)[0] != metadata:
                    raise StaleRead("original cost graph changed before accounting fence")
                row = db.execute(
                    "SELECT state FROM graph_original_model_cost_attempts_v1 "
                    "WHERE bot=? AND persona=? AND call_id=?",
                    namespace.as_tuple + (original_intent.call_id,),
                ).fetchone()
                if row is not None and row[0] != "closed":
                    raise UnavailableGuard("original cost fence attempt remains open")
                if attempt is not None and attempt[0] != intent_digest:
                    raise EventConflict("original call ID reused with different intent")
                db.execute(
                    "INSERT INTO graph_original_model_cost_attempts_v1"
                    "(bot,persona,call_id,intent_digest,attempt_id,anchor_json,state) "
                    "VALUES(?,?,?,?,?,?,'open') ON CONFLICT(bot,persona,call_id) "
                    "DO UPDATE SET intent_digest=excluded.intent_digest,"
                    "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                    "state='open'", namespace.as_tuple +
                    (original_intent.call_id, intent_digest, attempt_id,
                     canonical_json(asdict(anchor))),
                )
                db.commit()
            except BaseException:
                db.rollback()
                raise
        grant = port.begin(request)
        if type(grant) is not AccountingMaintenanceGrantV1 or (
                grant.call_id != original_intent.call_id
                or grant.admission_id != fact.admission.admission_id
                or grant.reservation_digest != original_intent.budget_reservation_digest
                or grant.observation_digest != fact.recovery.observation_digest
                or grant.terminal_receipt_digest != terminal_digest
                or grant.permit.operation_id != attempt_id
                or grant.permit.pinned_anchor != anchor):
            raise UnavailableGuard("accounting grant differs from original Authority fact")
        port.validate(request, grant)

        result = None
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    current, epoch = self._v2_graph_stamp(namespace)
                    if current != metadata or not self._accounting_anchor_covers(
                            current.requirements, anchor):
                        raise StaleRead("accounting graph stamp changed")
                    row = db.execute(
                        "SELECT attempt_id,state FROM graph_original_model_cost_attempts_v1 "
                        "WHERE bot=? AND persona=? AND call_id=?",
                        namespace.as_tuple + (original_intent.call_id,),
                    ).fetchone()
                    if row != (attempt_id, "open") or business_receipt_locked() is not None:
                        raise StaleRead("original cost business operation changed")
                    plan = prepare_original_model_cost_plan(
                        db, self.__d02_issuer, namespace, fact,
                        quote_id=quote_id, quote_version=quote_version)
                    if plan.bundle_operation_id != operation_id:
                        raise EventConflict("original cost operation differs")
                    application = apply_original_model_budget_in_transaction(
                        db, self.__d02_issuer, plan, fact)
                    write = application.cost_write
                    if not validate_d11_writes(
                            (write,), namespace, operation_id=operation_id,
                            activity_id=plan.quote.activity_id,
                            effect_id=plan.quote.effect_id):
                        raise UnavailableGuard("D11 cost write is invalid")
                    reconcile_runtime_write(db, write)
                    identity = OperationIdentity(
                        plan.quote.activity_id, plan.quote.effect_id,
                        original_intent.call_id, "accounting", operation_id,
                        canonical_digest({"input_refs": []}))
                    authority = AuthorityContext(
                        "host", "d11", "accounting:" + attempt_id,
                        namespace, ("activity",), "cost_accounting", ("internal",),
                        "original-model-cost-v1", target.activation_generation)
                    epochs = db.execute(
                        "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                        "WHERE bot=? AND persona=?", namespace.as_tuple,
                    ).fetchone() or (0, 0)
                    envelope = CommandEnvelope(
                        RUNTIME_SCHEMA, identity, authority,
                        VersionGuard((GraphVersion(write.key, 0),), (), *epochs,
                                     "accounting-v1", "accounting-v1",
                                     "accounting-v1", "accounting-v1", (), (), ()),
                        SourceQualification((), "derived", None, time.time(),
                                            "unknown", "ineligible", None,
                                            "not_applicable"),
                        (), plan.quote.parent_budget_lease_ref,
                        plan.quote.deadline_utc, 0.0, "accounting-v1",
                        (plan.original_operation_id,))
                    proposal = DomainProposal(
                        "d11", D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH,
                        envelope, (write,), DependencySet(), (), ("cost_settlement",))
                    bundle = DomainBundle(
                        envelope, (proposal,), (), (), (), (write.key.token,),
                        (), (), ())
                    event = Event(
                        Scope(*namespace.as_tuple, plan.quote.activity_id),
                        operation_id, time.time(), "domain_bundle",
                        {"bundle_digest": bundle.digest})
                    candidate = GraphCandidate(
                        event, (GraphVersion(write.key, 0),), (write,), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("original cost graph event already exists")
                    replacement = replace(
                        current.requirements,
                        deletion_seq=anchor.deletion_seq,
                        deletion_digest=anchor.deletion_digest,
                        execution_seq=anchor.execution_seq,
                        execution_digest=anchor.execution_digest,
                        revocation_epoch=anchor.revocation_epoch)
                    store.cas_graph_recovery_metadata(
                        current, replacement, _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence WHERE bot=? AND persona=?",
                        namespace.as_tuple).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq", namespace.as_tuple + (seq,))
                    result = OriginalModelCostCommitV1(
                        "committed", operation_id, original_intent.call_id,
                        quote_id, quote_version, terminal_digest, write.key.token,
                        canonical_digest(asdict(application.receipt)), seq,
                        current.graph_revision + 1, graph_receipt.epoch.revision)
                    receipt_data = {
                        "original_model_cost": asdict(result),
                        "original_intent_digest": intent_digest,
                        "terminal_receipt_digest": terminal_digest,
                        "quote_id": quote_id, "quote_version": quote_version,
                        "accounting_attempt_id": attempt_id,
                    }
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, bundle.digest, plan.quote.activity_id,
                            plan.quote.effect_id, seq, canonical_json(receipt_data)))
                    db.execute(
                        "UPDATE graph_original_model_cost_attempts_v1 "
                        "SET state='committed' WHERE bot=? AND persona=? "
                        "AND call_id=? AND attempt_id=?", namespace.as_tuple +
                        (original_intent.call_id, attempt_id))
                    db.commit()
                except BaseException:
                    db.rollback()
                    raise
        except BaseException:
            # The business transaction rolled back. Closing this *attempt*
            # leaves the fixed business operation and reservation untouched.
            with store._lock:
                committed = business_receipt_locked()
            if committed is not None:
                port.recover_finish(request)
                return replace(committed, status="duplicate")
            port.finish(request, grant)
            with store._lock:
                store._db.execute(
                    "UPDATE graph_original_model_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND call_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple +
                    (original_intent.call_id, attempt_id))
            raise
        port.finish(request, grant)
        return result

    def _qualified_first_ingress_acquire_return(
        self, namespace: NamespaceId, job_id: str, expected: PersistentJob,
        actor: str, clock, lease_seconds: int, *,
        original_context_verified: bool = False,
    ) -> PersistentJob:
        from datetime import datetime, timezone

        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import IssuerAuthorityDenied

        try:
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
            with self.__store._lock:
                current = self._first_ingress_encoding_job_locked(namespace, job_id)[0]
                if not original_context_verified:
                    self.__d11_issuer.authorize_existing_encoding_job(
                        self.__store._db, current, now_utc=now)
            if (current != expected or current.lease_holder != actor
                    or plan_job_acquire(current, actor, now_utc=now_text,
                                        lease_seconds=lease_seconds) != current):
                raise UnavailableGuard("job acquire result lost runnable eligibility; HOLD")
        except IssuerAuthorityDenied as exc:
            raise UnavailableGuard(
                "job acquire lost original signed authority; HOLD") from exc
        except Exception as exc:
            raise UnavailableGuard("job acquire result lost runnable eligibility; HOLD") from exc
        return current

    def _committed_first_ingress_baseline_locked(
        self, namespace, source_id, metadata, epoch, *, acquire_stamp=None,
    ):
        """Read the one previously committed D04 baseline in this graph snapshot."""
        from .authority_service.current_d04_baseline_graph_proof import (
            committed_baseline_current,
        )
        from .runtime.encoding_call_binding import CommittedEncodingBaselineV1

        db = self.__store._db
        opened = not db.in_transaction
        if opened:
            db.execute("BEGIN")
        try:
            source_ref = source_key(*namespace.as_tuple, source_id).token
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is None:
                raise UnavailableGuard("committed D04 baseline absent; HOLD")
            issued = db.execute(
                "SELECT operation_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall()
            if len(issued) != 1:
                raise UnavailableGuard("one committed D04 baseline required; HOLD")
            operation_id, bundle_digest = issued[0]
            writes = db.execute(
                "SELECT h.token,h.revision FROM graph_history AS h "
                "JOIN graph_atoms AS a ON a.token=h.token "
                "WHERE h.event_bot=? AND h.event_persona=? AND h.event_id=? "
                "AND a.type_name='d04.encoding_baseline.v1' AND h.valid=1",
                namespace.as_tuple + (operation_id,),
            ).fetchall()
            fence = db.execute(
                "SELECT post_graph_epoch FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if len(writes) != 1 or fence is None:
                raise UnavailableGuard("committed D04 baseline history absent; HOLD")
            baseline = CommittedEncodingBaselineV1(
                writes[0][0], writes[0][1], operation_id, bundle_digest,
                metadata.requirements.graph_incarnation, fence[0],
            )
            acquire_revision, acquire_epoch = (
                acquire_stamp if acquire_stamp is not None else
                (metadata.graph_revision, epoch.revision))
            if not committed_baseline_current(
                    db, namespace=namespace, baseline=baseline,
                    source_id=source_id, requirements=metadata.requirements,
                    current_graph_revision=metadata.graph_revision,
                    current_graph_epoch=epoch.revision,
                    acquire_graph_revision=acquire_revision,
                    acquire_graph_epoch=acquire_epoch,
                    issuer=self.__d11_issuer):
                raise UnavailableGuard("committed D04 baseline proof differs; HOLD")
            return baseline
        finally:
            if opened:
                db.execute("ROLLBACK")

    def _first_ingress_encoding_issue_context(
        self, namespace, planned, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading,
        frozen_binding=None, *, require_baseline_v3=False,
    ) -> FirstIngressEncodingIssueContextV2:
        """Gather current graph truth and the original D06 qualification."""
        from datetime import datetime
        with self.__store._lock:
            (current, _, _, current_outbox, _, _, current_source,
             current_access) = self._first_ingress_encoding_job_locked(
                 namespace, planned.job_id)
            if (current.operation_id != planned.operation_id
                    or current_outbox != outbox
                    or current_source != source_version
                    or current_access != access_version):
                raise UnavailableGuard("encoding source or access changed; HOLD")
            row = self.__store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_version.key.token,),
            ).fetchone()
            access_row = self.__store._db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_version.key.token,),
            ).fetchone()
            if (access_row is None or access_row[0] != access_version.revision
                    or access_row[2] != 1):
                raise UnavailableGuard("encoding current access changed; HOLD")
            try:
                access_value = json.loads(access_row[1])
                validate_access(access_value)
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("encoding current access invalid; HOLD") from exc
            if (access_value["status"] != "active"
                    or access_value["source_id"] != outbox.payload_ref
                    or authority.purpose not in access_value["purposes"]
                    or not set(authority.audience).issubset(
                        access_value["audiences"])):
                raise UnavailableGuard(
                    "encoding worker exceeds current access grant; HOLD")
            epochs = self.__store._db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            if epochs is None:
                raise UnavailableGuard("encoding authority epochs absent; HOLD")
            needs_baseline = (require_baseline_v3 or frozen_binding is not None
                              and frozen_binding.request.get("schema") ==
                              "sylanne.first-ingress-encoding-call.v3")
            if needs_baseline:
                metadata, epoch = self._v2_graph_stamp(namespace)
                acquire_stamp = None
                if frozen_binding is not None:
                    acquire_stamp = self.__store._db.execute(
                        "SELECT graph_revision,graph_epoch FROM "
                        "graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    if acquire_stamp is None:
                        raise UnavailableGuard("original V3 acquire stamp absent; HOLD")
                baseline = self._committed_first_ingress_baseline_locked(
                    namespace, outbox.payload_ref, metadata, epoch,
                    acquire_stamp=acquire_stamp)
                baseline_versions = (GraphVersion(
                    AtomKey.from_token(baseline.baseline_ref),
                    baseline.baseline_revision),)
            else:
                baseline = None
                baseline_versions = ()
            guard = VersionGuard(
                (source_version, access_version) + baseline_versions,
                (), epochs[0], epochs[1],
                self.__store._registry.catalogue_hash,
                self._version(self.__store._db, namespace, "scheme", "current"),
                self._version(self.__store._db, namespace, "operator", "current"),
                self._version(self.__store._db, namespace, "policy", "current"),
                (), (), (),
            )
            qualification = self._original_first_ingress_qualification_locked(
                namespace, planned.operation_id, source_version.key.token)
            issuance = self.__store._db.execute(
                "SELECT policy_json FROM runtime_ingress_issuance "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (planned.operation_id,),
            ).fetchone()
            if issuance is None:
                raise UnavailableGuard("original encoding interval absent; HOLD")
            try:
                character_interval_ref = IngressIssuancePolicy(
                    **json.loads(issuance[0])).character_interval_ref
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("original encoding interval invalid; HOLD") from exc
        if row is None or row[0] != source_version.revision or row[2] != 1:
            raise UnavailableGuard("encoding source changed before request issue; HOLD")
        source = SourceRecord.from_dict(json.loads(row[1]))
        if source.source_id != outbox.payload_ref:
            raise UnavailableGuard("encoding source differs from original outbox")
        job_deadline = datetime.fromisoformat(
            planned.deadline_utc.replace("Z", "+00:00")).timestamp()
        worker_deadline = datetime.fromisoformat(
            planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
        deadline = min(job_deadline, worker_deadline)
        if now_utc >= deadline:
            raise UnavailableGuard("encoding request deadline expired; HOLD")
        try:
            clock_epoch = clock_reading.sample.epoch
            clock_source = clock_reading.sample.source_id
            if (type(clock_epoch) is not str or not clock_epoch
                    or clock_source != self.__scene_clock_policy.source_id):
                raise ValueError("paired clock identity is invalid")
            current_monotonic_deadline = clock_reading.monotonic_after_seconds + (
                deadline - clock_reading.utc_upper_bound_seconds)
            if (not math.isfinite(current_monotonic_deadline)
                    or time.monotonic() >= current_monotonic_deadline):
                raise ValueError("paired monotonic deadline expired")
            # The frozen envelope value is request identity. Every check uses
            # this process's freshly rebuilt deadline from the paired sample.
            monotonic_deadline = current_monotonic_deadline
            if frozen_binding is not None:
                frozen = frozen_binding.request
                if (frozen.get("schema") not in {
                        "sylanne.first-ingress-encoding-call.v2",
                        "sylanne.first-ingress-encoding-call.v3"}
                        or frozen.get("clock_epoch") != clock_epoch
                        or frozen.get("acquire_operation_id") != acquire_operation_id):
                    raise ValueError("frozen clock epoch or acquire differs")
                monotonic_deadline = frozen["envelope"]["monotonic_deadline"]
                if (type(monotonic_deadline) not in (int, float)
                        or not math.isfinite(monotonic_deadline)):
                    raise ValueError("frozen monotonic deadline invalid")
        except (AttributeError, KeyError, TypeError, ValueError) as exc:
            raise UnavailableGuard("paired encoding clock context unavailable; HOLD") from exc
        return FirstIngressEncodingIssueContextV2(
            planned, source, replace(authority, worker_fence=planned.fence),
            source_version.revision, access_version.revision,
            tuple(access_value["audiences"]), tuple(access_value["purposes"]),
            guard, qualification, now_utc, deadline, worker_deadline,
            acquire_operation_id, character_interval_ref, clock_epoch,
            monotonic_deadline, current_monotonic_deadline, baseline)

    def _issue_first_ingress_encoding_binding(
        self, namespace, planned, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading,
        frozen_binding=None, *, require_baseline_v3=False,
    ):
        """Freeze the installed pure issuer output for one planned worker fence."""
        from .runtime.encoding_call_binding import (
            EncodingRequestIssueV2, prepare_binding,
        )
        from .model_broker.first_ingress_encoding import (
            FIRST_INGRESS_ENCODING_TEMPLATE_VERSION,
        )

        context = self._first_ingress_encoding_issue_context(
            namespace, planned, outbox, source_version, access_version,
            authority, now_utc, acquire_operation_id, clock_reading,
            frozen_binding, require_baseline_v3=require_baseline_v3)
        issue = self.__encoding_request_issuer(context)
        if type(issue) is not EncodingRequestIssueV2:
            raise UnavailableGuard("production encoding requires a V2 request issuer; HOLD")
        request = issue.request
        if (request.envelope.identity.activity_id != planned.activity_id
                or request.envelope.authority != context.authority
                or request.envelope.version_guard != context.version_guard
                or request.envelope.source_qualification != context.source_qualification
                or request.envelope.identity.operation_id != acquire_operation_id
                or request.envelope.identity.phase != "encode"
                or request.envelope.monotonic_deadline != context.monotonic_deadline
                or request.envelope.character_interval_ref
                != context.character_interval_ref
                or request.envelope.deadline_utc != context.deadline_utc
                or request.envelope.deadline_utc <= context.now_utc):
            raise UnavailableGuard("encoding request differs from trusted issuance context")
        return prepare_binding(
            namespace, planned.job_id, context.source, source_version.revision,
            access_version.revision, planned.budget_ref, planned.operation_id,
            request, prompt_template_version=FIRST_INGRESS_ENCODING_TEMPLATE_VERSION,
            provider_config_ref=issue.provider_config_ref,
            provider_config_digest=issue.provider_config_digest,
            production_context=context,
            baseline=context.baseline,
        )

    def _validate_first_ingress_encoding_binding_context(
        self, namespace, job, outbox, source_version, access_version,
        authority, now_utc, acquire_operation_id, clock_reading, binding,
    ) -> None:
        """Recheck frozen issuer claims against current worker and graph truth."""
        context = self._first_ingress_encoding_issue_context(
            namespace, job, outbox, source_version, access_version,
            authority, now_utc, acquire_operation_id, clock_reading, binding,
            require_baseline_v3=(binding.request.get("schema") ==
                                 "sylanne.first-ingress-encoding-call.v3"))
        envelope = binding.request["envelope"]
        if (binding.request.get("schema") not in {
                "sylanne.first-ingress-encoding-call.v2",
                "sylanne.first-ingress-encoding-call.v3"}
                or (context.baseline is not None and
                    binding.request.get("baseline") != asdict(context.baseline))
                or binding.request.get("original_operation_id")
                != context.job.operation_id
                or binding.request.get("worker_fence") != context.job.fence
                or binding.request.get("worker_lease_expires_utc")
                != context.job.lease_expires_utc
                or envelope.get("character_interval_ref")
                != context.character_interval_ref
                or envelope.get("monotonic_deadline")
                != context.monotonic_deadline
                or binding.source_revision != context.source_revision
                or binding.access_revision != context.access_revision
                or canonical_serialize(envelope["authority"])
                != canonical_serialize(context.authority)
                or canonical_serialize(envelope["version_guard"])
                != canonical_serialize(context.version_guard)
                or canonical_serialize(envelope["source_qualification"])
                != canonical_serialize(context.source_qualification)
                or not context.now_utc < envelope["deadline_utc"]
                <= context.deadline_utc):
            raise UnavailableGuard("encoding binding lost trusted issuance context; HOLD")

    def acquire_first_ingress_encoding_job_v3(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire new first-ingress work only with a committed D04 baseline."""
        return self.acquire_first_ingress_encoding_job_v2(
            authority, lease, job_id, acquire_operation_id,
            lease_seconds=lease_seconds, _require_baseline_v3=True)

    def _acquire_source_correction_job_v1(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
    ) -> PersistentJob:
        """Acquire a committed correction job; leave its head and outbox pending.

        The caller is a trusted D11 scheduler. Authority RPCs occur outside the
        graph lock; the job mutation, graph projection and V2 receipt share one
        GraphStore transaction. This is not a reevaluation or cost settlement.
        """
        from datetime import datetime, timezone

        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.d11_types import (
            RuntimeOutboxValue, job_graph_write, outbox_graph_write,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer
        from .runtime.source_correction_job import (
            SourceCorrectionJobHold, acquire_source_correction_job_in_transaction,
            plan_source_correction_job_acquire, read_source_correction_job_snapshot,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed V2 D11 job and trusted clock are required; HOLD")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or authority.worker_fence is not None
                or type(lease_seconds) is not int or not 1 <= lease_seconds <= 3600
                or type(acquire_operation_id) is not str
                or not acquire_operation_id or len(acquire_operation_id) > 128
                or authority.capability_ref != _operation_capability_ref(
                    namespace, authority.actor, "d11", frozenset({"d11"}),
                    authority.activation_generation, acquire_operation_id)):
            raise AuthorityDenied("D11 correction activity capability differs")
        try:
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
        except Exception as exc:
            raise UnavailableGuard("correction trusted clock is unavailable; HOLD") from exc

        def read_snapshot():
            db = store._db
            db.execute("BEGIN")
            try:
                snapshot = read_source_correction_job_snapshot(
                    db, self.__d11_issuer, namespace, job_id, now_utc=now)
                db.execute("COMMIT")
                return snapshot
            except BaseException:
                db.execute("ROLLBACK")
                raise

        with store._lock:
            pre_intent = store._db.execute(
                "SELECT fence_attempt_id,graph_revision,graph_epoch FROM "
                "graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            pre_receipt = store._db.execute(
                "SELECT post_graph_revision,post_graph_epoch FROM "
                "graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            pre_metadata, _ = self._v2_graph_stamp(namespace)
        active_scope = None
        if pre_intent is not None:
            pre_target = pre_metadata.requirements
            try:
                pre_anchor = port.current_anchor(
                    namespace=namespace,
                    authority_namespace=pre_target.authority_namespace)
                observed_permit, observed_state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=pre_target.authority_namespace,
                    operation_id=pre_intent[0])
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire Authority recovery unknown; HOLD") from exc
            if not self._anchor_matches(pre_target, pre_anchor):
                raise UnavailableGuard("correction recovery anchor changed; HOLD")
            if observed_state == "active":
                if (type(observed_permit) is not FencePermitV2
                        or observed_permit.operation != "write"
                        or observed_permit.operation_id != pre_intent[0]
                        or observed_permit.holder != self.__holder
                        or observed_permit.subject != port.installation_grant.subject
                        or observed_permit.pinned_anchor != pre_anchor):
                    raise UnavailableGuard("correction active write permit differs; HOLD")
                try:
                    active_scope = FenceScope(
                        namespace, pre_target.authority_namespace,
                        pre_target.activation_generation, "write", pre_intent[0],
                        observed_permit, pre_anchor,
                        NamespaceEpoch(*namespace.as_tuple, pre_intent[2]),
                        pre_intent[1])
                except (TypeError, ValueError) as exc:
                    raise UnavailableGuard(
                        "correction recovery write scope differs; HOLD") from exc
            elif observed_state not in {"absent", "finished"}:
                raise UnavailableGuard("correction acquire Authority state differs; HOLD")
        try:
            if active_scope is None:
                snapshot, anchor, metadata, epoch = self._read_v2(
                    authority, read_snapshot, return_recovery_context=True)
            else:
                # A durable write fence may block a new read fence after an
                # unknown begin or finish. It is independently validated before
                # and after the pinned SQLite read, without an RPC under lock.
                if port.validate_fence(active_scope) != active_scope.permit:
                    raise UnavailableGuard("correction recovery write permit changed; HOLD")
                with store._lock:
                    metadata, epoch = self._v2_graph_stamp(namespace)
                    if (pre_receipt is None and (metadata.graph_revision,
                                                epoch.revision) != pre_intent[1:3]
                            or pre_receipt is not None and (
                                metadata.graph_revision < pre_receipt[0]
                                or epoch.revision < pre_receipt[1])):
                        raise UnavailableGuard("correction recovery graph stamp differs; HOLD")
                    snapshot = read_snapshot()
                if port.validate_fence(active_scope) != active_scope.permit:
                    raise UnavailableGuard("correction recovery write permit changed; HOLD")
                anchor = pre_anchor
        except (UnavailableGuard, SourceCorrectionJobHold) as exc:
            raise UnavailableGuard("correction V2 read or identity unavailable; HOLD") from exc
        try:
            expected_acquire_id = source_correction_acquire_operation_id(
                namespace, job_id, snapshot.job.operation_id, authority.actor,
                authority.activation_generation, acquire_operation_id[-32:])
        except ValueError as exc:
            raise AuthorityDenied("correction acquire operation is invalid") from exc
        if acquire_operation_id != expected_acquire_id:
            raise AuthorityDenied("correction acquire operation names another job")
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation
                or snapshot.activation_generation != target.activation_generation):
            raise UnavailableGuard("correction activation changed; HOLD")
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))

        def digest_for(*, fixed_now: str, expected_revision: int,
                       expected_fence: int, expected_cancel: int,
                       graph_revision: int, graph_epoch: int) -> str:
            return canonical_digest({
                "schema": "sylanne.d06-source-correction-job-acquire.v1",
                "namespace": list(namespace.as_tuple), "job_id": job_id,
                "original_operation_id": snapshot.job.operation_id,
                "original_bundle_digest": snapshot.original_digest,
                "original_graph_revision": snapshot.original_graph_revision,
                "request_digest": snapshot.request_digest,
                "correction_source_ref": snapshot.correction_source_ref,
                "source_refs": list(snapshot.source_refs),
                "head_refs": list(snapshot.head_refs),
                "target_refs": list(snapshot.target_refs),
                "outbox_ref": snapshot.outbox_ref,
                "quote_id": snapshot.quote.quote_id,
                "quote_version": snapshot.quote.version,
                "quote_ceiling": dict(snapshot.quote.ceiling),
                "reservation_digest": snapshot.reservation_digest,
                "acquire_operation_id": acquire_operation_id,
                "actor": authority.actor,
                "activation_generation": authority.activation_generation,
                "expected_job_revision": expected_revision,
                "expected_fence": expected_fence,
                "expected_cancel_epoch": expected_cancel,
                "fixed_now_utc": fixed_now,
                "lease_seconds": lease_seconds,
                "graph_revision": graph_revision, "graph_epoch": graph_epoch,
            })

        with store._lock:
            db = store._db
            intent = db.execute(
                "SELECT request_digest,job_id,original_operation_id,actor,"
                "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch,encoding_binding_json "
                "FROM graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            receipt = db.execute(
                "SELECT request_digest,job_json,permit_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            rejection = db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_rejections_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
        if intent is None:
            if snapshot.job.phase != "queued":
                raise UnavailableGuard("correction job already has a worker lease; HOLD")
            try:
                planned = plan_source_correction_job_acquire(
                    snapshot, authority.actor, now_utc=now,
                    lease_seconds=lease_seconds)
            except SourceCorrectionJobHold as exc:
                raise UnavailableGuard(str(exc)) from exc
            if planned == snapshot.job:
                raise UnavailableGuard("correction job already acquired; HOLD")
            request_digest = digest_for(
                fixed_now=now_text, expected_revision=snapshot.job_revision,
                expected_fence=snapshot.job.fence,
                expected_cancel=snapshot.job.cancel_epoch,
                graph_revision=metadata.graph_revision, graph_epoch=epoch.revision)
            attempt_id = "d06-acquire-write-" + request_digest[:48]
            expected_intent = (
                request_digest, job_id, snapshot.job.operation_id, authority.actor,
                now_text, lease_seconds, snapshot.job_revision, snapshot.job.fence,
                snapshot.job.cancel_epoch, attempt_id, requirements_json, anchor_json,
                metadata.graph_revision, epoch.revision, None,
            )
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("correction acquire pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_intents_v2"
                        "(bot,persona,acquire_operation_id,request_digest,job_id,"
                        "original_operation_id,actor,fixed_now_utc,lease_seconds,"
                        "expected_job_revision,expected_fence,expected_cancel_epoch,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,) + expected_intent,
                    )
                    observed = db.execute(
                        "SELECT request_digest,job_id,original_operation_id,actor,"
                        "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                        "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json "
                        "FROM graph_job_acquire_intents_v2 WHERE bot=? AND persona=? "
                        "AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    if observed != expected_intent:
                        raise EventConflict("correction acquire identity was reused")
                    db.execute("COMMIT")
                    intent = observed
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if (intent[1:4] != (job_id, snapshot.job.operation_id, authority.actor)
                or intent[5] != lease_seconds or intent[10:12]
                != (requirements_json, anchor_json) or intent[14] is not None):
            raise UnavailableGuard("correction acquire intent differs; HOLD")
        request_digest = digest_for(
            fixed_now=intent[4], expected_revision=intent[6],
            expected_fence=intent[7], expected_cancel=intent[8],
            graph_revision=intent[12], graph_epoch=intent[13])
        attempt_id = "d06-acquire-write-" + request_digest[:48]
        if intent[0] != request_digest or intent[9] != attempt_id:
            raise UnavailableGuard("correction acquire digest differs; HOLD")
        if receipt is not None and rejection is not None:
            raise UnavailableGuard("correction acquire terminal ledgers disagree; HOLD")

        def finish_identity(permit, *, rejected=False):
            finish_id = ("abort:" if rejected else "finish:") + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_commit" if rejected else
                          "finish_source_correction_job_acquire",
                "business_operation_id": acquire_operation_id,
                "request_digest": request_digest,
            })
            return finish_id, finish_digest

        if receipt is not None or rejection is not None:
            terminal = receipt if receipt is not None else rejection
            permit = from_wire(json.loads(terminal[2] if receipt is not None
                                          else terminal[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.operation != "write" or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("correction acquire durable permit differs; HOLD")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire Authority state unknown; HOLD") from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("correction acquire Authority state differs; HOLD")
            if receipt is None:
                if (rejection[0] != "rejected_no_commit"
                        or rejection[2:4] != intent[12:14]
                        or rejection[4:6] != finish_identity(permit, rejected=True)):
                    raise UnavailableGuard("correction acquire rejection differs; HOLD")
                if state == "active":
                    scope = FenceScope(
                        namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id,
                        permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                                                       intent[13]), intent[12])
                    if port.validate_fence(scope) != permit:
                        raise UnavailableGuard("correction acquire permit changed; HOLD")
                    port.finish_fence(scope, request_id=rejection[4],
                                      request_digest=rejection[5])
                raise UnavailableGuard("correction acquire was rejected; HOLD")
            if (receipt[0] != request_digest
                    or receipt[3:5] != intent[12:14]
                    or receipt[5:7] != (intent[12] + 1, intent[13] + 1)
                    or receipt[7:9] != finish_identity(permit)):
                raise UnavailableGuard("correction acquire receipt differs; HOLD")
            try:
                historical = PersistentJob(**json.loads(receipt[1]))
                current_is_live = plan_source_correction_job_acquire(
                    snapshot, authority.actor, now_utc=now,
                    lease_seconds=lease_seconds) == snapshot.job
            except Exception as exc:
                raise UnavailableGuard("correction acquired lease expired; HOLD") from exc
            if (historical != snapshot.job or not current_is_live
                    or historical.lease_holder != authority.actor
                    or snapshot.graph_revision < receipt[5]
                    or snapshot.graph_epoch < receipt[6]):
                raise UnavailableGuard("correction acquired job is no longer current; HOLD")
            if state == "active":
                if ((snapshot.graph_revision, snapshot.graph_epoch)
                        != receipt[5:7]):
                    raise UnavailableGuard("unresolved correction acquire stamp changed; HOLD")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id,
                    permit, anchor, NamespaceEpoch(*namespace.as_tuple,
                                                   receipt[4]), receipt[3])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("correction acquire permit changed; HOLD")
                port.finish_fence(scope, request_id=receipt[7],
                                  request_digest=receipt[8])
            return historical

        if ((metadata.graph_revision, epoch.revision) != intent[12:14]
                or (snapshot.job_revision, snapshot.job.fence,
                    snapshot.job.cancel_epoch) != intent[6:9]):
            raise UnavailableGuard("uncommitted correction acquire prestate changed; HOLD")
        fixed_now = datetime.fromisoformat(intent[4].replace("Z", "+00:00")).timestamp()
        try:
            planned = plan_source_correction_job_acquire(
                snapshot, authority.actor, now_utc=fixed_now,
                lease_seconds=lease_seconds)
            plan_source_correction_job_acquire(
                snapshot, authority.actor, now_utc=now,
                lease_seconds=lease_seconds)
        except SourceCorrectionJobHold as exc:
            raise UnavailableGuard(str(exc)) from exc
        if planned == snapshot.job:
            raise UnavailableGuard("correction acquire has no new worker lease; HOLD")
        try:
            permit = port.begin_fence(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id,
                "correction acquire begin outcome unknown; HOLD") from exc
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("correction acquire write permit changed; HOLD")
        finish_id, finish_digest = finish_identity(permit)
        job_key = AtomKey.from_token(snapshot.quote.graph_job_ref)
        outbox_key = AtomKey.from_token(snapshot.outbox_ref)
        with store._lock:
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise UnavailableGuard("correction acquire graph stamp changed; HOLD")
            guarded_refs = (snapshot.correction_source_ref, *snapshot.source_refs,
                            *snapshot.head_refs, *snapshot.target_refs)
            rows = store._db.execute(
                "SELECT token,revision FROM graph_atoms WHERE token IN (" +
                ",".join("?" for _ in guarded_refs) + ")", guarded_refs,
            ).fetchall()
            outbox_row = store._db.execute(
                "SELECT value FROM graph_atoms WHERE token=?",
                (snapshot.outbox_ref,),
            ).fetchone()
        if len(rows) != len(set(guarded_refs)):
            raise UnavailableGuard("correction acquire graph reads absent; HOLD")
        if outbox_row is None:
            raise UnavailableGuard("correction acquire outbox is absent; HOLD")
        pending_outbox = RuntimeOutboxValue(**json.loads(outbox_row[0]))
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, snapshot.job.activity_id),
                  acquire_operation_id, fixed_now,
                  "source_correction_job_acquire_v1",
                  {"request_digest": request_digest}),
            (GraphVersion(job_key, snapshot.job_revision),
             GraphVersion(outbox_key, snapshot.outbox_revision),
             *(GraphVersion(AtomKey.from_token(ref), revision)
               for ref, revision in rows)),
            (job_graph_write(planned),
             outbox_graph_write(pending_outbox, job_key)), (epoch,),
        )
        transaction_state = {"phase": "before_transaction"}

        def guard(db):
            try:
                commit_now = trusted_upper(clock)
                expires = datetime.fromisoformat(
                    planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            except Exception as exc:
                raise UnavailableGuard("correction acquire trusted clock expired; HOLD") from exc
            if commit_now >= expires:
                raise UnavailableGuard("correction frozen worker lease expired; HOLD")
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("correction acquire graph stamp changed")
            if db.execute(
                    "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
            ).fetchone():
                raise UnavailableGuard("correction acquire receipt appeared before commit")
            current = read_source_correction_job_snapshot(
                db, self.__d11_issuer, namespace, job_id, now_utc=commit_now)
            if current != snapshot:
                raise StaleRead("correction original identity changed")
            acquired = acquire_source_correction_job_in_transaction(
                db, self.__d11_issuer, snapshot, scope, authority.actor,
                fence_holder=self.__holder, now_utc=fixed_now,
                lease_seconds=lease_seconds)
            if acquired != planned:
                raise StaleRead("correction acquired job differs from frozen plan")
            reconcile_runtime_write(db, candidate.writes[0])
            reconcile_runtime_write(db, candidate.writes[1])

        def receipt_hook(db, graph_receipt):
            if (graph_receipt.status != "committed"
                    or len(graph_receipt.revisions) != 2
                    or {item.key for item in graph_receipt.revisions}
                    != {job_key, outbox_key}):
                raise UnavailableGuard("correction job graph write was not committed")
            store.cas_graph_recovery_metadata(
                metadata, metadata.requirements,
                _capability=self.__graph_capability)
            db.execute(
                "INSERT INTO graph_job_acquire_receipts_v2"
                "(bot,persona,acquire_operation_id,request_digest,job_json,"
                "permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (acquire_operation_id, request_digest,
                    canonical_json(asdict(planned)), canonical_json(to_wire(permit)),
                    metadata.graph_revision, epoch.revision,
                    metadata.graph_revision + 1, graph_receipt.epoch.revision,
                    finish_id, finish_digest),
            )

        try:
            GraphStore.graph_commit(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
                _transaction_state=transaction_state)
        except Exception as exc:
            if transaction_state["phase"] not in {"before_transaction", "rolled_back"}:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire commit outcome unknown; HOLD") from exc
            abort_id, abort_digest = finish_identity(permit, rejected=True)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("correction acquire rollback cannot be proven")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_rejections_v2"
                        "(bot,persona,acquire_operation_id,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,
                            "rejected_no_commit", canonical_json(to_wire(permit)),
                            metadata.graph_revision, epoch.revision,
                            abort_id, abort_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            try:
                port.finish_fence(scope, request_id=abort_id,
                                  request_digest=abort_digest)
            except Exception as finish_exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id,
                    "correction acquire rejection finish unknown; HOLD") from finish_exc
            raise
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("correction acquire permit changed after commit")
            with store._lock:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current.graph_revision != metadata.graph_revision + 1
                        or current_epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("correction acquire committed stamp differs")
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finish_digest)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id,
                "correction acquire finish outcome unknown; HOLD") from exc
        return planned

    def acquire_first_ingress_encoding_job_v2(
        self, authority: AuthorityContext, lease: object, job_id: str,
        acquire_operation_id: str, *, lease_seconds: int,
        _require_baseline_v3: bool = False,
    ) -> PersistentJob:
        """Acquire exactly one original encoding job under a recoverable v2 write fence."""
        from datetime import datetime, timezone

        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire
        from .host.authority_profile import AdminIngressClockPolicy
        from .runtime.d11_types import job_graph_write, outbox_graph_write
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D11BudgetJobIssuer
        from .runtime.encoding_call_binding import (
            binding_from_json, binding_to_json, insert_binding, load_binding,
        )

        store = self.__store
        port = self.__content_fence_v2
        namespace = authority.namespace
        if (not isinstance(store, ProductionGraphStore) or port is None
                or type(self.__d11_issuer) is not D11BudgetJobIssuer
                or type(self.__scene_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed v2 D11 job and trusted clock are required")
        self._authorize(lease, authority, frozenset({"d11"}))
        if (authority.issuer_domain != "d11" or "activity" not in authority.owner_scope
                or type(acquire_operation_id) is not str
                or not acquire_operation_id or len(acquire_operation_id) > 128
                or type(lease_seconds) is not int or not 1 <= lease_seconds <= 3600):
            raise AuthorityDenied("D11 activity capability and bounded acquire identity required")
        if authority.capability_ref != _operation_capability_ref(
                namespace, authority.actor, "d11", frozenset({"d11"}),
                authority.activation_generation, acquire_operation_id):
            raise AuthorityDenied("D11 acquire lease is not scoped to this operation")

        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = store._db.execute(
                "SELECT request_digest,job_id,original_operation_id,actor,"
                "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch,encoding_binding_json "
                "FROM graph_job_acquire_intents_v2 "
                "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            receipt = store._db.execute(
                "SELECT request_digest,job_json,permit_json,pre_graph_revision,"
                "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_receipts_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            rejection = store._db.execute(
                "SELECT status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest "
                "FROM graph_job_acquire_rejections_v2 WHERE bot=? AND persona=? "
                "AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            erased = store._db.execute(
                "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                namespace.as_tuple + (acquire_operation_id,),
            ).fetchone()
            if intent is None:
                (job, job_key, job_revision, outbox, outbox_key,
                 outbox_revision, source_version, access_version) = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if store._db.execute(
                        "SELECT 1 FROM runtime_encoding_call_redactions_v1 "
                        "WHERE bot=? AND persona=? AND source_id=? LIMIT 1",
                        namespace.as_tuple + (outbox.payload_ref,),
                ).fetchone():
                    raise UnavailableGuard("encoding source request was erased; HOLD")
            else:
                job = None
        if erased is not None:
            raise UnavailableGuard("encoding request was erased; HOLD")
        if _require_baseline_v3 and (
                self.__encoding_request_issuer is None or
                intent is not None and (intent[14] is None or
                binding_from_json(intent[14]).request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3")):
            raise UnavailableGuard("V3 acquire requires original committed baseline; HOLD")
        original_operation_id = job.operation_id if intent is None else intent[2]
        if not _job_acquire_id_matches(
                acquire_operation_id, namespace, job_id,
                original_operation_id, authority.actor,
                authority.activation_generation):
            raise AuthorityDenied("D11 acquire lease names another job")
        target = metadata.requirements
        if (target.namespace != namespace
                or target.activation_generation != authority.activation_generation):
            raise UnavailableGuard("job acquire activation or namespace changed")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("job acquire Authority anchor differs")
        try:
            clock = port.read_ingress_clock(self.__scene_clock_policy)
            now = trusted_upper(clock)
            now_text = datetime.fromtimestamp(now, timezone.utc).isoformat().replace(
                "+00:00", "Z")
        except Exception as exc:
            raise UnavailableGuard("paired job clock is unavailable; HOLD") from exc
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))
        if intent is None:
            if acquire_operation_id == job.operation_id:
                raise AuthorityDenied("acquire operation must differ from original ingress")
            try:
                planned = plan_job_acquire(
                    job, authority.actor, now_utc=now_text,
                    lease_seconds=lease_seconds)
            except Exception as exc:
                raise UnavailableGuard("encoding job is not runnable; HOLD") from exc
            if planned == job or job.cancel_epoch:
                raise UnavailableGuard("encoding job has an active or cancelled lease; HOLD")
            binding = (self._issue_first_ingress_encoding_binding(
                namespace, planned, outbox, source_version, access_version,
                authority, now, acquire_operation_id, clock,
                require_baseline_v3=_require_baseline_v3)
                if self.__encoding_request_issuer is not None else None)
            binding_json = binding_to_json(binding) if binding is not None else None
            request_digest = canonical_digest({
                "schema": "sylanne.job-acquire.v2",
                "namespace": list(namespace.as_tuple), "job_id": job_id,
                "original_operation_id": job.operation_id,
                "acquire_operation_id": acquire_operation_id,
                "actor": authority.actor,
                "activation_generation": authority.activation_generation,
                "expected_job_revision": job_revision, "expected_fence": job.fence,
                "expected_cancel_epoch": job.cancel_epoch,
                "fixed_now_utc": now_text, "lease_seconds": lease_seconds,
            })
            attempt_id = "job-acquire-" + request_digest[:48]
            expected_intent = (
                request_digest, job_id, job.operation_id, authority.actor,
                now_text, lease_seconds, job_revision, job.fence, job.cancel_epoch,
                attempt_id, requirements_json, anchor_json,
                metadata.graph_revision, epoch.revision, binding_json,
            )
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("job acquire pre-stamp changed")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_intents_v2"
                        "(bot,persona,acquire_operation_id,request_digest,job_id,"
                        "original_operation_id,actor,fixed_now_utc,lease_seconds,"
                        "expected_job_revision,expected_fence,expected_cancel_epoch,"
                        "fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,) + expected_intent,
                    )
                    intent = db.execute(
                        "SELECT request_digest,job_id,original_operation_id,actor,"
                        "fixed_now_utc,lease_seconds,expected_job_revision,expected_fence,"
                        "expected_cancel_epoch,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch,encoding_binding_json "
                        "FROM graph_job_acquire_intents_v2 "
                        "WHERE bot=? AND persona=? AND acquire_operation_id=?",
                        namespace.as_tuple + (acquire_operation_id,),
                    ).fetchone()
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            if intent != expected_intent:
                raise EventConflict("acquire operation identity was reused")
        else:
            if (intent[1] != job_id or intent[3] != authority.actor
                    or intent[5] != lease_seconds
                    or intent[10] != requirements_json
                    or intent[11] != anchor_json):
                raise UnavailableGuard("original job acquire identity differs; HOLD")
            attempt_id = intent[9]
            request_digest = intent[0]
        if request_digest != canonical_digest({
            "schema": "sylanne.job-acquire.v2",
            "namespace": list(namespace.as_tuple), "job_id": intent[1],
            "original_operation_id": intent[2],
            "acquire_operation_id": acquire_operation_id,
            "actor": intent[3],
            "activation_generation": target.activation_generation,
            "expected_job_revision": intent[6], "expected_fence": intent[7],
            "expected_cancel_epoch": intent[8],
            "fixed_now_utc": intent[4], "lease_seconds": intent[5],
        }) or attempt_id != "job-acquire-" + request_digest[:48]:
            raise UnavailableGuard("job acquire intent digest differs")
        if receipt is not None and rejection is not None:
            raise UnavailableGuard("job acquire terminal ledgers disagree")

        def finish_identity(permit, *, rejected=False):
            finish_id = ("abort:" if rejected else "finish:") + attempt_id
            finish_digest = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "rejected_no_commit" if rejected else "finish_job_acquire",
                "business_operation_id": acquire_operation_id,
                "request_digest": request_digest,
            })
            return finish_id, finish_digest

        if receipt is not None or rejection is not None:
            row = receipt if receipt is not None else rejection
            permit = from_wire(json.loads(row[2] if receipt is not None else row[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id or permit.operation != "write"
                    or permit.holder != self.__holder
                    or permit.subject != port.installation_grant.subject
                    or permit.pinned_anchor != anchor):
                raise UnavailableGuard("job acquire durable permit differs")
            try:
                observed, state = port.get_fence_operation(
                    namespace=namespace, authority_namespace=target.authority_namespace,
                    operation_id=attempt_id)
            except Exception as exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire Authority state unknown; HOLD") from exc
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("job acquire Authority state differs")
            if receipt is not None:
                if (receipt[0] != request_digest
                        or receipt[3:5] != intent[12:14]
                        or receipt[5] != receipt[3] + 1
                        or receipt[8] != finish_identity(permit)[1]
                        or receipt[7] != finish_identity(permit)[0]):
                    raise UnavailableGuard("job acquire receipt identity differs")
                historical = PersistentJob(**json.loads(receipt[1]))
                with store._lock:
                    durable_binding = load_binding(store._db, namespace, job_id)
                frozen_binding = (binding_from_json(intent[14])
                                  if intent[14] is not None else None)
                if durable_binding != frozen_binding:
                    raise UnavailableGuard("replayed job binding differs from frozen intent; HOLD")
                replay_now = trusted_upper(clock)
                replay_now_text = datetime.fromtimestamp(
                    replay_now, timezone.utc).isoformat().replace("+00:00", "Z")
                with store._lock:
                    (current, _, _, current_outbox, _, _, current_source,
                     current_access) = self._first_ingress_encoding_job_locked(
                         namespace, job_id)
                    current_stamp = self._v2_graph_stamp(namespace)
                    if frozen_binding is not None:
                        self._validate_first_ingress_encoding_binding_context(
                            namespace, current, current_outbox,
                            current_source, current_access, authority,
                            replay_now, acquire_operation_id, clock,
                            frozen_binding)
                try:
                    current_is_live = plan_job_acquire(
                        current, authority.actor, now_utc=replay_now_text,
                        lease_seconds=lease_seconds) == current
                except Exception as exc:
                    raise UnavailableGuard("replayed job lease expired; HOLD") from exc
                if (current != historical or current.lease_holder != authority.actor
                        or not current_is_live):
                    raise UnavailableGuard("replayed job lease is no longer current; HOLD")
                if state == "active":
                    if current_stamp != (metadata, epoch) and (
                            current_stamp[0].graph_revision != receipt[5]
                            or current_stamp[1].revision != receipt[6]):
                        raise UnavailableGuard("unresolved job acquire stamp changed")
                    scope = FenceScope(namespace, target.authority_namespace,
                        target.activation_generation, "write", attempt_id, permit,
                        anchor, NamespaceEpoch(*namespace.as_tuple, receipt[4]),
                        receipt[3])
                    if port.validate_fence(scope) != permit:
                        raise UnavailableGuard("job acquire permit changed")
                    port.finish_fence(scope, request_id=receipt[7],
                                      request_digest=receipt[8])
                if frozen_binding is not None and frozen_binding.request.get(
                        "schema") == "sylanne.first-ingress-encoding-call.v3":
                    # Replaying V3 is not new budget admission. Its model cost
                    # may have settled the reservation. The result context
                    # rechecks signed provenance and current content under a
                    # new read fence without requiring reserved state.
                    original_context = (
                        self.read_first_ingress_original_model_result_context_v1(
                            replace(authority, worker_fence=historical.fence),
                            lease, job_id, acquire_operation_id))
                    if (original_context.original_operation_id
                            != historical.operation_id
                            or original_context.worker_actor != authority.actor
                            or original_context.worker_fence != historical.fence
                            or original_context.call_id != durable_binding.call_id):
                        raise UnavailableGuard("replayed job original context differs; HOLD")
                return self._qualified_first_ingress_acquire_return(
                    namespace, job_id, historical, authority.actor, clock,
                    lease_seconds, original_context_verified=(
                        frozen_binding is not None and frozen_binding.request.get(
                            "schema") == "sylanne.first-ingress-encoding-call.v3"))
            if (rejection[0] != "rejected_no_commit"
                    or rejection[2:4] != intent[12:14]
                    or rejection[4:6] != finish_identity(permit, rejected=True)):
                raise UnavailableGuard("job acquire rejection identity differs")
            if state == "active":
                scope = FenceScope(namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id, permit,
                    anchor, NamespaceEpoch(*namespace.as_tuple, intent[13]), intent[12])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("rejected job acquire permit changed")
                port.finish_fence(scope, request_id=rejection[4],
                                  request_digest=rejection[5])
            raise UnavailableGuard("job acquire is terminal rejected_no_commit")

        if (metadata.graph_revision, epoch.revision) != intent[12:14]:
            raise UnavailableGuard("uncommitted job acquire graph stamp changed")
        if job is None:
            with store._lock:
                (job, job_key, job_revision, outbox, outbox_key,
                 outbox_revision, source_version, access_version) = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
        if (job.operation_id != intent[2] or job_revision != intent[6]
                or job.fence != intent[7] or job.cancel_epoch != intent[8]):
            raise UnavailableGuard("uncommitted job acquire prestate changed")
        try:
            planned = plan_job_acquire(
                job, authority.actor, now_utc=intent[4], lease_seconds=lease_seconds)
            plan_job_acquire(job, authority.actor, now_utc=now_text,
                             lease_seconds=lease_seconds)
        except Exception as exc:
            raise UnavailableGuard("encoding job acquire deadline expired; HOLD") from exc
        if planned == job or job.cancel_epoch:
            raise UnavailableGuard("encoding job is no longer runnable; HOLD")
        frozen_binding = (binding_from_json(intent[14])
                          if intent[14] is not None else None)
        if frozen_binding is not None:
            if self.__encoding_request_issuer is None:
                raise UnavailableGuard("original encoding request issuer is unavailable; HOLD")
            current_binding = self._issue_first_ingress_encoding_binding(
                namespace, planned, outbox, source_version, access_version,
                authority, now, acquire_operation_id, clock,
                frozen_binding, require_baseline_v3=_require_baseline_v3)
            if current_binding != frozen_binding:
                raise UnavailableGuard("encoding request configuration changed; HOLD")
        elif self.__encoding_request_issuer is not None:
            # The original intent predates this issuer. It cannot gain a
            # request after its Authority operation identity was frozen.
            raise UnavailableGuard("original job acquire has no encoding request; HOLD")

        try:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id, "job acquire begin outcome unknown; HOLD") from exc
        scope = FenceScope(namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id, permit,
            anchor, epoch, metadata.graph_revision)
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("job acquire write permit changed")
        finish_id, finish_digest = finish_identity(permit)
        from .runtime.d11_types import RuntimeOutboxValue

        pending = RuntimeOutboxValue(**asdict(outbox))
        candidate = GraphCandidate(
            Event(Scope(*namespace.as_tuple, job.activity_id),
                  acquire_operation_id,
                  datetime.fromisoformat(intent[4].replace("Z", "+00:00")).timestamp(),
                  "job_acquire_v2", {"request_digest": request_digest}),
            (GraphVersion(job_key, job_revision),
             GraphVersion(outbox_key, outbox_revision),
             source_version, access_version),
            (job_graph_write(planned), outbox_graph_write(pending, job_key)),
            (epoch,),
        )
        transaction_state = {"phase": "before_transaction"}

        def guard(db):
            try:
                commit_now = trusted_upper(clock)
                commit_now_text = datetime.fromtimestamp(
                    commit_now, timezone.utc).isoformat().replace("+00:00", "Z")
                plan_job_acquire(job, authority.actor, now_utc=commit_now_text,
                                 lease_seconds=lease_seconds)
                planned_expires = datetime.fromisoformat(
                    planned.lease_expires_utc.replace("Z", "+00:00")).timestamp()
            except Exception as exc:
                raise UnavailableGuard("job acquire trusted clock expired; HOLD") from exc
            if commit_now >= planned_expires:
                raise UnavailableGuard("job acquire frozen lease expired; HOLD")
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("job acquire graph stamp changed")
            if db.execute(
                    "SELECT 1 FROM graph_job_acquire_receipts_v2 WHERE bot=? "
                    "AND persona=? AND acquire_operation_id=?",
                    namespace.as_tuple + (acquire_operation_id,),
            ).fetchone():
                raise UnavailableGuard("job acquire receipt appeared before commit")
            current = self._first_ingress_encoding_job_locked(namespace, job_id)[0]
            if current != job:
                raise StaleRead("job acquire durable prestate changed")
            self.__d11_issuer.authorize_existing_encoding_job(
                db, job, now_utc=commit_now)
            if frozen_binding is not None:
                self._validate_first_ingress_encoding_binding_context(
                    namespace, planned, outbox, source_version,
                    access_version, authority, commit_now,
                    acquire_operation_id, clock, frozen_binding)
                if (self.__encoding_request_issuer is None
                        or self._issue_first_ingress_encoding_binding(
                            namespace, planned, outbox, source_version,
                            access_version, authority, commit_now,
                            acquire_operation_id, clock, frozen_binding,
                            require_baseline_v3=_require_baseline_v3)
                        != frozen_binding):
                    raise UnavailableGuard(
                        "encoding request configuration changed; HOLD")
            if acquire_job(db, job_id, authority.actor,
                           now_utc=intent[4], lease_seconds=lease_seconds) != planned:
                raise StaleRead("job acquire mutation differed from frozen plan")
            reconcile_runtime_write(db, candidate.writes[0])
            reconcile_runtime_write(db, candidate.writes[1])
            if frozen_binding is not None:
                insert_binding(db, frozen_binding)

        def receipt_hook(db, graph_receipt):
            if graph_receipt.status != "committed" or len(graph_receipt.revisions) != 2:
                raise UnavailableGuard("job acquire graph event was not committed")
            if load_binding(db, namespace, job_id) != frozen_binding:
                raise UnavailableGuard("job acquire binding did not match frozen intent")
            store.cas_graph_recovery_metadata(
                metadata, metadata.requirements,
                _capability=self.__graph_capability)
            db.execute(
                "INSERT INTO graph_job_acquire_receipts_v2"
                "(bot,persona,acquire_operation_id,request_digest,job_json,"
                "permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (acquire_operation_id, request_digest,
                    canonical_json(asdict(planned)), canonical_json(to_wire(permit)),
                    metadata.graph_revision, epoch.revision,
                    metadata.graph_revision + 1, graph_receipt.epoch.revision,
                    finish_id, finish_digest),
            )

        try:
            GraphStore.graph_commit(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
                _transaction_state=transaction_state)
        except Exception as exc:
            if transaction_state["phase"] not in {"before_transaction", "rolled_back"}:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire commit outcome unknown; HOLD") from exc
            abort_id, abort_digest = finish_identity(permit, rejected=True)
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise UnavailableGuard("job acquire rollback cannot be proven")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_job_acquire_rejections_v2"
                        "(bot,persona,acquire_operation_id,status,permit_json,"
                        "graph_revision,graph_epoch,finish_request_id,"
                        "finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (acquire_operation_id,
                            "rejected_no_commit", canonical_json(to_wire(permit)),
                            metadata.graph_revision, epoch.revision,
                            abort_id, abort_digest),
                    )
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
            try:
                port.finish_fence(scope, request_id=abort_id,
                                  request_digest=abort_digest)
            except Exception as finish_exc:
                raise JobAcquireOutcomeUnknown(
                    acquire_operation_id, "job acquire rejection finish unknown; HOLD"
                ) from finish_exc
            raise
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("job acquire permit changed after commit")
            with store._lock:
                current, current_epoch = self._v2_graph_stamp(namespace)
                if (current.graph_revision != metadata.graph_revision + 1
                        or current_epoch.revision != epoch.revision + 1):
                    raise UnavailableGuard("job acquire committed stamp differs")
            port.finish_fence(scope, request_id=finish_id,
                              request_digest=finish_digest)
        except Exception as exc:
            raise JobAcquireOutcomeUnknown(
                acquire_operation_id, "job acquire finish outcome unknown; HOLD") from exc
        return self._qualified_first_ingress_acquire_return(
            namespace, job_id, planned, authority.actor, clock, lease_seconds)

    def cancel_persistent_job(self, authority: AuthorityContext, lease: object,
                              job_id: str, operation_id: str,
                              digest: str) -> PersistentJob:
        self._authorize(lease, authority, frozenset())
        return self._mutate_job(authority, job_id, lambda db: cancel_job(
            db, job_id, operation_id, digest))

    def _mutate_job(self, authority: AuthorityContext, job_id: str, mutation):
        namespace = authority.namespace
        store = self.__store
        with self._content_fence(namespace, authority.activation_generation, "write"):
            with store._lock:
                store._ensure_open()
                self._admit_content(namespace, authority.activation_generation, "write")
                store._db.execute("BEGIN IMMEDIATE")
                try:
                    if self._version(store._db, namespace, "activation", "current") != str(
                            authority.activation_generation):
                        raise StaleRead("activation generation changed")
                    job = get_job(store._db, job_id)
                    if (job.bot_id, job.persona_id) != namespace.as_tuple:
                        raise AuthorityDenied("job crosses namespace")
                    result = mutation(store._db)
                    store._db.execute("COMMIT")
                    return result
                except BaseException:
                    store._db.execute("ROLLBACK")
                    raise

    def _admit_runtime_bundle(self, db, bundle: DomainBundle, *,
                              now_utc: float | None = None,
                              require_arrival_quote: bool = False,
                              c02_terminal_recovery: _C02TerminalRecovery | None = None,
                              c02_terminal_bundle_json: str | None = None,
                              c02_terminal_quote_json: str | None = None) -> RuntimeAdmission:
        """Apply D02/D11 decisions in the graph's existing SQLite transaction."""
        from .runtime.issuers import (
            D03_ARRIVAL_WORK_KIND, D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
            D04_BASELINE_WORK_KIND, D06_FIRST_INGRESS_C02_WORK_KIND,
        )

        if self.__d02_issuer is None or self.__d11_issuer is None:
            raise UnavailableGuard("D02 and D11 runtime issuers are required")
        time_kwargs = {} if now_utc is None else {"now_utc": now_utc}
        if self.__d02_issuer.authorize_resources(
                bundle, db, **time_kwargs) is not True:
            raise AuthorityDenied("D02 resource admission did not approve the bundle")
        qualified_quote = getattr(self.__d02_issuer, "qualified_quote", None)
        if require_arrival_quote and not callable(qualified_quote):
            raise AuthorityDenied("D03 arrival requires a qualified resource quote")
        quote = (qualified_quote(bundle.envelope, db, **time_kwargs)
                 if callable(qualified_quote) else None)
        if require_arrival_quote and (quote is None or
                                      quote.work_kind != D03_ARRIVAL_WORK_KIND):
            raise AuthorityDenied("D03 arrival requires its signed resource quote")
        if quote is not None and quote.work_kind == D03_ARRIVAL_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d03_arrival_issuance_v2'",
            ).fetchone() is None:
                raise AuthorityDenied("D03 arrival quote lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,quote_id,bundle_digest FROM "
                "graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            source_refs = bundle.envelope.source_qualification.source_refs
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d03"
                    or len(source_refs) != 1
                    or row != (AtomKey.from_token(source_refs[0]).owner.subject,
                               quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D03 arrival quote cannot authorize a mixed bundle")
        if quote is not None and quote.work_kind == "d07.attention":
            row = db.execute(
                "SELECT c02_operation_id,source_ref,quote_id,bundle_digest "
                "FROM graph_d07_attention_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone() if db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d07_attention_issuance_v1'",
            ).fetchone() else None
            if (row != (
                    bundle.envelope.causation[0],
                    bundle.envelope.source_qualification.source_refs[0],
                    quote.quote_id, bundle.digest)
                    or len(bundle.proposals) != 1
                    or bundle.proposals[0].domain != "d07"
                    or {write.key.type_name for write in
                        bundle.proposals[0].typed_writes} != {
                            "d07.attention_ticket.v1", "d07.focus.v1"}
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs
                    or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D07 attention quote lacks sealed issuance")
        if quote is not None and quote.work_kind == D04_BASELINE_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is None:
                raise AuthorityDenied("D04 baseline quote lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,event_ref,quote_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d04"
                    or len(bundle.proposals[0].typed_writes) != 1
                    or bundle.proposals[0].typed_writes[0].key.type_name
                    != "d04.encoding_baseline.v1"
                    or row != (*bundle.envelope.input_refs, quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D04 baseline quote cannot authorize a mixed bundle")
        if quote is not None and quote.work_kind == D03_SELF_IDENTITY_PROJECTION_WORK_KIND:
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_d03_self_projection_issuance_v1'",
            ).fetchone() is None:
                raise AuthorityDenied("D03 self projection lacks sealed graph issuance")
            row = db.execute(
                "SELECT source_ref,certification_ref,quote_id,bundle_digest "
                "FROM graph_d03_self_projection_issuance_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                bundle.envelope.authority.namespace.as_tuple
                + (bundle.envelope.identity.operation_id,),
            ).fetchone()
            if (len(bundle.proposals) != 1 or bundle.proposals[0].domain != "d03"
                    or not bundle.proposals[0].typed_writes
                    or bundle.proposals[0].typed_writes[-1].key.type_name
                    != "d03.self_perspective.v1"
                    or len(bundle.envelope.input_refs) != 1
                    or row is None
                    or row[0] != bundle.envelope.input_refs[0]
                    or row[2:] != (quote.quote_id, bundle.digest)
                    or bundle.persistent_job_refs or bundle.outbox_refs
                    or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                raise AuthorityDenied("D03 self projection quote cannot authorize a mixed bundle")
        if c02_terminal_recovery is None:
            admission = self.__d11_issuer.admit_runtime(bundle, db, **time_kwargs)
        else:
            admission = self.__d11_issuer.admit_terminal_d06_first_ingress_c02_v2(
                db, bundle, seal=c02_terminal_recovery.seal,
                bundle_json=c02_terminal_bundle_json,
                quote_json=c02_terminal_quote_json, now_utc=now_utc)
        if not isinstance(admission, RuntimeAdmission):
            raise AuthorityDenied("D11 did not issue a typed runtime admission")
        envelope = bundle.envelope
        identity = envelope.identity
        budget = admission.budget
        if not isinstance(budget, BudgetAdmission):
            raise AuthorityDenied("D11 budget admission is missing")
        if budget.lease_id != envelope.parent_budget_lease_ref:
            raise AuthorityDenied("D11 budget lease differs from the command parent")
        lease = get_budget_lease(db, budget.lease_id)
        if (lease.state != "active" or
                (lease.bot_id, lease.persona_id) != envelope.authority.namespace.as_tuple
                or type(budget.expected_version) is not int
                or budget.expected_version != lease.version):
            raise StaleRead("D11 budget admission has stale lease version")
        budget_operation_id = budget.reservation_operation_id or identity.operation_id
        budget_digest = budget_operation_digest(envelope, budget.lease_id,
                                                budget.ceiling)
        if budget.pre_reserved:
            row = db.execute(
                "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
                "WHERE lease_id=? AND operation_id=?",
                (budget.lease_id, budget_operation_id),
            ).fetchone()
            if (row is None or row[0] != budget_digest
                    or json.loads(row[1]) != budget.ceiling
                    or row[2] not in {"reserved", "unknown"}):
                raise UnavailableGuard("matching durable budget reservation is absent")
        else:
            if budget.reservation_operation_id is not None:
                raise AuthorityDenied("inline reserve must use the bundle operation ID")
            reserve_budget(db, budget.lease_id, budget_operation_id,
                           budget_digest, budget.ceiling)
        if budget.settle_now:
            if len(bundle.d11_cost_settlement_refs) != 1:
                raise AuthorityDenied("settlement requires one D11 graph cost receipt")
            cost_receipt = settle_budget(db, budget.lease_id, budget_operation_id,
                                         budget_digest, budget.actual,
                                         execution_revoked=budget.execution_revoked)
            self._verify_cost_atom(db, bundle, lease, budget, budget_operation_id,
                                   cost_receipt)
        elif bundle.d11_cost_settlement_refs:
            raise AuthorityDenied("D11 graph cost receipt lacks budget settlement")
        jobs = admission.jobs
        if (not isinstance(jobs, tuple) or
                any(not isinstance(binding, JobBinding) for binding in jobs)):
            raise AuthorityDenied("D11 job bindings must be typed")
        if (len({item.graph_job_ref for item in jobs}) != len(jobs)
                or {item.graph_job_ref for item in jobs}
                != set(bundle.persistent_job_refs)):
            raise AuthorityDenied("durable jobs do not match graph job refs")
        outbox_refs = tuple(ref for item in jobs for ref in item.outbox_refs)
        if len(set(outbox_refs)) != len(outbox_refs) or set(outbox_refs) != set(bundle.outbox_refs):
            raise AuthorityDenied("outbox refs lack a unique durable job binding")
        for binding in jobs:
            job = binding.job
            if (job.operation_id != identity.operation_id
                    or job.activity_id != identity.activity_id
                    or job.effect_id != identity.effect_id
                    or (job.bot_id, job.persona_id) != envelope.authority.namespace.as_tuple
                    or job.budget_ref != budget.lease_id):
                raise AuthorityDenied("D11 durable job identity differs from bundle")
            if budget.pre_reserved:
                existing = get_job(db, job.job_id)
                if (existing.operation_id != job.operation_id
                        or existing.activity_id != job.activity_id
                        or existing.budget_ref != job.budget_ref
                        or (existing.bot_id, existing.persona_id)
                        != (job.bot_id, job.persona_id)
                        or existing.phase in {"draining", "cancelled", "failed"}):
                    raise UnavailableGuard("pre-reserved job is stale or cancelled")
            else:
                if job.phase not in {"queued", "waiting"}:
                    raise AuthorityDenied("new durable job must start queued or waiting")
                job_operation = "job:" + hashlib.sha256(
                    (bundle.digest + job.job_id).encode("utf-8")).hexdigest()[:32]
                create_job(db, job, job_operation, bundle.digest)
                existing = job
            if envelope.authority.worker_fence is not None and (
                    existing.phase != "running"
                    or existing.lease_holder != envelope.authority.actor
                    or existing.fence != envelope.authority.worker_fence
                    or existing.cancel_epoch != 0):
                raise UnavailableGuard("worker result lost its job fence")
        if (envelope.authority.worker_fence is not None and not jobs
                and (quote is None or quote.work_kind !=
                     D06_FIRST_INGRESS_C02_WORK_KIND)):
            raise UnavailableGuard("worker result has no durable job to fence")
        return admission

    @staticmethod
    def _verify_cost_atom(db, bundle, lease, budget, operation_id, receipt):
        """The graph cost atom must agree with the committed budget receipt."""
        ref = bundle.d11_cost_settlement_refs[0]
        writes = (write for proposal in bundle.proposals
                  for write in proposal.typed_writes)
        value = next((write.value for write in writes if write.key.token == ref), None)
        if not isinstance(value, dict):
            raise AuthorityDenied("D11 cost graph atom is missing")
        row = db.execute(
            "SELECT receipt_json FROM runtime_budget_operations WHERE bot_id=? "
            "AND persona_id=? AND operation_id=? AND phase='settle'",
            (lease.bot_id, lease.persona_id, operation_id),
        ).fetchone()
        if row is None:
            raise UnavailableGuard("D11 budget settlement receipt is missing")
        receipt_digest = hashlib.sha256(row[0].encode("utf-8")).hexdigest()
        identity = bundle.envelope.identity
        expected = {
            "bot_id": lease.bot_id, "persona_id": lease.persona_id,
            "activity_id": identity.activity_id,
            "bundle_operation_id": identity.operation_id,
            "effect_id": identity.effect_id,
            "lease_id": lease.lease_id, "currency": lease.currency,
            "cost_operation_id": operation_id,
            "status": receipt.status, "ceiling": budget.ceiling,
            "actual": budget.actual,
            "unconfirmed": budget.ceiling if budget.actual is None else {},
            "budget_phase": "settle", "budget_operation_id": operation_id,
            "budget_receipt_digest": receipt_digest,
        }
        if any(value.get(key) != item for key, item in expected.items()):
            raise AuthorityDenied("D11 cost graph atom differs from budget settlement")

    @staticmethod
    def _deletion_epochs_locked(db, namespace: NamespaceId) -> tuple[int, int]:
        row = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple).fetchone()
        if row is None or row[0] < 1 or row[1] < 0:
            raise UnavailableGuard("deletion access/delete epochs are unavailable")
        return row[0], row[1]

    def read_deletion_snapshot_candidate(
            self, authority: AuthorityContext, lease: object,
            keys: tuple[AtomKey, ...], *, page_limit: int = 128,
            max_pages: int = 16) -> DeletionSnapshotCandidate:
        """Collect bounded namespace history under one v2 Authority read fence.

        The caller supplies no cursor or completion flag. A partial result is
        evidence for more work only; deletion still needs independent admission.
        """
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("v2 deletion read fence is unavailable")
        if (lease not in self.__deletion_read_leases
                or authority.issuer_domain != "d06"
                or authority.purpose != "deletion_cleanup"
                or authority.audience != ("internal",)
                or authority.provider_policy_ref != "d06-deletion-closure-v1"
                or authority.activation_generation != self.__leases[lease][6]):
            raise AuthorityDenied("host-minted deletion read lease required")
        keys = tuple(keys)
        if not keys or len(keys) > 512 or len(set(keys)) != len(keys):
            raise ValueError("deletion read requires 1 to 512 unique keys")
        if (type(page_limit) is not int or not 1 <= page_limit <= 512
                or type(max_pages) is not int or not 1 <= max_pages <= 32):
            raise ValueError("deletion history page bounds are invalid")
        if any(not isinstance(key, AtomKey)
               or NamespaceId.from_key(key) != authority.namespace
               for key in keys):
            raise AuthorityDenied("deletion key crosses namespace")
        specs = self.__store._registry.specs
        if not specs or any(spec.writer_domain is None for spec in specs):
            raise UnavailableGuard("deletion read requires complete type ownership")
        domains = frozenset(spec.writer_domain for spec in specs)
        owner_kinds = frozenset(kind for spec in specs for kind in spec.owner_kinds)
        if not owner_kinds.issubset(authority.owner_scope):
            raise AuthorityDenied("deletion read owner scope is incomplete")
        self._authorize(lease, authority, domains, owner_read=True)

        store = self.__store
        namespace = authority.namespace
        candidate_sql = (
            "SELECT c.operation_id,c.schema,c.bundle_digest,c.fence_attempt_id,"
            "c.bundle_json,c.evidence_json,i.digest,i.fence_attempt_id,"
            "o.operation_id,r.operation_id "
            "FROM graph_first_ingress_c02_candidates_v1 c "
            "LEFT JOIN graph_bundle_intents_v2 i ON i.bot=c.bot "
            "AND i.persona=c.persona AND i.operation_id=c.operation_id "
            "LEFT JOIN graph_bundle_operations o ON o.bot=c.bot "
            "AND o.persona=c.persona AND o.operation_id=c.operation_id "
            "LEFT JOIN graph_bundle_rejections_v2 r ON r.bot=c.bot "
            "AND r.persona=c.persona AND r.operation_id=c.operation_id "
            "WHERE c.bot=? AND c.persona=? ORDER BY c.operation_id LIMIT ?"
        )
        candidate_args = namespace.as_tuple + (page_limit * max_pages + 1,)
        candidate_rows_at_read = None

        def reader():
            nonlocal candidate_rows_at_read
            from .runtime.c02_bundle_codec import c02_bundle_from_wire

            access_epoch, delete_epoch = self._deletion_epochs_locked(
                store._db, namespace)
            candidate_rows = store._db.execute(
                candidate_sql, candidate_args).fetchall()
            candidate_rows_at_read = candidate_rows
            if len(candidate_rows) > page_limit * max_pages:
                raise UnavailableGuard("pending C02 inventory exceeds read bounds; HOLD")
            pending_c02_sources = []
            for (operation_id, schema, digest, attempt_id, bundle_json,
                 evidence_json, intent_digest, intent_attempt, committed,
                 rejected) in candidate_rows:
                try:
                    bundle = c02_bundle_from_wire(bundle_json)
                    evidence = json.loads(evidence_json)
                    source = AtomKey.from_token(bundle.envelope.input_refs[0])
                    d06_writes = bundle.proposals[0].typed_writes
                    if (type(operation_id) is not str or not operation_id
                            or schema != "sylanne.first-ingress-c02-candidate.v1"
                            or digest != intent_digest or digest != bundle.digest
                            or attempt_id != intent_attempt
                            or committed is not None or rejected is not None
                            or bundle.envelope.identity.operation_id != operation_id
                            or bundle.envelope.authority.namespace != namespace
                            or len(bundle.envelope.input_refs) != 3
                            or bundle.envelope.source_qualification.source_refs
                            != (source.token,)
                            or len(d06_writes) != 2
                            or d06_writes[0].key.type_name != "memory.episode.v1"
                            or d06_writes[1].key.type_name != "memory.subjective_trace.v2"
                            or NamespaceId.from_key(d06_writes[0].key) != namespace
                            or NamespaceId.from_key(d06_writes[1].key) != namespace
                            or d06_writes[0].value.get("source_refs") != [source.token]
                            or d06_writes[1].value.get("episode_ref")
                            != d06_writes[0].key.token
                            or source.type_name != "memory.source"
                            or source.owner.kind != "event" or source.name != "record"
                            or NamespaceId.from_key(source) != namespace
                            or type(evidence) is not dict
                            or type(evidence.get("source_ref")) is not str
                            or evidence["source_ref"] != source.owner.subject
                            or canonical_json(evidence) != evidence_json):
                        raise ValueError("pending C02 source identity differs")
                except (ValueError, TypeError, KeyError, IndexError) as exc:
                    raise UnavailableGuard("pending C02 source is unreadable; HOLD") from exc
                pending_c02_sources.append((operation_id, source.token))
            cursor = None
            epoch = None
            first = None
            rows = {}
            edges = []
            pages_scanned = 0
            complete = False
            for _ in range(max_pages):
                page = GraphStore._deletion_snapshot_page(
                    store, namespace, keys, after=cursor, expected_epoch=epoch,
                    limit=page_limit, _capability=self.__graph_capability)
                pages_scanned += 1
                if first is None:
                    first = page
                    epoch = page.epoch
                for row in page.history_rows:
                    rows.setdefault((row.atom.key, row.atom.revision), row)
                edges.extend(page.history_edges)
                complete = page.complete
                if complete:
                    break
                cursor = page.next_after
            if (access_epoch, delete_epoch) != self._deletion_epochs_locked(
                    store._db, namespace):
                raise UnavailableGuard("deletion access/delete epochs changed during read")
            return DeletionSnapshotCandidate(
                first.snapshot, first.read_set, first.current_reverse_edges,
                tuple(rows.values()), tuple(edges), access_epoch, delete_epoch,
                complete, pages_scanned, tuple(pending_c02_sources))

        def final_check(candidate):
            if (candidate.access_epoch, candidate.delete_epoch) != (
                    self._deletion_epochs_locked(store._db, namespace)):
                raise UnavailableGuard("deletion access/delete epochs changed during read")
            if store._db.execute(candidate_sql, candidate_args).fetchall() != candidate_rows_at_read:
                raise UnavailableGuard("pending C02 inventory changed during read; HOLD")

        return self._read_v2(authority, reader, final_check=final_check)

    def read_snapshot(self, authority: AuthorityContext, lease: object,
                      keys) -> GraphSnapshot:
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        keys = tuple(keys)
        if not keys:
            raise ValueError("read_snapshot requires explicit keys")
        if any(NamespaceId.from_key(key) != authority.namespace
               or key.owner.kind not in authority.owner_scope for key in keys):
            raise AuthorityDenied("read key is outside authorized namespace or owner scope")
        domains = frozenset(self.__store._registry.spec(key.type_name).writer_domain
                            for key in keys)
        self._authorize(lease, authority, domains, owner_read=True)
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: GraphStore.graph_snapshot(
                self.__store, keys, _capability=self.__graph_capability),
                owner_binding=self.__owner_leases.get(lease),
                owner_session_proof=self.__owner_session_proofs.get(lease))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            store = self.__store
            with store._lock:
                self._admit_content(authority.namespace, authority.activation_generation,
                                    "read", tuple(key.token for key in keys))
                return GraphStore.graph_snapshot(
                    store, keys, _capability=self.__graph_capability)

    def project_workbench_snapshot_v1(
            self, authority: AuthorityContext, lease: object, *,
            view_registry: object, view_type: str, audience: str,
            purpose: str) -> WorkbenchProjectionSnapshotV1:
        """Read and project one complete D12 view inside one v2 read fence.

        Raw atoms remain inside the coordinator callback. Internal pages are
        pinned to one namespace epoch, and only the registry-validated field
        projection is returned to the D12 issuer.
        """
        from .workbench_api.domain_registry import (
            CurrentDomainViewRegistry, PROJECTION_CONTEXT_V2,
        )

        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if (authority.issuer_domain != "d12"
                or type(view_registry) is not CurrentDomainViewRegistry
                or not isinstance(view_type, str) or not view_type
                or not isinstance(audience, str) or audience not in authority.audience
                or purpose != authority.purpose):
            raise AuthorityDenied("complete D12 projection authority required")
        if (not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None):
            raise UnavailableGuard("complete workbench snapshot requires v2 read fence")
        try:
            types = view_registry.view_types(authority).get(view_type)
            owner_kind = view_registry.view_owner_kind(authority, view_type)
            context_version = view_registry.projection_context_version(authority, view_type)
        except Exception as exc:
            raise UnavailableGuard("complete workbench view is unavailable") from exc
        if (not isinstance(types, tuple) or not types or owner_kind not in authority.owner_scope
                or context_version != PROJECTION_CONTEXT_V2):
            raise AuthorityDenied("view does not require complete fenced projection")
        if (len(set(types)) != len(types)
                or any(not isinstance(name, str) or not name for name in types)):
            raise AuthorityDenied("view has invalid graph type scope")
        specs = tuple(self.__store._registry.spec(name) for name in types)
        if any(owner_kind not in spec.owner_kinds or not spec.writer_domain for spec in specs):
            raise AuthorityDenied("view type ownership is incomplete")
        domains = frozenset(spec.writer_domain for spec in specs)
        self._authorize(lease, authority, domains, owner_read=True)

        store = self.__store

        def read_and_project():
            page_after = None
            expected_epoch = None
            atoms = []
            while True:
                page = GraphStore.graph_query(
                    store, *authority.namespace.as_tuple, type_names=types,
                    owner_kind=owner_kind, after=page_after,
                    expected_epoch=expected_epoch, limit=512,
                    _capability=self.__graph_capability,
                )
                if not isinstance(page, GraphPage) or len(page.snapshot.epochs) != 1:
                    raise UnavailableGuard("complete workbench page is invalid")
                epoch = page.snapshot.epochs[0]
                if ((epoch.bot, epoch.persona) != authority.namespace.as_tuple
                        or (expected_epoch is not None and epoch != expected_epoch)):
                    raise StaleRead("complete workbench snapshot changed between pages")
                if expected_epoch is None:
                    expected_epoch = epoch
                previous_token = page_after.token if page_after is not None else None
                for atom in page.snapshot.atoms:
                    if (atom.key.owner.kind != owner_kind
                            or (atom.key.owner.bot, atom.key.owner.persona)
                            != authority.namespace.as_tuple
                            or atom.key.type_name not in types
                            or (previous_token is not None and atom.key.token <= previous_token)):
                        raise UnavailableGuard("complete workbench atoms are invalid")
                    atoms.append({
                        "key": atom.key.token, "type": atom.key.type_name,
                        "name": atom.key.name, "revision": atom.revision,
                        "value": atom.value,
                    })
                    previous_token = atom.key.token
                if page.next_after is None:
                    break
                if (not page.snapshot.atoms
                        or page.next_after != page.snapshot.atoms[-1].key
                        or page.next_after == page_after):
                    raise UnavailableGuard("complete workbench continuation is invalid")
                page_after = page.next_after

            proof = CompleteProjectionSnapshotV1(
                authority.namespace, expected_epoch, authority.activation_generation,
                view_type, types, owner_kind, audience, purpose,
                _seal=_COMPLETE_PROJECTION_SEAL,
            )
            projection = view_registry.project_workbench(
                authority, view_type, tuple(atoms), audience=audience,
                purpose=purpose, snapshot_proof=proof,
            )
            return WorkbenchProjectionSnapshotV1(authority.namespace, projection)

        return self._read_v2(
            authority, read_and_project,
            owner_binding=self.__owner_leases.get(lease),
            owner_session_proof=self.__owner_session_proofs.get(lease),
        )

    def query(self, authority: AuthorityContext, lease: object, *,
              type_names: tuple[str, ...], owner_kind: str, **filters):
        if not isinstance(authority, AuthorityContext):
            raise TypeError("authority required")
        if not type_names or owner_kind not in authority.owner_scope:
            raise AuthorityDenied("query must select authorized types and owner kind")
        if filters.get("include_invalid"):
            raise AuthorityDenied("ordinary content query cannot include invalid atoms")
        domains = frozenset(self.__store._registry.spec(name).writer_domain
                            for name in type_names)
        self._authorize(lease, authority, domains, owner_read=True)
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: GraphStore.graph_query(
                self.__store, *authority.namespace.as_tuple, type_names=type_names,
                owner_kind=owner_kind, _capability=self.__graph_capability, **filters),
                owner_binding=self.__owner_leases.get(lease),
                owner_session_proof=self.__owner_session_proofs.get(lease))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            store = self.__store
            with store._lock:
                # A range query has no finite content reference set. After any
                # deletion it remains closed until a D06 range-closure proof exists.
                self._admit_content(authority.namespace, authority.activation_generation,
                                    "read")
                return GraphStore.graph_query(
                    store, *authority.namespace.as_tuple, type_names=type_names,
                    owner_kind=owner_kind, _capability=self.__graph_capability, **filters)

    def get_operation(self, authority: AuthorityContext, lease: object,
                      operation_id: str) -> CommitReceipt | None:
        """Resolve an uncertain commit from the durable business operation ledger."""
        if not isinstance(authority, AuthorityContext) or not operation_id:
            raise ValueError("valid authority and operation ID are required")
        self._authorize(lease, authority, frozenset())
        if isinstance(self.__store, ProductionGraphStore) and self.__content_fence_v2 is not None:
            return self._read_v2(authority, lambda: self._get_operation_fenced(
                authority, operation_id, v2=True))
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            return self._get_operation_fenced(authority, operation_id)

    def get_dispatch_candidate_evidence(self, authority: AuthorityContext,
                                        lease: object, operation_id: str):
        """Rebuild a source-HOLD candidate from committed historical graph atoms."""
        if not isinstance(authority, AuthorityContext) or not operation_id:
            raise ValueError("authority and operation ID are required")
        self._authorize(lease, authority, frozenset({"d08", "d09"}))
        reader = lambda: self._get_dispatch_candidate_evidence_locked(
            authority.namespace, operation_id)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace, authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def _get_dispatch_candidate_evidence_locked(self, namespace, operation_id):
        from .domains.d08 import GoalExecutionProvider
        from .graph_types import AtomKey, GraphWrite

        store = self.__store
        db = store._db
        row = db.execute(
            "SELECT activity_id,effect_id,receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (operation_id,),
        ).fetchone()
        if row is None:
            return None
        data = json.loads(row[2]).get("dispatch_candidate")
        if data is None:
            return None
        if (type(data) is not dict or data.get("schema") != "sylanne.d11.dispatch_candidate.v1"
                or data.get("status") not in {"source_hold", "source_qualified"}
                or type(data.get("refs")) is not list or len(data["refs"]) != 4):
            raise UnavailableGuard("durable dispatch candidate receipt is invalid")
        event = db.execute(
            "SELECT revisions,epoch_revision,reads FROM graph_events WHERE bot=? "
            "AND persona=? AND session=? AND event_id=?",
            namespace.as_tuple + (row[0], operation_id),
        ).fetchone()
        if event is None or event[1] != data.get("graph_epoch"):
            raise UnavailableGuard("dispatch candidate graph event is missing")
        revisions = {item.key.token: item.revision
                     for item in GraphStore._version_rows(event[0])}
        typed_writes = []
        for position, item in enumerate(data["refs"]):
            if (type(item) is not list or len(item) != 2
                    or type(item[0]) is not str or type(item[1]) is not int
                    or item[1] < 1 or revisions.get(item[0]) != item[1]):
                raise UnavailableGuard("dispatch candidate write version differs")
            key = AtomKey.from_token(item[0])
            expected_type = (
                "d08.action_intent.v1", "d08.action_schema.v1",
                "d08.communication_intent_grant.v1", "d09.verified_segment_batch.v1",
            )[position]
            if key.type_name != expected_type:
                raise UnavailableGuard("dispatch candidate graph type differs")
            history = db.execute(
                "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
                "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
                (item[0], item[1]) + namespace.as_tuple + (row[0], operation_id),
            ).fetchone()
            if history is None or history[1] != 1:
                raise UnavailableGuard("dispatch candidate history is unavailable")
            typed_writes.append(("d09" if position == 3 else "d08",
                                 GraphWrite(key, json.loads(history[0]))))
        action = next(spec for spec in GoalExecutionProvider().register_types()
                      if spec.name == "d08.action_intent.v1").validator(
                          typed_writes[0][1].value)
        if (action.identity.operation_id != operation_id
                or action.identity.activity_id != row[0]
                or action.identity.effect_id != row[1]):
            raise UnavailableGuard("dispatch candidate operation identity differs")
        candidate = validate_dispatch_candidate_writes(
            tuple(typed_writes), namespace=namespace, identity=action.identity,
            read_versions=GraphStore._version_rows(event[2]),
            source_refs=tuple(data.get("source_refs", ())),
            access_epoch=data.get("access_epoch"),
            delete_epoch=data.get("delete_epoch"),
            query_epoch=data.get("query_epoch"),
        )
        if candidate is not None and data["status"] == "source_qualified":
            read_versions = GraphStore._version_rows(event[2])
            if (data.get("graph_epoch") != candidate.query_epoch + 1
                    or type(data.get("source_audience")) is not list
                    or type(data.get("source_proof_versions")) is not list):
                raise UnavailableGuard("dispatch source proof graph epoch differs")
            atoms = []
            for read in read_versions:
                if read.revision == 0:
                    atoms.append(GraphAtom(read.key, 0, {}, False))
                    continue
                history = db.execute(
                    "SELECT value,valid FROM graph_history WHERE token=? AND revision=?",
                    (read.key.token, read.revision),
                ).fetchone()
                if history is None:
                    raise UnavailableGuard("dispatch source proof history is unavailable")
                atoms.append(GraphAtom(read.key, read.revision, json.loads(history[0]),
                                       bool(history[1])))
            candidate = qualify_dispatch_candidate_sources(
                candidate, action, GraphSnapshot(tuple(atoms), (
                    NamespaceEpoch(*namespace.as_tuple, candidate.query_epoch),)),
                audience=tuple(data["source_audience"]),
                batch_audiences=tuple(typed_writes[3][1].value["audiences"]),
                current_barrier_confirmed=True,
                valid_until=typed_writes[3][1].value["valid_until"],
            )
            if (candidate.status != "source_qualified"
                    or [list(item) for item in candidate.source_proof_versions]
                    != data["source_proof_versions"]
                    or candidate.source_proof_digest != data.get("source_proof_digest")):
                raise UnavailableGuard("dispatch source proof differs from graph history")
        if candidate is None or candidate.digest != data.get("digest"):
            raise UnavailableGuard("dispatch candidate digest differs")
        if isinstance(store, ProductionGraphStore):
            metadata = self._v2_graph_stamp(namespace)[0]
            if (data.get("graph_incarnation") != metadata.requirements.graph_incarnation
                    or type(data.get("graph_revision")) is not int
                    or data["graph_revision"] > metadata.graph_revision):
                raise UnavailableGuard("dispatch candidate recovery stamp differs")
        return DispatchCandidateRecoveryV1(
            candidate, tuple((ref, revision) for ref, revision in data["refs"]),
            data["graph_epoch"], data["graph_incarnation"], data["graph_revision"],
        )

    def _get_operation_fenced(self, authority: AuthorityContext,
                              operation_id: str, *, v2: bool = False) -> CommitReceipt | None:
        namespace = authority.namespace
        store = self.__store
        with store._lock:
            store._ensure_open()
            if not v2:
                self._admit_content(namespace, authority.activation_generation, "read")
                if self._version(store._db, namespace, "activation", "current") != str(
                        authority.activation_generation):
                    raise StaleRead("activation generation changed")
            row = store._db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            graph = store._db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events WHERE bot=? "
                "AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
            if graph is None:
                raise EventConflict("bundle operation has no graph event")
            data = json.loads(row[4])
            return CommitReceipt(
                "committed", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]), GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )

    def _check_product_advance(self, db, bundle: DomainBundle,
                               snapshot: GraphSnapshot, writes: tuple) -> dict | None:
        """Bind an advance to current D04 state before any business write."""
        if not isinstance(self.__store, ProductionGraphStore):
            if bundle.product_advance is not None:
                raise UnavailableGuard("product advance evidence requires production graph authority")
            return None
        state_items = tuple(write for write in writes if write.key.type_name in {
            "d04.feeling_state.v1", "d04.mood_field.v1"})
        state_writes = {write.key.type_name: write for write in state_items}
        if len(state_writes) != len(state_items):
            raise AuthorityDenied("multiple D04 state writes of the same type")
        advance = False
        for write in state_writes.values():
            current = snapshot.get(write.key)
            if current is None:
                raise StaleRead("D04 write key is absent from the complete read set")
            if current.revision == 0:
                raise UnavailableGuard(
                    "initial D04 state needs an authenticated authored root; HOLD")
            if not current.valid:
                raise StaleRead("D04 state is invalid")
            old, new = current.value, write.value
            if new["revision"] != old["revision"] + 1:
                raise StaleRead("D04 state revision is not the next revision")
            if new["cursor"] < old["cursor"]:
                raise StaleRead("D04 state cursor moved backwards")
            if new["cursor"] == old["cursor"]:
                semantic_fields = ({"meaning_refs", "interpretation_refs",
                                    "active_driver_refs", "historical_source_refs", "revision"}
                                   if write.key.type_name == "d04.feeling_state.v1"
                                   else {"source_refs", "revision"})
                if any(new.get(name) != old.get(name)
                       for name in set(old) | set(new) if name not in semantic_fields):
                    raise AuthorityDenied("same-cursor D04 correction changed numerical state")
            else:
                advance = True
        evidence = bundle.product_advance
        if not advance:
            if evidence is not None:
                raise AuthorityDenied("product advance evidence has no existing interval to advance")
            if bundle.envelope.identity.phase == "d11.product_advance_candidate.v1":
                raise AuthorityDenied("product advance phase has no numerical interval")
            return None
        if evidence is None:
            raise UnavailableGuard("D04 time advance requires product numeric evidence")
        if (type(evidence) is not ProductAdvanceEvidenceV1
                or bundle.envelope.identity.phase != "d11.product_advance_candidate.v1"
                or set(state_writes) != {"d04.feeling_state.v1", "d04.mood_field.v1"}):
            raise AuthorityDenied("product advance requires one feeling and one mood write")
        feeling = state_writes["d04.feeling_state.v1"]
        mood = state_writes["d04.mood_field.v1"]
        if (feeling.key.token != evidence.feeling_ref
                or mood.key.token != evidence.mood_ref):
            raise AuthorityDenied("product advance refs differ from D04 writes")
        old_feeling, old_mood = snapshot.get(feeling.key), snapshot.get(mood.key)
        if (old_feeling is None or old_mood is None
                or not old_feeling.valid or not old_mood.valid
                or old_feeling.revision == 0 or old_mood.revision == 0
                or old_feeling.value["cursor"] != evidence.from_cursor
                or old_mood.value["cursor"] != evidence.from_cursor
                or feeling.value["cursor"] != evidence.to_cursor
                or mood.value["cursor"] != evidence.to_cursor
                or feeling.value["process_id"] != old_feeling.value["process_id"]
                or mood.value["mood_id"] != old_mood.value["mood_id"]):
            raise StaleRead("product advance does not follow the current joint state")
        candidate_digest = canonical_digest({
            "schema": "sylanne.d04.product.advance.candidate.v1",
            "feeling": {"ref": feeling.key.token, "value": feeling.value},
            "mood": {"ref": mood.key.token, "value": mood.value},
        })
        if evidence.candidate_digest != candidate_digest:
            raise AuthorityDenied("product evidence does not bind the exact D04 writes")
        namespace = bundle.envelope.authority.namespace
        parent = db.execute(
            "SELECT process_id,feeling_ref,mood_ref,to_cursor,next_error_bound "
            "FROM graph_product_advances WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (evidence.parent_operation_id,),
        ).fetchone()
        if (parent is None or parent[0] != old_feeling.value["process_id"]
                or (parent[1], parent[2]) != (evidence.feeling_ref, evidence.mood_ref)
                or parent[3] != evidence.from_cursor
                or parent[4] != evidence.previous_error_bound):
            raise StaleRead("product advance has no matching committed error predecessor")
        parent_event = db.execute(
            "SELECT e.revisions FROM graph_events e JOIN graph_bundle_operations b "
            "ON b.bot=e.bot AND b.persona=e.persona AND b.activity_id=e.session "
            "AND b.operation_id=e.event_id WHERE b.bot=? AND b.persona=? "
            "AND b.operation_id=?", namespace.as_tuple + (evidence.parent_operation_id,),
        ).fetchone()
        if parent_event is None:
            raise StaleRead("product advance parent graph receipt is missing")
        parent_versions = dict(json.loads(parent_event[0]))
        if (parent_versions.get(evidence.feeling_ref) != old_feeling.revision
                or parent_versions.get(evidence.mood_ref) != old_mood.revision):
            raise StaleRead("product advance parent is not the current joint state")
        conflict = db.execute(
            "SELECT 1 FROM graph_product_advances WHERE bot=? AND persona=? "
            "AND process_id=? AND (replay_key=? OR "
            "(from_cursor<? AND to_cursor>?)) LIMIT 1",
            namespace.as_tuple + (old_feeling.value["process_id"], evidence.replay_key,
                                  evidence.to_cursor, evidence.from_cursor),
        ).fetchone()
        if conflict is not None:
            raise EventConflict("product advance replay or interval already committed")
        issuer = self.__product_advance_issuer
        if issuer is None:
            raise UnavailableGuard("trusted product numeric issuer is unavailable")
        # Future issuer verification must be a local, pure check; FFI runs outside
        # this transaction and binds the complete joint input/output digests.
        if issuer.verify(evidence, bundle) is not True:
            raise AuthorityDenied("product numeric issuer did not verify evidence")
        return {**asdict(evidence), "process_id": old_feeling.value["process_id"]}

    def get_dispatch_admission(self, authority: AuthorityContext, lease: object,
                               admission_ref: str) -> DispatchAdmissionReceiptV1 | None:
        """Read a committed D11 admission identity through the normal content fence."""
        self._authorize(lease, authority, frozenset({"d11"}))
        reader = lambda: load_admission(
            self.__store._db, authority.namespace, admission_ref)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_committed_dispatch_action_job_binding(
            self, authority: AuthorityContext, lease: object,
            admission_ref: str):
        """Read an admission's historical D08/D11 job identity, never send authority."""
        from .runtime.dispatch_action_job_binding import load_action_job_binding

        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))

        def reader():
            db = self.__store._db
            binding = load_action_job_binding(db, authority.namespace, admission_ref)
            if binding is None:
                return None
            if self._get_committed_dispatch_request_locked(
                    authority.namespace, admission_ref) is None:
                raise UnavailableGuard("dispatch action/job binding lacks its command")
            row = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=? AND effect_id=?",
                authority.namespace.as_tuple + (
                    binding.operation_id, binding.effect_id),
            ).fetchone()
            recorded = (json.loads(row[0]).get("dispatch_action_job_binding")
                        if row else None)
            if recorded != {
                    "schema": binding.schema, "ref": binding.admission_ref,
                    "digest": binding.digest, "job_id": binding.job_id}:
                raise UnavailableGuard("dispatch action/job binding differs from graph receipt")
            return binding

        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def get_committed_dispatch_request(self, authority: AuthorityContext,
                                       lease: object, admission_ref: str):
        """Recover a historical D11 command, never a current platform send permit."""
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        reader = lambda: self._get_committed_dispatch_request_locked(
            authority.namespace, admission_ref)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def _get_committed_dispatch_request_locked(self, namespace, admission_ref):
        db = self.__store._db
        loaded = load_request(db, namespace, admission_ref)
        if loaded is None:
            return None
        receipt, request = loaded
        admission = receipt.admission
        candidate = self._get_dispatch_candidate_evidence_locked(
            namespace, request.operation_id)
        row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
            namespace.as_tuple + (request.operation_id, request.effect_id),
        ).fetchone()
        graph_admission = json.loads(row[0]).get("dispatch_admission") if row else None
        if (candidate is None or candidate.evidence.status != "source_qualified"
                or graph_admission != {
                    "schema": admission.schema, "ref": admission_ref,
                    "digest": receipt.receipt_digest,
                }
                or admission.candidate_digest != candidate.evidence.digest
                or admission.batch_digest != candidate.evidence.batch_digest
                or receipt.graph_epoch != candidate.graph_epoch
                or receipt.graph_revision != (
                    candidate.graph_revision if candidate.graph_revision is not None
                    else candidate.graph_epoch)
                or admission.graph_incarnation != (
                    candidate.graph_incarnation or "nonproduction-graphstore")
                or request.payload_ref != dispatch_segment_payload_ref(
                    candidate.evidence.batch_ref, request.segment_index)):
            raise UnavailableGuard("stored dispatch request differs from graph receipt")
        batch_ref, batch_revision = candidate.write_versions[3]
        batch_row = db.execute(
            "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
            "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
            (batch_ref, batch_revision) + namespace.as_tuple + (
                request.activity_id, request.operation_id),
        ).fetchone()
        if batch_row is None or batch_row[1] != 1:
            raise UnavailableGuard("stored dispatch request batch is unavailable")
        batch = json.loads(batch_row[0])
        index = request.segment_index
        if (type(index) is not int or not 0 <= index < len(batch["segments"])
                or batch["batch_digest"] != admission.batch_digest
                or batch["segments"][index]["effect_id"] != request.effect_id
                or batch["segments"][index]["payload_digest"] != request.payload_digest
                or batch["segments"][index]["segment_authorization_ref"]
                != request.segment_authorization_ref
                or batch["grant_manifest_digest"] != request.segment_manifest_digest
                or len(batch["segments"]) != request.segment_count):
            raise UnavailableGuard("stored dispatch request segment differs")
        return request

    def _read_dispatch_final_claim_prerequisite_locked(
            self, namespace: NamespaceId, binding, claimed_receipt,
            handoff_id: str, *, now_utc: float):
        """Read durable W01/D11 facts inside the caller's business transaction.

        This returns an explicit HOLD. It cannot be installed as Authority's
        final_handoff_authorizer: no current P2 or complete domain check is
        established here, and it does not write a graph claim or stamp.
        """
        from .authority_service.v2_contract import ExecutionBindingV2
        from .runtime.dispatch_current_source_budget import CurrentDispatchHold
        from .runtime.dispatch_final_claim import read_final_claim_prerequisite

        db = self.__store._db
        if not db.in_transaction:
            raise CurrentDispatchHold("final claim prerequisite needs a held business transaction")
        if type(binding) is not ExecutionBindingV2:
            raise CurrentDispatchHold("final claim prerequisite requires a V2 binding")
        if self._get_committed_dispatch_request_locked(
                namespace, binding.origin.admission_ref) is None:
            raise CurrentDispatchHold("committed graph dispatch command is absent")
        return read_final_claim_prerequisite(
            db, namespace, binding, claimed_receipt, handoff_id,
            now_utc=now_utc,
        )

    def _dispatch_full_graph_snapshot_locked(self, namespace: NamespaceId):
        """Read the complete namespace at one epoch in the final write transaction.

        GraphStore.graph_query starts its own transaction, so it cannot be
        nested in the final BEGIN IMMEDIATE. This reader is intentionally
        private and does not authorize a claim by itself.
        """
        from .runtime_contracts import QueryEpoch

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("final graph snapshot requires held write transaction")
        epoch = GraphStore.graph_epoch(
            store, *namespace.as_tuple, _capability=self.__graph_capability)
        rows = db.execute(
            "SELECT token,revision,value,valid FROM graph_atoms "
            "WHERE bot=? AND persona=? ORDER BY token", namespace.as_tuple,
        ).fetchall()
        atoms = []
        for token, revision, encoded, valid in rows:
            key = AtomKey.from_token(token)
            if (NamespaceId.from_key(key) != namespace
                    or type(revision) is not int or revision < 1
                    or valid not in (0, 1)):
                raise UnavailableGuard("final graph snapshot row is invalid")
            store._validate_key(key)
            atoms.append(GraphAtom(key, revision, json.loads(encoded), bool(valid)))
        count = db.execute(
            "SELECT COUNT(*) FROM graph_atoms WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()[0]
        if count != len(atoms):
            raise StaleRead("final graph snapshot coverage changed")
        return GraphSnapshot(tuple(atoms), (epoch,)), QueryEpoch(
            namespace, "all", epoch.revision)

    def _verify_dispatch_owner_graph_locked(
            self, namespace, witness, admission, graph_epoch):
        """Join the current Owner head to its durable graph issue proof."""
        from .authority_service.v2_owner_contract import (
            OwnerGraphCommitProofV1, canonical_digest as owner_digest,
        )

        db = self.__store._db
        metadata, epoch = self._v2_graph_stamp(namespace)
        grant_row = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (owner_grant_key(*namespace.as_tuple).token,),
        ).fetchone()
        proof_row = db.execute(
            "SELECT operation_id,request_digest,grant_id,grant_digest,"
            "graph_incarnation,graph_access_epoch,graph_epoch,"
            "graph_receipt_digest,proof_json "
            "FROM graph_owner_issue_operations_v1 WHERE bot=? AND persona=?",
            namespace.as_tuple,
        ).fetchone()
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        if (grant_row is None or proof_row is None or epochs is None
                or epoch.revision != graph_epoch):
            raise UnavailableGuard("current dispatch Owner graph proof absent; HOLD")
        try:
            grant = json.loads(grant_row[1])
            validate_owner_grant_v1(grant)
            proof = OwnerGraphCommitProofV1(
                namespace, proof_row[0], proof_row[1], proof_row[2],
                proof_row[3], proof_row[4], grant["grant_revision"],
                proof_row[5], proof_row[6], proof_row[7])
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("current dispatch Owner graph proof invalid; HOLD") from exc
        guard = witness.guard
        if (grant_row != (1, canonical_json(grant), 1)
                or proof_row[8] != canonical_json(asdict(proof))
                or "sha256:" + canonical_digest(grant) != proof.grant_digest
                or (witness.issue_operation_id, witness.grant_id,
                    witness.grant_digest) != (
                        proof.operation_id, proof.grant_id, proof.grant_digest)
                or (grant["issue_operation_id"], grant["grant_id"]) != (
                    proof.operation_id, proof.grant_id)
                or (grant["graph_incarnation"], proof.graph_incarnation,
                    admission.graph_incarnation) != (
                        metadata.requirements.graph_incarnation,) * 3
                or grant["activation_generation"]
                != metadata.requirements.activation_generation
                or grant["scope"] != "bot/persona"
                or proof.graph_access_epoch > epochs[0]
                or proof.graph_epoch > epoch.revision
                or (admission.access_epoch, admission.delete_epoch)
                != epochs
                or admission.owner_head_ref != grant["grant_id"]
                or admission.purpose not in grant["purposes"]
                or not set(admission.audience).issubset(grant["audiences"])
                or guard.namespace != namespace
                or guard.authority_id != metadata.requirements.authority_id
                or guard.authority_id != grant["authority_id"]
                or guard.installation_id != grant["installation_id"]
                or guard.installation_id
                != self.__content_fence_v2.installation_grant.installation_id
                or guard.authorization_revision != grant["grant_revision"]
                or guard.authorization_head != owner_digest(proof)
                or guard.minimum_revocation_revision != 0
                or guard.minimum_revocation_epoch != 0
                or guard.pending_revoke_operation_id is not None
                or metadata.requirements.revocation_epoch != 0):
            raise UnavailableGuard("current dispatch Owner authorization differs; HOLD")
        return epochs

    def _commit_dispatch_claim_atom_in_transaction(
            self, namespace: NamespaceId, value, claimed_receipt):
        """Persist an already verified final claim and recovery stamp atomically.

        This is a private transaction primitive, not the handoff authorizer.
        Its caller must have checked every current guard in this same write
        transaction. No public route invokes it until that verifier exists.
        """
        from .authority_service.v2_contract import (
            MutationReceiptV2, canonical_digest as authority_digest,
        )
        from .runtime.dispatch_graph_claim import (
            DispatchGraphClaimValueV1, dispatch_claim_graph_write,
        )

        store = self.__store
        db = store._db
        if not store._lock._is_owned() or not db.in_transaction:
            raise RuntimeError("dispatch claim requires the final graph transaction")
        if (type(namespace) is not NamespaceId
                or type(value) is not DispatchGraphClaimValueV1
                or type(claimed_receipt) is not MutationReceiptV2
                or namespace.as_tuple != (value.bot_id, value.persona_id)):
            raise UnavailableGuard("dispatch claim typed identity differs")
        pending = claimed_receipt.pending
        anchor = claimed_receipt.after_anchor
        if (claimed_receipt.durable_state != "committed"
                or pending.phase != "claimed"
                or pending.binding.operation_id != value.operation_id
                or pending.binding.origin.effect_id != value.effect_id
                or pending.binding.origin.activity_id != value.activity_id
                or pending.binding.origin.admission_ref != value.admission_ref
                or pending.binding.graph_incarnation != value.graph_incarnation
                or pending.permit.namespace != value.authority_namespace
                or pending.permit.fence_epoch != value.p2_fence_epoch
                or claimed_receipt.updated_revision != value.p2_revision
                or anchor.execution_seq != value.p2_execution_seq
                or anchor.execution_digest != value.p2_execution_digest
                or authority_digest(pending.binding) != value.binding_digest
                or authority_digest(claimed_receipt)
                != value.claimed_receipt_digest
                or authority_digest(replace(
                    pending.permit, revision=claimed_receipt.updated_revision,
                    pinned_anchor=anchor)) != value.p2_permit_digest):
            raise UnavailableGuard("dispatch claim differs from committed P2")
        metadata, epoch = self._v2_graph_stamp(namespace)
        requirements = metadata.requirements
        if (requirements.graph_incarnation != value.graph_incarnation
                or requirements.authority_namespace != value.authority_namespace
                or not self._accounting_anchor_covers(requirements, anchor)):
            raise StaleRead("dispatch claim recovery watermark differs from P2")
        write = dispatch_claim_graph_write(value)
        event_id = "dispatch-claim:" + value.effect_id
        existing = db.execute(
            "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
            (write.key.token,),
        ).fetchone()
        if existing is not None:
            if (existing[0] != 1 or existing[2] != 1
                    or json.loads(existing[1]) != write.value):
                raise EventConflict("dispatch effect already has a different graph claim")
            event_row = db.execute(
                "SELECT epoch_revision FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (value.activity_id, event_id),
            ).fetchone()
            if event_row is None or event_row[0] > epoch.revision:
                raise UnavailableGuard("dispatch claim event is unavailable")
            return GraphVersion(write.key, 1), event_row[0], False
        event = Event(
            Scope(*namespace.as_tuple, value.activity_id), event_id, time.time(),
            "dispatch_graph_claim_v1", {"claim_digest": canonical_digest(write.value)},
        )
        candidate = GraphCandidate(
            event, (GraphVersion(write.key, 0),), (write,), (epoch,))
        replacement = replace(
            requirements,
            deletion_seq=anchor.deletion_seq,
            deletion_digest=anchor.deletion_digest,
            execution_seq=anchor.execution_seq,
            execution_digest=anchor.execution_digest,
            revocation_epoch=anchor.revocation_epoch,
        )

        def stamp_claim(_db, receipt):
            if (receipt.status != "committed"
                    or receipt.revisions != (GraphVersion(write.key, 1),)):
                raise EventConflict("dispatch claim graph commit differs")
            store.cas_graph_recovery_metadata(
                metadata, replacement, _capability=self.__graph_capability)

        receipt = GraphStore._graph_commit_in_transaction(
            store, candidate, _receipt_hook=stamp_claim,
            _capability=self.__graph_capability)
        return receipt.revisions[0], receipt.epoch.revision, True

    def register_dispatch_final_claim_writer_v1(
            self, bootstrap: object, *, route_port=None, issuer_id=None):
        """Give trusted host composition one synchronous GraphWorker callback.

        The reverse mTLS listener registers this callback in its exclusive
        window. Merely receiving the five Authority DTOs never grants a claim.
        """
        self._admin(bootstrap)
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import InstalledDispatchRoutePort

        port = self.__content_fence_v2
        if (not isinstance(self.__store, ProductionGraphStore)
                or port is None
                or type(route_port) is not InstalledDispatchRoutePort
                or type(issuer_id) is not str or not issuer_id
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                or not callable(getattr(port, "read_current_effect", None))
                or not callable(getattr(port, "current_anchor", None))
                or not callable(getattr(port, "read_ingress_clock", None))):
            raise UnavailableGuard("installed final dispatch authorities unavailable; HOLD")

        def claim_writer(graph, context, binding, claimed, witness, snapshot):
            if graph is not self:
                raise UnavailableGuard("final dispatch GraphWorker identity differs; HOLD")
            return self._commit_dispatch_final_claim_v1(
                context, binding, claimed, witness, snapshot, route_port,
                issuer_id)

        return claim_writer

    def _commit_dispatch_final_claim_v1(
            self, context, binding, claimed, witness, authority_snapshot,
            route_port=None, issuer_id=None):
        """Recheck the exact P2 and current graph in one write transaction.

        All Authority reads precede the GraphStore lock. Incomplete domain
        checks explicitly HOLD before the private claim atom can be written.
        """
        from .authority_service.reverse_handoff import (
            require_exact_authority_snapshot,
            require_exact_reverse_handoff_identity,
        )
        from .authority_service.v2_contract import (
            AuthorityDispatchSnapshotV1, DispatchHandoffContextV1,
            ExecutionBindingV2, MutationReceiptV2, OwnerDispatchWitnessV1,
            canonical_digest as authority_digest,
        )
        from .authority_service.v2_execution_bridge import CurrentEffectReadV2
        from .runtime.dispatch_budget_check import (
            evaluate_dispatch_budget_authority_snapshot,
        )
        from .runtime.dispatch_current_commitments import (
            read_current_d08_action_conflict_evidence,
            read_current_d08_conflict_facts,
        )
        from .runtime.dispatch_current_commitment_check import (
            read_current_commitment_criteria_v1,
        )
        from .runtime.dispatch_admission import check_receipts_against_specs
        from .runtime.dispatch_graph_claim import DispatchGraphClaimValueV1
        from .authority_service.v2_contract import DispatchGraphClaimReceiptV1
        from .runtime.dispatch_current_projection import (
            read_current_dispatch_projection,
        )
        from .runtime.dispatch_current_social_checks import (
            verify_current_social_checks,
        )
        from .runtime.dispatch_current_segment import read_current_dispatch_segment
        from .domains.d08 import GoalExecutionProvider
        from .domains.d03.context import ContextProvider
        from .domains.d05.relationship import RelationshipProvider
        from .runtime.first_ingress_v2 import trusted_upper
        from .host.authority_profile import AdminIngressClockPolicy
        from .host.installed_dispatch_route import (
            InstalledDispatchRoutePort, InstalledDispatchRouteReadV1,
        )

        if (type(context) is not DispatchHandoffContextV1
                or type(binding) is not ExecutionBindingV2
                or type(claimed) is not MutationReceiptV2
                or type(witness) is not OwnerDispatchWitnessV1
                or type(authority_snapshot) is not AuthorityDispatchSnapshotV1):
            raise UnavailableGuard("typed final dispatch P2 evidence required; HOLD")
        try:
            namespace = NamespaceId(*binding.graph_namespace.split("/"))
            require_exact_reverse_handoff_identity(
                namespace_ref(namespace), context, binding, claimed)
            require_exact_authority_snapshot(context, witness, authority_snapshot)
        except (TypeError, ValueError, RuntimeError) as exc:
            raise UnavailableGuard("final dispatch P2 chain differs; HOLD") from exc
        permit = context.permit
        if (witness.context_digest != authority_digest(context)
                or witness.authority_namespace != permit.namespace
                or witness.graph_namespace != binding.graph_namespace
                or witness.guard.authority_id != permit.authority_id
                or witness.guard.namespace != namespace):
            raise UnavailableGuard("final dispatch Owner witness differs; HOLD")

        # The installed port reads live Authority state. No GraphStore lock is
        # held while these synchronous RPCs run on the GraphWorker thread.
        port = self.__content_fence_v2
        if (port is None or not callable(getattr(port, "read_current_effect", None))
                or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed final dispatch readers unavailable; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=permit.namespace)
        effect = port.read_current_effect(
            namespace=namespace, authority_namespace=permit.namespace,
            effect_id=permit.effect_id)
        now_utc = trusted_upper(port.read_ingress_clock(
            self.__dispatch_clock_policy))
        own = tuple(item for item in authority_snapshot.unresolved_effects
                    if item.effect_id == permit.effect_id)
        if (anchor != authority_snapshot.anchor or type(effect) is not CurrentEffectReadV2
                or len(own) != 1 or own[0].phase != "claimed"
                or own[0].mutation_id != effect.mutation_id
                or own[0].execution_seq != effect.effect_seq
                or own[0].append_digest != effect.append_digest
                or effect.state != "unresolved"
                or (effect.execution_head_seq, effect.execution_head_digest)
                != (anchor.execution_seq, anchor.execution_digest)):
            raise UnavailableGuard("current Authority P2 effect differs; HOLD")

        # Lock order: release the short graph selector read before the host
        # loop verifies the live AstrBot scene. Re-read that selector under the
        # final BEGIN IMMEDIATE; no host or Authority call occurs under it.
        store = self.__store
        if type(route_port) is not InstalledDispatchRoutePort:
            raise UnavailableGuard("installed final dispatch route reader unavailable; HOLD")
        with store._lock:
            db = store._db
            db.execute("BEGIN")
            try:
                from .runtime.dispatch_admission import load_admission
                receipt = load_admission(db, namespace, binding.origin.admission_ref)
                if receipt is None:
                    raise UnavailableGuard("final dispatch admission is absent; HOLD")
                frozen = receipt.admission
                from .runtime.dispatch_current_segment import read_current_dispatch_segment
                pre_route = read_current_dispatch_segment(
                    db, namespace, frozen.admission_ref, now_utc=now_utc)
                selectors = (frozen.account_ref, frozen.destination_ref,
                             frozen.scene_ref, pre_route.route_digest)
            finally:
                db.execute("ROLLBACK")
        live_route = route_port.read_live_host_scene_only(
            namespace=namespace, account_ref=selectors[0],
            destination_ref=selectors[1], scene_ref=selectors[2],
            route_digest=selectors[3])
        if (type(live_route) is not InstalledDispatchRouteReadV1
                or live_route.status != "verified_route"
                or live_route.route_digest != selectors[3]
                or live_route.graph_epoch is not None
                or live_route.current_scene is None):
            raise UnavailableGuard("current installed AstrBot route unavailable; HOLD")

        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                metadata, _ = self._v2_graph_stamp(namespace)
                requirements = metadata.requirements
                if (requirements.namespace != namespace
                        or requirements.graph_incarnation != binding.graph_incarnation
                        or requirements.authority_namespace != permit.namespace
                        or requirements.deletion_seq != anchor.deletion_seq
                        or requirements.revocation_epoch != anchor.revocation_epoch
                        or not self._accounting_anchor_covers(requirements, anchor)):
                    raise UnavailableGuard("final dispatch graph/Authority stamp differs; HOLD")
                provision_row = self._provision_row(db, namespace)
                if (provision_row is None or
                        self._decode_provision_receipt(provision_row).installation_id
                        != witness.guard.installation_id):
                    raise UnavailableGuard("final dispatch Owner installation differs; HOLD")
                prerequisite = self._read_dispatch_final_claim_prerequisite_locked(
                    namespace, binding, claimed, context.handoff_id,
                    now_utc=now_utc)
                from .runtime.dispatch_admission import load_admission
                admission_receipt = load_admission(
                    db, namespace, prerequisite.admission_ref)
                if (admission_receipt is None
                        or admission_receipt.admission.clock_policy_ref
                        != self.__dispatch_clock_policy.source_id
                        or admission_receipt.admission.clock_policy_digest
                        != canonical_digest(asdict(self.__dispatch_clock_policy))):
                    raise UnavailableGuard("final dispatch installed clock differs; HOLD")
                graph, query = self._dispatch_full_graph_snapshot_locked(namespace)
                segment = read_current_dispatch_segment(
                    db, namespace, prerequisite.admission_ref, now_utc=now_utc)
                if ((admission_receipt.admission.account_ref,
                     admission_receipt.admission.destination_ref,
                     admission_receipt.admission.scene_ref,
                     segment.route_digest) != selectors):
                    raise UnavailableGuard("final dispatch route changed during host read; HOLD")
                projection = read_current_dispatch_projection(
                    db, namespace, graph, query)
                blockers = evaluate_dispatch_budget_authority_snapshot(
                    context, witness, authority_snapshot, namespace=namespace,
                    proposed_footprint=binding.origin.footprint)
                if blockers:
                    raise UnavailableGuard(
                        "final dispatch Authority budget conflicts: "
                        + ",".join(blockers) + "; HOLD")
                facts = read_current_d08_conflict_facts(
                    db, namespace, graph, query)
                actions = tuple(item for item in facts.action_intents
                                if item.identity.operation_id == binding.operation_id
                                and item.identity.effect_id == binding.origin.effect_id)
                if len(actions) != 1:
                    raise UnavailableGuard("current D08 action is absent or ambiguous; HOLD")
                action = read_current_d08_action_conflict_evidence(
                    db, namespace, graph, query, actions[0].action_id,
                    permit, effect)
                if (action.effect_state != "unresolved"
                        or action.action_cancellation_state != "clear"
                        or action.job_cancellation_state != "clear"
                        or projection.coverage != "full"
                        or projection.missing_sources):
                    raise UnavailableGuard("current D08/graph checks incomplete; HOLD")
                candidate = self._get_dispatch_candidate_evidence_locked(
                    namespace, binding.operation_id)
                if candidate is None:
                    raise UnavailableGuard("current D08 schema candidate absent; HOLD")
                schema_ref, schema_revision = candidate.write_versions[1]
                schema_atom = graph.get(AtomKey.from_token(schema_ref))
                if (schema_atom is None or not schema_atom.valid
                        or schema_atom.revision != schema_revision):
                    raise UnavailableGuard("current D08 action schema differs; HOLD")
                schema = next(spec for spec in GoalExecutionProvider().register_types()
                              if spec.name == "d08.action_schema.v1").validator(
                                  schema_atom.value)
                commitment = read_current_commitment_criteria_v1(
                    db, namespace, graph, query, actions[0], schema,
                    claimed, context, witness, authority_snapshot, effect,
                    now_utc=now_utc)
                d03 = self.__providers.get("d03")
                d05 = self.__providers.get("d05")
                if (d03 is None or d05 is None
                        or type(d03[0]) is not ContextProvider
                        or type(d05[0]) is not RelationshipProvider
                        or len(admission_receipt.admission.audience) != 1):
                    raise UnavailableGuard("current D03/D05 provider or scope absent; HOLD")
                try:
                    catalogue_current = all(
                        store._registry.spec(spec.name) == spec
                        for provider in (d03[0], d05[0])
                        for spec in provider.type_specs())
                except (AttributeError, KeyError, TypeError, ValueError):
                    catalogue_current = False
                receipts = {
                    item.check_kind: item
                    for item in admission_receipt.admission.check_receipts}
                if set(receipts) != {item.check_kind for item in schema.required_checks}:
                    raise UnavailableGuard("current RequiredCheck set is incomplete; HOLD")
                role = receipts.get("role_binding")
                boundary = receipts.get("boundary")
                if role is None or boundary is None:
                    raise UnavailableGuard("current D03/D05 receipts absent; HOLD")
                social = verify_current_social_checks(
                    db, graph, projection, actions[0], schema, role, boundary,
                    context=d03[0], scene_ref=admission_receipt.admission.scene_ref,
                    audience_scope=admission_receipt.admission.audience[0],
                    now_utc=now_utc,
                    current_catalogue_confirmed=catalogue_current)
                if social.status != "verified" or social.verified is not True:
                    raise UnavailableGuard(
                        "current D03/D05 check incomplete: " + social.reason + "; HOLD")
                from .domains.d08.execution import BASE_REQUIRED_PROVIDERS
                if (schema.proactive or binding.origin.proactive_contact
                        or schema.action_kind != "message"
                        or {(item.check_kind, item.provider_id)
                            for item in schema.required_checks}
                        != set(BASE_REQUIRED_PROVIDERS)
                        or len(schema.required_checks) != len(BASE_REQUIRED_PROVIDERS)
                        or schema.required_checks != actions[0].required_checks):
                    raise UnavailableGuard(
                        "final dispatch action needs an unavailable current check; HOLD")
                try:
                    check_receipts_against_specs(
                        admission_receipt.admission, schema.required_checks,
                        now_utc)
                except ValueError as exc:
                    raise UnavailableGuard(
                        "final dispatch frozen RequiredCheck differs; HOLD") from exc
                owner_epochs = self._verify_dispatch_owner_graph_locked(
                    namespace, witness, admission_receipt.admission,
                    query.revision)
                if (live_route.route_digest != segment.route_digest
                        or live_route.current_scene.scene_ref
                        != admission_receipt.admission.scene_ref
                        or live_route.current_scene.namespace != namespace):
                    raise UnavailableGuard("final dispatch live scene differs; HOLD")
                evidence_digest = "sha256:" + canonical_digest({
                    "prerequisite": prerequisite,
                    "graph_epoch": query.revision,
                    "segment": segment,
                    "route": live_route,
                    "projection": projection.digest,
                    "social": social,
                    "commitment": commitment,
                    "action": action,
                    "owner_witness": witness,
                    "owner_epochs": owner_epochs,
                    "authority_snapshot": authority_snapshot,
                })
                value = DispatchGraphClaimValueV1(
                    namespace.bot_id, namespace.persona_id,
                    binding.graph_incarnation, binding.origin.activity_id,
                    binding.origin.effect_id, binding.operation_id,
                    context.handoff_id, prerequisite.admission_ref,
                    permit.namespace, authority_digest(context.permit),
                    permit.fence_epoch, claimed.updated_revision,
                    anchor.execution_seq, anchor.execution_digest,
                    authority_digest(context), authority_digest(witness),
                    authority_digest(binding), authority_digest(claimed),
                    evidence_digest,
                )
                version, graph_epoch, _ = self._commit_dispatch_claim_atom_in_transaction(
                    namespace, value, claimed)
                claim_receipt = DispatchGraphClaimReceiptV1(
                    authority_digest(context), binding.graph_namespace,
                    binding.graph_incarnation, f"graph:{version.revision}",
                    graph_epoch, owner_epochs[0], owner_epochs[1],
                    "dispatch-claim:" + binding.origin.effect_id,
                    "sha256:" + canonical_digest(asdict(value)), issuer_id,
                )
                db.execute("COMMIT")
                return claim_receipt
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def get_dispatch_text_segment(self, authority: AuthorityContext,
                                  lease: object, request):
        """Read one D09 body through its committed D11 admission and graph fence.

        The route is limited to the AstrBot ingress identity profile. This
        read is content provenance, not a current host send permit.
        """
        from .dispatch_runtime import DispatchRequest

        if type(request) is not DispatchRequest or request.namespace != "/".join(
                authority.namespace.as_tuple):
            raise ValueError("dispatch request namespace differs")
        self._authorize(lease, authority, frozenset({"d08", "d09", "d11"}))
        reader = lambda: self._get_dispatch_text_segment_locked(
            authority.namespace, request)
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._read_v2(authority, reader)
        with self._content_fence(authority.namespace,
                                 authority.activation_generation, "read"):
            with self.__store._lock:
                self._admit_content(authority.namespace,
                                    authority.activation_generation, "read")
                return reader()

    def _get_dispatch_text_segment_locked(self, namespace, request):
        from .domains.d09 import ClaimKind, ClaimUse, D09ExpressionProvider
        from .runtime.dispatch_candidate import GraphDispatchTextSegmentV1

        db = self.__store._db
        row = db.execute(
            "SELECT admission_ref FROM graph_dispatch_admissions "
            "WHERE bot=? AND persona=? AND operation_id=? AND effect_id=?",
            namespace.as_tuple + (request.operation_id, request.effect_id),
        ).fetchone() if db.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='graph_dispatch_admissions'"
        ).fetchone() else None
        if row is None:
            return None
        receipt = load_admission(db, namespace, row[0])
        candidate = self._get_dispatch_candidate_evidence_locked(
            namespace, request.operation_id)
        if receipt is None or candidate is None:
            raise UnavailableGuard("dispatch admission or candidate is absent")
        admission = receipt.admission
        evidence = candidate.evidence
        if (evidence.status != "source_qualified"
                or admission.request_digest != canonical_digest(request)
                or admission.candidate_digest != evidence.digest
                or admission.batch_digest != evidence.batch_digest
                or admission.segment_index != request.segment_index
                or admission.payload_digest != request.payload_digest
                or admission.dispatch_generation != request.dispatch_generation
                or admission.graph_incarnation != (
                    candidate.graph_incarnation or "nonproduction-graphstore")
                or receipt.graph_epoch != candidate.graph_epoch
                or request.payload_ref != dispatch_segment_payload_ref(
                    evidence.batch_ref, request.segment_index)):
            raise UnavailableGuard("dispatch text admission differs from graph candidate")
        batch_ref, batch_revision = candidate.write_versions[3]
        batch_row = db.execute(
            "SELECT value,valid FROM graph_history WHERE token=? AND revision=? "
            "AND event_bot=? AND event_persona=? AND event_session=? AND event_id=?",
            (batch_ref, batch_revision) + namespace.as_tuple + (
                request.activity_id, request.operation_id),
        ).fetchone()
        if batch_row is None or batch_row[1] != 1:
            raise UnavailableGuard("committed D09 batch is unavailable")
        batch = json.loads(batch_row[0])
        next(spec for spec in D09ExpressionProvider.register_types()
             if spec.name == "d09.verified_segment_batch.v1").validator(batch)
        index = request.segment_index
        if (type(index) is not int or not 0 <= index < len(batch["segments"])
                or batch_ref != evidence.batch_ref
                or batch["batch_digest"] != evidence.batch_digest
                or batch["scene_ref"] != admission.scene_ref
                or tuple(batch["audiences"]) != admission.audience
                or len(admission.audience) != 1):
            raise UnavailableGuard("D09 batch scope differs from dispatch admission")
        segment = batch["segments"][index]
        if (segment["effect_id"] != request.effect_id
                or segment["payload_digest"] != request.payload_digest
                or segment["segment_authorization_ref"] != request.segment_authorization_ref
                or batch["grant_manifest_digest"] != request.segment_manifest_digest
                or len(batch["segments"]) != request.segment_count):
            raise UnavailableGuard("D09 text segment differs from dispatch command")
        # Ingress freezes platform_ref=[platform_id,platform_name,self_id] and
        # conversation_ref=[UMO,conversation_id]. Rebuild its bot and scene.
        try:
            account = json.loads(admission.account_ref)
            route = json.loads(admission.audience[0])
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("AstrBot route encoding is unavailable") from exc
        from .host.identity import astrbot_namespace

        if (type(account) is not list or len(account) != 3
                or type(route) is not list or len(route) != 2
                or any(type(item) is not str or not item for item in (*account, *route))
                or admission.destination_ref != admission.audience[0]
                or json.dumps(account, ensure_ascii=True, separators=(",", ":"))
                != admission.account_ref
                or json.dumps(route, ensure_ascii=True, separators=(",", ":")) != admission.audience[0]):
            raise UnavailableGuard("dispatch route is not bound to AstrBot ingress")
        if astrbot_namespace(account[0], account[2], "route-check").bot_id != namespace.bot_id:
            raise UnavailableGuard("dispatch account differs from AstrBot graph namespace")
        from .runtime.first_ingress_v2 import scene_ref_for_conversation

        if scene_ref_for_conversation(
                namespace, admission.account_ref, admission.destination_ref,
        ) != admission.scene_ref:
            raise UnavailableGuard("dispatch scene differs from AstrBot ingress")
        uses = tuple(ClaimUse(item["claim_ref"], item["start"], item["end"],
                              ClaimKind(item["asserted_as"]))
                     for item in segment["claim_uses"])
        return GraphDispatchTextSegmentV1(
            segment["body"], tuple(segment["media_refs"]), uses,
            account[0], account[1], account[2], route[0], route[1],
            admission.scene_ref,
        )

    @staticmethod
    def _dispatch_clock_upper(reading) -> float:
        from .host.v2_fence_port import VerifiedIngressClockV2
        from .runtime.first_ingress_v2 import trusted_upper

        if type(reading) is not VerifiedIngressClockV2:
            raise UnavailableGuard("paired dispatch admission clock is unqualified")
        try:
            return trusted_upper(reading)
        except ValueError as exc:
            raise UnavailableGuard("paired dispatch admission clock is unqualified") from exc

    def _issue_dispatch_admission(self, db, bundle, snapshot, candidate,
                                  action, schema, grant, batch, *,
                                  graph_receipt, v2_write, now_utc, projection,
                                  clock_reading=None, dispatch_scope=None,
                                  dispatch_owner_guard=None,
                                  dispatch_current_effect=None):
        """Fail closed unless a host issuer supplies and proves every current fact.

        This is called from the graph receipt hook, after D11's reservation,
        while the ordinary graph write transaction and fence remain active.
        """
        issuer = self.__dispatch_admission_issuer
        if issuer is None:
            return None
        if (candidate.status != "source_qualified"
                or (isinstance(self.__store, ProductionGraphStore)
                    and v2_write is None)):
            raise UnavailableGuard("dispatch admission requires current D06 proof and write fence")
        if projection is None:
            raise UnavailableGuard("dispatch admission lacks complete D03/D05 graph projection")
        for method in ("issue_dispatch_admission", "verify_required_check",
                       "verify_command_provenance", "verify_journal_constraints",
                       "verify_domain_context"):
            if not callable(getattr(issuer, method, None)):
                raise UnavailableGuard("trusted dispatch admission issuer is incomplete")
        envelope = bundle.envelope
        identity = envelope.identity
        graph_incarnation = (
            v2_write[0].requirements.graph_incarnation
            if v2_write is not None else "nonproduction-graphstore"
        )
        if now_utc is None:
            raise UnavailableGuard("trusted dispatch admission clock is unavailable")
        if type(now_utc) not in (int, float) or not math.isfinite(now_utc):
            raise UnavailableGuard("trusted dispatch admission clock is invalid")
        now = float(now_utc)
        trusted_context = None
        if isinstance(self.__store, ProductionGraphStore):
            from .authority_service.v2_contract import FencePermitV2
            from .authority_service.v2_execution_bridge import CurrentEffectReadV2
            from .authority_service.v2_owner_contract import OwnerAuthorizationGuardV1
            from .host.authority_profile import AdminIngressClockPolicy
            from .host.v2_fence_port import VerifiedIngressClockV2
            from .runtime_contracts import FenceScope
            from .runtime.installed_dispatch_admission_issuer import (
                TrustedDispatchAdmissionContextV1,
            )

            if (type(dispatch_scope) is not FenceScope
                    or type(dispatch_scope.permit) is not FencePermitV2
                    or dispatch_scope.permit.operation != "write"
                    or type(clock_reading) is not VerifiedIngressClockV2
                    or type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy
                    or type(dispatch_owner_guard) is not OwnerAuthorizationGuardV1
                    or type(dispatch_current_effect) is not CurrentEffectReadV2
                    or dispatch_scope.permit.pinned_anchor != dispatch_scope.pinned_anchor
                    or dispatch_scope.graph_revision != v2_write[0].graph_revision
                    or dispatch_scope.graph_epoch != v2_write[1]):
                raise UnavailableGuard("trusted dispatch admission fence evidence unavailable; HOLD")
            trusted_context = TrustedDispatchAdmissionContextV1(
                dispatch_scope, clock_reading, self.__dispatch_clock_policy,
                projection, graph_receipt, dispatch_owner_guard,
                dispatch_current_effect)
        issuer_options = ({"trusted_context": trusted_context}
                          if trusted_context is not None else {})
        issued = issuer.issue_dispatch_admission(
            bundle, snapshot, candidate, db, graph_incarnation=graph_incarnation,
            now_utc=now, **issuer_options,
        )
        if (type(issued) is not tuple or len(issued) != 2
                or type(issued[1]) is not DispatchAdmissionV1):
            raise UnavailableGuard("trusted issuer did not produce typed dispatch admission")
        request, admission = issued
        from .domains.d03 import RoleBinding

        current_bindings = []
        for atom in projection.role_bindings:
            value = atom.value
            binding = RoleBinding(**{
                **value, "norm_refs": tuple(value["norm_refs"]),
                "source_refs": tuple(value["source_refs"]),
            })
            if (atom.key.name == binding.role_binding_id
                    and atom.revision == binding.binding_version
                    and binding.status == "active"
                    and binding.scene_ref == batch["scene_ref"]
                    and binding.effective_from <= now
                    and (binding.effective_until is None or now <= binding.effective_until)):
                current_bindings.append(binding)
        if not any(binding.role_binding_id == admission.binding_ref
                   for binding in current_bindings):
            raise UnavailableGuard("dispatch admission lacks a current D03 scene binding")
        from .domains.d05 import BoundaryRule, RelationshipProvider

        current_rules = tuple(BoundaryRule(**{
            **atom.value,
            "source_refs": tuple(atom.value["source_refs"]),
            "communicated_refs": tuple(atom.value["communicated_refs"]),
            "acknowledged_refs": tuple(atom.value["acknowledged_refs"]),
            "exception_refs": tuple(atom.value["exception_refs"]),
        }) for atom in projection.boundary_rules)
        if any(atom.key.name != rule.rule_id
               for atom, rule in zip(projection.boundary_rules, current_rules)):
            raise UnavailableGuard("current D05 boundary identity differs")
        # The transaction-checked projection proves read coverage. This only
        # vetoes explicit deny/conflict; the issuer still owns full D05 approval.
        for audience in envelope.authority.audience:
            boundary = RelationshipProvider().provide_required_check(
                subject_persona_ref=f"persona:{envelope.authority.namespace.persona_id}",
                target_entity_ref=action.target_ref,
                action_kind=action.action_kind,
                audience_scope=audience,
                scene_ref=batch["scene_ref"], at_time=now,
                rules=current_rules, coverage_complete=True,
            )
            if boundary.result in {"deny", "conflict"}:
                raise UnavailableGuard("current D05 boundary vetoed dispatch admission")
        if isinstance(self.__store, ProductionGraphStore):
            policy = self.__dispatch_clock_policy
            if (clock_reading is None or policy is None
                    or admission.clock_policy_ref != policy.source_id
                    or admission.clock_policy_digest != canonical_digest(asdict(policy))):
                raise UnavailableGuard("dispatch admission clock evidence differs")
        from .dispatch_runtime import DispatchRequest

        if type(request) is not DispatchRequest:
            raise UnavailableGuard("trusted issuer did not produce typed dispatch command")
        if request.payload_ref != dispatch_segment_payload_ref(
                candidate.batch_ref, request.segment_index):
            raise UnavailableGuard("dispatch payload reference differs from D09 graph segment")
        preflight = preflight_dispatch_admission(
            schema, action, batch, request, admission.check_receipts,
            now_utc=now, trusted_check_verifier=lambda spec, receipt: (
                issuer.verify_required_check(
                    spec, receipt, snapshot, db, **issuer_options) is True),
        )
        if set(preflight.missing) != {
            "d09.source_qualification", "dispatch.command_provenance",
            "graph.current_admission",
        }:
            raise UnavailableGuard("dispatch admission candidate or checks are incomplete")
        check_receipts_against_specs(admission, schema.required_checks, now)
        admission.require_current(now)
        if (issuer.verify_domain_context(
                    admission, snapshot, db, **issuer_options) is not True
                or issuer.verify_command_provenance(
                    request, admission, db, **issuer_options) is not True
                or issuer.verify_journal_constraints(
                    request, admission, **issuer_options) is not True):
            raise UnavailableGuard("dispatch domain, command, or journal is unverified")
        reads = tuple((item.key.token, item.revision) for item in snapshot.versions)
        parts = (action.identity.activity_id, action.identity.effect_id,
                 action.identity.attempt_id, action.identity.operation_id)
        segment = batch["segments"][request.segment_index]
        if (
            admission.namespace != "/".join(envelope.authority.namespace.as_tuple)
            or admission.graph_incarnation != graph_incarnation
            or (admission.activity_id, admission.effect_id,
                admission.attempt_id, admission.operation_id) != parts
            or admission.dispatch_generation != request.dispatch_generation
            or request.activation_generation != envelope.authority.activation_generation
            or admission.dispatch_generation != envelope.authority.activation_generation
            or admission.candidate_digest != candidate.digest
            or admission.request_digest != canonical_digest(request)
            or admission.action_intent_digest != candidate.action_digest
            or admission.action_schema_digest != candidate.schema_digest
            or admission.required_checks_digest != canonical_digest(schema.required_checks)
            or admission.grant_digest != candidate.grant_digest
            or admission.batch_digest != candidate.batch_digest
            or admission.segment_index != request.segment_index
            or admission.payload_digest != segment["payload_digest"]
            or admission.scene_ref != batch["scene_ref"]
            or admission.object_ref != action.target_ref
            or admission.action_ref != action.action_id
            or admission.purpose != action.purpose
            or admission.audience != envelope.authority.audience
            or admission.graph_reads != reads
            or admission.query_epoch != snapshot.epochs[0].revision
            or (admission.access_epoch, admission.delete_epoch) != (
                envelope.version_guard.access_epoch,
                envelope.version_guard.delete_epoch)
            or admission.budget_parent_lease_ref != envelope.parent_budget_lease_ref
            or admission.budget_lease_ref != envelope.parent_budget_lease_ref
            or admission.budget_reservation_operation_id != identity.operation_id
            or admission.budget_reservation_digest != budget_operation_digest(
                envelope, admission.budget_lease_ref, dict(admission.budget_ceiling))
            or not any(
                item.parent_budget_ref == admission.budget_lease_ref
                and item.upper_bound is not None
                for item in request.footprint.budgets
            )
        ):
            raise UnavailableGuard("dispatch admission differs from current graph candidate")
        if (admission.action_intent_schema_version != "d08.action_intent.v1"
                or admission.action_schema_version != "d08.action_schema.v1"
                or admission.required_checks_schema_version != "d08.required_check_spec.v1"):
            raise UnavailableGuard("dispatch contract schema version differs")
        lease = get_budget_lease(db, admission.budget_lease_ref)
        reservation = db.execute(
            "SELECT digest,ceiling_json,state FROM runtime_budget_reservations "
            "WHERE lease_id=? AND operation_id=?",
            (admission.budget_lease_ref, admission.budget_reservation_operation_id),
        ).fetchone()
        if (lease.state != "active" or lease.version != admission.budget_version
                or lease.currency != admission.budget_currency
                or (lease.bot_id, lease.persona_id) != envelope.authority.namespace.as_tuple
                or reservation is None
                or reservation[0] != admission.budget_reservation_digest
                or json.loads(reservation[1]) != dict(admission.budget_ceiling)
                or reservation[2] != "reserved"):
            raise UnavailableGuard("dispatch budget reservation changed before admission")
        if request.proactive_contact and admission.contact_reservation_ref is None:
            raise UnavailableGuard("proactive contact has no durable occupation")
        graph_revision = (v2_write[0].graph_revision + 1 if v2_write is not None
                          else graph_receipt.epoch.revision)
        receipt = DispatchAdmissionReceiptV1(
            admission, graph_revision, graph_receipt.epoch.revision,
            canonical_digest({
                "admission_digest": admission.digest,
                "graph_revision": graph_revision,
                "graph_epoch": graph_receipt.epoch.revision,
            }),
        )
        insert_admission(db, receipt, request)
        return receipt

    def commit_d03_message_arrival_v2(
            self, bootstrap: object, namespace: NamespaceId, source_ref: str,
            installation_policy, arrival_policy, clock_policy) -> CommitReceipt:
        """Adopt one committed ingress as a D03 fact with an installed price.

        The source ID selects an existing trusted ingress receipt. Identity,
        content, scene and source/access guards are rebuilt from this store;
        no caller candidate or quote is accepted. A committed receipt reports
        only the graph fact and a D11 reservation, never settled cost.
        """
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .domains.d03.message_arrival import (
            build_message_arrival_candidate, build_message_arrival_proposal,
        )
        from .host.authority_profile import (
            AdminD03ArrivalPolicy, AdminIngressClockPolicy,
        )
        from .host.ingress import HostIngressEnvelope, SourceLineage
        from .installation_policy import AdminInstallationPolicy
        from .runtime.first_ingress_v2 import (
            scene_ref_for_conversation, trusted_upper,
        )
        from .runtime.ingress_observation import read_committed_ingress_identity
        from .runtime.issuers import D03_ARRIVAL_WORK_KIND, d03_arrival_quote_id
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(arrival_policy) is not AdminD03ArrivalPolicy
                or type(clock_policy) is not AdminIngressClockPolicy):
            raise UnavailableGuard("installed D03 arrival policies are required; HOLD")
        if (namespace != installation_policy.namespace
                or type(source_ref) is not str or len(source_ref) != 64
                or any(ch not in "0123456789abcdef" for ch in source_ref)
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("D03 arrival v2 identity or authorities unavailable")
        policy = installation_policy
        grant = policy.root_grant
        if (D03_ARRIVAL_WORK_KIND not in grant.allowed_work_kinds
                or any(amount > grant.max_ceiling.get(name, 0)
                       for name, amount in arrival_policy.quote_ceiling.items())):
            raise UnavailableGuard("installed grant does not price D03 arrival")
        operation_id = "d03-arrival-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "source_ref": source_ref,
        })[:40]
        activity_id = "d03-activity-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "source_ref": source_ref,
            "kind": D03_ARRIVAL_WORK_KIND,
        })[:40]
        quote_id = d03_arrival_quote_id(namespace, operation_id)
        policy_digest = canonical_digest(arrival_policy.digest_payload())
        store = self.__store
        port = self.__content_fence_v2
        with store._lock:
            provision = self._provision_row(store._db, namespace)
            if provision is None:
                raise UnavailableGuard("D03 arrival namespace is not provisioned")
            genesis = self._decode_provision_receipt(provision)
            signed_grant, signature = self.__d11_issuer.signed_budget_grant_at_version(
                store._db, grant.lease_id, grant.version)
            if (signed_grant != grant or signature != genesis.root_grant_signature
                    or genesis.root_grant_id != grant.grant_id
                    or genesis.root_lease_id != grant.lease_id
                    or genesis.installation_id != policy.installation_id
                    or genesis.manifest_digest != policy.manifest_digest):
                raise UnavailableGuard("D03 arrival installed root grant differs")
            metadata, epoch = self._v2_graph_stamp(namespace)
            prior_authority = AuthorityContext(
                "host", "d11", "audit", namespace, ("persona", "event"),
                "context", (), grant.policy_ref,
                metadata.requirements.activation_generation)
            prior = self._get_operation_fenced(prior_authority, operation_id, v2=True)
            binding = store._db.execute(
                "SELECT source_ref,quote_id,policy_digest,bundle_digest "
                "FROM graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone() if store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_arrival_issuance_v2'",
            ).fetchone() else None
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if (target.namespace != namespace
                or target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or target.activation_generation != genesis.generation):
            raise UnavailableGuard("D03 arrival v2 recovery identity differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 arrival Authority anchor differs")
        if prior is not None:
            if (binding != (source_ref, quote_id, policy_digest,
                            prior.operation_digest)
                    or saved is None or saved[0] != prior.operation_digest
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D03 arrival replay receipt differs")
            attempt_id = domain_bundle_write_attempt_id_v1(
                namespace, operation_id, prior.operation_digest)
            permit = from_wire(json.loads(saved[1]))
            if (type(permit) is not FencePermitV2
                    or permit.operation_id != attempt_id
                    or permit.pinned_anchor != anchor
                    or permit.holder != self.__holder):
                raise UnavailableGuard("D03 arrival replay permit differs")
            with store._lock:
                quote = self.__d02_issuer._load_quote(store._db, quote_id, 1)
                policy_ref = quote.snapshot_ref.split(":")
                if len(policy_ref) != 3 or policy_ref[0] != "d03snap":
                    raise UnavailableGuard("D03 arrival replay policy binding differs")
                signed_policy = self.__d02_issuer._load_d03_arrival_policy(
                    store._db, policy_ref[1])
                original, _ = self.__d11_issuer.signed_budget_grant_at_version(
                    store._db, grant.lease_id, grant.version)
                budget = get_budget_lease(store._db, grant.lease_id)
                if (original != grant or quote.operation_id != operation_id
                        or quote.activity_id != activity_id
                        or quote.parent_budget_lease_ref != grant.lease_id
                        or quote.work_kind != D03_ARRIVAL_WORK_KIND
                        or dict(quote.ceiling) != dict(arrival_policy.quote_ceiling)
                        or signed_policy.installation_id != policy.installation_id
                        or signed_policy.grant_id != grant.grant_id
                        or signed_policy.grant_version != grant.version
                        or signed_policy.lease_id != grant.lease_id
                        or signed_policy.provider_policy_ref != grant.policy_ref
                        or signed_policy.snapshot_ref != arrival_policy.snapshot_ref
                        or signed_policy.resource_ref != arrival_policy.resource_ref
                        or signed_policy.deadline_after_seconds
                        != arrival_policy.deadline_after_seconds
                        or dict(signed_policy.quote_ceiling)
                        != dict(arrival_policy.quote_ceiling)
                        or budget.state != "active"
                        or (budget.bot_id, budget.persona_id) != namespace.as_tuple):
                    raise UnavailableGuard("D03 arrival replay quote or lease differs")
            expected_finish = "sha256:" + canonical_digest({
                "operation_id": attempt_id, "permit_token": permit.token,
                "action": "finish_domain_bundle",
                "business_operation_id": operation_id,
                "bundle_digest": prior.operation_digest,
            })
            if saved[6:] != ("finish:" + attempt_id, expected_finish):
                raise UnavailableGuard("D03 arrival replay finish receipt differs")
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != permit or state not in {"active", "finished"}:
                raise UnavailableGuard("D03 arrival replay Authority fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D03 arrival replay graph stamp differs")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", attempt_id,
                    permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != permit:
                    raise UnavailableGuard("D03 arrival replay permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D03 arrival finished graph stamp regressed")
            return replace(prior, status="duplicate")
        if binding is not None or saved is not None:
            raise UnavailableGuard("D03 arrival lacks a complete replay receipt")

        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D03 arrival clock unavailable; HOLD") from exc
        deadline = min(
            math.nextafter(math.fsum((now_utc, arrival_policy.deadline_after_seconds)),
                           -math.inf), grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D03 arrival deadline is unavailable")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D03 arrival monotonic deadline is invalid")
        with store._lock:
            if self._v2_graph_stamp(namespace) != (metadata, epoch):
                raise StaleRead("D03 arrival graph stamp changed")
            db = store._db
            receipt = read_committed_ingress_identity(db, namespace, source_ref)
            if receipt is None:
                raise UnavailableGuard("D03 arrival lacks committed host ingress")
            identity = json.loads(receipt.identity_json)
            source_atom_key = source_key(*namespace.as_tuple, source_ref)
            access_atom_key = access_key(*namespace.as_tuple, source_ref)
            source_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (source_atom_key.token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (access_atom_key.token,),
            ).fetchone()
            if (source_row is None or access_row is None
                    or not source_row[2] or not access_row[2]):
                raise UnavailableGuard("D03 arrival current source or access is unavailable")
            source = SourceRecord.from_dict(json.loads(source_row[1]))
            access = json.loads(access_row[1])
            ingress = HostIngressEnvelope(
                namespace, identity["platform_ref"], identity["conversation_ref"],
                identity["sender_ref"], identity["message_id"], source.text,
                source.occurred_at, source.recorded_at, identity["visibility"],
                SourceLineage(**identity["lineage"]),
            )
            scene = SimpleNamespace(
                namespace=namespace, platform_ref=ingress.platform_ref,
                conversation_ref=ingress.conversation_ref,
                visibility=ingress.visibility,
                scene_ref=scene_ref_for_conversation(
                    namespace, ingress.platform_ref, ingress.conversation_ref),
            )
            qualification = SourceQualification(
                (source_atom_key.token,), "reported", source.occurred_at,
                source.recorded_at, "external_report", "qualified", 0.5,
                "not_applicable",
            )
            candidate = build_message_arrival_candidate(
                ingress, scene, source, access, qualification,
                source_version=GraphVersion(source_atom_key, source_row[0]),
                access_version=GraphVersion(access_atom_key, access_row[0]),
            )
            sender_row = db.execute(
                "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                (candidate.sender_key.token,),
            ).fetchone()
            event_row = db.execute(
                "SELECT 1 FROM graph_atoms WHERE token=?",
                (candidate.event_key.token,),
            ).fetchone()
            if event_row is not None:
                raise UnavailableGuard("D03 arrival event exists without this operation")
            sender_atom = (GraphAtom(candidate.sender_key, sender_row[0],
                                     json.loads(sender_row[1]), bool(sender_row[2]))
                           if sender_row else None)
            guard_versions = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone() or (0, 0)
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d03",), activation_generation=target.activation_generation,
            operation_id=operation_id)
        authority = AuthorityContext(
            "host", "d11", capability, namespace, ("persona", "event"),
            "context", (ingress.conversation_ref,), grant.policy_ref,
            target.activation_generation)
        envelope = CommandEnvelope(
            RUNTIME_SCHEMA,
            OperationIdentity(
                activity_id, None, "arrival-attempt", "arrival", operation_id,
                canonical_digest({"input_refs": [source_atom_key.token]})),
            authority,
            VersionGuard(
                (GraphVersion(source_atom_key, source_row[0]),
                 GraphVersion(access_atom_key, access_row[0]),
                 GraphVersion(candidate.sender_key,
                              sender_row[0] if sender_row else 0),
                 GraphVersion(candidate.event_key, 0)),
                (QueryEpoch(namespace, "all", epoch.revision),),
                *authority_epochs, store._registry.catalogue_hash,
                guard_versions["scheme"], guard_versions["operator"],
                guard_versions["policy"], (), (),
                (VersionedRef(quote_id, 1),)),
            qualification, (source_atom_key.token,), grant.lease_id,
            deadline, monotonic_deadline, "character-v1", (ingress.message_id,),
        )
        proposal = build_message_arrival_proposal(
            envelope, candidate, sender_atom=sender_atom)
        bundle = DomainBundle(envelope, (proposal,), (), (), (), (), (), (), ())
        return self._commit_domain_bundle_v2(
            bundle, lease, arrival_issuance=(
                arrival_policy, policy.installation_id, now_utc, source_ref,
                policy_digest))

    def _recover_d03_self_projection_before_read(
        self, namespace, original_operation_id, installation_policy,
        admin_policy,
    ) -> CommitReceipt | None:
        """Resolve the original stage fence before opening another content read."""
        from .authority_service.v2_contract import from_wire

        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT source_ref FROM graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None:
                raise UnavailableGuard("D03 original ingress is unavailable; HOLD")
            source_ref = source_key(*namespace.as_tuple, identity[0]).token
            has_index = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_self_projection_intents_v1'",
            ).fetchone() is not None
            indexed = (store._db.execute(
                "SELECT operation_id,bundle_digest FROM "
                "graph_d03_self_projection_intents_v1 WHERE bot=? AND persona=? "
                "AND source_ref=? AND original_operation_id=?",
                namespace.as_tuple + (source_ref, original_operation_id),
            ).fetchone() if has_index else None)
            has_issued = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d03_self_projection_issuance_v1'",
            ).fetchone() is not None
            issued = (store._db.execute(
                "SELECT operation_id,certification_ref,quote_id,bundle_digest "
                "FROM graph_d03_self_projection_issuance_v1 WHERE bot=? "
                "AND persona=? AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall() if has_issued else [])
            if len(issued) > 1:
                raise UnavailableGuard("D03 self projection has multiple original receipts")
            if not issued and indexed is None:
                return None
            operation_id = issued[0][0] if issued else indexed[0]
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if intent is None or (indexed is not None
                                  and indexed != (operation_id, intent[0])):
                raise UnavailableGuard("D03 self projection durable intent differs")
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            prior = self._get_operation_fenced(
                AuthorityContext("host", "d11", "recovery", namespace,
                                 ("persona", "event"), "context", (),
                                 installation_policy.root_grant.policy_ref,
                                 metadata.requirements.activation_generation),
                operation_id, v2=True)
            if issued:
                quote = self.__d02_issuer._load_quote(store._db, issued[0][2], 1)
                if (prior is None or saved is None
                        or issued[0][3] != prior.operation_digest
                        or saved[0] != prior.operation_digest
                        or quote.operation_id != operation_id
                        or quote.work_kind != "d03.self_identity_projection"
                        or dict(quote.ceiling) != dict(admin_policy.quote_ceiling)
                        or not any(item.key.type_name == "d03.self_perspective.v1"
                                   for item in prior.write_versions)):
                    raise UnavailableGuard("D03 self projection receipt differs")
            elif prior is not None or saved is not None:
                raise UnavailableGuard("D03 self projection lacks sealed issuance")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 self projection recovery anchor differs")
        if issued:
            original_permit = from_wire(json.loads(saved[1]))
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=intent[1])
            if (observed != original_permit or state not in {"active", "finished"}
                    or original_permit.operation_id != intent[1]
                    or original_permit.pinned_anchor != anchor
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D03 self projection original fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D03 self projection active graph changed")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", intent[1],
                    original_permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original_permit:
                    raise UnavailableGuard("D03 self projection original permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D03 self projection graph receipt regressed")
            return replace(prior, status="duplicate")
        return self._reconcile_stage_retry(
            namespace, "d03", source_ref, original_operation_id,
            operation_id, intent, metadata, epoch, anchor)

    def _reconcile_stage_retry(self, namespace, stage, source_ref,
                               original_operation_id, operation_id,
                               intent, metadata, epoch, anchor) -> _StageRetry:
        """Finish the frozen no-commit attempt before pricing a new operation."""
        store, port = self.__store, self.__content_fence_v2
        target = metadata.requirements
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, intent[0])
        if (intent[1] != attempt_id
                or intent[2] != canonical_json(asdict(target))
                or intent[3] != canonical_json(asdict(anchor))
                or intent[4] > metadata.graph_revision
                or intent[5] > epoch.revision):
            raise UnavailableGuard("stage frozen attempt identity differs; HOLD")
        with store._lock:
            db = store._db
            rejection = db.execute(
                "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest FROM graph_bundle_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        if rejection is None:
            permit = port.begin_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                holder=self.__holder, generation=target.activation_generation,
                operation="write", operation_id=attempt_id,
                expected_anchor=anchor, retain_on_unknown=True)
            scope = FenceScope(
                namespace, target.authority_namespace,
                target.activation_generation, "write", attempt_id,
                permit, anchor, epoch, metadata.graph_revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("stage original write permit changed; HOLD")
            rejection = self._record_rejected_bundle_v2(
                namespace, operation_id, intent[0], attempt_id, metadata,
                epoch, intent, permit, allow_advanced_graph=True)
        self._finish_rejected_bundle_v2(
            namespace, metadata, epoch, anchor, attempt_id, intent[0],
            operation_id, rejection, allow_advanced_graph=True)
        table = ("graph_d03_self_projection_intents_v1" if stage == "d03" else
                 "graph_d04_baseline_intents_v1")
        from .runtime.issuers import (
            d03_self_identity_projection_quote_id, d04_baseline_quote_id,
        )
        quote_id = (d03_self_identity_projection_quote_id(namespace, operation_id)
                    if stage == "d03" else
                    d04_baseline_quote_id(namespace, operation_id))
        with store._lock:
            db = store._db
            if (db.execute(
                    f"SELECT operation_id,bundle_digest FROM {table} "
                    "WHERE bot=? AND persona=? AND source_ref=? "
                    "AND original_operation_id=?",
                    namespace.as_tuple + (source_ref, original_operation_id),
                ).fetchone() != (operation_id, intent[0])
                    or db.execute(
                        "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_reservations "
                        "WHERE operation_id=?", (operation_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_resource_quotes "
                        "WHERE quote_id=?", (quote_id,),
                    ).fetchone() is not None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_operations "
                        "WHERE bot_id=? AND persona_id=? AND operation_id=? "
                        "AND phase='reserve'",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is not None):
                raise UnavailableGuard("stage original no-commit differs; HOLD")
            previous = db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_stage_retry_lineage_v1'",
            ).fetchone()
            prior_lineage = (db.execute(
                "SELECT retry_index FROM graph_stage_retry_lineage_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone() if previous else None)
        next_retry_index = prior_lineage[0] + 1 if prior_lineage else 1
        if next_retry_index > 64:
            raise UnavailableGuard("stage retry bound reached; HOLD")
        return _StageRetry(
            operation_id, intent[0], attempt_id,
            canonical_digest(list(rejection)), next_retry_index)

    def _recover_stage_candidate_read(self, namespace, read_key,
                                      metadata, epoch, anchor) -> None:
        """Finish a durable content-free candidate read left active by a crash."""
        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            exists = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_stage_candidate_reads_v1'",
            ).fetchone()
            open_rows = (store._db.execute(
                "SELECT attempt_id,graph_revision,graph_epoch,anchor_json "
                "FROM graph_stage_candidate_reads_v1 WHERE bot=? AND persona=? "
                "AND read_key=? AND state='open'",
                namespace.as_tuple + (read_key,),
            ).fetchall() if exists else [])
        if len(open_rows) > 1:
            raise UnavailableGuard("stage candidate has multiple active read attempts")
        if not open_rows:
            return
        attempt_id, revision, read_epoch, anchor_json = open_rows[0]
        if (anchor_json != canonical_json(asdict(anchor))
                or metadata.graph_revision < revision
                or epoch.revision < read_epoch):
            raise UnavailableGuard("stage candidate read recovery anchor changed")
        permit, state = port.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=attempt_id)
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (revision, read_epoch):
                raise UnavailableGuard("stage candidate active read graph changed")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation, "read", attempt_id,
                permit, anchor, NamespaceEpoch(*namespace.as_tuple, read_epoch), revision)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("stage candidate read permit changed")
            port.finish_fence(scope, request_id="finish:" + attempt_id,
                              request_digest="sha256:" + canonical_digest({
                                  "operation_id": attempt_id,
                                  "permit_token": permit.token,
                                  "action": "finish_read",
                              }))
        elif state not in {"finished", "absent"}:
            raise UnavailableGuard("stage candidate read recovery state differs")
        with store._lock:
            store._db.execute(
                "UPDATE graph_stage_candidate_reads_v1 SET state='closed' "
                "WHERE bot=? AND persona=? AND read_key=? "
                "AND attempt_id=? AND state='open'",
                namespace.as_tuple + (read_key, attempt_id),
            )

    def _record_stage_candidate_read(self, namespace, read_key, attempt_id,
                                     metadata, epoch, anchor) -> None:
        store = self.__store
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("stage candidate graph changed before read intent")
                db.execute("""CREATE TABLE IF NOT EXISTS graph_stage_candidate_reads_v1(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    read_key TEXT NOT NULL, attempt_id TEXT NOT NULL,
                    graph_revision INTEGER NOT NULL, graph_epoch INTEGER NOT NULL,
                    anchor_json TEXT NOT NULL,
                    state TEXT NOT NULL CHECK(state IN ('open','closed')),
                    PRIMARY KEY(bot,persona,read_key,attempt_id))""")
                db.execute(
                    "INSERT INTO graph_stage_candidate_reads_v1"
                    "(bot,persona,read_key,attempt_id,graph_revision,"
                    "graph_epoch,anchor_json,state) VALUES(?,?,?,?,?,?,?,'open')",
                    namespace.as_tuple + (read_key, attempt_id,
                                          metadata.graph_revision, epoch.revision,
                                          canonical_json(asdict(anchor))),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def _close_stage_candidate_read(self, namespace, read_key, attempt_id) -> None:
        with self.__store._lock:
            self.__store._db.execute(
                "UPDATE graph_stage_candidate_reads_v1 SET state='closed' "
                "WHERE bot=? AND persona=? AND read_key=? "
                "AND attempt_id=? AND state='open'",
                namespace.as_tuple + (read_key, attempt_id),
            )

    def commit_d03_self_identity_projection_v1(
        self, bootstrap: object, namespace: NamespaceId, job_id: str,
        original_operation_id: str, installation_policy, admin_policy,
        clock_policy,
    ) -> CommitReceipt:
        """Project the paired Authority self and first-arrival perspective atomically.

        The initial read only constructs a candidate. The write fence obtains a
        fresh current Authority value and the graph transaction checks its stamp.
        """
        from .authority_service.v2_contract import FencePermitV2
        from .authority_service.v2_self_identity_contract import AuthorityCurrentSelfIdentityV1
        from .domains.d03.self_identity_qualification import (
            self_identity_mapping_from_current,
        )
        from .domains.d03.self_perspective import (
            build_self_identity_projection_bundle, self_mapping_key,
            self_perspective_id, self_perspective_key,
        )
        from .host.authority_profile import (
            AdminD03SelfIdentityProjectionPolicy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d03_self_identity_projection_identity import (
            d03_self_identity_projection_activity_id_v1,
            d03_self_identity_projection_operation_id_v1,
            d03_self_identity_projection_retry_operation_id_v2,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import (
            D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
            d03_self_identity_projection_quote_id,
        )
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD03SelfIdentityProjectionPolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__self_identity_port is None
                or self.__d02_issuer is None or self.__d11_issuer is None):
            raise UnavailableGuard("installed D03 self projection authorities required; HOLD")
        policy = installation_policy
        grant = policy.root_grant
        if (namespace != policy.namespace
                or D03_SELF_IDENTITY_PROJECTION_WORK_KIND not in grant.allowed_work_kinds):
            raise UnavailableGuard("installed D03 self projection grant differs; HOLD")
        store, port = self.__store, self.__content_fence_v2
        recovered = self._recover_d03_self_projection_before_read(
            namespace, original_operation_id, policy, admin_policy)
        if type(recovered) is CommitReceipt:
            return recovered
        retry = recovered if type(recovered) is _StageRetry else None
        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D03 self projection clock unavailable; HOLD") from exc
        deadline = min(math.nextafter(math.fsum((
            now_utc, admin_policy.deadline_after_seconds)), -math.inf),
            grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D03 self projection deadline unavailable; HOLD")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D03 self projection monotonic deadline differs")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
        target = metadata.requirements
        if (target.authority_id != policy.expected_authority_id
                or target.authority_namespace != policy.authority_namespace
                or port.installation_grant.installation_id != policy.installation_id):
            raise UnavailableGuard("D03 self projection installation differs; HOLD")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D03 self projection recovery anchor differs; HOLD")
        self._recover_stage_candidate_read(
            namespace, original_operation_id, metadata, epoch, anchor)
        read_operation = "d03-self-read-" + secrets.token_hex(16)
        self._record_stage_candidate_read(
            namespace, original_operation_id, read_operation, metadata, epoch, anchor)
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="read", operation_id=read_operation, expected_anchor=anchor)
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "read", read_operation,
                           permit, anchor, epoch, metadata.graph_revision)
        try:
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D03 self projection read permit changed")
            guarded = port.get_current_owner_guard_for_fence(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("D03 self projection Owner head unavailable")
            current = self.__self_identity_port.current_self_identity(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                request_operation_id=read_operation, permit=permit)
            if (type(current) is not AuthorityCurrentSelfIdentityV1
                    or current.permit != permit
                    or current.request_operation_id != read_operation
                    or current.graph_revision != metadata.graph_revision
                    or current.graph_epoch != epoch.revision):
                raise UnavailableGuard("D03 self projection current read differs; HOLD")
            candidate_mapping = self_identity_mapping_from_current(current)
            with store._lock:
                if self._v2_graph_stamp(namespace) != (metadata, epoch):
                    raise StaleRead("D03 self projection graph changed during read")
                db = store._db
                role, _, role_epoch, _ = self._scene_binding_state_locked(
                    namespace, guarded[0])
                if (role_epoch != epoch
                        or current.role_head_id != role.head_id
                        or current.owner_authorization_revision
                        != guarded[0].authorization_revision
                        or current.owner_authorization_head
                        != guarded[0].authorization_head
                        or current.graph_incarnation != target.graph_incarnation
                        or current.installation_id != policy.installation_id
                        or current.manifest_digest != policy.manifest_digest):
                    raise UnavailableGuard("D03 self projection current role differs; HOLD")
                job, _, _, outbox, _, _, source_version, access_version = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if (job.operation_id != original_operation_id
                        or job.phase != "queued" or job.cancel_epoch != 0
                        or job.fence != 0 or job.lease_holder is not None
                        or outbox.payload_ref != source_version.key.owner.subject):
                    raise UnavailableGuard("D03 self projection job is no longer queued; HOLD")
                source_ref = source_version.key.token
                qualification = self._original_first_ingress_qualification_locked(
                    namespace, original_operation_id, source_ref)
                arrivals = db.execute(
                    "SELECT operation_id,bundle_digest FROM "
                    "graph_d03_arrival_issuance_v2 WHERE bot=? AND persona=? "
                    "AND source_ref=?", namespace.as_tuple
                    + (source_version.key.owner.subject,),
                ).fetchall()
                if len(arrivals) != 1:
                    raise UnavailableGuard("D03 self projection needs one original arrival")
                arrival_rows = db.execute(
                    "SELECT a.token,a.revision,a.value,a.valid FROM graph_atoms AS a "
                    "JOIN graph_history AS h ON h.token=a.token AND h.revision=a.revision "
                    "WHERE h.event_bot=? AND h.event_persona=? AND h.event_id=? "
                    "AND a.type_name='d03.world_event'",
                    namespace.as_tuple + (arrivals[0][0],),
                ).fetchall()
                arrival_receipt = db.execute(
                    "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (arrivals[0][0],),
                ).fetchone()
                if len(arrival_rows) != 1 or arrival_receipt != (arrivals[0][1],):
                    raise UnavailableGuard("D03 self projection arrival receipt differs")
                event_row = arrival_rows[0]
                event_atom = GraphAtom(AtomKey.from_token(event_row[0]),
                                       event_row[1], json.loads(event_row[2]),
                                       bool(event_row[3]))
                mapping_key = self_mapping_key(namespace)
                mapping_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (mapping_key.token,),
                ).fetchone()
                mapping_atom = (GraphAtom(mapping_key, mapping_row[0],
                                          json.loads(mapping_row[1]), bool(mapping_row[2]))
                                if mapping_row else GraphAtom(mapping_key, 0, {}, False))
                perspective_key = self_perspective_key(namespace,
                    self_perspective_id(namespace, event_atom.value["scene_ref"],
                                        event_atom.key.token))
                perspective_row = db.execute(
                    "SELECT revision FROM graph_atoms WHERE token=?",
                    (perspective_key.token,),
                ).fetchone()
                identity_row = db.execute(
                    "SELECT conversation_ref FROM graph_first_ingress_identity_v1 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (original_operation_id,),
                ).fetchone()
                if identity_row is None:
                    raise UnavailableGuard("D03 self projection original ingress absent")
                guard_versions = dict(db.execute(
                    "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                    "AND persona=? AND ref='current'", namespace.as_tuple,
                ).fetchall())
                authority_epochs = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone() or (0, 0)
            if port.validate_fence(scope) != permit:
                raise UnavailableGuard("D03 self projection read permit changed")
        finally:
            port.finish_fence(scope, request_id="finish:" + read_operation,
                              request_digest="sha256:" + canonical_digest({
                                  "operation_id": read_operation,
                                  "permit_token": permit.token,
                                  "action": "finish_read",
                              }))
            self._close_stage_candidate_read(
                namespace, original_operation_id, read_operation)
        base_operation_id = d03_self_identity_projection_operation_id_v1(
            namespace, source_ref, candidate_mapping.certification_ref)
        if retry is not None and retry.retry_index == 1 and (
                retry.previous_operation_id != base_operation_id):
            raise UnavailableGuard("D03 Authority registration changed before retry; HOLD")
        operation_id = (
            d03_self_identity_projection_retry_operation_id_v2(
                namespace, source_ref, candidate_mapping.certification_ref,
                retry.previous_operation_id, retry.retry_index)
            if retry is not None else base_operation_id)
        activity_id = d03_self_identity_projection_activity_id_v1(namespace, source_ref)
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d03",), activation_generation=target.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                "host", "d11", capability, namespace, ("persona", "event"),
                "context", (identity_row[0],), grant.policy_ref,
                target.activation_generation)
            quote_id = d03_self_identity_projection_quote_id(namespace, operation_id)
            if perspective_row is not None:
                raise UnavailableGuard("D03 perspective exists without original stage receipt")
            read_versions = tuple(dict.fromkeys((
                *role.read_versions, source_version, access_version,
                GraphVersion(event_atom.key, event_atom.revision),
                GraphVersion(mapping_key, mapping_atom.revision),
                GraphVersion(perspective_key, perspective_row[0] if perspective_row else 0),
            )))
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(activity_id, None, "self-projection-attempt",
                                  D03_SELF_IDENTITY_PROJECTION_WORK_KIND,
                                  operation_id, canonical_digest({
                                      "input_refs": [source_ref]})),
                authority,
                VersionGuard(
                    read_versions, (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guard_versions["scheme"], guard_versions["operator"],
                    guard_versions["policy"], (), (), (VersionedRef(quote_id, 1),)),
                qualification, (source_ref,), grant.lease_id, deadline,
                monotonic_deadline, "character-v1", (original_operation_id,),
            )
            bundle = build_self_identity_projection_bundle(
                envelope, role, candidate_mapping, mapping_atom, event_atom)
            return self._commit_domain_bundle_v2(
                bundle, lease, self_identity_issuance=(
                    policy, admin_policy, policy.installation_id, now_utc,
                    source_ref, candidate_mapping, job_id, original_operation_id,
                    retry))
        finally:
            self.release_authority_lease(bootstrap, lease)

    def _recover_d04_baseline_before_read(
        self, namespace, original_operation_id, installation_policy,
        admin_policy,
    ) -> CommitReceipt | None:
        """Recover an original baseline write without requiring a queued job."""
        from .authority_service.v2_contract import from_wire

        store, port = self.__store, self.__content_fence_v2
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT source_ref FROM graph_first_ingress_identity_v1 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
            if identity is None:
                raise UnavailableGuard("D04 original ingress is unavailable; HOLD")
            source_ref = source_key(*namespace.as_tuple, identity[0]).token
            has_index = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d04_baseline_intents_v1'",
            ).fetchone() is not None
            indexed = (store._db.execute(
                "SELECT operation_id,bundle_digest FROM graph_d04_baseline_intents_v1 "
                "WHERE bot=? AND persona=? AND source_ref=? AND original_operation_id=?",
                namespace.as_tuple + (source_ref, original_operation_id),
            ).fetchone() if has_index else None)
            has_issued = store._db.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' "
                "AND name='graph_d04_baseline_issuance_v1'",
            ).fetchone() is not None
            issued = (store._db.execute(
                "SELECT operation_id,event_ref,quote_id,bundle_digest FROM "
                "graph_d04_baseline_issuance_v1 WHERE bot=? AND persona=? "
                "AND source_ref=?",
                namespace.as_tuple + (source_ref,),
            ).fetchall() if has_issued else [])
            if len(issued) > 1:
                raise UnavailableGuard("D04 baseline has multiple original receipts")
            if not issued and indexed is None:
                return None
            operation_id = issued[0][0] if issued else indexed[0]
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if intent is None or (indexed is not None
                                  and indexed != (operation_id, intent[0])):
                raise UnavailableGuard("D04 baseline durable intent differs")
            prior = self._get_operation_fenced(
                AuthorityContext("host", "d11", "recovery", namespace,
                                 ("persona", "event"), "context", (),
                                 installation_policy.root_grant.policy_ref,
                                 metadata.requirements.activation_generation),
                operation_id, v2=True)
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if issued:
                quote = self.__d02_issuer._load_quote(store._db, issued[0][2], 1)
                if (prior is None or saved is None
                        or issued[0][3] != prior.operation_digest
                        or saved[0] != prior.operation_digest
                        or quote.operation_id != operation_id
                        or quote.work_kind != "d04.encoding_baseline"
                        or dict(quote.ceiling) != dict(admin_policy.quote_ceiling)
                        or not any(item.key.type_name == "d04.encoding_baseline.v1"
                                   for item in prior.write_versions)):
                    raise UnavailableGuard("D04 baseline original receipt differs")
            elif prior is not None or saved is not None:
                raise UnavailableGuard("D04 baseline lacks sealed issuance")
        target = metadata.requirements
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("D04 baseline recovery anchor differs")
        if issued:
            observed, state = port.get_fence_operation(
                namespace=namespace,
                authority_namespace=target.authority_namespace,
                operation_id=intent[1])
            original_permit = from_wire(json.loads(saved[1]))
            if (observed != original_permit or state not in {"active", "finished"}
                    or original_permit.operation_id != intent[1]
                    or original_permit.pinned_anchor != anchor
                    or saved[4] != saved[2] + 1
                    or saved[5] != prior.invalidated_epochs[0].revision):
                raise UnavailableGuard("D04 baseline original fence differs")
            if state == "active":
                if (metadata.graph_revision, epoch.revision) != saved[4:6]:
                    raise UnavailableGuard("D04 baseline active graph changed")
                scope = FenceScope(
                    namespace, target.authority_namespace,
                    target.activation_generation, "write", intent[1],
                    original_permit, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original_permit:
                    raise UnavailableGuard("D04 baseline original permit changed")
                port.finish_fence(scope, request_id=saved[6],
                                  request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("D04 baseline graph receipt regressed")
            return replace(prior, status="duplicate")
        return self._reconcile_stage_retry(
            namespace, "d04", source_ref, original_operation_id,
            operation_id, intent, metadata, epoch, anchor)

    def commit_d04_encoding_baseline_v1(
        self, bootstrap: object, namespace: NamespaceId, job_id: str,
        original_operation_id: str, installation_policy, admin_policy,
        clock_policy,
    ) -> CommitReceipt:
        """Commit an unknown-valued D04 baseline from the original self view."""
        from .domains.d03.self_perspective import SelfPerspective
        from .domains.d04 import AffectProvider
        from .host.authority_profile import (
            AdminD04EncodingBaselinePolicy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.d04_baseline_retry_identity import (
            d04_baseline_retry_operation_id_v2,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import D04_BASELINE_WORK_KIND, d04_baseline_quote_id
        from .runtime_contracts import (
            CommandEnvelope, OperationIdentity, QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD04EncodingBaselinePolicy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__self_identity_port is None):
            raise UnavailableGuard("installed D04 baseline authorities required; HOLD")
        provider_entry = self.__providers.get("d04")
        if provider_entry is None or type(provider_entry[0]) is not AffectProvider:
            raise UnavailableGuard("current D04 baseline provider unavailable; HOLD")
        provider = provider_entry[0]
        policy = installation_policy
        grant = policy.root_grant
        if (policy.namespace != namespace
                or D04_BASELINE_WORK_KIND not in grant.allowed_work_kinds):
            raise UnavailableGuard("installed D04 baseline grant differs; HOLD")
        store, port = self.__store, self.__content_fence_v2
        recovered = self._recover_d04_baseline_before_read(
            namespace, original_operation_id, policy, admin_policy)
        if type(recovered) is CommitReceipt:
            return recovered
        retry = recovered if type(recovered) is _StageRetry else None
        with store._lock:
            original_metadata, _ = self._v2_graph_stamp(namespace)
            identity = store._db.execute(
                "SELECT conversation_ref FROM graph_first_ingress_identity_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (original_operation_id,),
            ).fetchone()
        if identity is None:
            raise UnavailableGuard("D04 baseline original ingress is absent; HOLD")
        original_lease, original_capability = self.grant(
            bootstrap, actor=self.__holder, issuer_domain="d11", namespace=namespace,
            domains=("d11",),
            activation_generation=original_metadata.requirements.activation_generation,
            operation_id=original_operation_id)
        try:
            original_authority = AuthorityContext(
                self.__holder, "d11", original_capability, namespace,
                ("activity",), "context", (identity[0],), grant.policy_ref,
                original_metadata.requirements.activation_generation)
            inputs = self.read_first_ingress_baseline_inputs_v1(
                original_authority, original_lease, job_id, original_operation_id)
        finally:
            self.release_authority_lease(bootstrap, original_lease)
        try:
            reading = port.read_ingress_clock(clock_policy)
            now_utc = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired D04 baseline clock unavailable; HOLD") from exc
        deadline = min(math.nextafter(math.fsum((
            now_utc, admin_policy.deadline_after_seconds)), -math.inf),
            grant.valid_until_utc)
        if deadline <= now_utc:
            raise UnavailableGuard("D04 baseline deadline unavailable; HOLD")
        monotonic_deadline = reading.monotonic_after_seconds + (
            deadline - reading.utc_upper_bound_seconds)
        if not math.isfinite(monotonic_deadline):
            raise UnavailableGuard("D04 baseline monotonic deadline differs")
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            if (metadata.graph_revision != inputs.graph_revision
                    or epoch.revision != inputs.graph_epoch):
                raise StaleRead("D04 baseline original graph changed")
            db = store._db
            perspectives = db.execute(
                "SELECT token,revision,value FROM graph_atoms WHERE bot=? "
                "AND persona=? AND type_name='d03.self_perspective.v1' AND valid=1",
                namespace.as_tuple,
            ).fetchall()
            matched = []
            for token, revision, encoded in perspectives:
                value = SelfPerspective(**json.loads(encoded))
                event_key = AtomKey.from_token(value.arrival_event_ref)
                event_row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (event_key.token,),
                ).fetchone()
                if (event_row is not None and event_row[2] == 1
                        and json.loads(event_row[1]).get("source_refs")
                        == [inputs.source_ref]):
                    matched.append((token, revision, value, event_key, event_row))
            if len(matched) != 1:
                raise UnavailableGuard("D04 baseline needs one committed self perspective")
            perspective_token, perspective_revision, perspective, event_key, event_row = (
                matched[0])
            perspective_key = AtomKey.from_token(perspective_token)
            origin = db.execute(
                "SELECT h.event_id,o.digest,i.source_ref,i.bundle_digest "
                "FROM graph_history AS h JOIN graph_bundle_operations AS o "
                "ON o.bot=h.event_bot AND o.persona=h.event_persona "
                "AND o.operation_id=h.event_id "
                "JOIN graph_d03_self_projection_issuance_v1 AS i "
                "ON i.bot=h.event_bot AND i.persona=h.event_persona "
                "AND i.operation_id=h.event_id "
                "WHERE h.token=? AND h.revision=?",
                (perspective_token, perspective_revision),
            ).fetchone()
            if (origin is None or origin[1] != origin[3]
                    or origin[2] != inputs.source_ref):
                raise UnavailableGuard("D04 baseline self perspective lacks stage receipt")
            mapping_key = AtomKey.from_token(perspective.identity_mapping_ref)
            keys = (AtomKey.from_token(inputs.source_ref),
                    access_key(*namespace.as_tuple,
                               AtomKey.from_token(inputs.source_ref).owner.subject),
                    event_key, perspective_key, mapping_key)
            atoms = []
            for key in keys:
                row = db.execute(
                    "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                    (key.token,),
                ).fetchone()
                if row is None:
                    raise UnavailableGuard("D04 baseline prerequisite graph atom absent")
                atoms.append(GraphAtom(key, row[0], json.loads(row[1]), bool(row[2])))
            snapshot = GraphSnapshot(tuple(atoms), (epoch,))
            guard_versions = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone() or (0, 0)
        base_operation_id = "d04-baseline-" + canonical_digest({
            "namespace": namespace.as_tuple, "source": inputs.source_ref,
            "event": event_key.token, "perspective": perspective_token,
            "perspective_revision": perspective_revision,
        })[:40]
        if retry is not None and retry.retry_index == 1 and (
                retry.previous_operation_id != base_operation_id):
            raise UnavailableGuard("D04 original perspective changed before retry; HOLD")
        operation_id = (
            d04_baseline_retry_operation_id_v2(
                namespace, inputs.source_ref, event_key.token,
                perspective_token, perspective_revision,
                retry.previous_operation_id, retry.retry_index)
            if retry is not None else base_operation_id)
        activity_id = "d04-baseline-activity-" + canonical_digest({
            "namespace": namespace.as_tuple, "source": inputs.source_ref,
        })[:40]
        lease, capability = self.grant(
            bootstrap, actor="host", issuer_domain="d11", namespace=namespace,
            domains=("d04",),
            activation_generation=metadata.requirements.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                "host", "d11", capability, namespace, ("persona", "event"),
                "context", (identity[0],), grant.policy_ref,
                metadata.requirements.activation_generation)
            quote_id = d04_baseline_quote_id(namespace, operation_id)
            input_refs = (inputs.source_ref, event_key.token)
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(activity_id, None, "baseline-attempt",
                                  "encoding_baseline", operation_id,
                                  canonical_digest({"input_refs": list(input_refs)})),
                authority,
                VersionGuard(
                    tuple(GraphVersion(atom.key, atom.revision) for atom in atoms),
                    (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guard_versions["scheme"], guard_versions["operator"],
                    guard_versions["policy"], (), (), (VersionedRef(quote_id, 1),)),
                inputs.qualification, input_refs, grant.lease_id,
                deadline, monotonic_deadline, "character-v1",
                (original_operation_id, origin[0]),
            )
            proposal = provider.propose_encoding_baseline(
                envelope, snapshot, source_refs=(inputs.source_ref,),
                perspective_ref=perspective_token,
                projection_policy_ref=admin_policy.snapshot_ref)
            bundle = DomainBundle(proposal.envelope, (proposal,), (), (), (), (), (), (), ())
            return self._commit_domain_bundle_v2(
                bundle, lease, baseline_issuance=(
                    admin_policy, policy.installation_id, now_utc,
                    inputs.source_ref, event_key.token, job_id, policy,
                    original_operation_id, retry))
        finally:
            self.release_authority_lease(bootstrap, lease)

    def first_ingress_c02_accounting_installed_v1(
        self, *, require_worker_result: bool = True,
    ) -> bool:
        """Whether the mandatory C02 unknown-cost continuation has its ports."""
        return (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None
                and (not require_worker_result
                     or self.__worker_result_fact_port is not None)
                and self.__model_terminal_cost_port is not None
                and self.__accounting_maintenance_port is not None
                and callable(getattr(self.__d02_issuer,
                                     "issue_c02_unknown_outcome", None))
                and callable(getattr(self.__d02_issuer,
                                     "original_c02_unknown_outcome", None))
                and self.__d11_issuer is not None)

    def recover_committed_first_ingress_c02_unknown_cost_v1(
        self, bootstrap: object, namespace: NamespaceId, operation_id: str,
        *, _terminal_pinned=None,
    ) -> None:
        """Settle a durable C02 completion without re-reading its model body.

        The Authority terminal authenticates the observation digest. A
        historical read/result digest has no independent post-finish seal, so
        this path never treats it as measured CPU use or body revalidation.
        """
        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .runtime.c02_cost_settlement import (
            C02CommittedCostProofV1, C02OriginalIntentLookupV1,
        )
        from .runtime.encoding_call_binding import binding_from_json, load_binding
        from .runtime.first_ingress_c02_identity import (
            first_ingress_c02_consumer_operation_id_v1,
        )
        from .runtime.model_cost_settlement import read_original_model_cost
        from .runtime.c02_terminal_job import _PinnedTerminalRead
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, from_wire as terminal_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
        )

        self._admin(bootstrap)
        if _terminal_pinned is not None and type(_terminal_pinned) is not _PinnedTerminalRead:
            raise UnavailableGuard("installed pinned C02 terminal fact required; HOLD")
        lookup = self.__original_c02_cost_intent_port
        if (type(namespace) is not NamespaceId or type(operation_id) is not str
                or not operation_id or not callable(lookup)
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed committed C02 recovery authorities required")
        store = self.__store
        with store._lock:
            metadata, _ = self._v2_graph_stamp(namespace)
            db = store._db
            row = db.execute(
                "SELECT activity_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("committed C02 receipt is absent; HOLD")
            detail = json.loads(row[1]).get("first_ingress_c02")
            event = db.execute(
                "SELECT revisions FROM graph_events WHERE bot=? AND persona=? "
                "AND session=? AND event_id=?",
                namespace.as_tuple + (row[0], operation_id),
            ).fetchone()
            job_writes = (() if event is None else tuple(
                version for version in GraphStore._version_rows(event[0])
                if version.key.type_name == "runtime.job"
                and version.key.owner == Owner(
                    "activity", *namespace.as_tuple, row[0])))
            if type(detail) is not dict or len(job_writes) != 1:
                raise UnavailableGuard("committed C02 job receipt differs; HOLD")
            terminal_seal = None
            if _terminal_pinned is not None:
                archived = db.execute(
                    "SELECT seal_json FROM graph_first_ingress_c02_committed_seals_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if archived is None or "terminal_read_fact_digest" not in detail:
                    raise UnavailableGuard("committed terminal C02 seal differs; HOLD")
                raw = json.loads(archived[0])
                raw["original_key"] = terminal_from_wire(
                    raw["original_key"], OriginalC02ResultKeyV1)
                terminal_seal = FrozenTerminalC02CandidateV2(**raw)
            job_id = job_writes[0].key.name
            job = db.execute(
                "SELECT operation_id,phase,lease_holder,fence "
                "FROM runtime_jobs WHERE bot_id=? AND persona_id=? "
                "AND activity_id=? AND job_id=?",
                namespace.as_tuple + (row[0], job_id),
            ).fetchone()
            if job is None or job[1:3] != ("completed", None):
                raise UnavailableGuard("committed C02 job receipt differs; HOLD")
            original_id, _, _, worker_fence = job
            acquired = db.execute(
                "SELECT i.acquire_operation_id,i.actor,i.encoding_binding_json,"
                "i.requirements_json,i.request_digest,r.request_digest,r.job_json "
                "FROM graph_job_acquire_intents_v2 AS i "
                "JOIN graph_job_acquire_receipts_v2 AS r "
                "ON r.bot=i.bot AND r.persona=i.persona "
                "AND r.acquire_operation_id=i.acquire_operation_id "
                "WHERE i.bot=? AND i.persona=? AND i.job_id=? "
                "AND i.original_operation_id=?",
                namespace.as_tuple + (job_id, original_id),
            ).fetchall()
            provision_row = self._provision_row(db, namespace)
            if provision_row is None:
                raise UnavailableGuard("C02 original installation is absent; HOLD")
            provision = self._decode_provision_receipt(provision_row)
            installed = self.__content_fence_v2.installation_grant
            if (provision.installation_id != installed.installation_id
                    or provision.authority_id != metadata.requirements.authority_id
                    or provision.authority_namespace !=
                    metadata.requirements.authority_namespace
                    or provision.generation !=
                    metadata.requirements.activation_generation):
                raise UnavailableGuard("C02 original installation differs; HOLD")
            matches = []
            for (acquire_id, actor, binding_json, requirements_json,
                 intent_digest, receipt_digest, original_job_json) in acquired:
                binding = binding_from_json(binding_json)
                frozen = binding.request
                historic = json.loads(requirements_json)
                original_job = PersistentJob(**json.loads(original_job_json))
                derived = first_ingress_c02_consumer_operation_id_v1(
                    namespace=namespace,
                    authority_id=metadata.requirements.authority_id,
                    authority_namespace=metadata.requirements.authority_namespace,
                    installation_id=provision.installation_id, job_id=job_id,
                    acquire_operation_id=acquire_id,
                    original_operation_id=original_id, call_id=binding.call_id,
                    binding_digest=binding.binding_digest,
                    model_request_digest=binding.model_request_digest)
                if derived != operation_id:
                    continue
                current = load_binding(db, namespace, job_id)
                if (binding.namespace != namespace or current != binding
                        or intent_digest != receipt_digest
                        or (original_job.job_id, original_job.operation_id,
                            original_job.activity_id, original_job.phase,
                            original_job.lease_holder, original_job.fence,
                            original_job.cancel_epoch) != (
                                job_id, original_id, row[0], "running",
                                actor, worker_fence, 0)
                        or frozen.get("schema") !=
                        "sylanne.first-ingress-encoding-call.v3"
                        or frozen.get("acquire_operation_id") != acquire_id
                        or frozen.get("original_operation_id") != original_id
                        or frozen.get("worker_fence") != worker_fence
                        or historic.get("graph_incarnation") !=
                        metadata.requirements.graph_incarnation
                        or historic.get("authority_id") !=
                        metadata.requirements.authority_id
                        or historic.get("authority_namespace") !=
                        metadata.requirements.authority_namespace):
                    raise UnavailableGuard("C02 original V3 identity differs; HOLD")
                matches.append((C02OriginalIntentLookupV1(
                    namespace, metadata.requirements.authority_id,
                    metadata.requirements.authority_namespace,
                    provision.installation_id, job_id, original_id, acquire_id,
                    binding.call_id, binding.binding_digest,
                    binding.model_request_digest, operation_id), actor))
            if len(matches) != 1:
                raise UnavailableGuard("C02 original V3 identity is ambiguous; HOLD")
            request, actor = matches[0]
            proof = C02CommittedCostProofV1(
                job_id, original_id, operation_id,
                *(detail.get(key) for key in (
                    "read_request_digest", "read_result_digest",
                    "original_intent_digest", "terminal_receipt_digest",
                    "observation_digest", "result_digest")))
        # Both Authority calls are made outside GraphStore's lock. The lookup
        # port holds the designated observer credential and returns its ledger intent.
        original_intent = lookup(request)
        if (type(original_intent) is not ModelEgressIntentV1
                or (original_intent.authority_id, original_intent.namespace,
                    original_intent.job_id, original_intent.operation_id,
                    original_intent.acquire_operation_id, original_intent.call_id,
                    original_intent.binding_digest, original_intent.request_digest,
                    original_intent.budget_reservation_operation_id,
                    original_intent.subject, original_intent.worker_fence) != (
                        request.authority_id, request.authority_namespace,
                        request.job_id, request.acquire_operation_id,
                        request.acquire_operation_id, request.call_id,
                        request.binding_digest, request.model_request_digest,
                    request.original_operation_id, actor, worker_fence)):
            raise UnavailableGuard("Authority original C02 intent differs; HOLD")
        if proof.original_intent_digest != canonical_digest(asdict(original_intent)):
            raise UnavailableGuard("Authority original C02 intent digest differs; HOLD")
        fact = read_original_model_cost(self.__model_terminal_cost_port, original_intent)
        if (fact.recovery.state != "observed"
                or proof.terminal_receipt_digest != canonical_digest(
                    asdict(fact.receipt))
                or proof.observation_digest != fact.recovery.observation_digest):
            raise UnavailableGuard("Authority original C02 terminal differs; HOLD")
        verified = (self._first_ingress_c02_duplicate_v2(
            namespace, operation_id, original_intent=original_intent,
            pinned_read=_terminal_pinned,
            request=_terminal_pinned.fact.request)
            if terminal_seal is not None else
            self._first_ingress_c02_duplicate_v1(
                namespace, operation_id, original_intent,
                terminal_receipt_digest=proof.terminal_receipt_digest))
        if verified is None:
            raise UnavailableGuard("committed C02 fence receipt is absent; HOLD")
        self._commit_first_ingress_c02_unknown_cost_v1(
            namespace, original_intent, proof, verified,
            terminal=(terminal_seal, _terminal_pinned)
            if terminal_seal is not None else None)

    def recover_committed_first_ingress_c02_unknown_cost_v2_pinned(
        self, bootstrap: object, namespace: NamespaceId, operation_id: str,
        pinned_read,
    ) -> None:
        """Settle the original terminal C02 price from a pinned v2 ACK."""
        self.recover_committed_first_ingress_c02_unknown_cost_v1(
            bootstrap, namespace, operation_id,
            _terminal_pinned=pinned_read)

    def _commit_first_ingress_c02_unknown_cost_v1(
        self, namespace: NamespaceId, original_intent, read, verified_completion,
        *, terminal=None,
    ) -> None:
        """Move completed local C02's entire upper bound to unconfirmed once."""
        from .authority_service.v2_accounting_contract import (
            AccountingMaintenanceGrantV1, AccountingMaintenanceRequestV1,
        )
        from .runtime.c02_cost_settlement import (
            C02CommittedCostProofV1,
            apply_c02_unknown_budget_in_transaction,
            apply_c02_terminal_unknown_budget_in_transaction,
            prepare_c02_unknown_cost_plan,
            prepare_c02_terminal_unknown_cost_plan,
        )
        from .runtime.d11_types import validate_d11_writes
        from .runtime.model_cost_settlement import read_original_model_cost

        if not self.first_ingress_c02_accounting_installed_v1(
                require_worker_result=(type(read) is not C02CommittedCostProofV1
                                       and terminal is None)):
            raise UnavailableGuard("C02 local accounting authority unavailable; HOLD")
        store = self.__store
        port = self.__accounting_maintenance_port
        operation_id = (read.consumer_operation_id
                        if type(read) is C02CommittedCostProofV1 else
                        read.request.consumer_operation_id)
        intent_digest = canonical_digest(asdict(original_intent))
        completion_digest = canonical_digest(asdict(verified_completion))

        def prior_locked(db):
            row = db.execute(
                "SELECT digest,activity_id,receipt_json FROM graph_bundle_operations "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (cost_operation_id,),
            ).fetchone()
            if row is None:
                return False
            data = json.loads(row[2])
            cost_ref = data.get("cost_ref")
            self.__d02_issuer.original_c02_unknown_outcome(db, quote)
            if (data.get("original_operation_id") != operation_id
                    or data.get("original_intent_digest") != intent_digest
                    or data.get("completion_digest") != completion_digest
                    or db.execute(
                        "SELECT 1 FROM graph_events WHERE bot=? AND persona=? "
                        "AND session=? AND event_id=?",
                        namespace.as_tuple + (row[1], cost_operation_id),
                    ).fetchone() is None
                    or db.execute(
                        "SELECT 1 FROM graph_atoms WHERE token=? AND valid=1",
                        (cost_ref,),
                    ).fetchone() is None
                    or db.execute(
                        "SELECT 1 FROM runtime_budget_operations WHERE bot_id=? "
                        "AND persona_id=? AND operation_id=? AND phase='settle'",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone() is None):
                raise UnavailableGuard("C02 cost receipt is incomplete or differs")
            return True

        with store._lock:
            db = store._db
            # The operation ID is stable even if accounting needs a new fence attempt.
            from .runtime.issuers import d06_first_ingress_c02_quote_id
            quote = self.__d02_issuer.original_signed_quote(
                db, d06_first_ingress_c02_quote_id(namespace, operation_id), 1)
            cost_operation_id = "c02-cost-" + canonical_digest({
                "namespace": list(namespace.as_tuple), "operation_id": operation_id,
            })[:48]
            committed = prior_locked(db)
            metadata, _ = self._v2_graph_stamp(namespace)
            attempt = db.execute(
                "SELECT intent_digest,completion_digest,attempt_id,anchor_json,state "
                "FROM graph_c02_cost_attempts_v1 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
        if committed:
            if (attempt is None or attempt[:2] != (
                    intent_digest, completion_digest) or attempt[4] != "committed"):
                raise UnavailableGuard("C02 cost lacks its original fence attempt")
            from .runtime.restore_anchor import RestoreAnchor
            port.recover_finish(AccountingMaintenanceRequestV1(
                attempt[2], original_intent, RestoreAnchor(**json.loads(attempt[3]))))
            return
        if attempt is not None and attempt[4] == "open":
            if attempt[:2] != (intent_digest, completion_digest):
                raise EventConflict("C02 accounting identity reused with different proof")
            from .runtime.restore_anchor import RestoreAnchor
            old = AccountingMaintenanceRequestV1(
                attempt[2], original_intent, RestoreAnchor(**json.loads(attempt[3])))
            try:
                port.recover_finish(old)
            except Exception:
                grant = port.begin(old)
                port.finish(old, grant)
            with store._lock:
                if prior_locked(store._db):
                    raise UnavailableGuard("C02 cost committed during recovery; retry")
                store._db.execute(
                    "UPDATE graph_c02_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND operation_id=? AND attempt_id=? "
                    "AND state='open'", namespace.as_tuple + (operation_id, attempt[2]))
        target = metadata.requirements
        if (original_intent.authority_id != target.authority_id
                or original_intent.namespace != target.authority_namespace):
            raise UnavailableGuard("C02 accounting Authority differs")
        # Network reads and Authority begin/finish stay outside GraphStore's lock.
        original_model_fact = read_original_model_cost(
            self.__model_terminal_cost_port, original_intent)
        if original_model_fact.recovery.state != "observed":
            raise UnavailableGuard("C02 original model terminal is unavailable")
        if (type(read) is C02CommittedCostProofV1
                and (read.original_intent_digest != intent_digest
                     or read.terminal_receipt_digest != canonical_digest(
                         asdict(original_model_fact.receipt)))):
            raise UnavailableGuard("C02 original terminal proof differs")
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._accounting_anchor_covers(target, anchor):
            raise UnavailableGuard("C02 accounting anchor differs")
        attempt_id = "c02-cost-fence-" + secrets.token_hex(24)
        request = AccountingMaintenanceRequestV1(attempt_id, original_intent, anchor)
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if prior_locked(db) or self._v2_graph_stamp(namespace)[0] != metadata:
                    raise StaleRead("C02 cost graph changed before fence")
                db.execute(
                    "INSERT INTO graph_c02_cost_attempts_v1"
                    "(bot,persona,operation_id,intent_digest,completion_digest,"
                    "attempt_id,anchor_json,state) VALUES(?,?,?,?,?,?,?,'open') "
                    "ON CONFLICT(bot,persona,operation_id) DO UPDATE SET "
                    "intent_digest=excluded.intent_digest,"
                    "completion_digest=excluded.completion_digest,"
                    "attempt_id=excluded.attempt_id,anchor_json=excluded.anchor_json,"
                    "state='open'",
                    namespace.as_tuple + (operation_id, intent_digest,
                    completion_digest, attempt_id, canonical_json(asdict(anchor))),
                )
                db.commit()
            except BaseException:
                db.rollback()
                raise
        grant = port.begin(request)
        terminal_digest = canonical_digest(asdict(original_model_fact.receipt))
        if (type(grant) is not AccountingMaintenanceGrantV1
                or grant.call_id != original_intent.call_id
                or grant.admission_id != original_model_fact.admission.admission_id
                or grant.observation_digest != original_model_fact.recovery.observation_digest
                or grant.terminal_receipt_digest != terminal_digest
                or grant.permit.operation_id != attempt_id
                or grant.permit.pinned_anchor != anchor):
            raise UnavailableGuard("C02 accounting grant differs")
        port.validate(request, grant)
        try:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    current, epoch = self._v2_graph_stamp(namespace)
                    if (current != metadata or prior_locked(db)
                            or not self._accounting_anchor_covers(
                                current.requirements, anchor)):
                        raise StaleRead("C02 cost graph changed")
                    if terminal is None:
                        plan = prepare_c02_unknown_cost_plan(
                            db, self.__d02_issuer, namespace, original_intent,
                            read, verified_completion)
                    else:
                        plan = prepare_c02_terminal_unknown_cost_plan(
                            db, self.__d02_issuer, namespace, original_intent,
                            terminal[0], terminal[1], verified_completion)
                    if plan.bundle_operation_id != cost_operation_id or plan.quote != quote:
                        raise EventConflict("C02 accounting plan differs")
                    if terminal is None:
                        application = apply_c02_unknown_budget_in_transaction(
                            db, self.__d02_issuer, plan, original_intent,
                            read, verified_completion)
                    else:
                        application = apply_c02_terminal_unknown_budget_in_transaction(
                            db, self.__d02_issuer, plan, namespace,
                            original_intent, terminal[0], terminal[1],
                            verified_completion)
                    write = application.cost_write
                    if not validate_d11_writes(
                            (write,), namespace, operation_id=cost_operation_id,
                            activity_id=quote.activity_id, effect_id=quote.effect_id):
                        raise UnavailableGuard("C02 cost graph write is invalid")
                    reconcile_runtime_write(db, write)
                    bundle_digest = canonical_digest({
                        "operation_id": cost_operation_id,
                        "write": asdict(write),
                        "completion_digest": completion_digest,
                    })
                    event = Event(Scope(*namespace.as_tuple, quote.activity_id),
                                  cost_operation_id, time.time(), "domain_bundle",
                                  {"bundle_digest": bundle_digest})
                    candidate = GraphCandidate(
                        event, (GraphVersion(write.key, 0),), (write,), (epoch,))
                    graph_receipt = GraphStore._graph_commit_in_transaction(
                        store, candidate, _capability=self.__graph_capability)
                    if graph_receipt.status != "committed":
                        raise EventConflict("C02 cost graph event already exists")
                    replacement = replace(
                        current.requirements,
                        deletion_seq=anchor.deletion_seq,
                        deletion_digest=anchor.deletion_digest,
                        execution_seq=anchor.execution_seq,
                        execution_digest=anchor.execution_digest,
                        revocation_epoch=anchor.revocation_epoch)
                    store.cas_graph_recovery_metadata(
                        current, replacement, _capability=self.__graph_capability)
                    seq_row = db.execute(
                        "SELECT last_seq FROM graph_bundle_sequence WHERE bot=? "
                        "AND persona=?", namespace.as_tuple).fetchone()
                    seq = (seq_row[0] if seq_row else 0) + 1
                    db.execute(
                        "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) "
                        "VALUES(?,?,?) ON CONFLICT(bot,persona) DO UPDATE SET "
                        "last_seq=excluded.last_seq", namespace.as_tuple + (seq,))
                    db.execute(
                        "INSERT INTO graph_bundle_operations"
                        "(bot,persona,operation_id,digest,activity_id,effect_id,"
                        "commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (cost_operation_id, bundle_digest,
                        quote.activity_id, quote.effect_id, seq, canonical_json({
                            "original_operation_id": operation_id,
                            "original_intent_digest": intent_digest,
                            "completion_digest": completion_digest,
                            "cost_ref": write.key.token,
                            "budget_receipt_digest": canonical_digest(
                                asdict(application.receipt)),
                        })),
                    )
                    db.execute(
                        "UPDATE graph_c02_cost_attempts_v1 SET state='committed' "
                        "WHERE bot=? AND persona=? AND operation_id=? "
                        "AND attempt_id=?", namespace.as_tuple +
                        (operation_id, attempt_id))
                    db.commit()
                except BaseException:
                    db.rollback()
                    raise
        except BaseException:
            with store._lock:
                committed = prior_locked(store._db)
            if committed:
                port.recover_finish(request)
                return
            port.finish(request, grant)
            with store._lock:
                store._db.execute(
                    "UPDATE graph_c02_cost_attempts_v1 SET state='closed' "
                    "WHERE bot=? AND persona=? AND operation_id=? "
                    "AND attempt_id=? AND state='open'",
                    namespace.as_tuple + (operation_id, attempt_id))
            raise
        port.finish(request, grant)

    @staticmethod
    def _terminal_c02_read_attempt_id_v2(request, original_key, bundle_digest):
        return "terminal-c02-read-" + canonical_digest({
            "schema": "sylanne.first-ingress-c02-terminal-attempt.v2",
            "original_read_attempt_id": request.read_attempt_id,
            "original_key": asdict(original_key),
            "consumer_operation_id": request.consumer_operation_id,
            "bundle_digest": bundle_digest,
        })[:48]

    def read_pending_first_ingress_c02_terminal_request_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str,
    ):
        """Worker-owned read of one durable, original terminal read identity."""
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed terminal C02 preflight required; HOLD")
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,graph_revision,graph_epoch "
                "FROM graph_bundle_intents_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_candidates_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            return self._first_ingress_c02_duplicate_v2(
                namespace, consumer_operation_id)
        if (intent is None or candidate is None
                or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v2"
                or candidate[1:3] != intent[:2]
                or intent[2:] != (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("terminal C02 first seal is unavailable; HOLD")
        try:
            raw = json.loads(candidate[6])
            raw["original_key"] = terminal_from_wire(
                raw["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw)
            inspection = inspect_frozen_terminal_c02_candidate_v2(
                namespace=namespace, operation_id=consumer_operation_id,
                seal=seal, bundle_json=candidate[3], quote_json=candidate[5])
            evidence = json.loads(candidate[4])
            worker_request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
            attempt_id = self._terminal_c02_read_attempt_id_v2(
                worker_request, seal.original_key, inspection.bundle.digest)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("terminal C02 durable attempt is invalid; HOLD") from exc
        if (canonical_json(evidence) != candidate[4]
                or canonical_serialize(asdict(seal)) != candidate[6]
                or inspection.bundle.digest != intent[0]
                or evidence.get("terminal_read_attempt_id") != attempt_id
                or worker_request.consumer_operation_id != consumer_operation_id
                or worker_request.namespace != namespace):
            raise UnavailableGuard("terminal C02 durable attempt differs; HOLD")
        return TerminalRecoveryReadRequestV1(
            seal.original_key, consumer_operation_id, attempt_id)

    def read_committed_first_ingress_c02_terminal_request_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str,
    ):
        """Return the original finished terminal attempt, or False for legacy cost."""
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id):
            raise UnavailableGuard("committed C02 identity required")
        with self.__store._lock:
            db = self.__store._db
            row = db.execute(
                "SELECT receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            if row is None:
                raise UnavailableGuard("committed C02 receipt absent; HOLD")
            detail = json.loads(row[0]).get("first_ingress_c02")
            if type(detail) is not dict:
                raise UnavailableGuard("committed C02 identity differs; HOLD")
            if "terminal_read_fact_digest" not in detail:
                return False
            archive = db.execute(
                "SELECT evidence_json,seal_json FROM "
                "graph_first_ingress_c02_committed_seals_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if archive is None:
            raise UnavailableGuard("committed C02 terminal seal absent; HOLD")
        try:
            evidence = json.loads(archive[0])
            raw = json.loads(archive[1])
            raw["original_key"] = terminal_from_wire(
                raw["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw)
            worker_request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
            request = TerminalRecoveryReadRequestV1(
                seal.original_key, consumer_operation_id,
                self._terminal_c02_read_attempt_id_v2(
                    worker_request, seal.original_key, seal.bundle_digest))
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("committed C02 terminal attempt invalid") from exc
        if evidence.get("terminal_read_attempt_id") != request.read_attempt_id:
            raise UnavailableGuard("committed C02 terminal attempt differs")
        self._first_ingress_c02_duplicate_v2(
            namespace, consumer_operation_id, request=request)
        return request

    def claim_pending_first_ingress_c02_terminal_read_v2(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, request,
    ) -> bool:
        """Durably mark the only permitted terminal read before any body RPC."""
        expected = self.read_pending_first_ingress_c02_terminal_request_v2(
            bootstrap, namespace, consumer_operation_id)
        if request != expected:
            raise UnavailableGuard("terminal C02 read attempt identity differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                if self.read_pending_first_ingress_c02_terminal_request_v2(
                        bootstrap, namespace, consumer_operation_id) != expected:
                    raise UnavailableGuard("terminal C02 first seal changed before read")
                db.execute("""CREATE TABLE IF NOT EXISTS
                    graph_first_ingress_c02_terminal_reads_v2 (
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, read_attempt_id TEXT NOT NULL,
                    request_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id),
                    UNIQUE(read_attempt_id))""")
                inserted = db.execute(
                    "INSERT OR IGNORE INTO graph_first_ingress_c02_terminal_reads_v2 "
                    "(bot,persona,operation_id,read_attempt_id,request_digest) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + (consumer_operation_id,
                                          expected.read_attempt_id, expected.digest),
                )
                row = db.execute(
                    "SELECT read_attempt_id,request_digest FROM "
                    "graph_first_ingress_c02_terminal_reads_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (consumer_operation_id,),
                ).fetchone()
                if row != (expected.read_attempt_id, expected.digest):
                    raise UnavailableGuard("terminal C02 read claim differs; HOLD")
                db.execute("COMMIT")
                return inserted.rowcount == 1
            except BaseException:
                db.execute("ROLLBACK")
                raise

    def recover_pending_first_ingress_c02_v2_pinned(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, installation_policy, admin_policy,
        clock_policy, pinned_query, pinned_read,
    ) -> CommitReceipt:
        """Commit one first-sealed result after its original worker lease expires."""
        from datetime import datetime

        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .host.terminal_c02_recovery_query import PinnedTerminalC02RecoveryQueryV1
        from .installation_policy import AdminInstallationPolicy
        from .runtime.c02_terminal_job import (
            OriginalC02JobLeaseV1, _PinnedTerminalRead,
        )
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
            recovery_fact_matches_frozen_v2,
        )

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str or not consumer_operation_id
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or type(pinned_query) is not PinnedTerminalC02RecoveryQueryV1
                or type(pinned_read) is not _PinnedTerminalRead
                or installation_policy.namespace != namespace
                or not self.first_ingress_c02_accounting_installed_v1(
                    require_worker_result=False)):
            raise UnavailableGuard("installed terminal C02 authorities required; HOLD")
        try:
            clock_reading = self.__content_fence_v2.read_ingress_clock(clock_policy)
            now = trusted_upper(clock_reading)
        except Exception as exc:
            raise UnavailableGuard("paired terminal C02 clock unavailable; HOLD") from exc
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_candidates_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            raise UnavailableGuard("C02 is already committed; use committed recovery")
        if (intent is None or candidate is None or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v2"
                or candidate[1:3] != intent[:2]
                or (intent[4], intent[5]) !=
                   (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("terminal C02 candidate or graph stamp differs; HOLD")
        try:
            raw_seal = json.loads(candidate[6])
            raw_seal["original_key"] = terminal_from_wire(
                raw_seal["original_key"], OriginalC02ResultKeyV1)
            seal = FrozenTerminalC02CandidateV2(**raw_seal)
            inspection = inspect_frozen_terminal_c02_candidate_v2(
                namespace=namespace, operation_id=consumer_operation_id,
                seal=seal, bundle_json=candidate[3], quote_json=candidate[5])
            evidence = json.loads(candidate[4])
            request = worker_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
        except (TypeError, ValueError, KeyError) as exc:
            raise UnavailableGuard("terminal C02 frozen bytes differ; HOLD") from exc
        bundle = inspection.bundle
        key = seal.original_key
        admin_digest = canonical_digest({
            "deadline_after_seconds": admin_policy.deadline_after_seconds,
            "quote_ceiling": dict(admin_policy.quote_ceiling),
            "snapshot_ref": admin_policy.snapshot_ref,
            "resource_ref": admin_policy.resource_ref,
        })
        local_deadline = (clock_reading.monotonic_after_seconds
                          + seal.business_deadline_utc
                          - clock_reading.utc_upper_bound_seconds)
        evidence_keys = {
            "schema", "read_request", "read_result_digest",
            "original_intent_digest", "terminal_receipt_digest",
            "observation_digest", "result_payload_digest",
            "admin_policy_digest", "installation_id", "manifest_digest",
            "source_ref", "encoding_baseline_ref", "call_id",
            "model_request_digest", "authority_operation_id", "binding_digest",
            "terminal_read_attempt_id",
        }
        if (type(evidence) is not dict or set(evidence) != evidence_keys
                or canonical_json(evidence) != candidate[4]
                or canonical_serialize(asdict(seal)) != candidate[6]
                or bundle.digest != intent[0]
                or domain_bundle_write_attempt_id_v1(
                    namespace, consumer_operation_id, bundle.digest) != intent[1]
                or evidence.get("schema") != candidate[0]
                or evidence.get("installation_id") != installation_policy.installation_id
                or evidence.get("manifest_digest") != installation_policy.manifest_digest
                or evidence.get("admin_policy_digest") != admin_digest
                or request.namespace != namespace
                or request.consumer_operation_id != consumer_operation_id
                or (request.authority_id, request.authority_namespace,
                    request.installation_id, request.job_id,
                    request.original_operation_id, request.acquire_operation_id,
                    request.call_id, request.binding_digest,
                    request.model_request_digest) !=
                   (key.authority_id, key.authority_namespace,
                    key.installation_id, key.job_id, key.original_operation_id,
                    key.acquire_operation_id, key.call_id, key.binding_digest,
                    key.model_request_digest)
                or evidence.get("original_intent_digest") != key.original_intent_digest
                or evidence.get("observation_digest") != key.observation_digest
                or evidence.get("terminal_receipt_digest") != key.terminal_receipt_digest
                or evidence.get("call_id") != key.call_id
                or evidence.get("model_request_digest") != key.model_request_digest
                or evidence.get("authority_operation_id") != key.acquire_operation_id
                or evidence.get("binding_digest") != key.binding_digest
                or evidence.get("terminal_read_attempt_id") !=
                   self._terminal_c02_read_attempt_id_v2(
                       request, key, bundle.digest)
                or pinned_query.request != pinned_read.fact.request
                or pinned_query.request.original_key != key
                or pinned_query.request.consumer_operation_id != consumer_operation_id
                or not seal.original_worker_lease_expires_utc <= now
                   < seal.business_deadline_utc
                or not math.isfinite(local_deadline)
                or time.monotonic() >= local_deadline):
            raise UnavailableGuard("terminal C02 frozen identity or deadline differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            if db.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' "
                    "AND name='graph_first_ingress_c02_terminal_reads_v2'",
            ).fetchone() is None:
                raise UnavailableGuard("terminal C02 original read was never claimed; HOLD")
            claimed = db.execute(
                "SELECT read_attempt_id,request_digest FROM "
                "graph_first_ingress_c02_terminal_reads_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if claimed != (pinned_query.request.read_attempt_id,
                       pinned_query.request.digest):
            raise UnavailableGuard("terminal C02 original read claim differs; HOLD")
        if not recovery_fact_matches_frozen_v2(
                seal=seal, fact=pinned_read.fact, trusted_now_utc=now):
            raise UnavailableGuard("terminal C02 pinned read differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            binding = load_binding(db, namespace, key.job_id)
            job = get_job(db, key.job_id)
            source_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (source_key(*namespace.as_tuple, evidence["source_ref"]).token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (access_key(*namespace.as_tuple, evidence["source_ref"]).token,),
            ).fetchone()
        if (binding is None or binding.source_id != evidence["source_ref"]
                or (job.phase, job.lease_holder, job.cancel_epoch, job.fence) != (
                    "running", bundle.envelope.authority.actor, 0,
                    bundle.envelope.authority.worker_fence)
                or datetime.fromisoformat(job.lease_expires_utc.replace(
                    "Z", "+00:00")).timestamp() !=
                   seal.original_worker_lease_expires_utc
                or source_row != (1,) or access_row != (1,)):
            raise UnavailableGuard("terminal C02 job or source differs; HOLD")
        original = OriginalC02JobLeaseV1(
            key.job_id, key.original_operation_id, key.acquire_operation_id,
            job.lease_holder, job.fence, job.cancel_epoch, job.lease_expires_utc)
        lease, capability = self.grant(
            bootstrap, actor=bundle.envelope.authority.actor,
            issuer_domain="d06", namespace=namespace, domains=("d06", "d11"),
            activation_generation=bundle.envelope.authority.activation_generation,
            operation_id=consumer_operation_id)
        try:
            if capability != bundle.envelope.authority.capability_ref:
                raise UnavailableGuard("terminal C02 process authority differs; HOLD")
            witness = _C02TerminalRecovery(
                seal, evidence, pinned_read, original, now, clock_reading,
                local_deadline, candidate[:5], candidate[3], candidate[5])
            return self._commit_domain_bundle_v2(
                bundle, lease, c02_terminal_recovery=witness)
        finally:
            self.release_authority_lease(bootstrap, lease)

    def recover_pending_first_ingress_c02_v1(
        self, bootstrap: object, namespace: NamespaceId,
        consumer_operation_id: str, installation_policy,
        admin_policy, clock_policy,
    ) -> CommitReceipt:
        """Resume one sealed C02 candidate without reopening its model result."""
        from datetime import datetime

        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_read_from_wire,
        )
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .runtime.c02_bundle_codec import (
            c02_bundle_from_wire, c02_bundle_to_wire,
        )
        from .runtime.encoding_call_binding import load_binding
        from .runtime.first_ingress_v2 import trusted_upper

        self._admin(bootstrap)
        if (type(namespace) is not NamespaceId
                or type(consumer_operation_id) is not str
                or not consumer_operation_id
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or installation_policy.namespace != namespace
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__worker_result_fact_port is None
                or self.__d11_issuer is None
                or not self.first_ingress_c02_accounting_installed_v1()):
            raise UnavailableGuard("installed pending C02 authorities required; HOLD")
        try:
            clock_reading = self.__content_fence_v2.read_ingress_clock(
                clock_policy)
            now = trusted_upper(clock_reading)
        except Exception as exc:
            raise UnavailableGuard("paired pending C02 clock unavailable; HOLD") from exc
        with self.__store._lock:
            db = self.__store._db
            metadata, epoch = self._v2_graph_stamp(namespace)
            intent = db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            candidate = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json FROM graph_first_ingress_c02_candidates_v1 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            committed = db.execute(
                "SELECT 1 FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
            rejected = db.execute(
                "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                "AND operation_id=?",
                namespace.as_tuple + (consumer_operation_id,),
            ).fetchone()
        if committed is not None:
            raise UnavailableGuard("C02 is already committed; use committed recovery")
        if (intent is None or candidate is None or rejected is not None
                or candidate[0] != "sylanne.first-ingress-c02-candidate.v1"
                or candidate[1:3] != intent[:2]
                or (intent[4], intent[5]) !=
                   (metadata.graph_revision, epoch.revision)):
            raise UnavailableGuard("pending C02 candidate or graph stamp differs; HOLD")
        try:
            bundle = c02_bundle_from_wire(candidate[3])
            evidence = json.loads(candidate[4])
            request = worker_read_from_wire(
                evidence["read_request"], WorkerModelResultReadRequestV1)
        except (KeyError, TypeError, ValueError) as exc:
            raise UnavailableGuard("pending C02 candidate wire differs; HOLD") from exc
        evidence_keys = {
            "schema", "read_request", "read_result_digest",
            "original_intent_digest", "terminal_receipt_digest",
            "observation_digest", "result_payload_digest",
            "admin_policy_digest", "installation_id", "manifest_digest",
            "source_ref", "encoding_baseline_ref", "call_id",
            "model_request_digest", "authority_operation_id", "binding_digest",
        }
        admin_digest = canonical_digest({
            "deadline_after_seconds": admin_policy.deadline_after_seconds,
            "quote_ceiling": dict(admin_policy.quote_ceiling),
            "snapshot_ref": admin_policy.snapshot_ref,
            "resource_ref": admin_policy.resource_ref,
        })
        envelope = bundle.envelope
        local_monotonic_deadline = (
            clock_reading.monotonic_after_seconds
            + (envelope.deadline_utc - clock_reading.utc_upper_bound_seconds))
        if (type(evidence) is not dict or set(evidence) != evidence_keys
                or canonical_json(evidence) != candidate[4]
                or c02_bundle_to_wire(bundle) != candidate[3]
                or bundle.digest != intent[0]
                or domain_bundle_write_attempt_id_v1(
                    namespace, consumer_operation_id, bundle.digest) != intent[1]
                or envelope.identity.phase != "first_ingress_c02"
                or envelope.identity.operation_id != consumer_operation_id
                or envelope.authority.namespace != namespace
                or request.namespace != namespace
                or request.consumer_operation_id != consumer_operation_id
                or evidence["schema"] != candidate[0]
                or evidence["installation_id"] != installation_policy.installation_id
                or evidence["manifest_digest"] != installation_policy.manifest_digest
                or evidence["admin_policy_digest"] != admin_digest
                or evidence["call_id"] != request.call_id
                or evidence["model_request_digest"] != request.model_request_digest
                or evidence["authority_operation_id"] != request.acquire_operation_id
                or evidence["binding_digest"] != request.binding_digest
                or not now < envelope.deadline_utc
                or not math.isfinite(local_monotonic_deadline)
                or time.monotonic() >= local_monotonic_deadline):
            raise UnavailableGuard("pending C02 frozen identity or deadline differs; HOLD")
        with self.__store._lock:
            db = self.__store._db
            binding = load_binding(db, namespace, request.job_id)
            job = get_job(db, request.job_id)
            source_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (source_key(*namespace.as_tuple,
                            evidence["source_ref"]).token,),
            ).fetchone()
            access_row = db.execute(
                "SELECT valid FROM graph_atoms WHERE token=?",
                (access_key(*namespace.as_tuple,
                            evidence["source_ref"]).token,),
            ).fetchone()
        if (binding is None or binding.source_id != evidence["source_ref"]
                or (job.phase, job.lease_holder, job.cancel_epoch, job.fence) != (
                    "running", envelope.authority.actor, 0,
                    envelope.authority.worker_fence)
                or datetime.fromisoformat(
                    job.lease_expires_utc.replace("Z", "+00:00")).timestamp() <= now
                or source_row != (1,) or access_row != (1,)):
            raise UnavailableGuard("pending C02 worker or source is unavailable; HOLD")
        lease, capability = self.grant(
            bootstrap, actor=envelope.authority.actor, issuer_domain="d06",
            namespace=namespace, domains=("d06", "d11"),
            activation_generation=envelope.authority.activation_generation,
            operation_id=consumer_operation_id)
        try:
            if capability != envelope.authority.capability_ref:
                raise UnavailableGuard("pending C02 process authority differs; HOLD")
            witness = _C02PendingRecovery(
                request, evidence, installation_policy, admin_policy, now,
                clock_reading, local_monotonic_deadline,
                candidate)
            return self._commit_domain_bundle_v2(
                bundle, lease, c02_recovery=witness)
        finally:
            self.release_authority_lease(bootstrap, lease)

    def commit_first_ingress_c02_v1(
        self, bootstrap: object, original_intent, read, installation_policy,
        admin_policy, clock_policy, *, _first_seal_v2: bool = False,
    ) -> CommitReceipt:
        """Adopt one finished V3 worker result through the shared D06 graph path."""
        from datetime import datetime
        from types import SimpleNamespace

        from .authority_service.v2_model_egress_contract import ModelEgressIntentV1
        from .authority_service.v2_worker_model_result_contract import WorkerModelResultReadV1
        from .domains.d04.encoding_baseline import decode_encoding_baseline
        from .domains.d06 import D06DomainAdapter, EncodingContext
        from .domains.d06.pipeline import D06MemoryPipeline
        from .host.authority_profile import (
            AdminD06FirstIngressC02Policy, AdminIngressClockPolicy,
        )
        from .installation_policy import AdminInstallationPolicy
        from .memory_repository import MemoryRepository
        from .runtime.encoding_call_binding import load_binding
        from .runtime.d11_types import (
            D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH, job_graph_write,
            runtime_job_key,
        )
        from .runtime.first_ingress_v2 import trusted_upper
        from .runtime.issuers import d06_first_ingress_c02_quote_id
        from .runtime_contracts import (
            CommandEnvelope, DependencySet, DomainProposal, OperationIdentity,
            QueryEpoch, RUNTIME_SCHEMA,
            VersionedRef,
        )

        self._admin(bootstrap)
        if (type(original_intent) is not ModelEgressIntentV1
                or type(read) is not WorkerModelResultReadV1
                or type(installation_policy) is not AdminInstallationPolicy
                or type(admin_policy) is not AdminD06FirstIngressC02Policy
                or type(clock_policy) is not AdminIngressClockPolicy
                or not isinstance(self.__store, ProductionGraphStore)
                or self.__content_fence_v2 is None
                or self.__worker_result_fact_port is None
                or self.__d11_issuer is None
                or not self.first_ingress_c02_accounting_installed_v1()):
            raise UnavailableGuard("installed first-ingress C02 authorities required; HOLD")
        read.require_original_intent(original_intent)
        request = read.request
        namespace = request.namespace
        if installation_policy.namespace != namespace:
            raise UnavailableGuard("C02 installation namespace differs; HOLD")
        duplicate = self._first_ingress_c02_duplicate_v1(
            namespace, request.consumer_operation_id, original_intent, read)
        if duplicate is not None:
            self._commit_first_ingress_c02_unknown_cost_v1(
                namespace, original_intent, read, duplicate)
            return duplicate
        try:
            reading = self.__content_fence_v2.read_ingress_clock(clock_policy)
            now = trusted_upper(reading)
        except Exception as exc:
            raise UnavailableGuard("paired C02 clock unavailable; HOLD") from exc
        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            job, _, _, outbox, _, _, source_version, access_version = (
                self._first_ingress_encoding_job_locked(namespace, request.job_id))
            binding = load_binding(store._db, namespace, request.job_id)
            if (binding is None
                    or binding.request.get("schema") !=
                    "sylanne.first-ingress-encoding-call.v3"
                    or (binding.call_id, binding.binding_digest,
                        binding.model_request_digest, binding.source_id) !=
                       (request.call_id, request.binding_digest,
                        request.model_request_digest, outbox.payload_ref)
                    or (job.operation_id, job.phase, job.lease_holder,
                        job.cancel_epoch, job.fence) !=
                       (request.original_operation_id, "running",
                        original_intent.subject, 0, original_intent.worker_fence)
                    or request.acquire_operation_id !=
                       binding.request["acquire_operation_id"]
                    or request.consumer_operation_id == job.operation_id):
                raise UnavailableGuard("C02 original V3 worker identity differs; HOLD")
            baseline = self._committed_first_ingress_baseline_locked(
                namespace, binding.source_id, metadata, epoch)
            if binding.request.get("baseline") != asdict(baseline):
                raise UnavailableGuard("C02 frozen baseline differs; HOLD")
            db = store._db
            source_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (source_version.key.token,),
            ).fetchone()
            baseline_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (baseline.baseline_ref,),
            ).fetchone()
            if source_row is None or baseline_row is None:
                raise UnavailableGuard("C02 source or baseline absent; HOLD")
            source = SourceRecord.from_dict(json.loads(source_row[0]))
            decoded = decode_encoding_baseline(json.loads(baseline_row[0]))
            perspective_key = AtomKey.from_token(decoded.perspective_ref)
            perspective_row = db.execute(
                "SELECT value FROM graph_atoms WHERE token=? AND valid=1",
                (perspective_key.token,),
            ).fetchone()
            if perspective_row is None:
                raise UnavailableGuard("C02 self perspective absent; HOLD")
            perspective = json.loads(perspective_row[0])
            event_key = AtomKey.from_token(perspective["arrival_event_ref"])
            mapping_key = AtomKey.from_token(perspective["identity_mapping_ref"])
            keys = tuple(dict.fromkeys((
                source_version.key, access_version.key, event_key,
                perspective_key, mapping_key,
                *(AtomKey.from_token(item.ref) for item in
                  decoded.then_feeling_versions),
                *(AtomKey.from_token(item.ref) for item in
                  decoded.interpretation_versions),
                AtomKey.from_token(baseline.baseline_ref),
            )))
            rows = [db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (key.token,),
            ).fetchone() for key in keys]
            if any(row is None or row[1] != 1 for row in rows):
                raise UnavailableGuard("C02 committed context changed; HOLD")
            versions = tuple(GraphVersion(key, row[0])
                             for key, row in zip(keys, rows))
            context = EncodingContext(
                event_key.token, perspective_key.token,
                tuple(item.ref for item in decoded.then_feeling_versions),
                tuple(item.ref for item in decoded.interpretation_versions),
                (), tuple((item.key.token, item.revision) for item in versions))
            qualification = self._original_first_ingress_qualification_locked(
                namespace, job.operation_id, source_version.key.token)
            job_key = runtime_job_key(*namespace.as_tuple, job.activity_id,
                                      job.job_id)
            job_row = db.execute(
                "SELECT revision,valid FROM graph_atoms WHERE token=?",
                (job_key.token,),
            ).fetchone()
            if job_row is None or job_row[1] != 1:
                raise UnavailableGuard("C02 original job projection absent; HOLD")
            authority_epochs = db.execute(
                "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                "WHERE bot=? AND persona=?", namespace.as_tuple,
            ).fetchone()
            guards = dict(db.execute(
                "SELECT kind,version FROM graph_guard_versions WHERE bot=? "
                "AND persona=? AND ref='current'", namespace.as_tuple,
            ).fetchall())
        repository = MemoryRepository(store, *namespace.as_tuple)
        # D06's preparation reads a snapshot through its repository.store.
        # Give it only coordinator-authorized reads of this same graph store;
        # ProductionGraphStore intentionally denies direct domain access.
        repository.store = SimpleNamespace(
            _registry=store._registry,
            graph_snapshot=lambda keys: GraphStore.graph_snapshot(
                store, keys, _capability=store._coordinator_capability),
            graph_epoch=lambda bot, persona: GraphStore.graph_epoch(
                store, bot, persona, _capability=store._coordinator_capability),
        )
        pipeline = D06MemoryPipeline(D06DomainAdapter(namespace), repository)
        audience = tuple(binding.request["envelope"]["authority"]["audience"])
        if len(audience) != 1:
            raise UnavailableGuard("C02 requires one original audience; HOLD")
        prepared = pipeline.prepare_worker_first_ingress_encoding(
            read, binding, source, context,
            encoding_baseline_ref=baseline.baseline_ref,
            audience=audience[0], purpose="consolidation")
        worker_expires = datetime.fromisoformat(job.lease_expires_utc.replace(
            "Z", "+00:00")).timestamp()
        deadline = min(now + admin_policy.deadline_after_seconds,
                       installation_policy.root_grant.valid_until_utc)
        if not _first_seal_v2:
            deadline = min(deadline, worker_expires)
        if deadline <= now:
            raise UnavailableGuard("C02 worker or quote deadline expired; HOLD")
        if _first_seal_v2 and deadline <= worker_expires:
            raise UnavailableGuard("C02 v2 business deadline cannot outlive worker lease; HOLD")
        operation_id = request.consumer_operation_id
        lease, capability = self.grant(
            bootstrap, actor=job.lease_holder, issuer_domain="d06",
            namespace=namespace, domains=("d06", "d11"),
            activation_generation=metadata.requirements.activation_generation,
            operation_id=operation_id)
        try:
            authority = AuthorityContext(
                job.lease_holder, "d06", capability, namespace,
                ("event", "activity"),
                "consolidation", audience,
                installation_policy.root_grant.policy_ref,
                metadata.requirements.activation_generation, job.fence)
            episode = prepared.prepared.proposal.episode
            trace = prepared.prepared.proposal.trace
            from .memory_types import episode_key, subjective_trace_v2_key
            output_versions = (
                GraphVersion(episode_key(*namespace.as_tuple,
                                         episode.episode_id), 0),
                GraphVersion(subjective_trace_v2_key(*namespace.as_tuple,
                                                     trace.trace_id), 0),
            )
            input_refs = (source_version.key.token, event_key.token,
                          baseline.baseline_ref)
            envelope = CommandEnvelope(
                RUNTIME_SCHEMA,
                OperationIdentity(job.activity_id, None, "first-ingress-c02",
                                  "first_ingress_c02", operation_id,
                                  canonical_digest({"input_refs": list(input_refs)})),
                authority,
                VersionGuard(
                    versions + (GraphVersion(job_key, job_row[0]),) + output_versions,
                    (QueryEpoch(namespace, "all", epoch.revision),),
                    *authority_epochs, store._registry.catalogue_hash,
                    guards["scheme"], guards["operator"], guards["policy"],
                    (), (), (VersionedRef(
                        d06_first_ingress_c02_quote_id(namespace, operation_id),
                        1),)),
                qualification, input_refs, job.budget_ref, deadline,
                reading.monotonic_after_seconds +
                (deadline - reading.utc_upper_bound_seconds),
                binding.request["envelope"]["character_interval_ref"],
                (job.operation_id, request.acquire_operation_id),
            )
            held = pipeline.compile_first_ingress_c02_v2(
                envelope, prepared, read,
                audience=audience[0], purpose="consolidation")
            completed_job = replace(
                job, phase="completed", result_ref=episode.episode_id,
                lease_holder=None, lease_expires_utc=None)
            job_proposal = DomainProposal(
                "d11", D11_PROPOSAL_SCHEMA, D11_PROPOSAL_SCHEMA_HASH,
                envelope, (job_graph_write(completed_job),),
                DependencySet(), (), ())
            bundle = DomainBundle(envelope, (held.proposal, job_proposal), (), (), (),
                                  (), (), (), ())
            receipt = self._commit_domain_bundle_v2(
                bundle, lease, c02_adoption=(
                    original_intent, read, binding, held, installation_policy,
                    admin_policy, now), c02_first_seal_v2=_first_seal_v2)
            verified = self._first_ingress_c02_duplicate_v1(
                namespace, operation_id, original_intent, read)
            if verified is None:
                raise UnavailableGuard("C02 content receipt missing before cost accounting")
            self._commit_first_ingress_c02_unknown_cost_v1(
                namespace, original_intent, read, verified)
            return receipt
        finally:
            self.release_authority_lease(bootstrap, lease)

    def commit_first_ingress_c02_v2(
        self, bootstrap: object, original_intent, read, installation_policy,
        admin_policy, clock_policy,
    ) -> CommitReceipt:
        """First-seal one C02 with a business deadline beyond its worker lease."""
        return self.commit_first_ingress_c02_v1(
            bootstrap, original_intent, read, installation_policy,
            admin_policy, clock_policy, _first_seal_v2=True)

    def _first_ingress_c02_duplicate_v2(
        self, namespace: NamespaceId, operation_id: str, *,
        original_intent=None, pinned_read=None, request=None,
    ) -> CommitReceipt | None:
        """Verify an exact v2 seal, business receipt and finished write fence."""
        from .authority_service.v2_contract import FencePermitV2, from_wire
        from .authority_service.v2_terminal_c02_recovery_contract import (
            OriginalC02ResultKeyV1, TerminalRecoveryReadRequestV1,
            from_wire as terminal_from_wire,
        )
        from .authority_service.v2_worker_model_result_contract import (
            WorkerModelResultReadRequestV1, from_wire as worker_from_wire,
        )
        from .runtime.c02_terminal_job import _PinnedTerminalRead
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            FrozenTerminalC02CandidateV2,
            inspect_frozen_terminal_c02_candidate_v2,
        )

        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            db = store._db
            archive = db.execute(
                "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                "evidence_json,quote_json,seal_json FROM "
                "graph_first_ingress_c02_committed_seals_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            row = db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            if archive is None:
                raise EventConflict("committed C02 v2 seal is absent")
            try:
                raw = json.loads(archive[6])
                raw["original_key"] = terminal_from_wire(
                    raw["original_key"], OriginalC02ResultKeyV1)
                seal = FrozenTerminalC02CandidateV2(**raw)
                inspection = inspect_frozen_terminal_c02_candidate_v2(
                    namespace=namespace, operation_id=operation_id, seal=seal,
                    bundle_json=archive[3], quote_json=archive[5])
                evidence = json.loads(archive[4])
                worker_request = worker_from_wire(
                    evidence["read_request"], WorkerModelResultReadRequestV1)
                data = json.loads(row[4])
                c02 = data["first_ingress_c02"]
            except (TypeError, ValueError, KeyError) as exc:
                raise UnavailableGuard("committed C02 v2 wire differs; HOLD") from exc
            expected_attempt = self._terminal_c02_read_attempt_id_v2(
                worker_request, seal.original_key, seal.bundle_digest)
            expected_request = TerminalRecoveryReadRequestV1(
                seal.original_key, operation_id, expected_attempt)
            common = {
                "read_request_digest": worker_request.digest,
                "read_result_digest": evidence["read_result_digest"],
                "original_intent_digest": seal.original_key.original_intent_digest,
                "terminal_receipt_digest": seal.original_key.terminal_receipt_digest,
                "observation_digest": seal.original_key.observation_digest,
                "result_digest": evidence["result_payload_digest"],
                "seal_schema": seal.schema,
                "original_key_digest": seal.original_key.digest,
                "signed_quote_digest": seal.quote_digest,
                "terminal_read_attempt_id": expected_attempt,
            }
            if (type(c02) is not dict or archive[0] != seal.schema
                    or archive[1] != row[0]
                    or archive[2] != domain_bundle_write_attempt_id_v1(
                        namespace, operation_id, row[0])
                    or inspection.bundle.digest != row[0]
                    or canonical_json(evidence) != archive[4]
                    or canonical_serialize(asdict(seal)) != archive[6]
                    or evidence.get("terminal_read_attempt_id") != expected_attempt
                    or worker_request.consumer_operation_id != operation_id
                    or (request is not None and request != expected_request)
                    or (original_intent is not None and
                        canonical_digest(asdict(original_intent)) !=
                        seal.original_key.original_intent_digest)):
                raise EventConflict("committed C02 v2 original identity differs")
            if "terminal_read_fact_digest" in c02:
                if (type(pinned_read) is _PinnedTerminalRead
                        and (pinned_read.fact.request != expected_request
                             or pinned_read.fact.digest != c02["terminal_read_fact_digest"])):
                    raise EventConflict("committed C02 v2 terminal fact differs")
                if (set(c02) != set(common) | {
                        "terminal_read_request_digest", "terminal_read_fact_digest"}
                        or any(c02[key] != value for key, value in common.items())
                        or c02["terminal_read_request_digest"] != expected_request.digest):
                    raise EventConflict("committed C02 v2 terminal receipt differs")
            elif c02 != {key: common[key] for key in (
                    "read_request_digest", "read_result_digest",
                    "original_intent_digest", "terminal_receipt_digest",
                    "observation_digest", "result_digest")}:
                raise EventConflict("committed C02 v2 live receipt differs")
            quote = self.__d02_issuer.original_signed_quote(
                db, seal.quote_id, seal.quote_version)
            if canonical_serialize(asdict(quote)) != archive[5]:
                raise UnavailableGuard("committed C02 v2 historical quote differs; HOLD")
            graph = db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
            fence = db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if graph is None or fence is None or fence[0] != row[0]:
                raise UnavailableGuard("committed C02 v2 graph or fence absent; HOLD")
            receipt = CommitReceipt(
                "duplicate", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]),
                GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace)
        if not self._anchor_matches(metadata.requirements, anchor):
            raise UnavailableGuard("C02 v2 replay Authority anchor differs")
        try:
            permit = from_wire(json.loads(fence[1]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("C02 v2 replay permit invalid") from exc
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, row[0])
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder
                or permit.generation != metadata.requirements.activation_generation
                or fence[4] != fence[2] + 1 or fence[5] < fence[3]
                or fence[6] != "finish:" + attempt_id
                or fence[7] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_domain_bundle",
                    "business_operation_id": operation_id,
                    "bundle_digest": row[0],
                })
                or metadata.graph_revision < fence[4]
                or epoch.revision < fence[5]):
            raise UnavailableGuard("C02 v2 replay write fence differs")
        observed, state = self.__content_fence_v2.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=permit.operation_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("C02 v2 replay Authority write state differs")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (fence[4], fence[5]):
                raise UnavailableGuard("C02 v2 replay active fence lost its graph stamp")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation,
                "write", permit.operation_id, permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, fence[3]), fence[2])
            if self.__content_fence_v2.validate_fence(scope) != permit:
                raise UnavailableGuard("C02 v2 replay active write permit differs")
            self.__content_fence_v2.finish_fence(
                scope, request_id=fence[6], request_digest=fence[7])
        return receipt

    def _first_ingress_c02_duplicate_v1(
        self, namespace: NamespaceId, operation_id: str, original_intent, read=None,
        *, terminal_receipt_digest: str | None = None,
    ) -> CommitReceipt | None:
        """Replay a committed C02 from its result or terminal and graph receipts."""
        from .authority_service.v2_contract import FencePermitV2, from_wire

        store = self.__store
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            row = store._db.execute(
                "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            if row is None:
                return None
            data = json.loads(row[4])
            c02 = data.get("first_ingress_c02")
            expected_c02 = (
                {"read_request_digest": read.request.digest,
                 "read_result_digest": canonical_digest(asdict(read)),
                 "original_intent_digest": canonical_digest(asdict(original_intent)),
                 "terminal_receipt_digest": canonical_digest(
                     asdict(read.terminal_receipt)),
                 "observation_digest": read.observation.digest,
                 "result_digest": canonical_digest(read.observation.result)}
                if read is not None else None)
            if (not isinstance(c02, dict)
                    or set(c02) != {
                        "read_request_digest", "read_result_digest",
                        "original_intent_digest", "terminal_receipt_digest",
                        "observation_digest", "result_digest"}
                    or (c02 != expected_c02 if read is not None else
                        c02["original_intent_digest"] != canonical_digest(
                            asdict(original_intent))
                        or c02["terminal_receipt_digest"] != terminal_receipt_digest
                        or any(type(value) is not str or len(value) != 64
                               or any(char not in "0123456789abcdef" for char in value)
                               for value in c02.values()))):
                raise EventConflict("C02 operation ID reused with different original result")
            graph = store._db.execute(
                "SELECT reads,revisions,epoch_revision FROM graph_events "
                "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                namespace.as_tuple + (row[1], operation_id),
            ).fetchone()
            fence = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,"
                "finish_request_digest FROM graph_bundle_fences_v2 WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            if graph is None or fence is None or fence[0] != row[0]:
                raise UnavailableGuard("C02 committed graph or fence receipt is absent")
            receipt = CommitReceipt(
                "duplicate", operation_id, row[0], row[1], row[2], row[3],
                GraphStore._version_rows(graph[0]),
                GraphStore._version_rows(graph[1]),
                (NamespaceEpoch(*namespace.as_tuple, graph[2]),),
                tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
            )
        anchor = self.__content_fence_v2.current_anchor(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace)
        if not self._anchor_matches(metadata.requirements, anchor):
            raise UnavailableGuard("C02 replay Authority anchor differs")
        try:
            permit = from_wire(json.loads(fence[1]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("C02 replay write permit is invalid") from exc
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, row[0])
        if (type(permit) is not FencePermitV2 or permit.operation != "write"
                or permit.operation_id != attempt_id
                or permit.pinned_anchor != anchor or permit.holder != self.__holder
                or permit.generation != metadata.requirements.activation_generation
                or fence[4] != fence[2] + 1
                or fence[5] < fence[3]
                or fence[6] != "finish:" + attempt_id
                or fence[7] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "finish_domain_bundle",
                    "business_operation_id": operation_id,
                    "bundle_digest": row[0],
                })
                or metadata.graph_revision < fence[4]
                or epoch.revision < fence[5]):
            raise UnavailableGuard("C02 replay graph write fence differs")
        observed, state = self.__content_fence_v2.get_fence_operation(
            namespace=namespace,
            authority_namespace=metadata.requirements.authority_namespace,
            operation_id=permit.operation_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("C02 replay Authority write state differs")
        if state == "active":
            if (metadata.graph_revision, epoch.revision) != (fence[4], fence[5]):
                raise UnavailableGuard("C02 replay active fence lost its graph stamp")
            scope = FenceScope(
                namespace, metadata.requirements.authority_namespace,
                metadata.requirements.activation_generation,
                "write", permit.operation_id, permit, anchor,
                NamespaceEpoch(*namespace.as_tuple, fence[3]), fence[2])
            if self.__content_fence_v2.validate_fence(scope) != permit:
                raise UnavailableGuard("C02 replay active write permit differs")
            self.__content_fence_v2.finish_fence(
                scope, request_id=fence[6], request_digest=fence[7])
        return receipt

    def commit_domain_bundle(self, bundle: DomainBundle, lease: object) -> CommitReceipt:
        if not isinstance(bundle, DomainBundle):
            raise TypeError("bundle must be DomainBundle")
        authority = bundle.envelope.authority
        self._authorize(lease, authority,
                        frozenset(proposal.domain for proposal in bundle.proposals))
        if (isinstance(self.__store, ProductionGraphStore)
                and self.__content_fence_v2 is not None):
            return self._commit_domain_bundle_v2(bundle, lease)
        with self._content_fence(authority.namespace, authority.activation_generation, "write"):
            store = self.__store
            with store._lock:
                self._admit_content(
                    authority.namespace, authority.activation_generation, "write",
                    tuple(item.key.token for item in bundle.envelope.version_guard.read_versions)
                    + tuple(write.key.token for proposal in bundle.proposals
                            for write in proposal.typed_writes),
                )
            return self._commit_domain_bundle_fenced(bundle, lease)

    def _validate_first_ingress_c02_terminal_locked(
        self, db, bundle, witness: _C02TerminalRecovery, job, seal, fact,
        v2_write,
    ) -> bool:
        """Check the original result, source and settled cost inside the write fence."""
        from .runtime.encoding_call_binding import binding_to_json, load_binding
        from .runtime.model_cost_settlement import OriginalModelCostCommitV1
        from .runtime.terminal_c02_recovery_candidate_v2 import (
            recovery_fact_matches_frozen_v2,
        )
        from .runtime.d11_types import job_graph_write

        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        key = seal.original_key
        evidence = witness.evidence
        if (v2_write is None or witness.seal != seal
                or fact != witness.pinned_read.fact
                or not recovery_fact_matches_frozen_v2(
                    seal=seal, fact=fact, trusted_now_utc=witness.now)
                or len(bundle.proposals) != 2
                or tuple(proposal.domain for proposal in bundle.proposals)
                   != ("d06", "d11")
                or len(bundle.proposals[1].typed_writes) != 1
                or envelope.identity.operation_id != seal.consumer_operation_id
                or envelope.authority.actor != witness.original.holder
                or envelope.authority.worker_fence != witness.original.fence
                or evidence.get("original_intent_digest") != key.original_intent_digest
                or evidence.get("observation_digest") != key.observation_digest
                or evidence.get("terminal_receipt_digest") != key.terminal_receipt_digest):
            raise UnavailableGuard("terminal C02 original result differs; HOLD")
        binding = load_binding(db, namespace, key.job_id)
        acquire = db.execute(
            "SELECT i.job_id,i.original_operation_id,i.actor,"
            "i.encoding_binding_json,i.graph_revision,i.graph_epoch "
            "FROM graph_job_acquire_intents_v2 AS i "
            "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
            namespace.as_tuple + (key.acquire_operation_id,),
        ).fetchone()
        if (binding is None or acquire is None
                or acquire[:4] != (key.job_id, key.original_operation_id,
                                    witness.original.holder, binding_to_json(binding))
                or binding.request.get("schema") !=
                   "sylanne.first-ingress-encoding-call.v3"
                or (binding.call_id, binding.binding_digest,
                    binding.model_request_digest) !=
                   (key.call_id, key.binding_digest, key.model_request_digest)
                or (job.bot_id, job.persona_id, job.operation_id,
                    job.activity_id, job.phase, job.lease_holder,
                    job.fence, job.cancel_epoch, job.result_ref) !=
                   (*namespace.as_tuple, key.original_operation_id,
                    envelope.identity.activity_id, "running",
                    witness.original.holder, witness.original.fence, 0, None)):
            raise UnavailableGuard("terminal C02 original binding or job differs; HOLD")
        expected_job = replace(
            job, phase="completed",
            result_ref=bundle.proposals[0].typed_writes[0].value["episode_id"],
            lease_holder=None, lease_expires_utc=None)
        if bundle.proposals[1].typed_writes[0] != job_graph_write(expected_job):
            raise UnavailableGuard("terminal C02 graph job projection differs; HOLD")
        metadata, epoch = self._v2_graph_stamp(namespace)
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=acquire[4:6])
        if (binding.request.get("baseline") != asdict(baseline)
                or evidence.get("encoding_baseline_ref") != baseline.baseline_ref
                or evidence.get("source_ref") != binding.source_id
                or envelope.input_refs[0] != source_key(
                    *namespace.as_tuple, binding.source_id).token):
            raise UnavailableGuard("terminal C02 committed source or baseline differs; HOLD")
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        source = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (envelope.input_refs[0],),
        ).fetchone()
        access = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (access_key(*namespace.as_tuple, binding.source_id).token,),
        ).fetchone()
        if (epochs != (envelope.version_guard.access_epoch,
                       envelope.version_guard.delete_epoch)
                or source != (binding.source_revision, 1)
                or access != (binding.access_revision, 1)):
            raise UnavailableGuard("terminal C02 current source access differs; HOLD")
        cost_operation_id = "model-cost-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "call_id": binding.call_id,
        })[:48]
        cost_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (cost_operation_id,),
        ).fetchone()
        if cost_row is None:
            raise UnavailableGuard("terminal C02 original model cost absent; HOLD")
        cost = OriginalModelCostCommitV1(
            **json.loads(cost_row[0])["original_model_cost"])
        if (cost.status != "committed" or cost.call_id != binding.call_id
                or cost.terminal_receipt_digest != key.terminal_receipt_digest
                or db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone() != ("settled",)):
            raise UnavailableGuard("terminal C02 original cost differs; HOLD")
        return True

    def _validate_first_ingress_c02_adoption_locked(
        self, db, bundle, adoption, v2_write,
    ) -> None:
        """Join the Authority finished-read fact to current graph and cost."""
        from datetime import datetime

        from .runtime.encoding_call_binding import binding_to_json, load_binding
        from .runtime.model_cost_settlement import OriginalModelCostCommitV1

        witness, fact, permit = adoption
        recovery = isinstance(witness, _C02PendingRecovery)
        if recovery:
            from .runtime.first_ingress_v2 import trusted_upper

            request = witness.request
            evidence = witness.evidence
            installation = witness.installation
            now = trusted_upper(witness.clock_reading)
            if (now >= bundle.envelope.deadline_utc
                    or time.monotonic() >= witness.local_monotonic_deadline):
                raise UnavailableGuard("pending C02 deadline expired; HOLD")
            held = None
        else:
            original_intent, read, binding, held, installation, _admin, now = witness
            request = read.request
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        if (v2_write is None or len(bundle.proposals) != 2
                or (not recovery and bundle.proposals[0] != held.proposal)
                or bundle.proposals[0].domain != "d06"
                or bundle.proposals[1].domain != "d11"
                or len(bundle.proposals[1].typed_writes) != 1
                or (not recovery and held.status != "candidate_hold")
                or request.namespace != namespace
                or request.consumer_operation_id != envelope.identity.operation_id
                or request.installation_id != installation.installation_id
                or fact.read_request != request
                or fact.write_permit != permit
                or fact.bundle_digest != bundle.digest
                or (fact.result_digest != evidence["read_result_digest"]
                    if recovery else
                    fact.result_digest != canonical_digest(asdict(read)))
                or (fact.original_intent_digest != evidence["original_intent_digest"]
                    if recovery else
                    fact.original_intent_digest != canonical_digest(
                        asdict(original_intent)))
                or (canonical_digest(asdict(fact.terminal_receipt))
                    != evidence["terminal_receipt_digest"] if recovery else
                    fact.terminal_receipt != read.terminal_receipt)
                or (fact.terminal_receipt.observation_digest
                    != evidence["observation_digest"] if recovery else
                    held.observation_digest != read.observation.digest)
                or (evidence["call_id"] != request.call_id
                    if recovery else held.call_id != request.call_id)
                or (evidence["model_request_digest"] != request.model_request_digest
                    if recovery else held.request_digest != request.model_request_digest)
                or (evidence["authority_operation_id"] != request.acquire_operation_id
                    if recovery else held.authority_operation_id != request.acquire_operation_id)
                or (not recovery and held.result_digest !=
                    canonical_digest(read.observation.result))):
            raise UnavailableGuard("C02 Authority result or held proposal differs; HOLD")
        if not recovery:
            read.require_original_intent(original_intent)
        job = get_job(db, request.job_id)
        current_binding = load_binding(db, namespace, request.job_id)
        if recovery:
            binding = current_binding
        acquire = db.execute(
            "SELECT i.job_id,i.original_operation_id,i.actor,"
            "i.encoding_binding_json,i.graph_revision,i.graph_epoch,"
            "r.job_json FROM graph_job_acquire_intents_v2 AS i "
            "JOIN graph_job_acquire_receipts_v2 AS r "
            "ON r.bot=i.bot AND r.persona=i.persona "
            "AND r.acquire_operation_id=i.acquire_operation_id "
            "WHERE i.bot=? AND i.persona=? AND i.acquire_operation_id=?",
            namespace.as_tuple + (request.acquire_operation_id,),
        ).fetchone()
        if (current_binding is None or current_binding != binding or acquire is None
                or acquire[:4] != (
                    request.job_id, request.original_operation_id,
                    envelope.authority.actor, binding_to_json(binding))
                or binding.request.get("schema") !=
                "sylanne.first-ingress-encoding-call.v3"
                or (binding.call_id, binding.binding_digest,
                    binding.model_request_digest) != (
                    request.call_id, request.binding_digest,
                    request.model_request_digest)
                or (job.bot_id, job.persona_id, job.operation_id,
                    job.activity_id, job.phase, job.lease_holder,
                    job.fence, job.cancel_epoch, job.result_ref) != (
                    *namespace.as_tuple, request.original_operation_id,
                    envelope.identity.activity_id, "running",
                    envelope.authority.actor, envelope.authority.worker_fence,
                    0, None)
                or json.loads(acquire[6]) != asdict(job)
                or datetime.fromisoformat(job.lease_expires_utc.replace(
                    "Z", "+00:00")).timestamp() <= now):
            raise UnavailableGuard("C02 original V3 worker or acquire differs; HOLD")
        from .runtime.d11_types import job_graph_write

        expected_job = replace(
            job, phase="completed",
            result_ref=bundle.proposals[0].typed_writes[0].value["episode_id"],
            lease_holder=None, lease_expires_utc=None)
        if bundle.proposals[1].typed_writes[0] != job_graph_write(expected_job):
            raise UnavailableGuard("C02 completed job projection differs; HOLD")
        metadata, epoch = self._v2_graph_stamp(namespace)
        baseline = self._committed_first_ingress_baseline_locked(
            namespace, binding.source_id, metadata, epoch,
            acquire_stamp=acquire[4:6])
        if (binding.request.get("baseline") != asdict(baseline)
                or (evidence["encoding_baseline_ref"] != baseline.baseline_ref
                    if recovery else held.encoding_baseline_ref != baseline.baseline_ref)
                or (evidence["source_ref"] != binding.source_id
                    if recovery else held.source_ref != binding.source_id)
                or envelope.input_refs[0] != source_key(
                    *namespace.as_tuple, binding.source_id).token):
            raise UnavailableGuard("C02 committed source or baseline differs; HOLD")
        epochs = db.execute(
            "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
            "WHERE bot=? AND persona=?", namespace.as_tuple,
        ).fetchone()
        source = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (envelope.input_refs[0],),
        ).fetchone()
        access = db.execute(
            "SELECT revision,valid FROM graph_atoms WHERE token=?",
            (access_key(*namespace.as_tuple, binding.source_id).token,),
        ).fetchone()
        if (epochs != (envelope.version_guard.access_epoch,
                       envelope.version_guard.delete_epoch)
                or source != (binding.source_revision, 1)
                or access != (binding.access_revision, 1)):
            raise UnavailableGuard("C02 source access or epoch changed; HOLD")
        cost_operation_id = "model-cost-" + canonical_digest({
            "namespace": list(namespace.as_tuple), "call_id": binding.call_id,
        })[:48]
        cost_row = db.execute(
            "SELECT receipt_json FROM graph_bundle_operations "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (cost_operation_id,),
        ).fetchone()
        if cost_row is None:
            raise UnavailableGuard("C02 original model cost is absent; HOLD")
        cost = OriginalModelCostCommitV1(
            **json.loads(cost_row[0])["original_model_cost"])
        if (cost.status != "committed"
                or cost.call_id != binding.call_id
                or cost.terminal_receipt_digest != canonical_digest(
                    asdict(fact.terminal_receipt))
                or db.execute(
                    "SELECT state FROM runtime_budget_reservations "
                    "WHERE lease_id=? AND operation_id=?",
                    (job.budget_ref, job.operation_id),
                ).fetchone() != ("settled",)):
            raise UnavailableGuard("C02 original terminal cost differs; HOLD")

    def _stage_retry_intent_locked(self, db, namespace, stage, source_ref,
                                   original_operation_id, operation_id, digest,
                                   retry: _StageRetry) -> None:
        """CAS the current stage head while retaining the rejected predecessor."""
        table = ("graph_d03_self_projection_intents_v1" if stage == "d03" else
                 "graph_d04_baseline_intents_v1")
        old = db.execute(
            f"SELECT operation_id,bundle_digest FROM {table} "
            "WHERE bot=? AND persona=? AND source_ref=? "
            "AND original_operation_id=?",
            namespace.as_tuple + (source_ref, original_operation_id),
        ).fetchone()
        previous_intent = db.execute(
            "SELECT digest,fence_attempt_id FROM graph_bundle_intents_v2 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        previous_rejection = db.execute(
            "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
            "finish_request_id,finish_request_digest "
            "FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
            "AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        if (old != (retry.previous_operation_id, retry.previous_bundle_digest)
                or previous_intent != (retry.previous_bundle_digest,
                                       retry.previous_attempt_id)
                or previous_rejection is None
                or previous_rejection[1] != "rejected_no_commit"
                or canonical_digest(list(previous_rejection))
                != retry.previous_rejection_digest
                or db.execute(
                    "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (retry.previous_operation_id,),
                ).fetchone() is not None
                or db.execute(
                    "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (retry.previous_operation_id,),
                ).fetchone() is not None):
            raise EventConflict("stage retry predecessor is not a rejected no-commit")
        db.execute("""CREATE TABLE IF NOT EXISTS graph_stage_retry_lineage_v1(
            bot TEXT NOT NULL, persona TEXT NOT NULL,
            stage TEXT NOT NULL CHECK(stage IN ('d03','d04')),
            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
            operation_id TEXT NOT NULL, previous_operation_id TEXT NOT NULL,
            retry_index INTEGER NOT NULL CHECK(retry_index > 0),
            previous_bundle_digest TEXT NOT NULL,
            previous_attempt_id TEXT NOT NULL,
            previous_rejection_digest TEXT NOT NULL,
            PRIMARY KEY(bot,persona,operation_id),
            UNIQUE(bot,persona,stage,source_ref,original_operation_id,retry_index))""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_stage_retry_lineage_no_update_v1
            BEFORE UPDATE ON graph_stage_retry_lineage_v1
            BEGIN SELECT RAISE(ABORT, 'stage retry lineage is immutable'); END""")
        db.execute("""CREATE TRIGGER IF NOT EXISTS graph_stage_retry_lineage_no_delete_v1
            BEFORE DELETE ON graph_stage_retry_lineage_v1
            BEGIN SELECT RAISE(ABORT, 'stage retry lineage is immutable'); END""")
        predecessor = db.execute(
            "SELECT retry_index FROM graph_stage_retry_lineage_v1 "
            "WHERE bot=? AND persona=? AND operation_id=?",
            namespace.as_tuple + (retry.previous_operation_id,),
        ).fetchone()
        if retry.retry_index != (predecessor[0] + 1 if predecessor else 1):
            raise EventConflict("stage retry ordinal is not consecutive")
        if retry.retry_index > 64:
            raise UnavailableGuard("stage retry bound reached; HOLD")
        db.execute(
            "INSERT INTO graph_stage_retry_lineage_v1"
            "(bot,persona,stage,source_ref,original_operation_id,operation_id,"
            "previous_operation_id,retry_index,previous_bundle_digest,"
            "previous_attempt_id,previous_rejection_digest) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            namespace.as_tuple + (
                stage, source_ref, original_operation_id, operation_id,
                retry.previous_operation_id, retry.retry_index,
                retry.previous_bundle_digest, retry.previous_attempt_id,
                retry.previous_rejection_digest),
        )
        updated = db.execute(
            f"UPDATE {table} SET operation_id=?,bundle_digest=? "
            "WHERE bot=? AND persona=? AND source_ref=? "
            "AND original_operation_id=? AND operation_id=? AND bundle_digest=?",
            (operation_id, digest) + namespace.as_tuple
            + (source_ref, original_operation_id,
               retry.previous_operation_id, retry.previous_bundle_digest),
        )
        if updated.rowcount != 1:
            raise EventConflict("stage retry head changed")

    def _commit_domain_bundle_v2(self, bundle: DomainBundle,
                                 lease: object, *, arrival_issuance=None,
                                 attention_issuance=None,
                                 baseline_issuance=None,
                                 self_identity_issuance=None,
                                 correction_issuance=None,
                                  c02_adoption=None,
                                  c02_recovery: _C02PendingRecovery | None = None,
                                  c02_terminal_recovery: _C02TerminalRecovery | None = None,
                                  c02_first_seal_v2: bool = False) -> CommitReceipt:
        """Commit under a durable write attempt; reconcile before any duplicate read."""
        from .authority_service.v2_contract import FencePermitV2, from_wire, to_wire

        store = self.__store
        port = self.__content_fence_v2
        authority = bundle.envelope.authority
        namespace = authority.namespace
        operation_id = bundle.envelope.identity.operation_id
        digest = bundle.digest
        if sum(item is not None for item in (
                c02_adoption, c02_recovery, c02_terminal_recovery)) > 1:
            raise ValueError("C02 cannot mix original adoption and recovery")
        if c02_first_seal_v2 and (c02_adoption is None or c02_recovery is not None
                                  or c02_terminal_recovery is not None):
            raise ValueError("C02 v2 first seal requires original adoption")
        if c02_terminal_recovery is not None and c02_terminal_recovery.seal.bundle_digest != digest:
            raise EventConflict("terminal C02 frozen bundle differs")
        c02_witness = (c02_terminal_recovery if c02_terminal_recovery is not None
                       else c02_recovery if c02_recovery is not None else c02_adoption)
        if (bundle.envelope.identity.phase == "first_ingress_c02") != (
                c02_witness is not None):
            raise UnavailableGuard("C02 requires its installed result adoption; HOLD")
        attempt_id = domain_bundle_write_attempt_id_v1(
            namespace, operation_id, digest)
        c02_candidate = None
        c02_first_seal_key = None
        if c02_terminal_recovery is not None:
            c02_candidate = c02_terminal_recovery.sealed_candidate
        elif c02_recovery is not None:
            c02_candidate = c02_recovery.sealed_candidate
        elif c02_adoption is not None:
            from .authority_service.v2_worker_model_result_contract import (
                to_wire as worker_read_to_wire,
            )
            from .runtime.c02_bundle_codec import (
                c02_bundle_from_wire, c02_bundle_to_wire,
            )
            if c02_first_seal_v2:
                from .authority_service.v2_terminal_c02_recovery_contract import (
                    OriginalC02ResultKeyV1,
                )

            original_intent, read, binding, held, installation, admin, _ = (
                c02_adoption)
            evidence = {
                "schema": ("sylanne.first-ingress-c02-candidate.v2"
                           if c02_first_seal_v2 else
                           "sylanne.first-ingress-c02-candidate.v1"),
                "read_request": worker_read_to_wire(read.request),
                "read_result_digest": canonical_digest(asdict(read)),
                "original_intent_digest": canonical_digest(asdict(original_intent)),
                "terminal_receipt_digest": canonical_digest(
                    asdict(read.terminal_receipt)),
                "observation_digest": held.observation_digest,
                "result_payload_digest": held.result_digest,
                "admin_policy_digest": canonical_digest({
                    "deadline_after_seconds": admin.deadline_after_seconds,
                    "quote_ceiling": dict(admin.quote_ceiling),
                    "snapshot_ref": admin.snapshot_ref,
                    "resource_ref": admin.resource_ref,
                }),
                "installation_id": installation.installation_id,
                "manifest_digest": installation.manifest_digest,
                "source_ref": held.source_ref,
                "encoding_baseline_ref": held.encoding_baseline_ref,
                "call_id": held.call_id,
                "model_request_digest": held.request_digest,
                "authority_operation_id": held.authority_operation_id,
                "binding_digest": binding.binding_digest,
            }
            if c02_first_seal_v2:
                request = read.request
                c02_first_seal_key = OriginalC02ResultKeyV1(
                    request.authority_id, request.authority_namespace,
                    request.namespace, request.installation_id, request.job_id,
                    request.original_operation_id, request.acquire_operation_id,
                    request.acquire_operation_id, request.call_id,
                    request.binding_digest, request.model_request_digest,
                    evidence["original_intent_digest"],
                    evidence["observation_digest"],
                    evidence["terminal_receipt_digest"])
                evidence["terminal_read_attempt_id"] = (
                    self._terminal_c02_read_attempt_id_v2(
                        request, c02_first_seal_key, digest))
            bundle_json = c02_bundle_to_wire(bundle)
            if (type(bundle_json) is not str
                    or c02_bundle_from_wire(bundle_json) != bundle):
                raise UnavailableGuard("C02 candidate bundle codec differs; HOLD")
            c02_candidate = (
                evidence["schema"], digest, attempt_id, bundle_json,
                canonical_json(evidence))
        with store._lock:
            metadata, epoch = self._v2_graph_stamp(namespace)
            prior = store._db.execute(
                "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (operation_id,),
            ).fetchone()
            saved = store._db.execute(
                "SELECT digest,permit_json,pre_graph_revision,pre_graph_epoch,"
                "post_graph_revision,post_graph_epoch,finish_request_id,finish_request_digest "
                "FROM graph_bundle_fences_v2 WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            intent = store._db.execute(
                "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
            rejection = store._db.execute(
                "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                "finish_request_id,finish_request_digest FROM graph_bundle_rejections_v2 "
                "WHERE bot=? AND persona=? AND operation_id=?",
                namespace.as_tuple + (operation_id,),
            ).fetchone()
        target = metadata.requirements
        if target.namespace != namespace or target.activation_generation != authority.activation_generation:
            raise UnavailableGuard("v2 graph recovery identity or generation differs")
        anchor = port.current_anchor(
            namespace=namespace, authority_namespace=target.authority_namespace)
        if not self._anchor_matches(target, anchor):
            raise UnavailableGuard("v2 graph recovery anchor differs")
        requirements_json = canonical_json(asdict(target))
        anchor_json = canonical_json(asdict(anchor))
        if c02_terminal_recovery is not None and intent is None:
            raise UnavailableGuard("terminal C02 durable first-seal intent is absent; HOLD")
        if intent is None and prior is None:
            with store._lock:
                db = store._db
                db.execute("BEGIN IMMEDIATE")
                try:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("v2 graph recovery stamp changed before intent")
                    if self_identity_issuance is not None:
                        db.execute("""CREATE TABLE IF NOT EXISTS graph_d03_self_projection_intents_v1(
                            bot TEXT NOT NULL, persona TEXT NOT NULL,
                            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
                            operation_id TEXT NOT NULL, bundle_digest TEXT NOT NULL,
                            PRIMARY KEY(bot,persona,source_ref,original_operation_id))""")
                        if self_identity_issuance[8] is None:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_d03_self_projection_intents_v1"
                                "(bot,persona,source_ref,original_operation_id,"
                                "operation_id,bundle_digest) VALUES(?,?,?,?,?,?)",
                                namespace.as_tuple + (self_identity_issuance[4],
                                                      self_identity_issuance[7],
                                                      operation_id, digest),
                            )
                        else:
                            self._stage_retry_intent_locked(
                                db, namespace, "d03", self_identity_issuance[4],
                                self_identity_issuance[7], operation_id, digest,
                                self_identity_issuance[8])
                        indexed = db.execute(
                            "SELECT operation_id,bundle_digest FROM "
                            "graph_d03_self_projection_intents_v1 WHERE bot=? AND persona=? "
                            "AND source_ref=? AND original_operation_id=?",
                            namespace.as_tuple + (self_identity_issuance[4],
                                                  self_identity_issuance[7]),
                        ).fetchone()
                        if indexed != (operation_id, digest):
                            raise EventConflict("D03 self stage recovery identity differs")
                    if baseline_issuance is not None:
                        db.execute("""CREATE TABLE IF NOT EXISTS graph_d04_baseline_intents_v1(
                            bot TEXT NOT NULL, persona TEXT NOT NULL,
                            source_ref TEXT NOT NULL, original_operation_id TEXT NOT NULL,
                            operation_id TEXT NOT NULL, bundle_digest TEXT NOT NULL,
                            PRIMARY KEY(bot,persona,source_ref,original_operation_id))""")
                        if baseline_issuance[8] is None:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_d04_baseline_intents_v1"
                                "(bot,persona,source_ref,original_operation_id,"
                                "operation_id,bundle_digest) VALUES(?,?,?,?,?,?)",
                                namespace.as_tuple + (baseline_issuance[3],
                                                      baseline_issuance[7],
                                                      operation_id, digest),
                            )
                        else:
                            self._stage_retry_intent_locked(
                                db, namespace, "d04", baseline_issuance[3],
                                baseline_issuance[7], operation_id, digest,
                                baseline_issuance[8])
                        indexed = db.execute(
                            "SELECT operation_id,bundle_digest FROM "
                            "graph_d04_baseline_intents_v1 WHERE bot=? AND persona=? "
                            "AND source_ref=? AND original_operation_id=?",
                            namespace.as_tuple + (baseline_issuance[3],
                                                  baseline_issuance[7]),
                        ).fetchone()
                        if indexed != (operation_id, digest):
                            raise EventConflict("D04 baseline recovery identity differs")
                    db.execute(
                        "INSERT OR IGNORE INTO graph_bundle_intents_v2"
                        "(bot,persona,operation_id,digest,fence_attempt_id,"
                        "requirements_json,anchor_json,graph_revision,graph_epoch) "
                        "VALUES(?,?,?,?,?,?,?,?,?)",
                        namespace.as_tuple + (
                            operation_id, digest, attempt_id, requirements_json,
                            anchor_json, metadata.graph_revision, epoch.revision),
                    )
                    intent = db.execute(
                        "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                        "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                    if c02_candidate is not None:
                        if c02_first_seal_v2:
                            db.execute("""CREATE TABLE IF NOT EXISTS
                                graph_first_ingress_c02_candidates_v2 (
                                bot TEXT NOT NULL, persona TEXT NOT NULL,
                                operation_id TEXT NOT NULL,
                                schema TEXT NOT NULL CHECK(schema=
                                    'sylanne.first-ingress-c02-candidate.v2'),
                                bundle_digest TEXT NOT NULL,
                                fence_attempt_id TEXT NOT NULL,
                                bundle_json TEXT NOT NULL,
                                evidence_json TEXT NOT NULL,
                                quote_json TEXT NOT NULL,
                                seal_json TEXT NOT NULL,
                                PRIMARY KEY(bot,persona,operation_id),
                                FOREIGN KEY(bot,persona,operation_id)
                                    REFERENCES graph_bundle_intents_v2(
                                        bot,persona,operation_id))""")
                            quote, seal = self.__d11_issuer.issue_d06_first_ingress_c02_quote_at_first_seal_v2(
                                db, bundle, c02_adoption[5],
                                original_key=c02_first_seal_key,
                                sealed_at_utc=c02_adoption[6])
                            candidate_values = c02_candidate + (
                                canonical_serialize(asdict(quote)),
                                canonical_serialize(asdict(seal)))
                            db.execute(
                                "INSERT INTO graph_first_ingress_c02_candidates_v2"
                                "(bot,persona,operation_id,schema,bundle_digest,"
                                "fence_attempt_id,bundle_json,evidence_json,"
                                "quote_json,seal_json) VALUES(?,?,?,?,?,?,?,?,?,?)",
                                namespace.as_tuple + (operation_id,)
                                + candidate_values)
                            sealed = db.execute(
                                "SELECT schema,bundle_digest,fence_attempt_id,"
                                "bundle_json,evidence_json,quote_json,seal_json "
                                "FROM graph_first_ingress_c02_candidates_v2 "
                                "WHERE bot=? AND persona=? AND operation_id=?",
                                namespace.as_tuple + (operation_id,),
                            ).fetchone()
                            if sealed != candidate_values:
                                raise EventConflict("C02 v2 first seal differs")
                        else:
                            db.execute(
                                "INSERT OR IGNORE INTO graph_first_ingress_c02_candidates_v1"
                                "(bot,persona,operation_id,schema,bundle_digest,"
                                "fence_attempt_id,bundle_json,evidence_json) "
                                "VALUES(?,?,?,?,?,?,?,?)",
                                namespace.as_tuple + (operation_id,) + c02_candidate,
                            )
                            sealed = db.execute(
                                "SELECT schema,bundle_digest,fence_attempt_id,"
                                "bundle_json,evidence_json FROM "
                                "graph_first_ingress_c02_candidates_v1 WHERE bot=? "
                                "AND persona=? AND operation_id=?",
                                namespace.as_tuple + (operation_id,),
                            ).fetchone()
                        if sealed[:5] != c02_candidate or intent[0:2] != (
                                digest, attempt_id):
                            raise EventConflict("C02 candidate or intent identity differs")
                    db.execute("COMMIT")
                except BaseException:
                    db.execute("ROLLBACK")
                    raise
        if intent is None:
            raise UnavailableGuard("durable v2 bundle intent is absent")
        if intent[0] != digest:
            raise EventConflict("operation ID reused with different bundle")
        c02_v2_quote = None
        if c02_candidate is not None and prior is None:
            with store._lock:
                if c02_first_seal_v2 or c02_terminal_recovery is not None:
                    sealed = store._db.execute(
                        "SELECT schema,bundle_digest,fence_attempt_id,"
                        "bundle_json,evidence_json,quote_json,seal_json "
                        "FROM graph_first_ingress_c02_candidates_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
                else:
                    sealed = store._db.execute(
                        "SELECT schema,bundle_digest,fence_attempt_id,"
                        "bundle_json,evidence_json FROM "
                        "graph_first_ingress_c02_candidates_v1 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (operation_id,),
                    ).fetchone()
            if sealed is None:
                raise UnavailableGuard("durable C02 candidate is absent; HOLD")
            if sealed[:5] != c02_candidate:
                raise EventConflict("durable C02 candidate identity differs")
            if c02_first_seal_v2 or c02_terminal_recovery is not None:
                from .authority_service.v2_terminal_c02_recovery_contract import (
                    OriginalC02ResultKeyV1, from_wire as terminal_key_from_wire,
                )
                from .runtime.terminal_c02_recovery_candidate_v2 import (
                    FrozenTerminalC02CandidateV2,
                    inspect_frozen_terminal_c02_candidate_v2,
                )

                try:
                    raw_seal = json.loads(sealed[6])
                    raw_seal["original_key"] = terminal_key_from_wire(
                        raw_seal["original_key"], OriginalC02ResultKeyV1)
                    seal = FrozenTerminalC02CandidateV2(**raw_seal)
                    inspection = inspect_frozen_terminal_c02_candidate_v2(
                        namespace=namespace, operation_id=operation_id,
                        seal=seal, bundle_json=sealed[3],
                        quote_json=sealed[5])
                except (TypeError, ValueError, KeyError) as exc:
                    raise UnavailableGuard("durable C02 v2 seal is invalid; HOLD") from exc
                expected_key = (c02_terminal_recovery.seal.original_key
                                if c02_terminal_recovery is not None else
                                c02_first_seal_key)
                if inspection.bundle != bundle or seal.original_key != expected_key:
                    raise EventConflict("durable C02 v2 original key or bundle differs")
                if (c02_terminal_recovery is not None
                        and seal != c02_terminal_recovery.seal):
                    raise EventConflict("durable C02 v2 seal differs")
                with store._lock:
                    c02_v2_quote = self.__d02_issuer.original_signed_quote(
                        store._db, seal.quote_id, seal.quote_version)
                if canonical_serialize(asdict(c02_v2_quote)) != sealed[5]:
                    raise UnavailableGuard("durable C02 v2 signed quote differs; HOLD")
        if (intent[1] != attempt_id or intent[2] != requirements_json
                or intent[3] != anchor_json):
            raise UnavailableGuard("durable v2 bundle intent identity differs")
        if prior is None and (intent[4], intent[5]) != (
                metadata.graph_revision, epoch.revision):
            raise UnavailableGuard("uncommitted v2 bundle intent lost its graph stamp")
        if rejection is not None:
            if prior is not None or saved is not None:
                raise UnavailableGuard("rejected v2 bundle has a business receipt")
            self._finish_rejected_bundle_v2(
                namespace, metadata, epoch, anchor, attempt_id, digest,
                operation_id, rejection)
            raise UnavailableGuard("v2 bundle is terminal rejected_no_commit")
        if prior is not None:
            if prior[0] != digest:
                raise EventConflict("operation ID reused with different bundle")
            if saved is None or saved[0] != digest:
                raise UnavailableGuard("durable v2 bundle fence receipt is absent")
            try:
                original = from_wire(json.loads(saved[1]))
            except (TypeError, ValueError) as exc:
                raise UnavailableGuard("durable v2 bundle permit is invalid") from exc
            if (type(original) is not FencePermitV2
                    or original.operation_id != attempt_id
                    or original.operation != "write" or original.holder != self.__holder
                    or original.subject != port.installation_grant.subject
                    or original.authority_id != target.authority_id
                    or original.namespace != target.authority_namespace
                    or original.generation != target.activation_generation
                    or original.pinned_anchor != anchor
                    or (saved[2], saved[3]) != (intent[4], intent[5])
                    or saved[4] != saved[2] + 1
                    or saved[5] < saved[3]
                    or saved[6] != "finish:" + attempt_id
                    or saved[7] != "sha256:" + canonical_digest({
                        "operation_id": attempt_id, "permit_token": original.token,
                        "action": "finish_domain_bundle",
                        "business_operation_id": operation_id, "bundle_digest": digest,
                    })):
                raise UnavailableGuard("durable v2 bundle fence identity differs")
            observed, state = port.get_fence_operation(
                namespace=namespace, authority_namespace=target.authority_namespace,
                operation_id=attempt_id)
            if observed != original or state not in {"active", "finished"}:
                raise UnavailableGuard("v2 bundle Authority fence status differs")
            if state == "active":
                if (metadata.graph_revision != saved[4]
                        or epoch.revision != saved[5]):
                    raise UnavailableGuard("active v2 bundle fence lost its business stamp")
                scope = FenceScope(
                    namespace, target.authority_namespace, target.activation_generation,
                    "write", attempt_id, original, anchor,
                    NamespaceEpoch(*namespace.as_tuple, saved[3]), saved[2])
                if port.validate_fence(scope) != original:
                    raise UnavailableGuard("v2 bundle write permit changed")
                port.finish_fence(scope, request_id=saved[6], request_digest=saved[7])
            elif (metadata.graph_revision < saved[4]
                  or epoch.revision < saved[5]):
                raise UnavailableGuard("finished v2 bundle fence lost its business stamp")
            return self._read_v2(authority, lambda: self._commit_domain_bundle_fenced(
                bundle, lease, v2_read=True))
        if saved is not None:
            raise UnavailableGuard("v2 bundle fence exists without business receipt")
        dispatch_clock_reading = None
        if (self.__dispatch_admission_issuer is not None
                and any(write.key.type_name == "d09.verified_segment_batch.v1"
                        for proposal in bundle.proposals for write in proposal.typed_writes)):
            from .host.authority_profile import AdminIngressClockPolicy

            if type(self.__dispatch_clock_policy) is not AdminIngressClockPolicy:
                raise UnavailableGuard("dispatch admission clock policy is unavailable")
            try:
                dispatch_clock_reading = port.read_ingress_clock(
                    self.__dispatch_clock_policy)
            except Exception as exc:
                raise UnavailableGuard("paired dispatch admission clock is unavailable") from exc
        permit = port.begin_fence(
            namespace=namespace, authority_namespace=target.authority_namespace,
            holder=self.__holder, generation=target.activation_generation,
            operation="write", operation_id=attempt_id, expected_anchor=anchor,
            retain_on_unknown=True)
        scope = FenceScope(namespace, target.authority_namespace,
                           target.activation_generation, "write", attempt_id,
                           permit, anchor, epoch, metadata.graph_revision)
        finish_id = "finish:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "finish_domain_bundle", "business_operation_id": operation_id,
            "bundle_digest": digest,
        })
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 bundle write permit changed")
        dispatch_owner_guard = None
        dispatch_current_effect = None
        if dispatch_clock_reading is not None:
            from .authority_service.v2_execution_bridge import CurrentEffectReadV2

            owner_reader = getattr(port, "get_current_owner_guard_for_fence", None)
            effect_reader = getattr(port, "read_current_effect", None)
            if not callable(owner_reader) or not callable(effect_reader):
                raise UnavailableGuard("dispatch admission Owner/effect reader unavailable; HOLD")
            guarded = owner_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                permit=permit)
            if (type(guarded) is not tuple or len(guarded) != 2
                    or type(guarded[0]) is not OwnerAuthorizationGuardV1
                    or guarded[1] != permit):
                raise UnavailableGuard("dispatch admission Owner guard differs; HOLD")
            dispatch_owner_guard = guarded[0]
            dispatch_current_effect = effect_reader(
                namespace=namespace, authority_namespace=target.authority_namespace,
                effect_id=bundle.envelope.identity.effect_id)
            if (type(dispatch_current_effect) is not CurrentEffectReadV2
                    or dispatch_current_effect.effect_id
                    != bundle.envelope.identity.effect_id
                    or port.validate_fence(scope) != permit):
                raise UnavailableGuard("dispatch admission current effect differs; HOLD")
        c02_fact = None
        if c02_witness is not None and c02_terminal_recovery is None:
            from .authority_service.v2_worker_result_read_fact_contract import (
                WorkerResultReadFactRequestV2, WorkerResultReadFactV2,
            )

            request = (c02_recovery.request if c02_recovery is not None
                       else c02_adoption[1].request)
            c02_fact = self.__worker_result_fact_port.current_worker_result_read_fact(
                WorkerResultReadFactRequestV2(
                    read_request=request, write_permit=permit,
                    bundle_digest=digest))
            if (type(c02_fact) is not WorkerResultReadFactV2
                    or c02_fact.read_request != request
                    or c02_fact.write_permit != permit
                    or c02_fact.bundle_digest != digest
                    or (c02_fact.result_digest !=
                        (c02_recovery.evidence["read_result_digest"]
                         if c02_recovery is not None else
                         canonical_digest(asdict(c02_adoption[1]))))):
                raise UnavailableGuard("original Authority worker result fact differs; HOLD")
        transaction_state = {"phase": "before_transaction"}
        try:
            scene_owner_guard = None
            if correction_issuance is not None:
                owner_authority, principal, binding, session_proof = correction_issuance[6:]
                _, current_binding = self._owner_binding_in_fence(
                    owner_authority, scope, principal, binding, session_proof)
                if (current_binding != binding
                        or "workbench.correct" not in current_binding.capabilities
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current correction Owner authority changed; HOLD")
            if any(
                    proposal.domain == "d03" and any(
                        write.key.type_name == "d03.world_event"
                        and (write.value.get("kind") == "message_received"
                             or write.value.get("reality") == "host_observed")
                        for write in proposal.typed_writes)
                    for proposal in bundle.proposals):
                reader = getattr(port, "get_current_owner_guard_for_fence", None)
                if not callable(reader):
                    raise UnavailableGuard("current scene Owner guard port is unavailable")
                guarded = reader(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    permit=permit)
                if (type(guarded) is not tuple or len(guarded) != 2
                        or type(guarded[0]) is not OwnerAuthorizationGuardV1
                        or guarded[1] != permit
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current scene Owner guard is unavailable")
                scene_owner_guard = guarded[0]
            qualified_self = None
            current_self_policy = (
                self_identity_issuance[0] if self_identity_issuance is not None else
                baseline_issuance[6] if baseline_issuance is not None
                and len(baseline_issuance) == 9 else None)
            if current_self_policy is not None:
                from .domains.d03.self_identity_qualification import (
                    qualify_authority_current_self_identity,
                )

                if self.__self_identity_port is None:
                    raise UnavailableGuard("current Authority self identity port unavailable; HOLD")
                reader = getattr(port, "get_current_owner_guard_for_fence", None)
                if not callable(reader):
                    raise UnavailableGuard("current Owner guard port unavailable; HOLD")
                guarded = reader(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    permit=permit)
                if (type(guarded) is not tuple or len(guarded) != 2
                        or type(guarded[0]) is not OwnerAuthorizationGuardV1
                        or guarded[1] != permit):
                    raise UnavailableGuard("current Owner guard unavailable; HOLD")
                scene_owner_guard = guarded[0]
                with store._lock:
                    if self._v2_graph_stamp(namespace) != (metadata, epoch):
                        raise StaleRead("self identity graph changed before Authority read")
                    role, _, role_epoch, _ = self._scene_binding_state_locked(
                        namespace, scene_owner_guard)
                    activation_key = AtomKey(
                        Owner("persona", *namespace.as_tuple),
                        "d01.persona_activation.v1", "current")
                    row = store._db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (activation_key.token,),
                    ).fetchone()
                    if row is None:
                        raise UnavailableGuard("current D01 activation unavailable; HOLD")
                    activation_atom = GraphAtom(
                        activation_key, row[0], json.loads(row[1]), bool(row[2]))
                if role_epoch != epoch:
                    raise StaleRead("current D01 epoch changed before Authority read")
                current = self.__self_identity_port.current_self_identity(
                    namespace=namespace,
                    authority_namespace=target.authority_namespace,
                    request_operation_id=operation_id,
                    permit=permit,
                )
                qualified_mapping = qualify_authority_current_self_identity(
                    role=role, activation_atom=activation_atom,
                    policy=current_self_policy,
                    installation_grant=port.installation_grant,
                    owner_guard=scene_owner_guard,
                    request_operation_id=operation_id, permit=permit,
                    port=SimpleNamespace(current_self_identity=lambda **_: current),
                )
                if (current.graph_revision != metadata.graph_revision
                        or current.graph_epoch != epoch.revision
                        or port.validate_fence(scope) != permit):
                    raise UnavailableGuard("current self identity changed; HOLD")
                if (self_identity_issuance is not None
                        and qualified_mapping != self_identity_issuance[5]):
                    raise UnavailableGuard("current self identity changed; HOLD")
                qualified_self = (role, qualified_mapping, current)
            receipt = self._commit_domain_bundle_fenced(
                bundle, lease, v2_write=(metadata, epoch, finish_id,
                                         finish_digest, canonical_json(to_wire(permit))),
                v2_transaction_state=transaction_state,
                dispatch_clock_reading=dispatch_clock_reading,
                dispatch_admission_scope=scope,
                dispatch_admission_owner_guard=dispatch_owner_guard,
                dispatch_admission_current_effect=dispatch_current_effect,
                scene_owner_guard=scene_owner_guard,
                now_utc=(arrival_issuance[2] if arrival_issuance else
                         attention_issuance[1] if attention_issuance else
                         baseline_issuance[2] if baseline_issuance else
                         self_identity_issuance[3] if self_identity_issuance else
                         correction_issuance[2] if correction_issuance else
                          c02_witness.now if isinstance(
                              c02_witness, (_C02PendingRecovery,
                                            _C02TerminalRecovery)) else
                         c02_adoption[6] if c02_adoption is not None else None),
                arrival_issuance=arrival_issuance,
                attention_issuance=attention_issuance,
                baseline_issuance=baseline_issuance,
                self_identity_issuance=self_identity_issuance,
                correction_issuance=correction_issuance,
                qualified_self=qualified_self,
                 c02_adoption=(c02_witness, c02_fact, permit)
                 if c02_witness is not None else None,
                 c02_first_seal_quote=c02_v2_quote,
                 c02_terminal_recovery=c02_terminal_recovery)
        except Exception:
            if transaction_state["phase"] in {"before_transaction", "rolled_back"}:
                rejection = self._record_rejected_bundle_v2(
                    namespace, operation_id, digest, attempt_id, metadata, epoch,
                    intent, permit,
                    c02_first_seal_v2=(c02_first_seal_v2
                                       or c02_terminal_recovery is not None))
                self._finish_rejected_bundle_v2(
                    namespace, metadata, epoch, anchor, attempt_id, digest,
                    operation_id, rejection)
            raise
        if port.validate_fence(scope) != permit:
            raise UnavailableGuard("v2 bundle write permit changed after commit")
        with store._lock:
            current, current_epoch = self._v2_graph_stamp(namespace)
            if (current.requirements != metadata.requirements
                    or current.graph_revision != metadata.graph_revision + 1
                    or current_epoch.revision != receipt.invalidated_epochs[0].revision):
                raise UnavailableGuard("v2 bundle graph stamp changed after commit")
        port.finish_fence(scope, request_id=finish_id, request_digest=finish_digest)
        return receipt

    def _record_rejected_bundle_v2(self, namespace, operation_id, digest,
                                   attempt_id, metadata, epoch, intent, permit,
                                   *, allow_advanced_graph=False,
                                   c02_first_seal_v2=False):
        """Record a proven rollback before any Authority abort finish."""
        from .authority_service.v2_contract import to_wire

        store = self.__store
        finish_id = "abort:" + attempt_id
        finish_digest = "sha256:" + canonical_digest({
            "operation_id": attempt_id, "permit_token": permit.token,
            "action": "rejected_no_commit", "business_operation_id": operation_id,
            "bundle_digest": digest,
        })
        expected = (
            digest, "rejected_no_commit", canonical_json(to_wire(permit)),
            metadata.graph_revision, epoch.revision, finish_id, finish_digest,
        )
        with store._lock:
            db = store._db
            db.execute("BEGIN IMMEDIATE")
            try:
                current_intent = db.execute(
                    "SELECT digest,fence_attempt_id,requirements_json,anchor_json,"
                    "graph_revision,graph_epoch FROM graph_bundle_intents_v2 "
                    "WHERE bot=? AND persona=? AND operation_id=?",
                    namespace.as_tuple + (operation_id,),
                ).fetchone()
                if (current_intent != intent
                        or self._v2_graph_stamp(namespace) != (metadata, epoch)
                        or (allow_advanced_graph and
                            (intent[4] > metadata.graph_revision
                             or intent[5] > epoch.revision))
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_operations WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone() is not None
                        or db.execute(
                            "SELECT 1 FROM graph_bundle_fences_v2 WHERE bot=? "
                            "AND persona=? AND operation_id=?",
                            namespace.as_tuple + (operation_id,),
                        ).fetchone() is not None):
                    raise UnavailableGuard("v2 bundle rollback cannot be proven")
                db.execute(
                    "INSERT OR IGNORE INTO graph_bundle_rejections_v2"
                    "(bot,persona,operation_id,digest,status,permit_json,"
                    "graph_revision,graph_epoch,finish_request_id,finish_request_digest) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (operation_id,) + expected,
                )
                recorded = db.execute(
                    "SELECT digest,status,permit_json,graph_revision,graph_epoch,"
                    "finish_request_id,finish_request_digest "
                    "FROM graph_bundle_rejections_v2 WHERE bot=? AND persona=? "
                    "AND operation_id=?", namespace.as_tuple + (operation_id,),
                ).fetchone()
                if recorded != expected:
                    raise UnavailableGuard("v2 bundle rejection identity differs")
                db.execute(
                    "DELETE FROM " + (
                        "graph_first_ingress_c02_candidates_v2 "
                        if c02_first_seal_v2 else
                        "graph_first_ingress_c02_candidates_v1 ") +
                    "WHERE bot=? AND persona=? AND operation_id=? "
                    "AND bundle_digest=?",
                    namespace.as_tuple + (operation_id, digest),
                )
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        return expected

    def _finish_rejected_bundle_v2(self, namespace, metadata, epoch, anchor,
                                   attempt_id, digest, operation_id, rejection,
                                   *, allow_advanced_graph=False):
        from .authority_service.v2_contract import FencePermitV2, from_wire

        port = self.__content_fence_v2
        target = metadata.requirements
        try:
            permit = from_wire(json.loads(rejection[2]))
        except (TypeError, ValueError) as exc:
            raise UnavailableGuard("durable v2 rejected permit is invalid") from exc
        if (rejection[0] != digest or rejection[1] != "rejected_no_commit"
                or type(permit) is not FencePermitV2
                or permit.operation_id != attempt_id or permit.operation != "write"
                or permit.subject != port.installation_grant.subject
                or permit.holder != self.__holder
                or permit.authority_id != target.authority_id
                or permit.namespace != target.authority_namespace
                or permit.generation != target.activation_generation
                or permit.pinned_anchor != anchor
                or (not allow_advanced_graph and
                    (rejection[3], rejection[4]) !=
                    (metadata.graph_revision, epoch.revision))
                or (allow_advanced_graph and
                    (rejection[3] > metadata.graph_revision
                     or rejection[4] > epoch.revision))
                or rejection[5] != "abort:" + attempt_id
                or rejection[6] != "sha256:" + canonical_digest({
                    "operation_id": attempt_id, "permit_token": permit.token,
                    "action": "rejected_no_commit",
                    "business_operation_id": operation_id, "bundle_digest": digest,
                })):
            raise UnavailableGuard("durable v2 rejected fence identity differs")
        observed, state = port.get_fence_operation(
            namespace=namespace, authority_namespace=target.authority_namespace,
            operation_id=attempt_id)
        if observed != permit or state not in {"active", "finished"}:
            raise UnavailableGuard("rejected v2 Authority fence status differs")
        scope = FenceScope(
            namespace, target.authority_namespace,
            target.activation_generation, "write", attempt_id,
            permit, anchor,
            NamespaceEpoch(*namespace.as_tuple, rejection[4]), rejection[3])
        if (state == "active" and
                ((rejection[3], rejection[4]) !=
                 (metadata.graph_revision, epoch.revision)
                 or port.validate_fence(scope) != permit)):
            raise UnavailableGuard("rejected v2 write permit changed")
        port.finish_fence(scope, request_id=rejection[5], request_digest=rejection[6])

    def _commit_domain_bundle_fenced(self, bundle: DomainBundle,
                                     lease: object, *, v2_read: bool = False,
                                     v2_write=None, v2_transaction_state=None,
                                      in_transaction: bool = False,
                                      now_utc: float | None = None,
                                      dispatch_clock_reading=None,
                                      dispatch_admission_scope=None,
                                      dispatch_admission_owner_guard=None,
                                      dispatch_admission_current_effect=None,
                                      ingress_deadline_check=None,
                                     scene_owner_guard=None,
                                      arrival_issuance=None,
                                      attention_issuance=None,
                                      baseline_issuance=None,
                                      self_identity_issuance=None,
                                      correction_issuance=None,
                                       qualified_self=None,
                                       c02_adoption=None,
                                       c02_first_seal_quote=None,
                                       c02_terminal_recovery: _C02TerminalRecovery | None = None
                                       ) -> CommitReceipt:
        """Join a caller-owned graph transaction when ``in_transaction`` is set.

        The caller holds the store lock and owns COMMIT or ROLLBACK.
        """
        envelope = bundle.envelope
        namespace = envelope.authority.namespace
        domains = frozenset(proposal.domain for proposal in bundle.proposals)
        if not domains:
            raise ValueError("domain bundle requires proposals")
        self._authorize(lease, envelope.authority, domains)
        store = self.__store
        writes = tuple(write for proposal in bundle.proposals for write in proposal.typed_writes)
        dispatch_candidate = validate_dispatch_candidate_writes(
            tuple((proposal.domain, write) for proposal in bundle.proposals
                  for write in proposal.typed_writes),
            namespace=namespace, identity=envelope.identity,
            read_versions=envelope.version_guard.read_versions,
            source_refs=envelope.source_qualification.source_refs,
            access_epoch=envelope.version_guard.access_epoch,
            delete_epoch=envelope.version_guard.delete_epoch,
            query_epoch=envelope.version_guard.query_epochs[0].revision
            if len(envelope.version_guard.query_epochs) == 1 else -1,
        )
        if len({write.key for write in writes}) != len(writes):
            raise ValueError("duplicate writes across proposals")
        read_map = {item.key: item.revision for item in envelope.version_guard.read_versions}
        if not set(write.key for write in writes).issubset(read_map):
            raise ValueError("all writes require read versions, including absent keys")
        for proposal in bundle.proposals:
            registration = self.__providers.get(proposal.domain)
            if registration is None:
                raise AuthorityDenied("unregistered proposal domain")
            _, schema, schema_hash = registration
            if (proposal.proposal_schema, proposal.proposal_schema_hash) != (schema, schema_hash):
                raise AuthorityDenied("proposal schema differs from registered provider")
            for write in proposal.typed_writes:
                spec = store._registry.spec(write.key.type_name)
                if (spec.writer_domain != proposal.domain or spec.schema_hash is None
                        or write.key.owner.kind not in envelope.authority.owner_scope):
                    raise AuthorityDenied("writer lacks registered type or owner capability")
                if not set(write.dependencies).issubset(read_map):
                    raise ValueError("dependency is outside complete read set")
            for ref in (proposal.dependencies.current_invalidation
                        + proposal.dependencies.historical_provenance
                        + proposal.dependencies.associations
                        + proposal.dependencies.numeric_coupling):
                if read_map.get(ref.key) != ref.revision:
                    raise StaleRead("dependency reference is not guarded")
            current = {ref.key for ref in proposal.dependencies.current_invalidation}
            actual_current = set()
            for write in proposal.typed_writes:
                actual_current.update(write.dependencies)
                if not set(write.dependencies).issubset(current):
                    raise ValueError("graph invalidation edges must match classified dependencies")
            if actual_current != current:
                raise ValueError("classified current dependencies are not materialized")
        write_tokens = {write.key.token for write in writes}
        for write in writes:
            if (write.key.type_name == "runtime.job"
                    and write.key.token not in bundle.persistent_job_refs
                    and not (c02_adoption is not None
                             and write == bundle.proposals[1].typed_writes[0])):
                raise ValueError("runtime.job write must be a bound persistent job ref")
            if (write.key.type_name == "runtime.outbox"
                    and write.key.token not in bundle.outbox_refs):
                raise ValueError("runtime.outbox write must be a bound outbox ref")
            if write.key.type_name == "runtime.outbox":
                if write.value.get("dispatch_generation") != envelope.authority.activation_generation:
                    raise StaleRead("outbox dispatch generation differs from active holder")
                if write.value.get("idempotency_key") not in bundle.idempotency_keys:
                    raise AuthorityDenied("outbox idempotency key is not in the bundle ledger")
        part_refs = (
            ("experience", bundle.experience_refs), ("choice", bundle.choice_refs),
            ("d02_settlement", bundle.d02_settlement_refs),
            ("cost_settlement", bundle.d11_cost_settlement_refs),
            ("idempotency", bundle.idempotency_keys),
            ("persistent_job", bundle.persistent_job_refs),
            ("outbox", bundle.outbox_refs),
        )
        for kind, refs in part_refs:
            for ref in refs:
                if kind in {"idempotency"}:
                    continue
                key = self._parse_ref(ref, namespace)
                if key.token not in write_tokens:
                    raise ValueError(f"{kind} reference must be written in the same bundle")
                required_type = {
                    "cost_settlement": "runtime.cost_settlement",
                    "persistent_job": "runtime.job",
                    "outbox": "runtime.outbox",
                }.get(kind)
                if required_type is not None and key.type_name != required_type:
                    raise AuthorityDenied(f"{kind} requires {required_type}")
                required_writer = {
                    "d02_settlement": "d02", "cost_settlement": "d11",
                    "persistent_job": "d11", "outbox": "d11",
                }.get(kind)
                if required_writer is not None and (
                        store._registry.spec(key.type_name).writer_domain != required_writer):
                    raise AuthorityDenied(f"{kind} requires the {required_writer} graph writer")
        new_sources = []
        for source in envelope.source_qualification.source_refs:
            key = self._parse_ref(source, namespace)
            if key not in read_map:
                raise StaleRead("source outside complete read set")
            if key != source_key(*namespace.as_tuple, key.owner.subject or ""):
                raise AuthorityDenied("source reference is not a canonical D06 source")
            access = access_key(*namespace.as_tuple, key.owner.subject or "")
            access_revision = read_map.get(access)
            if access_revision is None:
                raise StaleRead("source access record is outside complete read set")
            if read_map[key] == 0:
                if access_revision != 0:
                    raise StaleRead("new source cannot reuse an existing access record")
                source_writes = tuple((proposal.domain, write) for proposal in bundle.proposals
                                      for write in proposal.typed_writes if write.key == key)
                access_writes = tuple((proposal.domain, write) for proposal in bundle.proposals
                                      for write in proposal.typed_writes if write.key == access)
                if (len(source_writes) != 1 or len(access_writes) != 1
                        or source_writes[0][0] != "d06" or access_writes[0][0] != "d06"):
                    raise AuthorityDenied("new source requires D06 source and access writes")
                record = access_writes[0][1].value
                if (record.get("source_id") != key.owner.subject
                        or record.get("status") != "active"
                        or not set(envelope.authority.audience).issubset(record.get("audiences", ()))
                        or envelope.authority.purpose not in record.get("purposes", ())
                        or key not in access_writes[0][1].dependencies):
                    raise AuthorityDenied("new source access does not cover this use")
                if not (bundle.persistent_job_refs and bundle.outbox_refs
                        and bundle.idempotency_keys):
                    raise ValueError("new source requires encoding job, outbox and idempotency")
                new_sources.append(key)
            elif access_revision == 0:
                raise StaleRead("existing source has no access record")
        digest = bundle.digest
        identity = envelope.identity
        event = Event(Scope(*namespace.as_tuple, identity.activity_id),
                      identity.operation_id, envelope.source_qualification.learned_at,
                      "domain_bundle", {"bundle_digest": digest})
        result: list[CommitReceipt] = []
        runtime_admissions: list[RuntimeAdmission] = []
        product_advances: list[dict] = []
        qualified_dispatch_candidates = []
        guard_snapshots: list[GraphSnapshot] = []
        dispatch_projections = []

        def guard(db):
            if v2_write is not None:
                expected, expected_epoch = v2_write[:2]
                if self._v2_graph_stamp(namespace) != (expected, expected_epoch):
                    raise StaleRead("v2 graph recovery stamp changed")
                if db.execute(
                        "SELECT 1 FROM graph_bundle_rejections_v2 WHERE bot=? "
                        "AND persona=? AND operation_id=?",
                        namespace.as_tuple + (identity.operation_id,),
                ).fetchone() is not None:
                    raise UnavailableGuard("v2 bundle is terminal rejected_no_commit")
                if self_identity_issuance is not None or baseline_issuance is not None:
                    stage_table = ("graph_d03_self_projection_intents_v1"
                                   if self_identity_issuance is not None else
                                   "graph_d04_baseline_intents_v1")
                    stage_source = (self_identity_issuance[4]
                                    if self_identity_issuance is not None else
                                    baseline_issuance[3])
                    original_op = (self_identity_issuance[7]
                                   if self_identity_issuance is not None else
                                   baseline_issuance[7])
                    if db.execute(
                            f"SELECT operation_id,bundle_digest FROM {stage_table} "
                            "WHERE bot=? AND persona=? AND source_ref=? "
                            "AND original_operation_id=?",
                            namespace.as_tuple + (stage_source, original_op),
                    ).fetchone() != (identity.operation_id, digest):
                        raise EventConflict("stage current attempt changed")
            elif not v2_read:
                self._admit_content(
                    namespace, envelope.authority.activation_generation, "write",
                    tuple(item.key.token for item in envelope.version_guard.read_versions)
                    + tuple(write.key.token for write in writes),
                )
            prior = db.execute(
                "SELECT digest FROM graph_bundle_operations WHERE bot=? AND persona=? "
                "AND operation_id=?", namespace.as_tuple + (identity.operation_id,),
            ).fetchone()
            if prior is not None:
                if prior[0] != digest:
                    raise EventConflict("operation ID reused with different bundle")
                return
            if c02_terminal_recovery is not None:
                row = db.execute(
                    "SELECT schema,bundle_digest,fence_attempt_id,bundle_json,"
                    "evidence_json,quote_json,seal_json FROM "
                    "graph_first_ingress_c02_candidates_v2 WHERE bot=? "
                    "AND persona=? AND operation_id=?",
                    namespace.as_tuple + (identity.operation_id,),
                ).fetchone()
                witness = c02_terminal_recovery
                if (row is None or row[:5] != witness.sealed_candidate
                        or row[3] != witness.bundle_json
                        or row[5] != witness.quote_json
                        or row[6] != canonical_serialize(asdict(witness.seal))
                        or time.monotonic() >= witness.local_monotonic_deadline):
                    raise UnavailableGuard("terminal C02 first seal changed; HOLD")
            elif c02_adoption is not None:
                self._validate_first_ingress_c02_adoption_locked(
                    db, bundle, c02_adoption, v2_write)
            if attention_issuance is not None:
                from .runtime.reply_model_job import (
                    d07_attention_quote_id_v1,
                    read_settled_c02_reply_source_v1,
                    source_key_from_ref,
                )
                from .runtime.issuers import ResourceQuote
                from .runtime_contracts import VersionedRef

                installed, attention_now = attention_issuance
                admin = installed.d07_attention
                policy = installed.installation_policy
                source_ref = envelope.source_qualification.source_refs[0]
                source_id = source_key_from_ref(source_ref, namespace)
                c02_operation_id = envelope.causation[0]
                source_atom_key = source_key(*namespace.as_tuple, source_id)
                access_atom_key = access_key(*namespace.as_tuple, source_id)
                source_atoms = []
                for key in (source_atom_key, access_atom_key):
                    row = db.execute(
                        "SELECT revision,value,valid FROM graph_atoms WHERE token=?",
                        (key.token,),
                    ).fetchone()
                    if row is None:
                        raise UnavailableGuard("D07 attention source is absent; HOLD")
                    source_atoms.append(GraphAtom(
                        key, row[0], json.loads(row[1]), bool(row[2])))
                c02_row = db.execute(
                    "SELECT digest,activity_id,effect_id,commit_seq,receipt_json "
                    "FROM graph_bundle_operations WHERE bot=? AND persona=? "
                    "AND operation_id=?",
                    namespace.as_tuple + (c02_operation_id,),
                ).fetchone()
                if c02_row is None:
                    raise UnavailableGuard("D07 attention original C02 absent; HOLD")
                c02_event = db.execute(
                    "SELECT reads,revisions,epoch_revision FROM graph_events "
                    "WHERE bot=? AND persona=? AND session=? AND event_id=?",
                    namespace.as_tuple + (c02_row[1], c02_operation_id),
                ).fetchone()
                if c02_event is None:
                    raise UnavailableGuard("D07 attention C02 event absent; HOLD")
                c02_detail = json.loads(c02_row[4])
                c02_receipt = CommitReceipt(
                    "committed", c02_operation_id, c02_row[0], c02_row[1],
                    c02_row[2], c02_row[3],
                    GraphStore._version_rows(c02_event[0]),
                    GraphStore._version_rows(c02_event[1]),
                    (NamespaceEpoch(*namespace.as_tuple, c02_event[2]),),
                    tuple(c02_detail["ledger_refs"]),
                    tuple(c02_detail["outbox_refs"]))
                current = read_settled_c02_reply_source_v1(
                    db, self.__d02_issuer, namespace, c02_receipt, source_ref,
                    GraphSnapshot(tuple(source_atoms), (v2_write[1],)))
                ticket_write = next(
                    (write for write in writes if
                     write.key.type_name == "d07.attention_ticket.v1"), None)
                focus_write = next(
                    (write for write in writes if
                     write.key.type_name == "d07.focus.v1"), None)
                quote_id = d07_attention_quote_id_v1(
                    namespace, identity.operation_id)
                grant = self.__d11_issuer.current_budget_grant(
                    db, policy.root_lease.lease_id)
                budget = get_budget_lease(db, grant.lease_id)
                provision_row = self._provision_row(db, namespace)
                provision = (self._decode_provision_receipt(provision_row)
                             if provision_row is not None else None)
                if (v2_write is None or grant != policy.root_grant
                        or provision is None
                        or provision.installation_id != policy.installation_id
                        or provision.root_grant_id != grant.grant_id
                        or provision.root_lease_id != grant.lease_id
                        or budget.state != "active"
                        or "d07.attention" not in grant.allowed_work_kinds
                        or identity.phase != "post_c02_attention"
                        or identity.activity_id != c02_receipt.activity_id
                        or current.source_qualification !=
                           envelope.source_qualification
                        or current.conversation_ref !=
                           envelope.authority.audience[0]
                        or envelope.parent_budget_lease_ref != grant.lease_id
                        or ticket_write is None or focus_write is None
                        or len(writes) != 2
                        or ticket_write.value.get("causal_root") != source_ref
                        or ticket_write.value.get("source_refs") != [source_ref]
                        or ticket_write.value.get("category") != "interaction"
                        or ticket_write.value.get("valid_until") !=
                           envelope.deadline_utc
                        or focus_write.value.get("primary_ticket_ref") !=
                           ticket_write.key.token
                        or not attention_now < envelope.deadline_utc
                        or envelope.deadline_utc >
                           attention_now + admin.deadline_after_seconds
                        or envelope.version_guard.resource_lease_versions !=
                           (VersionedRef(quote_id, 1),)
                        or any(amount > grant.max_ceiling.get(name, 0)
                               or amount > budget.available(name)
                               for name, amount in admin.quote_ceiling.items())):
                    raise AuthorityDenied("D07 attention signed issuance differs")
                quote = ResourceQuote(
                    quote_id, 1, *namespace.as_tuple, identity.activity_id,
                    identity.operation_id, None, grant.lease_id,
                    "d07.attention", admin.snapshot_ref,
                    envelope.deadline_utc, admin.resource_ref, None,
                    (), (), dict(admin.quote_ceiling), None,
                    envelope.deadline_utc)
                self.__d02_issuer.issue_quote(db, quote)
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote_id, "1"),
                )
                db.execute("""CREATE TABLE IF NOT EXISTS graph_d07_attention_issuance_v1(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, c02_operation_id TEXT NOT NULL,
                    source_ref TEXT NOT NULL, quote_id TEXT NOT NULL,
                    policy_digest TEXT NOT NULL, bundle_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id))""")
                db.execute(
                    "INSERT INTO graph_d07_attention_issuance_v1"
                    "(bot,persona,operation_id,c02_operation_id,source_ref,"
                    "quote_id,policy_digest,bundle_digest) VALUES(?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (identity.operation_id,
                    c02_operation_id, source_ref, quote_id,
                    canonical_digest({
                        "deadline_after_seconds": admin.deadline_after_seconds,
                        "quote_ceiling": dict(admin.quote_ceiling),
                        "snapshot_ref": admin.snapshot_ref,
                        "resource_ref": admin.resource_ref,
                    }), digest),
                )
            if arrival_issuance is not None:
                admin_policy, installation_id, arrival_now, source_ref, policy_digest = (
                    arrival_issuance)
                if (v2_write is None or len(bundle.proposals) != 1
                        or bundle.proposals[0].domain != "d03"
                        or bundle.persistent_job_refs or bundle.outbox_refs
                        or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs
                        or envelope.source_qualification.source_refs
                        != (source_key(*namespace.as_tuple, source_ref).token,)
                        or policy_digest != canonical_digest(
                            admin_policy.digest_payload())):
                    raise AuthorityDenied("D03 arrival issuance identity differs")
                pre_quote = replace(envelope, version_guard=replace(
                    envelope.version_guard, resource_lease_versions=()))
                quote = self.__d11_issuer.issue_d03_arrival_quote(
                    db, pre_quote, admin_policy,
                    installation_id=installation_id, now_utc=arrival_now)
                refs = envelope.version_guard.resource_lease_versions
                if len(refs) != 1 or (refs[0].ref, refs[0].version) != (
                        quote.quote_id, quote.version):
                    raise AuthorityDenied("D03 arrival quote guard differs")
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote.quote_id,
                                          str(quote.version)),
                )
                db.execute("""CREATE TABLE IF NOT EXISTS graph_d03_arrival_issuance_v2(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, source_ref TEXT NOT NULL,
                    quote_id TEXT NOT NULL, policy_digest TEXT NOT NULL,
                    bundle_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id))""")
                db.execute(
                    "INSERT INTO graph_d03_arrival_issuance_v2"
                    "(bot,persona,operation_id,source_ref,quote_id,policy_digest,bundle_digest) "
                    "VALUES(?,?,?,?,?,?,?)",
                    namespace.as_tuple + (identity.operation_id, source_ref,
                                          quote.quote_id, policy_digest, digest),
                )
            if correction_issuance is not None:
                admin_policy, installation_id, correction_now, request, pre_quote, planned = (
                    correction_issuance[:6])
                if (v2_write is None or identity.phase != "source-correction"
                        or tuple(item.domain for item in bundle.proposals)
                        not in {("d06", "d07", "d11"), ("d06", "d11")}
                        or bundle.persistent_job_refs != (planned.graph_job_ref,)
                        or bundle.outbox_refs != planned.outbox_refs
                        or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                    raise AuthorityDenied("source correction bundle identity differs")
                quote = self.__d11_issuer.issue_d06_source_correction_quote(
                    db, pre_quote, admin_policy, request,
                    installation_id=installation_id, now_utc=correction_now,
                    planned_quote=planned)
                refs = envelope.version_guard.resource_lease_versions
                if (quote != planned or len(refs) != 1
                        or (refs[0].ref, refs[0].version)
                        != (quote.quote_id, quote.version)):
                    raise AuthorityDenied("source correction quote plan changed")
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote.quote_id,
                                          str(quote.version)),
                )
            if baseline_issuance is not None:
                (admin_policy, installation_id, baseline_now, source_ref,
                 event_ref, job_id, installation_policy,
                 original_operation_id, _retry) = baseline_issuance
                if (v2_write is None or len(bundle.proposals) != 1
                        or bundle.proposals[0].domain != "d04"
                        or envelope.input_refs != (source_ref, event_ref)
                        or bundle.persistent_job_refs or bundle.outbox_refs
                        or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs
                        or qualified_self is None
                        or installation_policy.installation_id != installation_id):
                    raise AuthorityDenied("D04 baseline stage identity differs")
                baseline_write = bundle.proposals[0].typed_writes[0]
                perspective_key = AtomKey.from_token(
                    baseline_write.value["perspective_ref"])
                perspective_row = db.execute(
                    "SELECT value,valid FROM graph_atoms WHERE token=?",
                    (perspective_key.token,),
                ).fetchone()
                if (perspective_key.type_name != "d03.self_perspective.v1"
                        or perspective_row is None or perspective_row[1] != 1):
                    raise UnavailableGuard("D04 baseline lacks current self perspective; HOLD")
                mapping_key = AtomKey.from_token(
                    json.loads(perspective_row[0])["identity_mapping_ref"])
                mapping_row = db.execute(
                    "SELECT value,valid FROM graph_atoms WHERE token=?",
                    (mapping_key.token,),
                ).fetchone()
                if (mapping_row is None or mapping_row[1] != 1
                        or json.loads(mapping_row[0]) != asdict(qualified_self[1])):
                    raise UnavailableGuard("D04 baseline current Authority self differs; HOLD")
                job, _, _, outbox, _, _, source_version, access_version = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if (job.operation_id != original_operation_id
                        or job.phase != "queued" or job.cancel_epoch != 0
                        or job.fence != 0 or job.lease_holder is not None
                        or source_version.key.token != source_ref
                        or outbox.payload_ref != source_version.key.owner.subject
                        or source_version not in envelope.version_guard.read_versions
                        or access_version not in envelope.version_guard.read_versions):
                    raise UnavailableGuard("D04 baseline job/source changed; HOLD")
                pre_quote = replace(envelope, version_guard=replace(
                    envelope.version_guard, resource_lease_versions=()))
                quote = self.__d11_issuer.issue_d04_baseline_quote(
                    db, pre_quote, admin_policy,
                    installation_id=installation_id, now_utc=baseline_now)
                refs = envelope.version_guard.resource_lease_versions
                if len(refs) != 1 or (refs[0].ref, refs[0].version) != (
                        quote.quote_id, quote.version):
                    raise AuthorityDenied("D04 baseline quote guard differs")
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote.quote_id,
                                          str(quote.version)),
                )
                db.execute("""CREATE TABLE IF NOT EXISTS graph_d04_baseline_issuance_v1(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, source_ref TEXT NOT NULL,
                    event_ref TEXT NOT NULL, quote_id TEXT NOT NULL,
                    bundle_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id))""")
                db.execute(
                    "INSERT INTO graph_d04_baseline_issuance_v1"
                    "(bot,persona,operation_id,source_ref,event_ref,quote_id,bundle_digest) "
                    "VALUES(?,?,?,?,?,?,?)",
                    namespace.as_tuple + (identity.operation_id, source_ref,
                                          event_ref, quote.quote_id, digest),
                )
            if self_identity_issuance is not None:
                (installation_policy, admin_policy, installation_id, stage_now,
                 source_ref, candidate, job_id, original_operation_id, _retry) = (
                    self_identity_issuance)
                if (v2_write is None or qualified_self is None
                        or len(bundle.proposals) != 1
                        or bundle.proposals[0].domain != "d03"
                        or envelope.identity.phase != "d03.self_identity_projection"
                        or envelope.input_refs != (source_ref,)
                        or bundle.persistent_job_refs or bundle.outbox_refs
                        or bundle.d02_settlement_refs or bundle.d11_cost_settlement_refs):
                    raise AuthorityDenied("D03 self projection issuance identity differs")
                role, qualified_mapping, current_self = qualified_self
                expected_metadata, expected_epoch = v2_write[:2]
                if (qualified_mapping != candidate
                        or current_self.graph_revision != expected_metadata.graph_revision
                        or current_self.graph_epoch != expected_epoch.revision
                        or installation_policy.installation_id != installation_id):
                    raise UnavailableGuard("D03 current self proof changed; HOLD")
                job, _, _, _, _, _, source_version, access_version = (
                    self._first_ingress_encoding_job_locked(namespace, job_id))
                if (job.operation_id != original_operation_id or job.phase != "queued"
                        or job.cancel_epoch != 0 or job.fence != 0
                        or job.lease_holder is not None
                        or source_version.key.token != source_ref
                        or source_version not in envelope.version_guard.read_versions
                        or access_version not in envelope.version_guard.read_versions):
                    raise UnavailableGuard("D03 self projection job/source changed; HOLD")
                pre_quote = replace(envelope, version_guard=replace(
                    envelope.version_guard, resource_lease_versions=()))
                quote = self.__d11_issuer.issue_d03_self_identity_projection_quote(
                    db, pre_quote, admin_policy, installation_id=installation_id,
                    qualified_mapping=qualified_mapping, now_utc=stage_now)
                refs = envelope.version_guard.resource_lease_versions
                if len(refs) != 1 or (refs[0].ref, refs[0].version) != (
                        quote.quote_id, quote.version):
                    raise AuthorityDenied("D03 self projection quote guard differs")
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote.quote_id,
                                          str(quote.version)),
                )
                db.execute("""CREATE TABLE IF NOT EXISTS graph_d03_self_projection_issuance_v1(
                    bot TEXT NOT NULL, persona TEXT NOT NULL,
                    operation_id TEXT NOT NULL, source_ref TEXT NOT NULL,
                    certification_ref TEXT NOT NULL, quote_id TEXT NOT NULL,
                    bundle_digest TEXT NOT NULL,
                    PRIMARY KEY(bot,persona,operation_id))""")
                db.execute(
                    "INSERT INTO graph_d03_self_projection_issuance_v1"
                    "(bot,persona,operation_id,source_ref,certification_ref,quote_id,bundle_digest) "
                    "VALUES(?,?,?,?,?,?,?)",
                    namespace.as_tuple + (identity.operation_id, source_ref,
                                          qualified_mapping.certification_ref,
                                          quote.quote_id, digest),
                )
            if c02_adoption is not None:
                witness = c02_adoption[0]
                if isinstance(witness, _C02TerminalRecovery):
                    request = witness.seal.original_key
                    installation = admin = None
                    stage_now = witness.now
                elif isinstance(witness, _C02PendingRecovery):
                    from .runtime.first_ingress_v2 import trusted_upper

                    request = witness.request
                    installation, admin, stage_now = (
                        witness.installation, witness.admin,
                        trusted_upper(witness.clock_reading))
                else:
                    _, read, _, _, installation, admin, stage_now = witness
                    request = read.request
                if c02_first_seal_quote is None:
                    if c02_terminal_recovery is not None:
                        raise UnavailableGuard("terminal C02 original signed quote absent; HOLD")
                    pre_quote = replace(envelope, version_guard=replace(
                        envelope.version_guard, resource_lease_versions=()))
                    quote = self.__d11_issuer.issue_d06_first_ingress_c02_quote(
                        db, pre_quote, admin,
                        installation_id=installation.installation_id,
                        job_id=request.job_id, now_utc=stage_now)
                else:
                    quote = c02_first_seal_quote
                refs = envelope.version_guard.resource_lease_versions
                if len(refs) != 1 or (refs[0].ref, refs[0].version) != (
                        quote.quote_id, quote.version):
                    raise AuthorityDenied("C02 signed quote guard differs")
                db.execute(
                    "INSERT INTO graph_guard_versions(bot,persona,kind,ref,version) "
                    "VALUES(?,?,?,?,?)",
                    namespace.as_tuple + ("resource_lease", quote.quote_id,
                                          str(quote.version)),
                )
            snapshot = self._check_guard(
                db, bundle, ingress_deadline_check=ingress_deadline_check,
                scene_owner_guard=scene_owner_guard)
            if dispatch_candidate is not None and self.__dispatch_admission_issuer is not None:
                from .runtime.dispatch_current_projection import (
                    read_current_dispatch_projection,
                )

                if len(envelope.version_guard.query_epochs) != 1:
                    raise UnavailableGuard("dispatch admission needs one full graph query")
                try:
                    dispatch_projections.append(read_current_dispatch_projection(
                        db, namespace, snapshot, envelope.version_guard.query_epochs[0],
                    ))
                except ValueError as exc:
                    raise UnavailableGuard(
                        "dispatch D03/D05 graph projection is incomplete") from exc
            guard_snapshots.append(snapshot)
            product_advance = self._check_product_advance(db, bundle, snapshot, writes)
            if product_advance is not None:
                product_advances.append(product_advance)
            for source in envelope.source_qualification.source_refs:
                key = self._parse_ref(source, namespace)
                if key in new_sources:
                    continue
                atom = snapshot.get(key)
                access = snapshot.get(access_key(*namespace.as_tuple,
                                                 key.owner.subject or ""))
                if atom is None or not atom.valid or access is None or not access.valid:
                    raise StaleRead("source or access is absent or invalid")
                if (access.value.get("status") != "active"
                        or access.value.get("source_id") != key.owner.subject
                        or not set(envelope.authority.audience).issubset(
                            access.value.get("audiences", ()))
                        or envelope.authority.purpose not in access.value.get("purposes", ())):
                    raise AuthorityDenied("source access no longer covers this use")
            if (dispatch_candidate is not None
                    and len(envelope.version_guard.query_epochs) == 1
                    and envelope.version_guard.query_epochs[0].scope_ref == "all"):
                from .domains.d08 import GoalExecutionProvider

                action_write = next(write for write in writes
                                    if write.key.type_name == "d08.action_intent.v1")
                action = next(spec for spec in GoalExecutionProvider().register_types()
                              if spec.name == "d08.action_intent.v1").validator(
                                  action_write.value)
                qualified_dispatch_candidates.append(qualify_dispatch_candidate_sources(
                    dispatch_candidate, action, snapshot,
                    audience=envelope.authority.audience,
                    batch_audiences=tuple(next(write.value["audiences"] for write in writes
                                               if write.key.type_name ==
                                               "d09.verified_segment_batch.v1")),
                    current_barrier_confirmed=True,
                    valid_until=next(write.value["valid_until"] for write in writes
                                     if write.key.type_name == "d09.verified_segment_batch.v1"),
                ))
            for proposal in bundle.proposals:
                if self_identity_issuance is not None:
                    from .domains.d03.self_perspective import (
                        validate_self_identity_projection_snapshot,
                    )

                    validate_self_identity_projection_snapshot(
                        proposal, snapshot, qualified_self[0], qualified_self[1])
                else:
                    if c02_adoption is not None and proposal.domain == "d11":
                        from .runtime.d11_types import validate_d11_writes

                        validate_d11_writes(
                            proposal.typed_writes, namespace,
                            operation_id=(c02_terminal_recovery.seal.original_key.original_operation_id
                                          if c02_terminal_recovery is not None else
                                          c02_adoption[0].request.original_operation_id
                                          if isinstance(c02_adoption[0], _C02PendingRecovery)
                                          else c02_adoption[0][2].budget_reservation_operation_id),
                            activity_id=identity.activity_id,
                            effect_id=identity.effect_id)
                        continue
                    provider = self.__providers[proposal.domain][0]
                    # Providers may return approval or the exact unchanged proposal.
                    # A transformed candidate would need its own validation pass.
                    validated = provider.validate(proposal, snapshot)
                    if validated is not True and validated != proposal:
                        raise AuthorityDenied("domain validation did not approve proposal")
            runtime_admissions.append(self._admit_runtime_bundle(
                db, bundle, now_utc=(
                    self._dispatch_clock_upper(dispatch_clock_reading)
                    if dispatch_clock_reading is not None else now_utc),
                require_arrival_quote=arrival_issuance is not None,
                c02_terminal_recovery=c02_terminal_recovery,
                c02_terminal_bundle_json=(c02_terminal_recovery.bundle_json
                                          if c02_terminal_recovery is not None else None),
                c02_terminal_quote_json=(c02_terminal_recovery.quote_json
                                         if c02_terminal_recovery is not None else None)))
            if c02_adoption is not None:
                from .runtime.d11_types import job_graph_write

                result_ref = bundle.proposals[1].typed_writes[0].value["result_ref"]
                if c02_terminal_recovery is None:
                    from .runtime.jobs import transition_job

                    completed = transition_job(
                        db, (c02_adoption[0].request.job_id
                             if isinstance(c02_adoption[0], _C02PendingRecovery)
                             else c02_adoption[0][1].request.job_id),
                        envelope.authority.actor, envelope.authority.worker_fence,
                        target_phase="completed", result_ref=result_ref)
                else:
                    from .runtime.c02_terminal_job import (
                        complete_original_c02_job_in_transaction,
                    )

                    witness = c02_terminal_recovery
                    completed = complete_original_c02_job_in_transaction(
                        db, original=witness.original, seal=witness.seal,
                        pinned_read=witness.pinned_read,
                        consumer_operation_id=identity.operation_id,
                        result_ref=result_ref, now_utc=now_utc,
                        current_gate=lambda conn, job, seal, fact:
                            self._validate_first_ingress_c02_terminal_locked(
                                conn, bundle, witness, job, seal, fact, v2_write))
                if job_graph_write(completed) != bundle.proposals[1].typed_writes[0]:
                    raise UnavailableGuard("C02 job transition differs from graph write")
            for proposal in bundle.proposals:
                for write in proposal.typed_writes:
                    if write.key.type_name.startswith("runtime."):
                        if proposal.domain != "d11":
                            raise AuthorityDenied("runtime graph write requires D11")
                        reconcile_runtime_write(db, write)

        def receipt_hook(db, graph_receipt):
            if c02_adoption is not None and isinstance(
                    c02_adoption[0], (_C02PendingRecovery, _C02TerminalRecovery)):
                from .runtime.first_ingress_v2 import trusted_upper

                if (trusted_upper(c02_adoption[0].clock_reading)
                        >= envelope.deadline_utc
                        or time.monotonic()
                        >= c02_adoption[0].local_monotonic_deadline):
                    raise UnavailableGuard("pending C02 deadline expired before commit")
            prior = db.execute(
                "SELECT digest,receipt_json FROM graph_bundle_operations WHERE bot=? "
                "AND persona=? AND operation_id=?",
                namespace.as_tuple + (identity.operation_id,),
            ).fetchone()
            if prior:
                if prior[0] != digest:
                    raise EventConflict("operation ID reused with different bundle")
                if graph_receipt.status != "duplicate":
                    raise EventConflict("operation ledger and graph event disagree")
                data = json.loads(prior[1])
                # Stored receipt is reconstructed from current canonical graph
                # event data; no caller-supplied status can mark a duplicate.
                result.append(CommitReceipt(
                    "duplicate", identity.operation_id, digest,
                    identity.activity_id, identity.effect_id, data["commit_seq"],
                    envelope.version_guard.read_versions,
                    graph_receipt.revisions, (graph_receipt.epoch,),
                    tuple(data["ledger_refs"]), tuple(data["outbox_refs"]),
                ))
                return
            if graph_receipt.status != "committed":
                raise EventConflict("graph event exists without bundle operation ledger")
            if identity.phase == "ingress" and not envelope.version_guard.query_epochs:
                # This runs after graph writes but before SQLite COMMIT.  The
                # sealed four-key exception must still hold, and the current
                # process clock may have advanced during provider validation.
                if v2_write is not None:
                    expected, expected_epoch = v2_write[:2]
                    current_metadata, current_epoch = self._v2_graph_stamp(namespace)
                    if (current_metadata != expected
                            or current_epoch != graph_receipt.epoch
                            or current_epoch.revision != expected_epoch.revision + 1):
                        raise StaleRead("v2 graph recovery stamp changed")
                elif not v2_read:
                    self._admit_content(
                        namespace, envelope.authority.activation_generation, "write",
                        tuple(item.key.token for item in envelope.version_guard.read_versions)
                        + tuple(write.key.token for write in writes),
                    )
                if self._version(db, namespace, "activation", "current") != str(
                        envelope.authority.activation_generation):
                    raise StaleRead("ingress activation generation changed before commit")
                epoch_row = db.execute(
                    "SELECT access_epoch,delete_epoch FROM graph_authority_epochs "
                    "WHERE bot=? AND persona=?", namespace.as_tuple,
                ).fetchone() or (0, 0)
                if tuple(epoch_row) != (
                        envelope.version_guard.access_epoch,
                        envelope.version_guard.delete_epoch):
                    raise StaleRead("ingress access or deletion epoch changed before commit")
                if not self._exact_ingress_without_query(
                        db, bundle, deadline_check=ingress_deadline_check):
                    raise UnavailableGuard("sealed ingress authority changed before commit")
            seq_row = db.execute(
                "SELECT last_seq FROM graph_bundle_sequence WHERE bot=? AND persona=?",
                namespace.as_tuple,
            ).fetchone()
            seq = (seq_row[0] if seq_row else 0) + 1
            db.execute(
                "INSERT INTO graph_bundle_sequence(bot,persona,last_seq) VALUES(?,?,?) "
                "ON CONFLICT(bot,persona) DO UPDATE SET last_seq=excluded.last_seq",
                namespace.as_tuple + (seq,),
            )
            ledger_refs = tuple(ref for kind, refs in part_refs if kind not in {"outbox"}
                                for ref in refs)
            data = {"commit_seq": seq, "ledger_refs": list(ledger_refs),
                    "outbox_refs": list(bundle.outbox_refs)}
            if c02_adoption is not None:
                witness = c02_adoption[0]
                observation_digest = (witness.evidence["observation_digest"]
                                      if isinstance(witness, (_C02PendingRecovery,
                                                              _C02TerminalRecovery))
                                      else witness[3].observation_digest)
                result_digest = (witness.evidence["result_payload_digest"]
                                 if isinstance(witness, (_C02PendingRecovery,
                                                         _C02TerminalRecovery))
                                 else witness[3].result_digest)
                if c02_terminal_recovery is None:
                    fact = c02_adoption[1]
                    data["first_ingress_c02"] = {
                        "read_request_digest": fact.read_request_digest,
                        "read_result_digest": fact.result_digest,
                        "original_intent_digest": fact.original_intent_digest,
                        "terminal_receipt_digest": canonical_digest(
                            asdict(fact.terminal_receipt)),
                        "observation_digest": observation_digest,
                        "result_digest": result_digest,
                    }
                else:
                    fact = c02_terminal_recovery.pinned_read.fact
                    data["first_ingress_c02"] = {
                        "seal_schema": c02_terminal_recovery.seal.schema,
                        "read_request_digest": canonical_digest(
                            c02_terminal_recovery.evidence["read_request"]),
                        "read_result_digest": c02_terminal_recovery.evidence["read_result_digest"],
                        "terminal_read_request_digest": fact.request.digest,
                        "terminal_read_fact_digest": fact.digest,
                        "original_key_digest": c02_terminal_recovery.seal.original_key.digest,
                        "signed_quote_digest": c02_terminal_recovery.seal.quote_digest,
                        "terminal_read_attempt_id": fact.request.read_attempt_id,
                        "original_intent_digest": c02_terminal_recovery.seal.original_key.original_intent_digest,
                        "terminal_receipt_digest": c02_terminal_recovery.seal.original_key.terminal_receipt_digest,
                        "observation_digest": observation_digest,
                        "result_digest": result_digest,
                    }
            if dispatch_candidate is not None:
                candidate_evidence = (qualified_dispatch_candidates[0]
                                      if qualified_dispatch_candidates else dispatch_candidate)
                versions = {item.key.token: item.revision
                            for item in graph_receipt.revisions}
                refs = (dispatch_candidate.action_ref,
                        dispatch_candidate.schema_ref,
                        dispatch_candidate.grant_ref,
                        dispatch_candidate.batch_ref)
                if any(versions.get(ref, 0) < 1 for ref in refs):
                    raise UnavailableGuard("dispatch candidate lacks same-commit graph versions")
                data["dispatch_candidate"] = {
                    "schema": "sylanne.d11.dispatch_candidate.v1",
                    "status": candidate_evidence.status,
                    "digest": candidate_evidence.digest,
                    "refs": [[ref, versions[ref]] for ref in refs],
                    "graph_epoch": graph_receipt.epoch.revision,
                    "source_refs": list(dispatch_candidate.source_refs),
                    "access_epoch": dispatch_candidate.access_epoch,
                    "delete_epoch": dispatch_candidate.delete_epoch,
                    "query_epoch": dispatch_candidate.query_epoch,
                    "source_audience": list(candidate_evidence.source_audience),
                    "source_proof_versions": [list(item) for item in
                                              candidate_evidence.source_proof_versions],
                    "source_proof_digest": candidate_evidence.source_proof_digest,
                    "graph_incarnation": (
                        v2_write[0].requirements.graph_incarnation
                        if v2_write is not None else None),
                    "graph_revision": (
                        v2_write[0].graph_revision + 1
                        if v2_write is not None else None),
                }
                if self.__dispatch_admission_issuer is not None:
                    from .domains.d08 import ActionCancellationState, GoalExecutionProvider
                    from .runtime.dispatch_action_job_binding import bind_action_job

                    admission_jobs = runtime_admissions[0].jobs
                    if (len(admission_jobs) != 1
                            or len(bundle.persistent_job_refs) != 1
                            or len(bundle.outbox_refs) != 1
                            or admission_jobs[0].graph_job_ref
                            != bundle.persistent_job_refs[0]
                            or set(admission_jobs[0].outbox_refs)
                            != set(bundle.outbox_refs)):
                        raise UnavailableGuard(
                            "dispatch admission requires one D11 job and its outbox")

                    d08_types = {spec.name: spec for spec in
                                 GoalExecutionProvider().register_types()}
                    linked = {write.key.type_name: write.value for write in writes
                              if write.key.type_name in {
                                  "d08.action_intent.v1", "d08.action_schema.v1",
                                  "d08.communication_intent_grant.v1",
                                  "d09.verified_segment_batch.v1",
                              }}
                    action = d08_types["d08.action_intent.v1"].validator(
                        linked["d08.action_intent.v1"])
                    admission_receipt = self._issue_dispatch_admission(
                        db, bundle, guard_snapshots[0], candidate_evidence,
                        action,
                        d08_types["d08.action_schema.v1"].validator(
                            linked["d08.action_schema.v1"]),
                        d08_types["d08.communication_intent_grant.v1"].validator(
                            linked["d08.communication_intent_grant.v1"]),
                        linked["d09.verified_segment_batch.v1"],
                        graph_receipt=graph_receipt, v2_write=v2_write,
                        projection=dispatch_projections[0] if dispatch_projections else None,
                        now_utc=(
                            self._dispatch_clock_upper(dispatch_clock_reading)
                            if dispatch_clock_reading is not None else now_utc),
                        clock_reading=dispatch_clock_reading,
                        dispatch_scope=dispatch_admission_scope,
                        dispatch_owner_guard=dispatch_admission_owner_guard,
                        dispatch_current_effect=dispatch_admission_current_effect,
                    )
                    issued = load_request(
                        db, namespace, admission_receipt.admission.admission_ref)
                    outbox_writes = tuple(
                        write for write in writes
                        if write.key.type_name == "runtime.outbox")
                    if (issued is None or issued[0] != admission_receipt
                            or len(outbox_writes) != 1
                            or outbox_writes[0].key.token != bundle.outbox_refs[0]):
                        raise UnavailableGuard("dispatch outbox payload is unbound")
                    request = issued[1]
                    outbox = outbox_writes[0].value
                    job = admission_jobs[0].job
                    if (outbox.get("job_id") != job.job_id
                            or outbox.get("job_ref")
                            != admission_jobs[0].graph_job_ref
                            or outbox.get("operation_id") != request.operation_id
                            or outbox.get("effect_id") != request.effect_id
                            or outbox.get("activity_id") != request.activity_id
                            or (outbox.get("bot_id"), outbox.get("persona_id"))
                            != namespace.as_tuple
                            or outbox.get("payload_ref") != request.payload_ref
                            or outbox.get("dispatch_generation")
                            != request.dispatch_generation
                            or outbox.get("phase") != "pending"):
                        raise UnavailableGuard("dispatch outbox payload differs from request")
                    try:
                        action_job_binding = bind_action_job(
                            db, action, admission_receipt)
                    except ValueError as exc:
                        raise UnavailableGuard(
                            "dispatch action/attempt lacks an exact D11 job binding") from exc
                    cancel_writes = tuple(
                        (proposal.domain, write)
                        for proposal in bundle.proposals
                        for write in proposal.typed_writes
                        if write.key.type_name == "d08.action_cancellation.v1"
                    )
                    expected_cancel = ActionCancellationState.for_action(
                        action, state="active", actor=envelope.authority.actor,
                        source_refs=envelope.source_qualification.source_refs,
                        operation_id=identity.operation_id,
                    )
                    cancel_key = AtomKey(
                        Owner("activity", *namespace.as_tuple, identity.activity_id),
                        "d08.action_cancellation.v1", action.action_id,
                    )
                    if (len(cancel_writes) != 1
                            or cancel_writes[0][0] != "d08"
                            or cancel_writes[0][1].key != cancel_key
                            or cancel_writes[0][1].value != json.loads(
                                canonical_serialize(asdict(expected_cancel)))
                            or tuple(ref.revision for ref in
                                     envelope.version_guard.read_versions
                                     if ref.key == cancel_key) != (0,)
                            or tuple(ref.revision for ref in graph_receipt.revisions
                                     if ref.key == cancel_key) != (1,)
                            or (admission_receipt.admission.action_ref,
                                admission_receipt.admission.attempt_id,
                                admission_receipt.admission.operation_id) != (
                                    action.action_id, identity.attempt_id,
                                    identity.operation_id)
                            or (action_job_binding.action_id,
                                action_job_binding.attempt_id,
                                action_job_binding.operation_id) != (
                                    action.action_id, identity.attempt_id,
                                    identity.operation_id)):
                        raise UnavailableGuard(
                            "dispatch admission lacks same-commit D08 active cancellation head")
                    data["dispatch_admission"] = {
                        "schema": admission_receipt.admission.schema,
                        "ref": admission_receipt.admission.admission_ref,
                        "digest": admission_receipt.receipt_digest,
                    }
                    data["dispatch_action_job_binding"] = {
                        "schema": action_job_binding.schema,
                        "ref": action_job_binding.admission_ref,
                        "digest": action_job_binding.digest,
                        "job_id": action_job_binding.job_id,
                    }
            if product_advances:
                data["product_advance_candidate"] = product_advances[0]
            if correction_issuance is not None:
                request = correction_issuance[3]
                correction_ref = bundle.proposals[0].typed_writes[0].key.token
                from .domains.d06 import source_correction_head_key
                head_refs = tuple(source_correction_head_key(
                    namespace, AtomKey.from_token(ref).owner.subject).token
                    for ref in request.source_refs)
                expected_writes = {
                    correction_ref, *request.target_refs,
                    *head_refs, bundle.persistent_job_refs[0], bundle.outbox_refs[0],
                }
                written = {item.key.token for item in graph_receipt.revisions}
                if (not expected_writes.issubset(written)
                        or v2_write is None or len(bundle.outbox_refs) != 1):
                    raise UnavailableGuard("source correction graph writes differ")
                data["source_correction"] = {
                    "request_digest": request.request_digest,
                    "correction_source_ref": correction_ref,
                    "source_refs": list(request.source_refs),
                    "correction_head_refs": list(head_refs),
                    "invalidated_target_refs": list(request.target_refs),
                    "reevaluation_outbox_ref": bundle.outbox_refs[0],
                    "audit_event_ref": identity.operation_id,
                    "graph_revision": v2_write[0].graph_revision + 1,
                    "access_epoch": request.access_epoch,
                    "deletion_epoch": request.deletion_epoch,
                    "reevaluation_status": "pending",
                }
            db.execute(
                "INSERT INTO graph_bundle_operations(bot,persona,operation_id,digest,"
                "activity_id,effect_id,commit_seq,receipt_json) VALUES(?,?,?,?,?,?,?,?)",
                namespace.as_tuple + (identity.operation_id, digest, identity.activity_id,
                                      identity.effect_id, seq, canonical_json(data)),
            )
            if c02_adoption is not None:
                if c02_first_seal_quote is not None:
                    db.execute("""CREATE TABLE IF NOT EXISTS
                        graph_first_ingress_c02_committed_seals_v2 (
                        bot TEXT NOT NULL, persona TEXT NOT NULL,
                        operation_id TEXT NOT NULL,
                        schema TEXT NOT NULL CHECK(schema=
                            'sylanne.first-ingress-c02-candidate.v2'),
                        bundle_digest TEXT NOT NULL,
                        fence_attempt_id TEXT NOT NULL,
                        bundle_json TEXT NOT NULL,
                        evidence_json TEXT NOT NULL,
                        quote_json TEXT NOT NULL,
                        seal_json TEXT NOT NULL,
                        PRIMARY KEY(bot,persona,operation_id))""")
                    copied = db.execute(
                        "INSERT INTO graph_first_ingress_c02_committed_seals_v2 "
                        "SELECT * FROM graph_first_ingress_c02_candidates_v2 "
                        "WHERE bot=? AND persona=? AND operation_id=? "
                        "AND bundle_digest=?",
                        namespace.as_tuple + (identity.operation_id, digest),
                    )
                    if copied.rowcount != 1:
                        raise UnavailableGuard("C02 v2 committed seal was lost")
                deleted = db.execute(
                    "DELETE FROM " + (
                        "graph_first_ingress_c02_candidates_v2 "
                        if c02_first_seal_quote is not None else
                        "graph_first_ingress_c02_candidates_v1 ") +
                    "WHERE bot=? AND persona=? AND operation_id=? "
                    "AND bundle_digest=?",
                    namespace.as_tuple + (identity.operation_id, digest),
                )
                if deleted.rowcount != 1:
                    raise UnavailableGuard("C02 pending candidate was lost before commit")
            if product_advances:
                advance = product_advances[0]
                db.execute(
                    "INSERT INTO graph_product_advances"
                    "(bot,persona,operation_id,process_id,feeling_ref,mood_ref,"
                    "parent_operation_id,replay_key,from_cursor,to_cursor,candidate_digest,"
                    "numeric_input_digest,numeric_output_digest,native_manifest_sha256,"
                    "native_sha256,previous_error_bound,next_error_bound) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        identity.operation_id, advance["process_id"], advance["feeling_ref"],
                        advance["mood_ref"], advance["parent_operation_id"], advance["replay_key"],
                        advance["from_cursor"], advance["to_cursor"], advance["candidate_digest"],
                        advance["numeric_input_digest"], advance["numeric_output_digest"],
                        advance["native_manifest_sha256"], advance["native_sha256"],
                        advance["previous_error_bound"], advance["next_error_bound"]),
                )
            for kind, refs in part_refs:
                for ref in refs:
                    db.execute(
                        "INSERT INTO graph_bundle_refs(bot,persona,operation_id,ref_kind,ref) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + (identity.operation_id, kind, ref),
                    )
            for ref in bundle.outbox_refs:
                db.execute(
                    "INSERT INTO graph_bundle_outbox(bot,persona,outbox_ref,operation_id,phase) "
                    "VALUES(?,?,?,?, 'pending')",
                    namespace.as_tuple + (ref, identity.operation_id),
                )
            if len(runtime_admissions) != 1:
                raise UnavailableGuard("D11 runtime admission was not recorded")
            for binding in runtime_admissions[0].jobs:
                for outbox_ref in binding.outbox_refs:
                    db.execute(
                        "INSERT INTO graph_outbox_jobs(bot,persona,outbox_ref,job_id,operation_id) "
                        "VALUES(?,?,?,?,?)",
                        namespace.as_tuple + (outbox_ref, binding.job.job_id,
                                              identity.operation_id),
                    )
            for proposal in bundle.proposals:
                for kind, edges in (("historical_provenance", proposal.dependencies.historical_provenance),
                                    ("association", proposal.dependencies.associations),
                                    ("numeric_coupling", proposal.dependencies.numeric_coupling)):
                    for write in proposal.typed_writes:
                        for ref in edges:
                            db.execute(
                                "INSERT INTO graph_dependency_edges(dependent_token,dependency_token,"
                                "dependency_revision,edge_kind,operation_id) VALUES(?,?,?,?,?)",
                                (write.key.token, ref.key.token, ref.revision, kind,
                                 identity.operation_id),
                            )
            if v2_write is not None:
                expected, expected_epoch, finish_id, finish_digest, permit_json = v2_write
                store.cas_graph_recovery_metadata(
                    expected, expected.requirements,
                    _capability=self.__graph_capability)
                db.execute(
                    "INSERT INTO graph_bundle_fences_v2"
                    "(bot,persona,operation_id,digest,permit_json,pre_graph_revision,"
                    "pre_graph_epoch,post_graph_revision,post_graph_epoch,"
                    "finish_request_id,finish_request_digest) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                    namespace.as_tuple + (
                        identity.operation_id, digest, permit_json,
                        expected.graph_revision, expected_epoch.revision,
                        expected.graph_revision + 1, graph_receipt.epoch.revision,
                        finish_id, finish_digest),
                )
            result.append(CommitReceipt(
                "committed", identity.operation_id, digest, identity.activity_id,
                identity.effect_id, seq, envelope.version_guard.read_versions,
                graph_receipt.revisions, (graph_receipt.epoch,), ledger_refs,
                bundle.outbox_refs,
            ))

        candidate = GraphCandidate(event, envelope.version_guard.read_versions,
                                   writes, ())
        if in_transaction:
            GraphStore._graph_commit_in_transaction(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
            )
        else:
            GraphStore.graph_commit(
                store, candidate, _guard=guard, _receipt_hook=receipt_hook,
                _capability=self.__graph_capability,
                _transaction_state=v2_transaction_state,
            )
        return result[0]


__all__ = [
    "GraphCoordinator", "AuthorityDenied", "UnavailableGuard",
    "FirstIngressOutcomeUnknown", "namespace_ref",
    "BudgetAdmission", "JobBinding", "RuntimeAdmission", "ScheduleAdmission",
    "OwnerLeaseBindingV1", "budget_operation_digest",
]
